"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Cpu, RefreshCw, AlertTriangle } from "lucide-react";
import { Card, Chip, Dot, Btn, Stat, Meter, type ChipTone } from "../console/ui/primitives";
import { describeProbeStatus } from "./lib/probe-error";

// ── Types ─────────────────────────────────────────────────────────────────────

interface ConnectionSummary {
  services: Array<{ service: string; keySource: string | null; stoppedWorking: boolean; callsLast24h: number }>;
}

interface LlmSummary {
  rows: Array<{ model: string | null; costUsd: number }>;
  totalCostUsd: number;
}

interface RagSummary {
  totalTickers: number;
  totalChunks: number;
  vectorStoreTotalVectors: number;
  globalBreakdown?: Record<string, number>;
  earningsTranscripts?: {
    featureEnabled: boolean;
    storageRightsConfirmed: boolean;
    enabled: boolean;
    capability: "disabled" | "unknown" | "available" | "endpoint_not_entitled" | "access_denied";
    lastCapability?: {
      httpStatus?: number;
    };
    ingestedCount: number;
  };
}

interface ServerSummary {
  hostInfo?: { cpuCount?: number; ramTotalGb?: number; memoryTotalBytes?: number };
  resources?: Array<{ status?: string; state?: string; name?: string }>;
  metrics?: {
    cpu?: Array<{ value: number }>;
  };
}

interface TranscriptSummary {
  turns: Array<{ id: string; role: string; text: string; model: string | null; createdAt: string }>;
}

export default function OperatorDashboard() {
  const [connections, setConnections] = useState<ConnectionSummary | null>(null);
  const [llm, setLlm] = useState<LlmSummary | null>(null);
  const [rag, setRag] = useState<RagSummary | null>(null);
  const [server, setServer] = useState<ServerSummary | null>(null);
  const [transcript, setTranscript] = useState<TranscriptSummary | null>(null);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  // Each probe's failure as its raw HTTP status, or "network" when the fetch itself never
  // got a response. Kept raw here (not pre-formatted into "HTTP 403" strings) so render sites
  // can turn it into human copy via describeProbeStatus — see ./lib/probe-error.
  const [probeErrors, setProbeErrors] = useState<Record<string, number | "network">>({});

  const fetchDashboardData = async () => {
    setError(null);
    setProbeErrors({});
    try {
      const results = await Promise.allSettled([
        fetch("/api/admin/connections-health"),
        fetch("/api/admin/llm-usage?sinceDays=30"),
        fetch("/api/admin/rag-coverage?sinceDays=30"),
        fetch("/api/admin/server-metrics"),
        fetch("/api/chat-history?limit=10")
      ]);

      const [resConn, resLlm, resRag, resServ, resTrans] = results;
      const errs: Record<string, number | "network"> = {};

      if (resConn.status === "fulfilled") {
        if (resConn.value.ok) setConnections(await resConn.value.json());
        else errs.connections = resConn.value.status;
      } else errs.connections = "network";

      if (resLlm.status === "fulfilled") {
        if (resLlm.value.ok) setLlm(await resLlm.value.json());
        else errs.llm = resLlm.value.status;
      } else errs.llm = "network";

      if (resRag.status === "fulfilled") {
        if (resRag.value.ok) setRag(await resRag.value.json());
        else errs.rag = resRag.value.status;
      } else errs.rag = "network";

      if (resServ.status === "fulfilled") {
        if (resServ.value.ok) setServer(await resServ.value.json());
        else errs.server = resServ.value.status;
      } else errs.server = "network";

      if (resTrans.status === "fulfilled") {
        if (resTrans.value.ok) setTranscript(await resTrans.value.json());
        else errs.transcript = resTrans.value.status;
      } else errs.transcript = "network";

      setProbeErrors(errs);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to load dashboard data");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const handleRefresh = () => {
    setRefreshing(true);
    fetchDashboardData();
  };

  // Helper formats
  const fmtCost = (usd: number) => {
    if (usd === 0) return "$0.00";
    if (usd < 0.01) return `$${usd.toFixed(4)}`;
    return `$${usd.toFixed(2)}`;
  };

  const getSourceLabel = (src: string) => {
    if (src === "sec-edgar") return "SEC";
    if (src.startsWith("fundamentals:")) return "Fund Card";
    if (src.startsWith("disclosure:congress")) return "Congress";
    if (src.startsWith("disclosure:insider")) return "Insider";
    if (src.includes("socratic-memory")) return "Coach";
    if (src.startsWith("sec8k-summary")) return "8-K Summary";
    if (src === "fmp-earnings-transcript") return "Earnings Transcript";
    return src.split(":").pop() || src;
  };

  const getSourceTone = (src: string): ChipTone => {
    if (src === "sec-edgar") return "accent";
    if (src.startsWith("fundamentals:")) return "info";
    if (src.startsWith("disclosure:congress")) return "warn";
    if (src.startsWith("disclosure:insider")) return "muted";
    if (src.includes("socratic-memory")) return "pos";
    if (src.startsWith("sec8k-summary")) return "neg";
    if (src === "fmp-earnings-transcript") return "info";
    return "muted";
  };

  const failedConnections = connections?.services.filter((s) => s.stoppedWorking) ?? [];
  const earningsStatus = rag?.earningsTranscripts;
  const earningsStatusView = !earningsStatus?.featureEnabled
    ? { label: "Off", tone: "muted" as const }
    : !earningsStatus.storageRightsConfirmed
      ? { label: "Rights unconfirmed", tone: "warn" as const }
      : earningsStatus.capability === "endpoint_not_entitled"
        ? { label: "Plan excludes endpoint", tone: "warn" as const }
        : earningsStatus.capability === "access_denied"
          ? {
              label: `Access denied${earningsStatus.lastCapability?.httpStatus ? ` (HTTP ${earningsStatus.lastCapability.httpStatus})` : ""}`,
              tone: "warn" as const
            }
        : earningsStatus.capability === "available"
          ? { label: "Available", tone: "pos" as const }
          : { label: "Not checked", tone: "muted" as const };

  // All five probes 403'd → this login isn't an operator. One honest notice
  // instead of five per-card probe errors (presentation of a real 403, not a gate).
  const allForbidden =
    Object.keys(probeErrors).length === 5 &&
    Object.values(probeErrors).every((e) => e === 403);

  // Short, human chip/badge text for a single probe's failure — see ./lib/probe-error for the
  // "why" (this presents a real 403 from requireAdmin, it doesn't paper over it).
  const probeErrorLabel = (entry: number | "network" | undefined): string | null =>
    entry === undefined ? null : entry === "network" ? "Request failed" : describeProbeStatus(entry).shortMessage;

  const currentCpu = server?.metrics?.cpu?.slice(-1)[0]?.value ?? 0;

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="flex items-center justify-between gap-4">
        <div>
          <h1 className="text-xl font-bold tracking-tight">Operator overview</h1>
          <p className="mt-1 text-[length:var(--con-fs-sm)] text-[color:var(--con-muted)]">
            Real-time status, diagnostics, and metrics across the Socratic Trade environment.
          </p>
        </div>
        <Btn variant="outline" size="sm" disabled={loading || refreshing} onClick={handleRefresh}>
          <RefreshCw className={`h-3.5 w-3.5 ${refreshing ? "animate-spin" : ""}`} />
          {refreshing ? "Refreshing..." : "Refresh"}
        </Btn>
      </div>

      {error && (
        /* Plain div, not Card: con-card's unlayered background/border beat
           Tailwind's layered utilities, so a tinted Card never actually tints. */
        <div className="rounded-[var(--con-radius)] border border-[color:var(--con-neg-border)] bg-[color:var(--con-neg-soft)] p-4">
          <div className="flex items-start gap-3 text-[length:var(--con-fs-sm)] text-[color:var(--con-neg)]">
            <AlertTriangle className="mt-0.5 h-5 w-5 shrink-0" />
            <div>
              <span className="font-semibold">Operator access required</span>
              <p className="mt-1 text-[length:var(--con-fs-xs)] opacity-90">{error}</p>
            </div>
          </div>
        </div>
      )}

      {loading ? (
        <div className="py-20 text-center text-[length:var(--con-fs-sm)] text-[color:var(--con-muted)]">
          Loading dashboard...
        </div>
      ) : allForbidden ? (
        <Card>
          <div className="flex items-start gap-3 text-[length:var(--con-fs-sm)]">
            <AlertTriangle className="mt-0.5 h-5 w-5 shrink-0 text-[color:var(--con-warn)]" />
            <div>
              <div className="font-semibold">Operator access required</div>
              <p className="mt-1 text-[color:var(--con-muted)]">
                This login does not have admin rights on the server.
              </p>
            </div>
          </div>
        </Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2">
          {/* ── 1. API connections ───────────────────────────────────────────── */}
          <Card
            title="API connections"
            action={
              <Link href="/admin/connections" className="con-btn con-btn-ghost con-btn-sm">
                Open →
              </Link>
            }
            className="flex h-full flex-col"
          >
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-[length:var(--con-fs-xs)] text-[color:var(--con-muted)]">Overall health</span>
                <Chip tone={failedConnections.length > 0 ? "neg" : probeErrors.connections ? "warn" : "pos"}>
                  <span title={typeof probeErrors.connections === "number" ? `HTTP ${probeErrors.connections}` : undefined}>
                    {failedConnections.length > 0 ? `${failedConnections.length} Offline` :
                     probeErrors.connections ? probeErrorLabel(probeErrors.connections) : "All Operations Online"}
                  </span>
                </Chip>
              </div>
              <div className="grid grid-cols-2 gap-3">
                {connections?.services.slice(0, 6).map((srv) => (
                  <div key={`${srv.service}:${srv.keySource ?? ""}`} className="con-tile flex items-center justify-between">
                    <span className="con-mono mr-2 truncate text-[length:var(--con-fs-xs)] font-medium" title={`${srv.service}${srv.keySource ? ` (${srv.keySource})` : ""}`}>
                      {srv.service}
                      {srv.keySource && <span className="ml-1 text-[color:var(--con-faint)]">({srv.keySource})</span>}
                    </span>
                    <Dot tone={srv.stoppedWorking ? "neg" : srv.callsLast24h > 0 ? "pos" : "muted"} pulse={srv.stoppedWorking} />
                  </div>
                ))}
              </div>
            </div>
          </Card>

          {/* ── 2. LLM usage & cost ──────────────────────────────────────────── */}
          <Card
            title="LLM usage & cost"
            action={
              <Link href="/admin/llm-usage" className="con-btn con-btn-ghost con-btn-sm">
                Open →
              </Link>
            }
            className="flex h-full flex-col"
          >
            <div className="flex h-full flex-col justify-between">
              <div className="mb-4">
                {probeErrors.llm ? (
                  <span
                    className="text-[length:var(--con-fs-sm)] text-[color:var(--con-warn)]"
                    title={typeof probeErrors.llm === "number" ? `HTTP ${probeErrors.llm}` : undefined}
                  >
                    {probeErrorLabel(probeErrors.llm)}
                  </span>
                ) : (
                  <Stat label="Last 30 days spend" value={llm ? fmtCost(llm.totalCostUsd) : "$0.00"} />
                )}
              </div>
              <div className="flex-1 space-y-2 border-t border-[color:var(--con-line)] pt-4">
                <span className="con-card-title mb-2 block">
                  Cost by model
                  {probeErrors.llm && <span className="ml-1.5 font-normal normal-case text-[color:var(--con-warn)]">(unavailable)</span>}
                </span>
                {(() => {
                  const agg = (llm?.rows ?? []).reduce<Record<string, number>>((acc, row) => {
                    const model = row.model ?? "Unknown";
                    acc[model] = (acc[model] || 0) + (row.costUsd || 0);
                    return acc;
                  }, {});
                  return Object.entries(agg)
                    .sort(([, a], [, b]) => b - a)
                    .slice(0, 3)
                    .map(([model, cost]) => (
                      <div key={model} className="flex items-center justify-between text-[length:var(--con-fs-xs)]">
                        <span className="con-mono max-w-[180px] truncate text-[color:var(--con-muted)]" title={model}>
                          {model}
                        </span>
                        <span className="con-num font-semibold">{fmtCost(cost)}</span>
                      </div>
                    ));
                })()}
              </div>
            </div>
          </Card>

          {/* ── 3. RAG coverage ──────────────────────────────────────────────── */}
          <Card
            title="RAG coverage"
            action={
              <Link href="/admin/rag-coverage" className="con-btn con-btn-ghost con-btn-sm">
                Open →
              </Link>
            }
            className="flex h-full flex-col"
          >
            <div className="space-y-4">
              {probeErrors.rag && (
                <div
                  className="flex items-center gap-1.5 text-[length:var(--con-fs-xs)] text-[color:var(--con-warn)]"
                  title={typeof probeErrors.rag === "number" ? `HTTP ${probeErrors.rag}` : undefined}
                >
                  <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
                  {probeErrorLabel(probeErrors.rag)}
                </div>
              )}
              <div className="grid grid-cols-3 gap-2 text-center">
                <div className="con-tile">
                  <div className="text-[length:var(--con-fs-xs)] text-[color:var(--con-muted)]">Tickers</div>
                  <div className="con-num mt-0.5 text-lg font-bold">{rag?.totalTickers ?? 0}</div>
                </div>
                <div className="con-tile">
                  <div className="text-[length:var(--con-fs-xs)] text-[color:var(--con-muted)]">Chunks</div>
                  <div className="con-num mt-0.5 text-lg font-bold">{rag?.totalChunks ?? 0}</div>
                </div>
                <div className="con-tile">
                  <div className="text-[length:var(--con-fs-xs)] text-[color:var(--con-muted)]">Vectors</div>
                  <div className="con-num mt-0.5 text-lg font-bold">{rag?.vectorStoreTotalVectors ?? 0}</div>
                </div>
              </div>

              {rag?.globalBreakdown && Object.keys(rag.globalBreakdown).length > 0 && (
                <div className="space-y-1.5 border-t border-[color:var(--con-line)] pt-3">
                  <span className="con-card-title mb-1 block">Index breakdown</span>
                  <div className="flex flex-wrap gap-1.5">
                    {Object.entries(rag.globalBreakdown)
                      .slice(0, 4)
                      .map(([src, count]) => (
                        <Chip key={src} tone={getSourceTone(src)} className="con-mono">
                          {count} {getSourceLabel(src)}
                        </Chip>
                      ))}
                  </div>
                </div>
              )}
              {earningsStatus && (
                <div className="flex items-center justify-between gap-3 border-t border-[color:var(--con-line)] pt-3 text-[length:var(--con-fs-xs)]">
                  <div>
                    <div className="text-[color:var(--con-muted)]">Earnings transcripts</div>
                    <div className="mt-0.5 text-[color:var(--con-faint)]">
                      {earningsStatus.ingestedCount.toLocaleString()} periods indexed
                    </div>
                  </div>
                  <Chip tone={earningsStatusView.tone}>{earningsStatusView.label}</Chip>
                </div>
              )}
            </div>
          </Card>

          {/* ── 4. Server & infrastructure ───────────────────────────────────── */}
          <Card
            title="Server & infrastructure"
            action={
              <Link href="/admin/server" className="con-btn con-btn-ghost con-btn-sm">
                Open →
              </Link>
            }
            className="flex h-full flex-col"
          >
            <div className="space-y-4">
              {probeErrors.server && (
                <div
                  className="mb-2 flex items-center gap-1.5 text-[length:var(--con-fs-xs)] text-[color:var(--con-warn)]"
                  title={typeof probeErrors.server === "number" ? `HTTP ${probeErrors.server}` : undefined}
                >
                  <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
                  {probeErrorLabel(probeErrors.server)}
                </div>
              )}
              <div className="space-y-3">
                {/* CPU Load */}
                <div>
                  <div className="mb-1 flex items-center justify-between text-[length:var(--con-fs-xs)]">
                    <span className="flex items-center gap-1 text-[color:var(--con-muted)]">
                      <Cpu className="h-3.5 w-3.5" /> CPU load
                    </span>
                    <span className="con-num font-semibold">{currentCpu.toFixed(1)}%</span>
                  </div>
                  <Meter value={currentCpu} max={100} />
                </div>

                {/* RAM */}
                <div>
                  <div className="mb-1 flex items-center justify-between text-[length:var(--con-fs-xs)]">
                    <span className="text-[color:var(--con-muted)]">Total memory (RAM)</span>
                    <span className="con-num font-semibold">
                      {server?.hostInfo?.memoryTotalBytes ? (server.hostInfo.memoryTotalBytes / 1024 / 1024 / 1024).toFixed(1) : 0} GB
                    </span>
                  </div>
                </div>
              </div>

              {/* Containers list */}
              <div className="flex items-center justify-between border-t border-[color:var(--con-line)] pt-3 text-[length:var(--con-fs-xs)]">
                <span className="text-[color:var(--con-muted)]">Docker containers</span>
                <span className="con-mono font-semibold">
                  {server?.resources?.filter((c) => { const s = c.status ?? ""; return (s.includes("running") || s.includes("healthy")) && !s.includes("unhealthy"); }).length ?? 0} Running
                </span>
              </div>
            </div>
          </Card>

          {/* ── 5. Chat transcript (full-width span) ─────────────────────────── */}
          <Card
            title="Chat transcript"
            action={
              <Link href="/admin/transcript" className="con-btn con-btn-ghost con-btn-sm">
                Open →
              </Link>
            }
            className="sm:col-span-2"
          >
            <div className="divide-y divide-[color:var(--con-line)]">
              {probeErrors.transcript && (
                <div
                  className="flex items-center gap-1.5 pb-3 text-[length:var(--con-fs-xs)] text-[color:var(--con-warn)]"
                  title={typeof probeErrors.transcript === "number" ? `HTTP ${probeErrors.transcript}` : undefined}
                >
                  <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
                  {probeErrorLabel(probeErrors.transcript)}
                </div>
              )}
              {transcript?.turns.filter((t) => t.role === "assistant").reverse().slice(0, 2).map((t, i) => (
                <div key={t.id} className={`${i > 0 ? "pt-3.5" : ""} flex flex-col gap-1.5 pb-3.5`}>
                  <div className="flex items-center justify-between text-[length:var(--con-fs-xs)]">
                    <Chip tone="accent" className="con-mono">
                      {t.model ?? "Unknown Model"}
                    </Chip>
                    <span className="con-mono text-[color:var(--con-faint)]">
                      {new Date(t.createdAt).toLocaleString()}
                    </span>
                  </div>
                  <p className="con-tile con-mono line-clamp-2 text-[length:var(--con-fs-xs)] italic text-[color:var(--con-muted)]">
                    {t.text}
                  </p>
                </div>
              ))}
              {transcript?.turns.filter((t) => t.role === "assistant").length === 0 && (
                <div className="py-4 text-center text-[length:var(--con-fs-xs)] text-[color:var(--con-muted)]">
                  No transcripts recorded yet.
                </div>
              )}
            </div>
          </Card>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { Btn, Card, Chip, Meter, Segmented, Stat, TextInput, type ChipTone } from "../../console/ui/primitives";
import { describeProbeNetworkError, describeProbeStatus, type ProbeErrorDescription } from "../lib/probe-error";

// ── Types ─────────────────────────────────────────────────────────────────────

interface TickerCoverage {
  symbol: string;
  filings: number;
  chunks: number;
  latestChunkAt: string | null;
  breakdown?: Record<string, number>;
}

interface VectorStoreHealth {
  configured: boolean;
  indexName: string;
  exists?: boolean;
  totalVectorCount?: number;
  dimension?: number;
  error?: string;
  lastIngest?: {
    at?: string;
    attempted?: number;
    indexed?: number;
    skipped?: boolean;
    error?: string;
    budgetSkipped?: number;
    writeUnitBudgetSkipped?: number;
    budget?: {
      requested?: number;
      allowed?: number;
      skipped?: number;
      usedLast24h?: number;
      limitPer24h?: number;
    };
    writeBudget?: {
      requestedEstimatedWriteUnits?: number;
      allowedEstimatedWriteUnits?: number;
      skipped?: number;
      usedLast24h?: number;
      limitPer24h?: number;
    };
  };
}

interface VectorIndexStats {
  indexName: string;
  totalVectorCount?: number;
  dimension?: number;
  error?: string;
}

interface CoverageData {
  sinceDays: number;
  perTicker: TickerCoverage[];
  globalBreakdown?: Record<string, number>;
  totalTickers: number;
  totalChunks: number;
  totalFilings: number;
  vectorStore: VectorStoreHealth;
  vectorStoreTotalVectors: number;
  allVectorIndexes?: VectorIndexStats[];
  allVectorStoreTotalVectors?: number;
  coverageGaps: string[];
  providerUsage?: {
    pinecone?: {
      monthlyUsageApiAvailable: boolean;
      note: string;
      configuredIndexVectors?: number;
      allVisibleIndexVectors?: number;
    };
    voyage?: {
      usageApiAvailable: boolean;
      note: string;
    };
  };
  ragUsage: {
    sinceDays: number;
    totalCostUsd: number;
    rows: Array<{
      userId: string;
      operation: string;
      provider: string;
      model: string | null;
      calls: number;
      tokensIn: number;
      tokensOut: number;
      batchCount: number;
      costEstUsd: number;
    }>;
  };
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function fmtCost(usd: number): string {
  if (usd === 0) return "$0.00";
  if (usd < 0.01) return `$${usd.toFixed(5)}`;
  return `$${usd.toFixed(4)}`;
}

// Headline totals show 2 decimals — a $34.8565 total reads as noise. Per-line-item
// costs keep fmtCost's 4dp (sub-cent precision matters for one call, not for a total).
function fmtTotalCost(usd: number): string {
  return `$${usd.toFixed(2)}`;
}

function fmtRelDate(iso: string | null): string {
  if (!iso) return "never";
  try {
    const d = new Date(iso);
    const now = Date.now();
    const diff = now - d.getTime();
    const mins = Math.floor(diff / 60_000);
    if (mins < 1) return "just now";
    if (mins < 60) return `${mins}m ago`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours}h ago`;
    const days = Math.floor(hours / 24);
    if (days < 30) return `${days}d ago`;
    return d.toLocaleDateString();
  } catch {
    return iso;
  }
}

function fmtInt(value: number | undefined): string {
  return typeof value === "number" && Number.isFinite(value) ? value.toLocaleString() : "configured";
}

function opLabel(op: string): string {
  const map: Record<string, string> = {
    embed: "Embed",
    rerank: "Rerank",
    query: "Query",
    upsert: "Upsert"
  };
  return map[op] ?? op;
}

function providerLabel(provider: string): string {
  const map: Record<string, string> = {
    voyage: "Voyage",
    pinecone: "Pinecone"
  };
  return map[provider] ?? provider;
}

function getSourceLabel(src: string): string {
  if (src === "sec-edgar") return "SEC";
  if (src.startsWith("fundamentals:")) return "Fund Card";
  if (src.startsWith("disclosure:congress")) return "Congress";
  if (src.startsWith("disclosure:insider")) return "Insider";
  if (src.includes("socratic-memory")) return "Coach";
  if (src.startsWith("sec8k-summary")) return "8-K Summary";
  if (src === "fmp-earnings-transcript") return "Earnings Transcript";
  return src.split(":").pop() || src;
}

function getSourceTone(src: string): ChipTone {
  if (src === "sec-edgar") return "accent";
  if (src.startsWith("fundamentals:")) return "info";
  if (src.startsWith("disclosure:congress")) return "warn";
  if (src.startsWith("disclosure:insider")) return "muted";
  if (src.includes("socratic-memory")) return "pos";
  if (src.startsWith("sec8k-summary")) return "neg";
  if (src === "fmp-earnings-transcript") return "info";
  return "muted";
}

// ── Components ────────────────────────────────────────────────────────────────

function StatusNotice({ tone, title, children }: { tone: "warning" | "danger" | "info"; title: string; children: React.ReactNode }) {
  const styles = {
    warning: "border-[color:var(--con-warn-border)] bg-[color:var(--con-warn-soft)] text-[color:var(--con-warn)]",
    danger: "border-[color:var(--con-neg-border)] bg-[color:var(--con-neg-soft)] text-[color:var(--con-neg)]",
    info: "border-[color:var(--con-line)] bg-[color:var(--con-surface-2)] text-[color:var(--con-fg)]"
  }[tone];
  return (
    <div className={`rounded-[var(--con-radius-sm)] border p-3 text-[length:var(--con-fs-sm)] ${styles}`}>
      <strong>{title}</strong>
      <div className="mt-1 opacity-90">{children}</div>
    </div>
  );
}

function TickerRow({ coverage }: { coverage: TickerCoverage }) {
  const maxChunks = 200; // reasonable visual scale cap
  return (
    <div className="flex items-center gap-3 border-b border-[color:var(--con-line)] py-2 text-[length:var(--con-fs-sm)] last:border-0">
      <div className="con-mono w-16 shrink-0 font-semibold">{coverage.symbol}</div>
      <div className="min-w-0 flex-1">
        <Meter value={coverage.chunks} max={maxChunks} />
        <div className="mt-1.5 flex flex-wrap items-center gap-3 text-[length:var(--con-fs-xs)] text-[color:var(--con-muted)]">
          <span className="font-semibold text-[color:var(--con-fg)]">{coverage.chunks} chunks</span>
          <span>{coverage.filings} filing{coverage.filings !== 1 ? "s" : ""}</span>
          {coverage.breakdown && Object.entries(coverage.breakdown).map(([src, count]) => {
            if (count === 0) return null;
            return (
              <Chip key={src} tone={getSourceTone(src)} className="con-mono">
                {count} {getSourceLabel(src)}
              </Chip>
            );
          })}
          <span className="ml-auto text-[color:var(--con-faint)]">{fmtRelDate(coverage.latestChunkAt)}</span>
        </div>
      </div>
    </div>
  );
}

function VectorIndexRow({ row, configuredIndex }: { row: VectorIndexStats; configuredIndex: string }) {
  const configured = row.indexName === configuredIndex;
  return (
    <div className="flex items-center gap-3 border-b border-[color:var(--con-line)] px-4 py-2 text-[length:var(--con-fs-xs)] last:border-0">
      <span className="con-mono min-w-0 flex-1 truncate" title={row.indexName}>
        {row.indexName}
      </span>
      {configured && <Chip tone="accent">configured</Chip>}
      <span className="con-mono w-24 text-right">{row.totalVectorCount ?? "?"}</span>
      <span className="con-mono w-20 text-right text-[color:var(--con-muted)]">{row.dimension ?? "?"}d</span>
    </div>
  );
}

// ── Main Component ────────────────────────────────────────────────────────────

const WINDOW_OPTIONS = [
  { label: "7d", days: 7 },
  { label: "30d", days: 30 },
  { label: "90d", days: 90 }
];

export function RagCoverageClient() {
  const [days, setDays] = useState(30);
  const [data, setData] = useState<CoverageData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<ProbeErrorDescription | null>(null);
  const [search, setSearch] = useState("");

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const params = new URLSearchParams({ sinceDays: String(days) });
      const res = await fetch(`/api/admin/rag-coverage?${params}`);
      if (!res.ok) {
        setError(describeProbeStatus(res.status));
        return;
      }
      setData(await res.json());
    } catch {
      setError(describeProbeNetworkError());
    } finally {
      setLoading(false);
    }
  }, [days]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const filtered = data
    ? data.perTicker.filter((t) =>
        t.symbol.toLowerCase().includes(search.toLowerCase())
      )
    : [];

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-xl font-semibold">RAG coverage</h1>
        <p className="mt-1 text-[length:var(--con-fs-sm)] text-[color:var(--con-muted)]">
          What&apos;s in the vector index per ticker — chunk counts, freshness, and coverage gaps.
        </p>
      </div>

      {/* Controls */}
      <div className="flex flex-wrap items-center gap-3">
        <Segmented
          value={String(days)}
          onChange={(v) => setDays(Number(v))}
          ariaLabel="Time window"
          options={WINDOW_OPTIONS.map((opt) => ({ value: String(opt.days), label: opt.label }))}
        />
        {/* con-input is width:100% (unlayered CSS beats Tailwind's w-auto), so size via a wrapper. */}
        <div className="w-44">
          <TextInput
            placeholder="Filter ticker…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            aria-label="Filter ticker"
          />
        </div>
        <Btn variant="outline" size="sm" className="ml-auto" onClick={fetchData} disabled={loading}>
          {loading ? "Loading…" : "Refresh"}
        </Btn>
      </div>

      {error && (
        <div
          className="rounded-[var(--con-radius-sm)] border border-[color:var(--con-neg-border)] bg-[color:var(--con-neg-soft)] p-3 text-[length:var(--con-fs-sm)] text-[color:var(--con-neg)]"
          title={error.rawLabel}
        >
          {error.message}
        </div>
      )}

      {data && (
        <>
          {/* Summary row */}
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            <div className="con-tile">
              <Stat label="Tickers indexed" value={String(data.totalTickers)} />
            </div>
            <div className="con-tile">
              <Stat
                label="Total chunks"
                value={String(data.totalChunks)}
                sub={`${data.totalFilings} filing${data.totalFilings !== 1 ? "s" : ""}`}
              />
            </div>
            <div className="con-tile">
              <Stat
                label="Pinecone vectors"
                value={String(data.vectorStoreTotalVectors)}
                sub={data.vectorStore?.indexName ?? "No index"}
              />
            </div>
            <div className="con-tile">
              <Stat
                label="App-recorded RAG"
                value={fmtTotalCost(data.ragUsage.totalCostUsd)}
                sub={`estimated Voyage cost, last ${data.sinceDays}d`}
              />
            </div>
          </div>

          {/* Global breakdown badges */}
          {data.globalBreakdown && Object.keys(data.globalBreakdown).length > 0 && (
            <Card title="Corpus composition">
              <div className="flex flex-wrap gap-2">
                {Object.entries(data.globalBreakdown)
                  .sort((a, b) => b[1] - a[1])
                  .map(([src, count]) => (
                    <Chip key={src} tone={getSourceTone(src)} className="con-mono">
                      <span className="font-semibold">{count.toLocaleString()}</span>
                      <span className="font-sans opacity-80">{getSourceLabel(src)}</span>
                    </Chip>
                  ))}
              </div>
            </Card>
          )}

          {(data.providerUsage?.pinecone || data.providerUsage?.voyage) && (
            <StatusNotice tone="info" title="Provider Usage Cross-Check">
              <div className="space-y-1">
                {data.providerUsage?.pinecone?.note && <p>{data.providerUsage.pinecone.note}</p>}
                {data.providerUsage?.voyage?.note && <p>{data.providerUsage.voyage.note}</p>}
              </div>
            </StatusNotice>
          )}

          {(data.vectorStoreTotalVectors > 0 && data.totalChunks === 0) && (
            <StatusNotice tone="warning" title="Pinecone Has Vectors, Local Coverage Ledger Is Empty">
              The configured Pinecone index reports {data.vectorStoreTotalVectors.toLocaleString()} vector{data.vectorStoreTotalVectors === 1 ? "" : "s"}, but this app&apos;s local <span className="con-mono">document_chunks</span> table has zero rows. Ticker coverage below is a local ledger view, not a full Pinecone inventory.
            </StatusNotice>
          )}
          {((data.allVectorStoreTotalVectors ?? 0) > data.vectorStoreTotalVectors) && (
            <StatusNotice tone="warning" title="Other Pinecone Indexes Also Consume This Org's Quota">
              This project key can see {(data.allVectorStoreTotalVectors ?? 0).toLocaleString()} vector{(data.allVectorStoreTotalVectors ?? 0) === 1 ? "" : "s"} across all Pinecone indexes, while the configured app index has {data.vectorStoreTotalVectors.toLocaleString()}. Pinecone Write Units are organization-level, so older indexes can explain quota usage that this ticker table does not show.
            </StatusNotice>
          )}

          {/* Vector store health */}
          {data.vectorStore && !data.vectorStore.configured && (
            <StatusNotice tone="warning" title="Pinecone/Voyage Not Configured">
              Shared RAG writes and retrieval are disabled because the backend keys are missing for this scope.
            </StatusNotice>
          )}
          {data.vectorStore?.exists === false && (
            <StatusNotice tone="danger" title="Pinecone Index Missing">
              The configured index <span className="con-mono">{data.vectorStore.indexName}</span> does not exist.
            </StatusNotice>
          )}
          {data.vectorStore?.error && (
            <StatusNotice tone="danger" title="Pinecone API Error">
              <span className="con-mono">{data.vectorStore.indexName}</span>: {data.vectorStore.error}
            </StatusNotice>
          )}
          {data.vectorStore?.lastIngest?.error && (
            <StatusNotice tone="danger" title="Last RAG Ingest Failed">
              {data.vectorStore.lastIngest.error}
              {data.vectorStore.lastIngest.at ? ` (${fmtRelDate(data.vectorStore.lastIngest.at)})` : ""}
            </StatusNotice>
          )}
          {(data.vectorStore?.lastIngest?.budgetSkipped ?? 0) > 0 && (
            <StatusNotice tone="warning" title="RAG Ingest Budget Reached">
              Skipped {data.vectorStore.lastIngest!.budgetSkipped} document{data.vectorStore.lastIngest!.budgetSkipped === 1 ? "" : "s"} before embedding. Current cap is {data.vectorStore.lastIngest!.budget?.limitPer24h ?? "configured"} texts per 24 hours.
            </StatusNotice>
          )}
          {(data.vectorStore?.lastIngest?.writeUnitBudgetSkipped ?? 0) > 0 && (
            <StatusNotice tone="warning" title="Pinecone Write Unit Budget Reached">
              Skipped {data.vectorStore.lastIngest!.writeUnitBudgetSkipped} document{data.vectorStore.lastIngest!.writeUnitBudgetSkipped === 1 ? "" : "s"} before Voyage embedding or Pinecone upsert. This run requested about {fmtInt(data.vectorStore.lastIngest!.writeBudget?.requestedEstimatedWriteUnits)} Write Units; {fmtInt(data.vectorStore.lastIngest!.writeBudget?.allowedEstimatedWriteUnits)} remained out of the {fmtInt(data.vectorStore.lastIngest!.writeBudget?.limitPer24h)} daily cap.
            </StatusNotice>
          )}

          {data.allVectorIndexes && data.allVectorIndexes.length > 0 && (
            <Card padded={false} className="overflow-hidden">
              <div className="con-card-title flex items-center gap-3 border-b border-[color:var(--con-line)] px-4 py-3">
                <span className="flex-1">Pinecone Index</span>
                <span className="w-24 text-right">Vectors</span>
                <span className="w-20 text-right">Dim</span>
              </div>
              <div>
                {data.allVectorIndexes
                  .slice()
                  .sort((a, b) => (b.totalVectorCount ?? -1) - (a.totalVectorCount ?? -1))
                  .map((row) => (
                    <VectorIndexRow key={row.indexName} row={row} configuredIndex={data.vectorStore?.indexName ?? ""} />
                  ))}
              </div>
            </Card>
          )}

          {/* Coverage gaps warning */}
          {data.coverageGaps.length > 0 && (
            <div className="rounded-[var(--con-radius-sm)] border border-[color:var(--con-neg-border)] bg-[color:var(--con-neg-soft)] p-3 text-[length:var(--con-fs-sm)] text-[color:var(--con-neg)]">
              <strong>{data.coverageGaps.length} ticker{data.coverageGaps.length !== 1 ? "s" : ""} have filing records but zero chunks in the index:</strong>{" "}
              {data.coverageGaps.join(", ")}
            </div>
          )}

          {/* Per-ticker list */}
          <Card padded={false} className="overflow-hidden">
            <div className="con-card-title flex items-center gap-3 border-b border-[color:var(--con-line)] px-4 py-3">
              <span className="w-16 shrink-0">Ticker</span>
              <span className="flex-1">Chunk coverage</span>
            </div>
            <div className="max-h-[60vh] overflow-y-auto px-4">
              {filtered.length === 0 ? (
                <div className="py-12 text-center text-[length:var(--con-fs-sm)] text-[color:var(--con-muted)]">
                  {search ? "No tickers match your filter." : "No indexed filings yet."}
                </div>
              ) : (
                filtered.map((t) => <TickerRow key={t.symbol} coverage={t} />)
              )}
            </div>
          </Card>

          {/* RAG usage table */}
          {data.ragUsage.rows.length > 0 && (
            <Card title="App-recorded RAG usage" padded={false} className="overflow-hidden">
              <div className="con-card-title flex items-center gap-3 border-b border-[color:var(--con-line)] px-4 py-2">
                <span className="w-24 shrink-0">Operation</span>
                <span className="w-20 shrink-0">Provider</span>
                <span className="flex-1">Model</span>
                <span className="w-16 text-right">Calls</span>
                <span className="w-20 text-right">Units / Tokens</span>
                <span className="w-20 text-right">Cost</span>
              </div>
              <div className="max-h-[30vh] divide-y divide-[color:var(--con-line)] overflow-y-auto">
                {data.ragUsage.rows.map((row, i) => (
                  <div key={i} className="flex items-center gap-3 px-4 py-2 text-[length:var(--con-fs-xs)]">
                    <span className="con-mono w-24 shrink-0">{opLabel(row.operation)}</span>
                    <span className="w-20 shrink-0 text-[color:var(--con-muted)]">{providerLabel(row.provider)}</span>
                    <span className="flex-1 truncate text-[color:var(--con-muted)]">{row.model ?? "—"}</span>
                    <span className="con-mono w-16 text-right text-[color:var(--con-muted)]">{row.calls}</span>
