"use client";

/** Destinations: left rail on desktop (≥1024px), bottom tab bar on mobile.
 *  Approvals carries the console's only red badge — its count is everything
 *  waiting for a decision there: pending trade proposals PLUS pending
 *  learned-context confirmations (one badge, one number, never two). */

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useId, useRef, useState } from "react";
import {
  Activity as ActivityIcon,
  BarChart3,
  Brain,
  Eye,
  Globe,
  Inbox,
  LayoutDashboard,
  LayoutGrid,
  ListChecks,
  MessageSquare,
  Pin,
  Plug,
  Radar,
  ReceiptText,
  Settings as SettingsIcon,
  Shield,
  X
} from "lucide-react";
import { nextSheetFocusTarget } from "../ui/sheet";
import { cx } from "../lib/format";
import { useNavDirtyGuard } from "../lib/useDirtyGuard";
import { DEFAULT_MOBILE_TAB_HREFS, MOBILE_TABS_MAX, MOBILE_TABS_MIN, useMobileTabs, type MobileTabsState } from "../lib/mobile-tabs";

/** Pending learned-context confirmations (risk-tier queue). Not part of the
 *  dashboard snapshot, so it's polled here — cheap endpoint, 60s cadence,
 *  refreshed when the tab becomes visible. Errors leave the last good count. */
function useLearnedPendingCount(): number {
  const [count, setCount] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const load = () => {
      void fetch("/api/learned-context/pending", { cache: "no-store" })
        .then((r) => (r.ok ? (r.json() as Promise<unknown>) : null))
        .then((rows) => {
          if (!cancelled && Array.isArray(rows)) setCount(rows.length);
        })
        .catch(() => {});
    };
    load();
    const interval = setInterval(() => {
      if (typeof document !== "undefined" && document.visibilityState === "hidden") return;
      load();
    }, 60_000);
    const onVisible = () => {
      if (document.visibilityState === "visible") load();
    };
    document.addEventListener("visibilitychange", onVisible);
    return () => {
      cancelled = true;
      clearInterval(interval);
      document.removeEventListener("visibilitychange", onVisible);
    };
  }, []);
  return count;
}

function badgeTitle(proposals: number, learned: number): string {
  const parts: string[] = [];
  if (proposals > 0) parts.push(`${proposals} trade proposal${proposals === 1 ? "" : "s"}`);
  if (learned > 0) parts.push(`${learned} learned-context item${learned === 1 ? "" : "s"}`);
  return `${parts.join(" and ")} waiting for your decision`;
}

interface Destination {
  href: string;
  label: string;
  icon: typeof LayoutDashboard;
  /** Concise hover explanation (native title) — every destination has one. */
  desc: string;
}

export const DESTINATIONS: Destination[] = [
  { href: "/console", label: "Thesis", icon: LayoutDashboard, desc: "Live thesis, actions, evidence, dissent, and framework learning." },
  { href: "/console/approvals", label: "Proposals", icon: Inbox, desc: "Trade proposals awaiting your judgment." },
  { href: "/console/activity", label: "Journal", icon: ActivityIcon, desc: "Decision journal: everything the agent did, newest first." },
  { href: "/console/scan", label: "Evidence", icon: Radar, desc: "The market scan: screened and scored symbols from the latest run." },
  { href: "/console/watchlist", label: "Watchlist", icon: Eye, desc: "Symbols the agent monitors, with price alerts that notify you when a level is crossed." },
  { href: "/console/macro", label: "Regime", icon: Globe, desc: "Macro and market-regime board: rates, credit, volatility, breadth." },
  { href: "/console/orders", label: "Orders", icon: ListChecks, desc: "Order history and open orders at the broker." },
  { href: "/console/assistant", label: "Coach", icon: MessageSquare, desc: "Coach Socratic Trade about its reasoning, accounts, and market focus." },
  { href: "/console/strategy", label: "Strategy", icon: Brain, desc: "The agent's brain: instructions, models, scoring weights, presets." },
  { href: "/console/guardrails", label: "Guardrails", icon: Shield, desc: "Autonomy, spending caps, protective stops, schedule, and the trading rulebook." },
  { href: "/console/connections", label: "Connections", icon: Plug, desc: "Broker accounts and provider API keys." },
  { href: "/console/results", label: "Outcomes", icon: BarChart3, desc: "Realized performance, equity curve, thesis scorecards, and learning evidence." },
  { href: "/console/usage", label: "Usage", icon: ReceiptText, desc: "Your LLM usage and estimated model cost by key, model, and workflow." },
  { href: "/console/settings", label: "Settings", icon: SettingsIcon, desc: "Notifications, sharing, confirmations, and console preferences." }
];

/** Canonical destination name for page titles. Every page h1 renders through this
 *  (h1 === rail label, the 2026-07-16 naming canon) so nav and titles can't drift
 *  apart again — 9 of 13 surfaces had diverged (click "Outcomes", land on "Results"). */
export function destinationLabel(href: string): string {
  return DESTINATIONS.find((d) => d.href === href)?.label ?? href;
}

function isActive(pathname: string, href: string): boolean {
  return href === "/console" ? pathname === "/console" : pathname.startsWith(href);
}

/** Single source of truth for destination grouping — desktop rail and the
 *  mobile Tabs menu both render from this so the two surfaces cannot drift
 *  apart. Order: Core (the three permanent-feeling primaries) first, then
 *  Monitor / Review, then Configure last (Settings is deliberately the
 *  lowest item in both surfaces). Anything not explicitly placed here falls
 *  into the last group so a newly added destination stays reachable even if
 *  this list isn't updated in lockstep. */
const GROUPED_DESTINATION_HREFS: { label: string; hrefs: string[] }[] = [
  { label: "Core", hrefs: ["/console", "/console/approvals", "/console/activity"] },
  { label: "Monitor", hrefs: ["/console/scan", "/console/watchlist", "/console/macro", "/console/orders"] },
  { label: "Review", hrefs: ["/console/assistant", "/console/results", "/console/usage"] },
  { label: "Configure", hrefs: ["/console/strategy", "/console/guardrails", "/console/connections", "/console/settings"] }
];

export function groupedDestinations(destinations: Destination[]): { label: string; items: Destination[] }[] {
  const placed = new Set<string>();
  const groups = GROUPED_DESTINATION_HREFS.map((group) => {
    const items = group.hrefs
      .map((href) => destinations.find((d) => d.href === href))
      .filter((d): d is Destination => d !== undefined);
    items.forEach((d) => placed.add(d.href));
    return { label: group.label, items };
  });
  const unmapped = destinations.filter((d) => !placed.has(d.href));
  if (unmapped.length > 0) groups[groups.length - 1].items.push(...unmapped);
  return groups;
}

export function DesktopRail({ pendingCount }: { pendingCount: number }) {
  const pathname = usePathname() ?? "";
  const guardNav = useNavDirtyGuard();
  const learnedCount = useLearnedPendingCount();
  const decisionCount = pendingCount + learnedCount;
  return (
    <nav className="hidden w-52 shrink-0 flex-col gap-1 px-3 py-4 lg:flex border-r border-[color:var(--con-line)] bg-[color:var(--con-surface-2)] shadow-sm mr-4" aria-label="Console navigation">
      {groupedDestinations(DESTINATIONS).map((group, i) => (
        <div key={group.label} className={cx("flex flex-col gap-1", i > 0 && "mt-4")}>
          <div className="con-card-title px-3 pb-1">{group.label}</div>
          {group.items.map((d) => {
            const Icon = d.icon;
            const active = isActive(pathname, d.href);
            return (
              <Link
                key={d.href}
                href={d.href}
                className="con-nav-item"
                data-active={active}
                aria-current={active ? "page" : undefined}
                title={d.desc}
                onClick={(e) => guardNav(e, d.href)}
              >
                <Icon size={16} />
                <span className="flex-1">{d.label}</span>
                {d.href === "/console/approvals" && decisionCount > 0 && (
                  <span className="con-badge" title={badgeTitle(pendingCount, learnedCount)}>
                    {decisionCount}
                  </span>
                )}
              </Link>
            );
          })}
        </div>
      ))}
    </nav>
  );
}

const FOCUSABLE_SELECTOR =
  'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])';

/** Sheet stops just above the fixed tab bar (rather than covering it) so the
 * bar — and any pin toggle's live effect on it — stays visible the whole
 * time the sheet is open. `barHeight` is the tab bar's real measured height
 * (see `MobileTabBar`'s ResizeObserver), so this tracks safe-area insets and
 * font-scaling exactly instead of guessing a fixed offset. `GAP` is the
 * small breathing-room reveal between the sheet and the bar; `TOP_GAP` keeps
 * the sheet off the very top of the viewport (status bar / notch). A floor
 * is used until the first measurement lands (effectively instant — the bar
 * is always mounted before a user can tap "Tabs" to open this). */
const TABS_SHEET_GAP = 0;
const TABS_SHEET_TOP_GAP = 16;
const TABS_SHEET_BAR_FLOOR = 56;

/** The bottom-sheet destination picker — replaces the old "More" list.
 *  Unlike the shared `Sheet` (a centered dialog on desktop, plain bottom
 *  sheet on mobile), this always slides up from the bottom with an explicit
 *  transform/opacity transition, because it only ever renders on mobile
 *  (`lg:hidden`) alongside the bottom tab bar. `prefers-reduced-motion`
 *  collapses the transition to 0ms rather than skipping it, so the sheet
 *  still ends up in the right place either way.
 *
 *  It floats above the tab bar (not over it) and stretches to fill nearly
 *  all remaining vertical space, so a typical phone shows every destination
 *  without scrolling while the bar's pin state stays live underneath —
 *  see `TABS_SHEET_GAP` etc. above for why. */
function TabsSheet({
  open,
  onClose,
  pathname,
  guardNav,
  tabs,
  decisionCount,
  pendingCount,
  learnedCount,
  barHeight
}: {
  open: boolean;
  onClose: () => void;
  pathname: string;
  guardNav: (event: { preventDefault: () => void } | undefined, href: string) => boolean;
  tabs: MobileTabsState;
  decisionCount: number;
  pendingCount: number;
  learnedCount: number;
  barHeight: number;
}) {
  const sheetRef = useRef<HTMLDivElement>(null);
  const openerRef = useRef<HTMLElement | null>(null);
  const headingId = useId();
  const [entered, setEntered] = useState(false);
  const barOffset = Math.max(barHeight, TABS_SHEET_BAR_FLOOR);

  useEffect(() => {
    if (!open) {
      setEntered(false);
      return;
    }
    const raf = requestAnimationFrame(() => setEntered(true));

    const active = document.activeElement;
    openerRef.current = active instanceof HTMLElement && active !== document.body && active !== document.documentElement ? active : null;
    const sheet = sheetRef.current;
    const focusables = sheet
      ? Array.from(sheet.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR)).filter((el) => !el.hasAttribute("disabled"))
      : [];
    try {
      (focusables[0] ?? sheet)?.focus({ preventScroll: true });
    } catch {
      (focusables[0] ?? sheet)?.focus();
    }

    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        onClose();
        return;
      }
      if (e.key !== "Tab") return;
      const current = sheetRef.current;
      if (!current) return;
      const tabbables = Array.from(current.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR)).filter((el) => !el.hasAttribute("disabled"));
      const activeEl = document.activeElement;
      const isInside = activeEl instanceof Node ? current.contains(activeEl) : false;
      const target = nextSheetFocusTarget(
        tabbables,
        activeEl instanceof HTMLElement ? activeEl : null,
        current,
        e.shiftKey,
        isInside
      );
      if (target) {
        e.preventDefault();
        target.focus({ preventScroll: true });
      }
    };
    window.addEventListener("keydown", onKey);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("keydown", onKey);
      const opener = openerRef.current;
      openerRef.current = null;
      if (opener && opener.isConnected) opener.focus({ preventScroll: true });
    };
  }, [open, onClose]);

  if (!open) return null;

  return (
    <>
      {/* Scrim stops above the tab bar (not inset-0) so the bar reads as
       * live/interactive, not dimmed, while the sheet is open. */}
      <div className="con-scrim lg:hidden" style={{ bottom: barOffset }} onClick={onClose} aria-hidden />
      <div
        ref={sheetRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={headingId}
        tabIndex={-1}
        className={cx(
          "fixed inset-x-0 z-[101] flex flex-col overflow-hidden rounded-t-[24px] border border-[color:var(--con-line-strong)] bg-[color:var(--con-surface)] shadow-[var(--con-shadow-lg)] transition-[transform,opacity] duration-200 ease-out motion-reduce:transition-none motion-reduce:duration-0 lg:hidden",
          entered ? "translate-y-0 opacity-100" : "translate-y-full opacity-0"
        )}
        style={{
          bottom: barOffset + TABS_SHEET_GAP,
          maxHeight: `calc(100dvh - ${barOffset + TABS_SHEET_GAP + TABS_SHEET_TOP_GAP}px)`
        }}
      >
        <header className="flex items-center justify-between gap-4 border-b border-[color:var(--con-line)] px-5 py-3.5 relative">
          <div className="absolute top-2 left-1/2 -translate-x-1/2 w-9 h-1.5 rounded-full bg-[color:var(--con-line-strong)] opacity-60"></div>
          <h2 id={headingId} className="text-[length:var(--con-fs-md)] font-semibold mt-2">
            More
          </h2>
          <button
            type="button"
            aria-label="Close"
            className="text-[color:var(--con-faint)] transition-colors hover:text-[color:var(--con-fg)]"
            onClick={onClose}
          >
            <X size={18} />
          </button>
        </header>
        <div className="overflow-y-auto px-3 py-3">
          {groupedDestinations(DESTINATIONS).map((group) => (
            <div key={group.label} className="mb-4 last:mb-1">
              <div className="px-2 pb-1.5 text-[length:var(--con-fs-xs)] font-semibold uppercase tracking-[0.07em] text-[color:var(--con-faint)]">
                {group.label}
              </div>
              <div className="flex flex-col gap-1 pl-2">
                {group.items.map((d) => {
                  const Icon = d.icon;
                  const active = isActive(pathname, d.href);
                  const pinned = tabs.isPinned(d.href);
                  const canToggle = tabs.canToggle(d.href);
                  const pinTitle = pinned
                    ? canToggle
                      ? "Remove from tabs"
                      : `Keep at least ${MOBILE_TABS_MIN} tabs`
                    : canToggle
                      ? "Add to tabs"
                      : `Up to ${MOBILE_TABS_MAX} tabs — remove one first`;
                  return (
                    <div key={d.href} className="flex items-center gap-1">
                      <Link
                        href={d.href}
                        className="con-nav-item flex-1"
                        data-active={active}
                        aria-current={active ? "page" : undefined}
                        title={d.desc}
                        onClick={(e) => {
                          if (guardNav(e, d.href)) onClose();
                        }}
                      >
                        <Icon size={16} />
                        <span className="flex-1">{d.label}</span>
                        {d.href === "/console/approvals" && decisionCount > 0 && (
                          <span className="con-badge" title={badgeTitle(pendingCount, learnedCount)}>
                            {decisionCount}
                          </span>
                        )}
                      </Link>
                      <button
                        type="button"
                        aria-pressed={pinned}
                        aria-label={pinned ? `Remove ${d.label} from tabs` : `Add ${d.label} to tabs`}
                        title={pinTitle}
                        disabled={!canToggle}
                        className="flex h-9 w-9 shrink-0 items-center justify-center rounded-[var(--con-radius-sm)] text-[color:var(--con-faint)] transition-colors enabled:hover:bg-[color:var(--con-surface-2)] enabled:hover:text-[color:var(--con-fg)] disabled:opacity-40"
                        onClick={(e) => {
                          e.stopPropagation();
                          tabs.togglePin(d.href);
                        }}
                      >
                        <Pin size={16} fill={pinned ? "currentColor" : "none"} />
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </div>
    </>
  );
}

export function MobileTabBar({ pendingCount }: { pendingCount: number }) {
  const pathname = usePathname() ?? "";
  const [tabsOpen, setTabsOpen] = useState(false);
  const guardNav = useNavDirtyGuard();
  const learnedCount = useLearnedPendingCount();
  const decisionCount = pendingCount + learnedCount;
  const tabsState = useMobileTabs(DESTINATIONS.map((d) => d.href));
  const navRef = useRef<HTMLElement>(null);
  const [barHeight, setBarHeight] = useState(0);

  // Real measured height (incl. the bar's own safe-area padding) so the
  // TabsSheet can stop exactly above it on any device/font-scale, rather
  // than guessing a fixed px offset.
  useEffect(() => {
    const el = navRef.current;
    if (!el) return;
    const measure = () => setBarHeight(el.getBoundingClientRect().height);
    measure();
    if (typeof ResizeObserver !== "undefined") {
      const ro = new ResizeObserver(measure);
      ro.observe(el);
      return () => ro.disconnect();
    }
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, []);

  // SSR-safe: before mount, tabHrefs is already DEFAULT_MOBILE_TAB_HREFS (the
  // hook's initial state), so this matches the server render exactly.
  const activeHrefs = tabsState.mounted ? tabsState.tabHrefs : [...DEFAULT_MOBILE_TAB_HREFS];
  const tabs = DESTINATIONS.filter((d) => activeHrefs.includes(d.href));
  const tabsButtonActive = !DESTINATIONS.some((d) => activeHrefs.includes(d.href) && isActive(pathname, d.href));

  return (
    <>
      <nav
        ref={navRef}
        className="fixed inset-x-0 bottom-0 z-50 border-t border-[color:var(--con-line-strong)] bg-[color:var(--con-surface)]/85 backdrop-blur-xl supports-[backdrop-filter]:bg-[color:var(--con-surface)]/70 lg:hidden"
        style={{ paddingBottom: "env(safe-area-inset-bottom)" }}
        aria-label="Console navigation"
      >
        <div className="flex">
          {tabs.map((d) => {
            const Icon = d.icon;
            const active = isActive(pathname, d.href);
            return (
              <Link
                key={d.href}
                href={d.href}
                className="con-tab-item"
                data-active={active}
                aria-current={active ? "page" : undefined}
                title={d.desc}
                style={active ? { fontWeight: 800 } : undefined}
                onClick={(e) => {
                  if (guardNav(e, d.href)) {
                    setTabsOpen(false);
                  }
                }}
              >
                <span
                  className="relative flex h-7 w-10 items-center justify-center rounded-full transition-colors"
                  style={active ? { background: "var(--con-accent-soft)" } : undefined}
                >
                  <Icon size={19} />
                  {d.href === "/console/approvals" && decisionCount > 0 && (
                    <span className="con-badge absolute -right-2.5 -top-1" title={badgeTitle(pendingCount, learnedCount)}>
                      {decisionCount}
                    </span>
                  )}
                </span>
                {d.label}
              </Link>
            );
          })}
          <button
            type="button"
            className="con-tab-item"
            data-active={tabsButtonActive || tabsOpen}
            title={tabsOpen ? "Close more menu" : "Choose which screens show up here, or jump to any screen"}
            style={tabsButtonActive || tabsOpen ? { fontWeight: 800 } : undefined}
            onClick={() => setTabsOpen(!tabsOpen)}
          >
            <span
              className="relative flex h-7 w-10 items-center justify-center rounded-full transition-colors"
              style={tabsButtonActive || tabsOpen ? { background: "var(--con-accent-soft)" } : undefined}
            >
              <LayoutGrid size={19} />
            </span>
            {/* Was "Tabs" — unclear for the standard mobile overflow-menu pattern this
                is (the grid of every destination, with pin/unpin to customize the bar
                above). "More" is the conventional label for this affordance. */}
            More
          </button>
        </div>
      </nav>

      <TabsSheet
        open={tabsOpen}
        onClose={() => setTabsOpen(false)}
        pathname={pathname}
        guardNav={guardNav}
        tabs={tabsState}
        decisionCount={decisionCount}
        pendingCount={pendingCount}
        learnedCount={learnedCount}
        barHeight={barHeight}
      />
    </>
  );
}

"use client";

/** Policy editing toolkit: sparse-draft editing over the live policy, a diff
 *  review sheet, and asymmetric friction — tightening saves with one click,
 *  loosening brokerage-account authority requires typing CONFIRM. The commit model comes
 *  from the explainability design: you never "save settings", you review and
 *  commit a change. The diff/classification logic lives in ../lib/policy-diff
 *  (pure, unit-tested); this file is the React skin over it. */

import { useEffect, useMemo, useState, type ReactNode } from "react";
import { Lock, Unlock } from "lucide-react";
import { DEFAULT_POLICY } from "@/lib/defaults";
import type { TradingPolicy } from "@/lib/types";
import { savePolicy, ConsoleApiError, type PolicyPatchBody } from "../lib/api";
import type { RealityInfo } from "../lib/derive";
import {
  buildPatch,
  classifyExtraPatch,
  clearedFallback,
  computeDiff,
  getAtPath,
  isBlank,
  type DiffEntry,
  type ExtraDiffEntry,
  type FieldDef
} from "../lib/policy-diff";
import { fmtNum, EM_DASH } from "../lib/format";
import { useConsoleData } from "../lib/useConsoleData";
import { useUnsavedChanges } from "../lib/useDirtyGuard";
import { useToast } from "../ui/toast";
import { Btn, Chip, LiveTag, NumInput, Segmented, Select, TextInput, Toggle } from "../ui/primitives";
import { Sheet } from "../ui/sheet";
import { TypedConfirm } from "./chrome";

export type { FieldDef, FieldKind, DiffEntry } from "../lib/policy-diff";
export { getAtPath, computeDiff, buildPatch } from "../lib/policy-diff";

// ── Draft state (sparse: only touched fields) ────────────────────────────────

export interface PolicyDraft {
  values: Record<string, unknown>;
  set: (path: string, value: unknown) => void;
  clear: () => void;
}

export function usePolicyDraft(): PolicyDraft {
  const [values, setValues] = useState<Record<string, unknown>>({});
  return {
    values,
    set: (path, value) => setValues((prev) => ({ ...prev, [path]: value })),
    clear: () => setValues({})
  };
}

// ── Field renderer ───────────────────────────────────────────────────────────

function fmtValue(def: FieldDef, v: unknown): string {
  if (def.kind === "select") {
    const label = (value: unknown) => def.options?.find((o) => o.value === String(value))?.label ?? String(value);
    return isBlank(v) ? `default (${label(getAtPath(DEFAULT_POLICY, def.path))})` : label(v);
  }
  if (isBlank(v)) {
    if (!def.optional) return EM_DASH;
    // Honest blank label: the server re-applies the shipped default for fields
    // that have one — only claim "off" when clearing truly turns the guard off.
    const fallback = clearedFallback(def);
    return fallback !== undefined ? `default (${fmtValue(def, fallback)})` : "off";
  }
  if (def.kind === "bool") return v === true ? "on" : "off";
  if (def.kind === "money") return `$${fmtNum(v as number)}`;
  if (def.kind === "pct") return `${fmtNum(v as number)}%`;
  if (def.kind === "minutes") return `${fmtNum(v as number)} min`;
  if (def.kind === "seconds") return `${fmtNum(v as number)} s`;
  return String(v);
}

export function PolicyFieldRow({ def, policy, draft }: { def: FieldDef; policy: TradingPolicy; draft: PolicyDraft }) {
  const current = getAtPath(policy, def.path);
  const touched = def.path in draft.values;
  const value = touched ? draft.values[def.path] : current;
  // While the input is focused we render the raw typed text, so transient
  // states like "0." or "12." survive keystrokes (Number() would collapse
  // them). The parsed number is still committed to the draft on every change;
  // blur snaps the text back to the canonical value.
  const [editText, setEditText] = useState<string | null>(null);

  if (def.kind === "bool") {
    return (
      <div className="flex items-start justify-between gap-4 py-2">
        <div>
          <div className="text-[length:var(--con-fs-sm)] font-semibold">
            {def.label}
            {touched && <span className="ml-2 text-[length:var(--con-fs-xs)] text-[color:var(--con-warn)]">edited</span>}
          </div>
          {def.hint && <p className="mt-0.5 max-w-xl text-[length:var(--con-fs-xs)] leading-snug text-[color:var(--con-faint)]">{def.hint}</p>}
        </div>
        <Toggle checked={value === true} onChange={(next) => draft.set(def.path, next)} label={def.label} />
      </div>
    );
  }

  if (def.kind === "select") {
    const fallback = String(getAtPath(DEFAULT_POLICY, def.path) ?? "");
    const selected = isBlank(value) ? fallback : String(value);
    return (
      <div className="py-2">
        <div className="flex items-end justify-between gap-4">
          <label className="text-[length:var(--con-fs-sm)] font-semibold" htmlFor={`pf-${def.path}`}>
            {def.label}
            {touched && <span className="ml-2 text-[length:var(--con-fs-xs)] text-[color:var(--con-warn)]">edited</span>}
          </label>
          <div className="w-52">
            <Select id={`pf-${def.path}`} value={selected} onChange={(e) => draft.set(def.path, e.target.value)}>
              {(def.options ?? []).map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </Select>
          </div>
        </div>
        {def.hint && <p className="mt-0.5 max-w-xl text-[length:var(--con-fs-xs)] leading-snug text-[color:var(--con-faint)]">{def.hint}</p>}
      </div>
    );
  }

  const unit = def.kind === "money" ? "$" : def.kind === "pct" ? "%" : def.kind === "minutes" ? "min" : def.kind === "seconds" ? "sec" : undefined;
  const numeric = def.kind !== "text";
  const display = isBlank(value) ? "" : String(value);
  const blankFallback = def.optional ? clearedFallback(def) : undefined;
  const blankPlaceholder = def.optional ? (blankFallback !== undefined ? `default ${blankFallback}` : "off") : undefined;

  return (
    <div className="py-2">
      <div className="flex items-end justify-between gap-4">
        <label className="text-[length:var(--con-fs-sm)] font-semibold" htmlFor={`pf-${def.path}`}>
          {def.label}
          {touched && <span className="ml-2 text-[length:var(--con-fs-xs)] text-[color:var(--con-warn)]">edited</span>}
        </label>
        <div className="flex w-36 items-center gap-1.5">
          {unit === "$" && <span className="text-[color:var(--con-faint)]">$</span>}
          {numeric ? (
            <NumInput
              id={`pf-${def.path}`}
              value={editText ?? display}
              placeholder={blankPlaceholder}
              onFocus={() => setEditText(display)}
              onBlur={() => setEditText(null)}
              onChange={(e) => {
                const raw = e.target.value;
                setEditText(raw);
                const parsed = Number(raw);
                draft.set(def.path, raw === "" || !Number.isFinite(parsed) ? null : parsed);
              }}
            />
          ) : (
            <TextInput id={`pf-${def.path}`} value={display} onChange={(e) => draft.set(def.path, e.target.value)} />
          )}
          {unit && unit !== "$" && <span className="text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">{unit}</span>}
        </div>
      </div>
      {def.hint && <p className="mt-0.5 max-w-xl text-[length:var(--con-fs-xs)] leading-snug text-[color:var(--con-faint)]">{def.hint}</p>}
    </div>
  );
}

export function PolicyDualModeRow({
  label,
  moneyDef,
  pctDef,
  policy,
  draft,
  hint
}: {
  label: string;
  moneyDef: FieldDef;
  pctDef: FieldDef;
  policy: TradingPolicy;
  draft: PolicyDraft;
  hint?: string;
}) {
  const moneyTouched = moneyDef.path in draft.values;
  const pctTouched = pctDef.path in draft.values;
  const moneyValue = moneyTouched ? draft.values[moneyDef.path] : getAtPath(policy, moneyDef.path);
  const pctValue = pctTouched ? draft.values[pctDef.path] : getAtPath(policy, pctDef.path);
  const policyMode: "money" | "pct" = !isBlank(getAtPath(policy, pctDef.path)) ? "pct" : "money";
  const [draftMode, setDraftMode] = useState<"money" | "pct">(policyMode);
  const [editText, setEditText] = useState<string | null>(null);
  // Sync draft mode when the policy mode changes (e.g. account switch) so the first
  // keystroke after the switch doesn't snap back to the stale previous account's mode.
  useEffect(() => { setDraftMode(policyMode); }, [policyMode]);
  // A mode choice is interaction state only while this field pair has an active draft. After
  // discard/save or an account switch, derive from that account's persisted policy immediately;
  // this avoids a stale selector without an effect-driven synchronization render.
  const mode = moneyTouched || pctTouched ? draftMode : policyMode;
  const activeDef = mode === "money" ? moneyDef : pctDef;
  const activeValue = mode === "money" ? moneyValue : pctValue;
  const touched = moneyTouched || pctTouched;
  const display = isBlank(activeValue) ? "" : String(activeValue);
  const unit = mode === "money" ? "$" : "%";

  const setMode = (next: "money" | "pct") => {
    setDraftMode(next);
    setEditText(null);
    if (next === "money") {
      draft.set(pctDef.path, null);
      if (!(moneyDef.path in draft.values)) draft.set(moneyDef.path, isBlank(moneyValue) ? null : moneyValue);
    } else {
      draft.set(moneyDef.path, null);
      if (!(pctDef.path in draft.values)) draft.set(pctDef.path, isBlank(pctValue) ? null : pctValue);
    }
  };

  return (
    <div className="py-2">
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <div className="text-[length:var(--con-fs-sm)] font-semibold">
            {label}
            {touched && <span className="ml-2 text-[length:var(--con-fs-xs)] text-[color:var(--con-warn)]">edited</span>}
          </div>
          {hint && <p className="mt-0.5 max-w-xl text-[length:var(--con-fs-xs)] leading-snug text-[color:var(--con-faint)]">{hint}</p>}
        </div>
        <div className="flex min-w-[18rem] flex-wrap items-center justify-end gap-2">
          <Segmented
            value={mode}
            onChange={setMode}
            ariaLabel={`${label} mode`}
            options={[
              { value: "money", label: "Dollar", title: moneyDef.hint ?? `Use a dollar cap for ${label}.` },
              { value: "pct", label: "Percent", title: pctDef.hint ?? `Use a portfolio percentage cap for ${label}.` }
            ]}
          />
          <div className="flex w-36 items-center gap-1.5">
            {unit === "$" && <span className="text-[color:var(--con-faint)]">$</span>}
            <NumInput
              id={`pf-${activeDef.path}`}
              value={editText ?? display}
              placeholder="off"
              onFocus={() => setEditText(display)}
              onBlur={() => setEditText(null)}
              onChange={(e) => {
                const raw = e.target.value;
                setEditText(raw);
                const parsed = Number(raw);
                draft.set(activeDef.path, raw === "" || !Number.isFinite(parsed) ? null : parsed);
                draft.set(mode === "money" ? pctDef.path : moneyDef.path, null);
              }}
              title={activeDef.hint}
            />
            {unit === "%" && <span className="text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">%</span>}
          </div>
        </div>
      </div>
    </div>
  );
}

// ── Save bar + review sheet ──────────────────────────────────────────────────

function DirectionTag({ direction }: { direction: DiffEntry["direction"] }) {
  if (direction === "changed") return null;
  const unlocks = direction === "looser";
  const Icon = unlocks ? Unlock : Lock;
  const label = unlocks ? "Unlocks" : "Locks Down";
  const title = unlocks
    ? "Raises a cap, removes a protection, broadens the universe, or otherwise expands trading authority."
    : "Adds a protection, lowers a cap, narrows the universe, or otherwise restricts trading authority.";
  return (
    <span
      className="inline-flex items-center gap-1 rounded-full border border-current px-1.5 py-0.5 text-[length:var(--con-fs-xs)] font-bold"
      style={{ color: unlocks ? "var(--con-warn)" : "var(--con-pos)" }}
      title={title}
    >
      <Icon size={12} aria-hidden />
      {label}
    </span>
  );
}

export function PolicySaveBar({
  policy,
  draft,
  defs,
  reality,
  extraPatch
}: {
  policy: TradingPolicy;
  draft: PolicyDraft;
  defs: FieldDef[];
  reality: RealityInfo;
  /** Extra body merged into the PUT (e.g. full arrays that aren't diffable). */
  extraPatch?: PolicyPatchBody;
}) {
  const { refresh } = useConsoleData();
  const toast = useToast();
  const [reviewOpen, setReviewOpen] = useState(false);
  const [typed, setTyped] = useState("");
  const [busy, setBusy] = useState(false);

  const diff = useMemo(() => computeDiff(policy, draft.values, defs), [policy, draft, defs]);
  const extraEntries: ExtraDiffEntry[] = useMemo(() => classifyExtraPatch(policy, extraPatch), [policy, extraPatch]);
  const changeCount = diff.length + extraEntries.length;
  // Register the uncommitted draft with the shell's unsaved-changes guard (beforeunload + nav
  // interception). The onReview opener powers the nav prompt's "Review & save" option. Must run
  // before the early return.
  useUnsavedChanges(changeCount > 0, () => setReviewOpen(true));
  if (changeCount === 0) return null;

  // extraPatch changes (universe, blocklist, order types, sell-to-fund-buy) can
  // loosen the cage too — they must cost the typed word on brokerage accounts like any field.
  const hasLooser = diff.some((d) => d.direction === "looser") || extraEntries.some((e) => e.direction === "looser");
  // Loosening a guardrail on a live account normally costs a typed word; the owner can turn that off
  // in Settings → Advanced action confirmation (policy.requireTypedConfirmation).
  const needsTyped = reality.tone === "live" && hasLooser && policy.requireTypedConfirmation !== false;

  const commit = async () => {
    setBusy(true);
    try {
      await savePolicy(
        { ...buildPatch(diff, policy), ...(extraPatch ?? {}) },
        policy.connectedAccountId
      );
      await refresh();
      draft.clear();
      setReviewOpen(false);
      setTyped("");
      toast.push("pos", "Guardrails updated", "Takes effect from the next policy-gate evaluation.");
    } catch (error) {
      toast.push("neg", "Save refused", error instanceof ConsoleApiError ? error.message : String(error));
    } finally {
      setBusy(false);
    }
  };

  return (
    <>
      <div className="sticky bottom-16 z-40 lg:bottom-4">
        <div className="con-card flex items-center justify-between gap-3 border-[color:var(--con-warn)] px-4 py-2.5">
          <span className="text-[length:var(--con-fs-sm)] font-semibold">
            {changeCount} uncommitted {changeCount === 1 ? "change" : "changes"}
          </span>
          <div className="flex gap-2">
            <Btn variant="ghost" size="sm" onClick={() => draft.clear()}>
              Discard
            </Btn>
            <Btn variant="primary" size="sm" onClick={() => setReviewOpen(true)}>
              Review &amp; save
            </Btn>
          </div>
        </div>
      </div>

      <Sheet open={reviewOpen} onClose={() => setReviewOpen(false)} title="Review changes" tone={needsTyped ? "live" : undefined}>
        <div className="mb-3 flex items-center gap-2 text-[length:var(--con-fs-sm)]">
          <Chip tone={reality.tone}>
            {reality.word} · {reality.phrase}
          </Chip>
          <span className="text-[color:var(--con-muted)]">Changes apply to this account only.</span>
        </div>
        <div className="flex flex-col divide-y divide-[color:var(--con-line)]">
          {diff.map((d) => (
            <div key={d.def.path} className="flex items-center justify-between gap-3 py-2 text-[length:var(--con-fs-sm)]">
              <span className="font-semibold">{d.def.label}</span>
              <span className="con-num flex items-center gap-2">
                <span className="text-[color:var(--con-faint)]">{fmtValue(d.def, d.from)}</span>
                <span className="text-[color:var(--con-faint)]">→</span>
                <span>{fmtValue(d.def, d.to)}</span>
                <DirectionTag direction={d.direction} />
              </span>
            </div>
          ))}
          {extraEntries.map((entry) => (
            <div key={entry.key} className="flex items-center justify-between gap-3 py-2 text-[length:var(--con-fs-sm)]">
              <span className="font-semibold">{entry.label}</span>
              <span className="flex min-w-0 items-center gap-2">
                <span className="truncate text-[color:var(--con-faint)]">{entry.summary}</span>
                <DirectionTag direction={entry.direction} />
              </span>
            </div>
          ))}
        </div>

        {needsTyped ? (
          <TypedConfirm
            phrase="CONFIRM"
            value={typed}
            onChange={setTyped}
            busy={busy}
            variant="primary"
            confirmLabel={
              <>
                Commit changes <LiveTag />
              </>
            }
            note="At least one change expands authority on a brokerage account. Unlocking authority costs a typed word; locking things down never does."
            onConfirm={() => void commit()}
          />
        ) : (
          <div className="mt-4 flex justify-end gap-2">
            <Btn variant="ghost" onClick={() => setReviewOpen(false)} disabled={busy}>
              Cancel
            </Btn>
            <Btn variant="primary" onClick={() => void commit()} disabled={busy}>
              {busy ? "Saving…" : "Commit changes"}
            </Btn>
          </div>
        )}
      </Sheet>
    </>
  );
}

// ── Section wrapper ──────────────────────────────────────────────────────────

export function AdvancedGroup({ title, children, defaultOpen }: { title: string; children: ReactNode; defaultOpen?: boolean }) {
  return (
    <details className="con-disclosure border-t border-[color:var(--con-line)]" open={defaultOpen}>
      <summary>{title}</summary>
      <div className="pb-3">{children}</div>
    </details>
  );
}

"use client";

/** Positions table with a per-position protection column derived honestly
 *  from the snapshot (resting broker stop order, app-managed stop rule, or
 *  "—" when nothing protects). Money in tabular numerals; missing = "—". */

import type { DashboardSnapshot } from "../../dashboard-types";
import type { OptionPosition } from "@/lib/types";
import { deriveProtection } from "../lib/derive";
import { fmtMoney, fmtPct, fmtQty, EM_DASH } from "../lib/format";
import { Card, Dash, Empty, SignedText } from "../ui/primitives";
import { SymbolButton } from "../ui/symbol-drilldown";

/** Concentration cue for a position's weight vs. policy.maxSymbolExposurePct.
 *  Text-first (the label always names "over cap"), color only reinforces —
 *  a colorblind or screen-reader user still gets the same information. */
interface ExposureCue {
  tone?: "warn" | "neg";
  label?: string;
  title?: string;
}

function exposureCue(weightPct: number | undefined, capPct: number | undefined): ExposureCue {
  if (weightPct === undefined || !capPct || capPct <= 0 || weightPct <= capPct) return {};
  const ratio = weightPct / capPct;
  const grossly = ratio >= 1.5;
  return {
    tone: grossly ? "neg" : "warn",
    label: grossly ? "well over cap" : "over cap",
    title: `${fmtPct(weightPct, 1)} of account value exceeds the ${capPct}% max-single-symbol exposure cap (${ratio.toFixed(1)}x).`
  };
}

export function PositionsCard({ snapshot }: { snapshot: DashboardSnapshot }) {
  const positions = snapshot.positions ?? [];
  const equity = snapshot.portfolio?.totalMarketValue;
  const exposureCap = snapshot.policy.maxSymbolExposurePct;

  // Computed once per position and shared by both the ≥lg table and the
  // <lg card list below, so the two layouts can never drift out of sync.
  const rows = positions.map((p) => {
    const short = p.quantity < 0;
    const costBasis = p.averageCost * p.quantity;
    const unrealized =
      Number.isFinite(p.marketValue) && Number.isFinite(costBasis) ? p.marketValue - costBasis : undefined;
    const unrealizedPct =
      unrealized !== undefined && costBasis !== 0 ? (unrealized / Math.abs(costBasis)) * 100 : undefined;
    const weightPct = equity && equity !== 0 ? (p.marketValue / equity) * 100 : undefined;
    const protection = deriveProtection(p, snapshot.orders ?? [], snapshot.policy, snapshot.stopPlanBySymbol?.[p.symbol]);
    const meta = snapshot.symbolMetaBySymbol?.[p.symbol];
    const exposure = exposureCue(weightPct, exposureCap);
    return { p, short, unrealized, unrealizedPct, weightPct, protection, meta, exposure };
  });

  return (
    <>
      <Card title={`Positions (${positions.length})`} padded={false}>
        {positions.length === 0 ? (
        <Empty>No open positions in this account.</Empty>
      ) : (
        <>
          <div className="hidden overflow-x-auto lg:block">
            <table className="con-table">
              <thead>
                <tr>
                  <th title="Ticker — click a symbol to open its price history and details.">Symbol</th>
                  <th className="num" title="Shares held; negative means a short position.">Qty</th>
                  <th className="num" title="Average price paid per share.">Avg cost</th>
                  <th className="num" title="Current market value of the position.">Value</th>
                  <th className="num" title="Share of the account's total market value currently tied to this position.">Weight</th>
                  <th className="num" title="Market value minus cost basis — the gain or loss if you closed now.">Unrealized</th>
                  <th title="What protects this position: a resting broker stop order, an app-managed stop rule, or nothing (—).">Protection</th>
                </tr>
              </thead>
              <tbody>
                {rows.map(({ p, short, unrealized, unrealizedPct, weightPct, protection, meta, exposure }) => (
                  <tr key={p.symbol}>
                    <td>
                      <SymbolButton symbol={p.symbol} />
                      {short && (
                        <span className="ml-1.5 text-[length:var(--con-fs-xs)] font-semibold text-[color:var(--con-warn)]">SHORT</span>
                      )}
                      {meta?.companyName && (
                        <span className="block max-w-44 truncate pl-[26px] text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">
                          {meta.companyName}
                        </span>
                      )}
                    </td>
                    <td className="num con-num">{fmtQty(p.quantity)}</td>
                    <td className="num con-num">{fmtMoney(p.averageCost)}</td>
                    <td className="num con-num">{fmtMoney(p.marketValue)}</td>
                    <td className="num con-num" title={exposure.title}>
                      {weightPct === undefined ? (
                        <Dash />
                      ) : (
                        <span style={exposure.tone ? { color: exposure.tone === "neg" ? "var(--con-neg)" : "var(--con-warn)" } : undefined}>
                          {fmtPct(weightPct, 1, true)}
                          {exposure.label && (
                            <span className="ml-1 text-[length:var(--con-fs-xs)] font-semibold">({exposure.label})</span>
                          )}
                        </span>
                      )}
                    </td>
                    <td className="num">
                      {unrealized === undefined ? (
                        <Dash />
                      ) : (
                        <SignedText value={unrealized}>
                          {`${unrealized > 0 ? "+" : ""}${fmtMoney(unrealized)}`}
                          {unrealizedPct !== undefined ? ` (${fmtPct(unrealizedPct, 1, true)})` : ""}
                        </SignedText>
                      )}
                    </td>
                    <td title={protection.detail}>
                      {protection.label === null ? (
                        <span className="text-[color:var(--con-faint)]">{EM_DASH}</span>
                      ) : (
                        <span
                          className="text-[length:var(--con-fs-xs)] font-semibold"
                          style={{ color: protection.tone === "warn" ? "var(--con-warn)" : protection.tone === "pos" ? "var(--con-pos)" : "var(--con-muted)" }}
                        >
                          {protection.label}
                        </span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* <lg: the table's horizontal scroll isn't a good hand-held experience —
              one card per position instead, same fields plus the same honest
              protection/exposure cues. */}
          <div className="flex flex-col divide-y divide-[color:var(--con-line)] lg:hidden">
            {rows.map(({ p, short, unrealized, unrealizedPct, weightPct, protection, meta, exposure }) => (
              <div key={p.symbol} className="flex flex-col gap-2 px-4 py-3 text-[length:var(--con-fs-sm)]">
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <div className="flex items-center gap-1.5">
                      <SymbolButton symbol={p.symbol} />
                      {short && <span className="text-[length:var(--con-fs-xs)] font-semibold text-[color:var(--con-warn)]">SHORT</span>}
                    </div>
                    {meta?.companyName && (
                      <div className="mt-0.5 max-w-48 truncate text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">
                        {meta.companyName}
                      </div>
                    )}
                  </div>
                  {weightPct !== undefined && (
                    <span
                      className="con-num shrink-0 text-right font-semibold"
                      style={exposure.tone ? { color: exposure.tone === "neg" ? "var(--con-neg)" : "var(--con-warn)" } : undefined}
                      title={exposure.title}
                    >
                      {fmtPct(weightPct, 1, true)}
                      {exposure.label && <span className="block text-[length:var(--con-fs-xs)]">{exposure.label}</span>}
                    </span>
                  )}
                </div>
                <div className="con-num grid grid-cols-2 gap-x-3 gap-y-1.5">
                  <div>
                    <div className="text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">Qty</div>
                    <div>{fmtQty(p.quantity)}</div>
                  </div>
                  <div className="text-right">
                    <div className="text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">Value</div>
                    <div>{fmtMoney(p.marketValue)}</div>
                  </div>
                  <div>
                    <div className="text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">P&amp;L</div>
                    <div>
                      {unrealized === undefined ? (
                        <Dash />
                      ) : (
                        <SignedText value={unrealized}>
                          {`${unrealized > 0 ? "+" : ""}${fmtMoney(unrealized)}`}
                          {unrealizedPct !== undefined ? ` (${fmtPct(unrealizedPct, 1, true)})` : ""}
                        </SignedText>
                      )}
                    </div>
                  </div>
                  <div className="text-right" title={protection.detail}>
                    <div className="text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">Protection</div>
                    <div>
                      {protection.label === null ? (
                        <span className="text-[color:var(--con-faint)]">{EM_DASH}</span>
                      ) : (
                        <span
                          className="text-[length:var(--con-fs-xs)] font-semibold"
                          style={{ color: protection.tone === "warn" ? "var(--con-warn)" : protection.tone === "pos" ? "var(--con-pos)" : "var(--con-muted)" }}
                        >
                          {protection.label}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </>
      )}
    </Card>
    {snapshot.options && snapshot.options.length > 0 && (
      <Card title="Unmanaged Options (no automated exit protection)" padded={false} className="mt-4">
        <div className="hidden overflow-x-auto lg:block">
          <table className="con-table">
            <thead>
              <tr>
                <th title="OCC option symbol.">Symbol</th>
                <th title="Underlying symbol.">Underlying</th>
                <th title="Option type (Call/Put) and strike price.">Strike / Type</th>
                <th title="Expiration date.">Expiration</th>
                <th className="num" title="Number of contracts held; negative means short/written.">Qty</th>
                <th className="num" title="Average price paid per contract (not multiplier-adjusted).">Avg cost</th>
                <th className="num" title="Current market value of the option position (multiplier-adjusted).">Value</th>
                <th className="num" title="Gain or loss if closed now.">Unrealized P&amp;L</th>
              </tr>
            </thead>
            <tbody>
              {snapshot.options.map((opt) => {
                const qty = opt.quantity;
                const costBasis = opt.averageCost * qty * 100;
                const unrealized = opt.marketValue - costBasis;
                const unrealizedPct = costBasis !== 0 ? (unrealized / Math.abs(costBasis)) * 100 : undefined;

                return (
                  <tr key={opt.symbol}>
                    <td className="font-mono text-xs">{opt.symbol}</td>
                    <td>
                      <SymbolButton symbol={opt.underlyingSymbol} />
                    </td>
                    <td>
                      <span className="font-semibold">${opt.strikePrice}</span>{" "}
                      <span className={opt.optionType === "call" ? "text-indigo-400" : "text-pink-400"}>
                        {opt.optionType.toUpperCase()}
                      </span>
                    </td>
                    <td>{opt.expirationDate}</td>
                    <td className="num con-num">{fmtQty(qty)}</td>
                    <td className="num con-num">{fmtMoney(opt.averageCost)}</td>
                    <td className="num con-num">{fmtMoney(opt.marketValue)}</td>
                    <td className="num">
                      <SignedText value={unrealized}>
                        {`${unrealized > 0 ? "+" : ""}${fmtMoney(unrealized)}`}
                        {unrealizedPct !== undefined ? ` (${fmtPct(unrealizedPct, 1, true)})` : ""}
                      </SignedText>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        <div className="flex flex-col divide-y divide-[color:var(--con-line)] lg:hidden">
          {snapshot.options.map((opt) => {
            const qty = opt.quantity;
            const short = qty < 0;
            const costBasis = opt.averageCost * qty * 100;
            const unrealized = opt.marketValue - costBasis;
            const unrealizedPct = costBasis !== 0 ? (unrealized / Math.abs(costBasis)) * 100 : undefined;

            return (
              <div key={opt.symbol} className="flex flex-col gap-2 px-4 py-3 text-[length:var(--con-fs-sm)]">
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <div className="flex items-center gap-1.5">
                      <span className="font-mono text-xs">{opt.symbol}</span>
                      {short && <span className="text-[length:var(--con-fs-xs)] font-semibold text-[color:var(--con-warn)]">SHORT</span>}
                    </div>
                    <div className="mt-0.5 text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)] flex items-center gap-1">
                      <span>Underlying:</span>
                      <SymbolButton symbol={opt.underlyingSymbol} />
                      <span>| Strike: ${opt.strikePrice} | {opt.optionType.toUpperCase()} | Exp: {opt.expirationDate}</span>
                    </div>
                  </div>
                </div>
                <div className="con-num grid grid-cols-2 gap-x-3 gap-y-1.5">
                  <div>
                    <div className="text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">Qty (Contracts)</div>
                    <div>{fmtQty(qty)}</div>
                  </div>
                  <div className="text-right">
                    <div className="text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">Value</div>
                    <div>{fmtMoney(opt.marketValue)}</div>
                  </div>
                  <div>
                    <div className="text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">Avg Cost</div>
                    <div>{fmtMoney(opt.averageCost)}</div>
                  </div>
                  <div className="text-right">
                    <div className="text-[length:var(--con-fs-xs)] text-[color:var(--con-faint)]">P&amp;L</div>
                    <div>
                      <SignedText value={unrealized}>
                        {`${unrealized > 0 ? "+" : ""}${fmtMoney(unrealized)}`}
                        {unrealizedPct !== undefined ? ` (${fmtPct(unrealizedPct, 1, true)})` : ""}
                      </SignedText>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </Card>
    )}
  </>
);
}

