  href?: string;
  title?: string;
  confidence?: number;
  /** ISO timestamp of the decision/proposal — rendered top-right as a relative
   *  "15m ago" (like Journal entries); absent for rows with no known time. */
  at?: string;
};

type EvidenceRow = {
  title: string;
  meta: string;
  metaTitle?: string;
  body: string;
