import fs from "fs";
import path from "path";
import { getDb } from "../../src/lib/db";
import { loadCikMap, loadTickerCikMap } from "../../src/lib/web-sources/sec8k";
import { SP500_SYMBOLS } from "../../src/lib/sp500";
import { NASDAQ100_SYMBOLS, DOW30_SYMBOLS } from "../../src/lib/index-universes";
import { normalizeSymbol } from "../../src/lib/money";

interface UniverseEntry {
  cik: string;
  ticker: string;
  title: string;
  inclusionReason: string;
  /** Alternative tickers for the same CIK (e.g. GOOG/GOOGL for Alphabet). */
  aliases?: string[];
}

async function fetchSecTickerList(): Promise<Array<{ cik: number; ticker: string; title: string }>> {
  // SEC company_tickers.json is fetched directly to preserve the original ordering (prominence order)
  // because loadCikMap converts it to a key-value record where order is lost.
  const { secUserAgent } = await import("../../src/lib/web-sources/http");
  const { politeFetchText } = await import("../../src/lib/web-sources/http");
  const url = "https://www.sec.gov/files/company_tickers.json";
  console.log(`  Fetching company tickers from SEC: ${url}`);
  const text = await politeFetchText(url, { headers: { "user-agent": secUserAgent() } });
  const data = JSON.parse(text) as Record<string, { cik_str: number; ticker: string; title: string }>;
  return Object.values(data).map(row => ({
    cik: row.cik_str,
    ticker: row.ticker,
    title: row.title
  }));
}

async function main() {
  console.log("\n▶ SEC/RAG 1,000-Stock Universe Manifest Generator");

  const now = Date.now();

  // 1. Load active/traded symbols from DB history
  const db = getDb();
  const fillSymbols = db.prepare("SELECT DISTINCT symbol FROM fill_events").all() as Array<{ symbol: string }>;
  const chunkSymbols = db.prepare("SELECT DISTINCT symbol FROM document_chunks").all() as Array<{ symbol: string }>;
  const watchlistSymbols = db.prepare("SELECT DISTINCT symbol FROM user_watchlist").all() as Array<{ symbol: string }>;
  const skippedSymbols = db.prepare("SELECT DISTINCT symbol FROM skipped_candidate_counterfactuals").all() as Array<{ symbol: string }>;

  const dbSymbols = new Set<string>();
  [fillSymbols, chunkSymbols, watchlistSymbols, skippedSymbols].forEach(list => {
    list.forEach(s => {
      const norm = normalizeSymbol(s.symbol);
      if (norm) dbSymbols.add(norm);
    });
  });
  console.log(`  Found ${dbSymbols.size} unique symbols from local database history (fills/chunks/watchlists/skipped).`);

  // 2. Load index symbols
  const indexSymbols = new Set<string>([
    ...SP500_SYMBOLS,
    ...NASDAQ100_SYMBOLS,
    ...DOW30_SYMBOLS
  ].map(normalizeSymbol).filter(Boolean) as string[]);
  console.log(`  Found ${indexSymbols.size} unique symbols in S&P 500, Nasdaq 100, and Dow 30.`);

  // 3. Fetch full SEC ticker CIK list
  let secList: Array<{ cik: number; ticker: string; title: string }> = [];
  try {
    secList = await fetchSecTickerList();
    console.log(`  Loaded ${secList.length} company tickers from the SEC.`);
  } catch (err) {
    console.error("  ❌ Failed to fetch SEC ticker list:", err);
    process.exit(1);
  }

  // Build direct mapping records
  const secTickerToCik: Record<string, string> = {};
  const secCikToTicker: Record<string, string> = {};
  const secCikToTitle: Record<string, string> = {};

  secList.forEach(row => {
    const normTicker = normalizeSymbol(row.ticker);
    const paddedCik = String(row.cik).padStart(10, "0");
    if (normTicker) {
      secTickerToCik[normTicker] = paddedCik;
      // Keep first matching CIK ticker mapping for reverse lookup, or update if prominent
      if (!secCikToTicker[paddedCik]) {
        secCikToTicker[paddedCik] = normTicker;
      }
      secCikToTitle[paddedCik] = row.title;
    }
  });

  const universe: UniverseEntry[] = [];
  const addedCiks = new Set<string>();
  const addedTickers = new Set<string>();

  const addIssuer = (cik: string, ticker: string, title: string, reason: string) => {
    if (addedCiks.has(cik)) {
      // CIK already exists — track alias ticker for multi-ticker entities (e.g. GOOG/GOOGL)
      if (!addedTickers.has(ticker)) {
        addedTickers.add(ticker);
        const existing = universe.find(e => e.cik === cik);
        if (existing) {
          existing.aliases = existing.aliases ?? [];
          if (!existing.aliases.includes(ticker)) {
            existing.aliases.push(ticker);
          }
        }
      }
      return false;
    }
    if (universe.length >= 1000) return false; // hard cap at 1,000 CIKs
    addedCiks.add(cik);
    addedTickers.add(ticker);
    universe.push({
      cik,
      ticker,
      title,
      inclusionReason: reason,
      aliases: [],
    });
    return true;
  };

  // Tranche 1: Traded database symbols
  console.log("  Processing Tranche 1: DB History...");
  let dbAdded = 0;
  for (const sym of dbSymbols) {
    const cik = secTickerToCik[sym];
    if (cik) {
      const title = secCikToTitle[cik] ?? "";
      // NOTE: we use "top-prominence" here rather than "held-history" so the
      // frozen manifest never leaks which symbols come from the owner's real
      // trade/watch history. The DB is the selection mechanism; the manifest
      // is a neutral reference file tracked in the public repo.
      if (addIssuer(cik, sym, title, "top-prominence")) {
        dbAdded++;
      }
    } else {
      console.log(`  ⚠️  Ticker ${sym} from DB history could not be mapped to an SEC CIK.`);
    }
  }
  console.log(`  Added ${dbAdded} issuers from DB history.`);

  // Tranche 2: Index symbols
  console.log("  Processing Tranche 2: Index Members...");
  let indexAdded = 0;
  for (const sym of indexSymbols) {
    const cik = secTickerToCik[sym];
    if (cik) {
      const title = secCikToTitle[cik] ?? "";
      if (addIssuer(cik, sym, title, "index-member")) {
        indexAdded++;
      }
    }
  }
  console.log(`  Added ${indexAdded} new issuers from index memberships.`);

  // Tranche 3: Top prominent SEC companies by original listing order
  console.log("  Processing Tranche 3: Filling up to 1,000 using top market-cap SEC listings...");
  let secAdded = 0;
  for (const row of secList) {
    if (universe.length >= 1000) break;
    const normTicker = normalizeSymbol(row.ticker);
    const paddedCik = String(row.cik).padStart(10, "0");
    if (normTicker) {
      if (addIssuer(paddedCik, normTicker, row.title, "top-prominence")) {
        secAdded++;
      }
    }
  }

  console.log(`  Added ${secAdded} new issuers from top SEC listings.`);
  console.log(`  Total universe size: ${universe.length} CIKs.`);

  if (universe.length < 1000) {
    console.warn(`  ⚠️  Warning: Managed to gather only ${universe.length} symbols. Universe is below 1,000.`);
  }

  // Sort by ticker before writing to avoid leaking DB-derived provenance through insertion order.
  universe.sort((a, b) => a.ticker.localeCompare(b.ticker));

  // 4. Save the manifest
  const destDir = path.dirname(path.resolve("data/rag-universe-manifest.json"));
  if (!fs.existsSync(destDir)) {
    fs.mkdirSync(destDir, { recursive: true });
  }

  const manifestPath = path.resolve("data/rag-universe-manifest.json");
  fs.writeFileSync(manifestPath, JSON.stringify(universe, null, 2), "utf8");
  console.log(`  Manifest frozen successfully! Wrote to: ${manifestPath}`);
  console.log("══ Done ══════════════════════════════════════════════════\n");
}

main().catch(err => {
  console.error("Universe generator crashed:", err);
  process.exit(1);
});

import { pathToFileURL } from "node:url";
import { getDb } from "../../src/lib/db";
import { retrieveFusedContext } from "../../src/lib/rag/search-fusion";

interface GoldenSetItem {
  id: string;
  query: string;
  expected_cik: string;
  expected_accession: string;
  expected_text_snippet: string;
  category: string;
}

export async function runEvaluationHarness() {
  const db = getDb();
  const items = db.prepare("SELECT * FROM sec_eval_golden_set").all() as GoldenSetItem[];

  if (items.length === 0) {
    console.log("Evaluation golden set is empty. Insert records first.");
    return { recallAt10: 0, recallAt50: 0, ndcg: 0, count: 0, skipped: 0 };
  }

  let totalRecallAt10 = 0;
  let totalRecallAt50 = 0;
  let totalNdcg = 0;
  // Metrics must be divided by the number of queries that actually RAN. Rows whose CIK cannot be
  // resolved are skipped and reported separately — counting them in the denominator would deflate
  // global recall/nDCG while the report claims those queries were evaluated.
  let evaluated = 0;
  let skipped = 0;

  const categoryStats: Record<string, { count: number; recallAt10: number; recallAt50: number; ndcg: number }> = {};

  for (const item of items) {
    // Resolve symbol from CIK, check sec_filings first, fall back to sec_ingest_tasks
    let symbol: string | undefined;
    const filingRow = db.prepare("SELECT ticker FROM sec_filings WHERE cik = ? LIMIT 1").get(item.expected_cik) as any;
    if (filingRow?.ticker) {
      symbol = filingRow.ticker;
    } else {
      const taskRow = db.prepare("SELECT symbol FROM sec_ingest_tasks WHERE cik = ? LIMIT 1").get(item.expected_cik) as any;
      if (taskRow?.symbol) {
        symbol = taskRow.symbol;
      }
    }

    if (!symbol) {
      console.warn(`[rag-eval] No symbol found for CIK ${item.expected_cik} (${item.category}: "${item.query.slice(0, 60)}...") — skipping`);
      skipped++;
      continue;
    }
    evaluated++;

    // Retrieve top 50 fused context results
    const results = await retrieveFusedContext(item.query, symbol, 50);

    let rank = -1;
    for (let i = 0; i < results.length; i++) {
      const textMatches = results[i].text.toLowerCase().includes(item.expected_text_snippet.toLowerCase());
      const accMatches = results[i].accession === item.expected_accession;
      if (textMatches && accMatches) {
        rank = i + 1; // 1-indexed rank
        break;
      }
    }

    const recallAt10 = rank > 0 && rank <= 10 ? 1 : 0;
    const recallAt50 = rank > 0 && rank <= 50 ? 1 : 0;
    const ndcg = rank > 0 ? 1 / Math.log2(rank + 1) : 0;

    totalRecallAt10 += recallAt10;
    totalRecallAt50 += recallAt50;
    totalNdcg += ndcg;

    if (!categoryStats[item.category]) {
      categoryStats[item.category] = { count: 0, recallAt10: 0, recallAt50: 0, ndcg: 0 };
    }
    const cat = categoryStats[item.category];
    cat.count++;
    cat.recallAt10 += recallAt10;
    cat.recallAt50 += recallAt50;
    cat.ndcg += ndcg;
  }

  const count = evaluated;
  const metrics = {
    recallAt10: count > 0 ? totalRecallAt10 / count : 0,
    recallAt50: count > 0 ? totalRecallAt50 / count : 0,
    ndcg: count > 0 ? totalNdcg / count : 0,
    count,
    skipped
  };

  console.log("\n================ RAG EVALUATION REPORT ================");
  console.log(`Evaluated ${count} of ${items.length} Golden Set queries (${skipped} skipped — unresolved CIK):\n`);
  console.log(`Global Recall@10: ${(metrics.recallAt10 * 100).toFixed(2)}%`);
  console.log(`Global Recall@50: ${(metrics.recallAt50 * 100).toFixed(2)}%`);
  console.log(`Global nDCG:      ${metrics.ndcg.toFixed(4)}\n`);

  console.log("Category Breakdown:");
  console.log("-------------------------------------------------------");
  console.log("Category        | Count | Recall@10 | Recall@50 | nDCG");
  console.log("-------------------------------------------------------");
  for (const [name, stats] of Object.entries(categoryStats)) {
    const c = stats.count;
    console.log(
      `${name.padEnd(15)} | ${String(c).padEnd(5)} | ${(stats.recallAt10 / c * 100).toFixed(1).padStart(8)}% | ${(stats.recallAt50 / c * 100).toFixed(1).padStart(8)}% | ${(stats.ndcg / c).toFixed(4).padStart(6)}`
    );
  }
  console.log("=======================================================\n");

  return metrics;
}

// ESM-safe direct-run guard: this repo is `type: module`, so `require` is undefined when the
// script runs under `tsx`/node as an ES module. Compare the module URL against the invoked
// script path instead; under vitest (which imports this module) argv[1] is the runner, not us.
const invokedDirectly = (() => {
  try {
    return Boolean(process.argv[1]) && import.meta.url === pathToFileURL(process.argv[1]).href;
  } catch {
    return false;
  }
})();

if (invokedDirectly) {
  runEvaluationHarness().catch(err => {
    console.error("Evaluation harness failed:", err);
    process.exit(1);
  });
}

#!/usr/bin/env tsx

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import {
  buildCongressScoreObservations,
  congressScoreObservationsFromExportRows,
  evaluateCongressScore,
  type CongressScoreObservation
} from "../../src/lib/congress-score-eval";

interface Args {
  input?: string;
  userId: string;
  horizonDays: number;
  auditLimit: number;
  quantiles: number;
  minNamesPerDate: number;
  minObservations: number;
  minDates: number;
  minTickers: number;
  minTopBucketObservations: number;
  requireBenchmarkReturn: boolean;
  placeboSeed?: number;
}

class CongressExportNotReadyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CongressExportNotReadyError";
  }
}

async function main(): Promise<void> {
  const args = parseArgs(process.argv.slice(2));
  const observations = args.input
    ? readExport(resolve(args.input), args.horizonDays)
    : await buildCongressScoreObservations(args.userId, {
        horizonDays: args.horizonDays,
        auditLimit: args.auditLimit
      });
  const result = evaluateCongressScore(observations, {
    quantiles: args.quantiles,
    minNamesPerDate: args.minNamesPerDate,
    minObservations: args.minObservations,
    minDates: args.minDates,
    minTickers: args.minTickers,
    minTopBucketObservations: args.minTopBucketObservations,
    requireBenchmarkReturn: args.requireBenchmarkReturn,
    placeboSeed: args.placeboSeed
  });
  console.log(JSON.stringify(result, null, 2));
  if (!result.goNoGo.pass) process.exitCode = 2;
}

function parseArgs(argv: string[]): Args {
  const args: Args = {
    userId: "local",
    horizonDays: 63,
    auditLimit: 1000,
    quantiles: 5,
    minNamesPerDate: 10,
    minObservations: 500,
    minDates: 60,
    minTickers: 50,
    minTopBucketObservations: 100,
    requireBenchmarkReturn: true,
    placeboSeed: 17
  };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    const next = argv[i + 1];
    if (arg === "--input" && next) args.input = next, i++;
    else if (arg === "--user" && next) args.userId = next, i++;
    else if (arg === "--horizon-days" && next) args.horizonDays = numberArg(next, args.horizonDays), i++;
    else if (arg === "--audit-limit" && next) args.auditLimit = numberArg(next, args.auditLimit), i++;
    else if (arg === "--quantiles" && next) args.quantiles = numberArg(next, args.quantiles), i++;
    else if (arg === "--min-names-per-date" && next) args.minNamesPerDate = numberArg(next, args.minNamesPerDate), i++;
    else if (arg === "--min-observations" && next) args.minObservations = numberArg(next, args.minObservations), i++;
    else if (arg === "--min-dates" && next) args.minDates = numberArg(next, args.minDates), i++;
    else if (arg === "--min-tickers" && next) args.minTickers = numberArg(next, args.minTickers), i++;
    else if (arg === "--min-top-bucket-observations" && next) args.minTopBucketObservations = numberArg(next, args.minTopBucketObservations), i++;
    else if (arg === "--allow-raw-returns") args.requireBenchmarkReturn = false;
    else if (arg === "--placebo-seed" && next) args.placeboSeed = numberArg(next, args.placeboSeed ?? 17), i++;
    else if (arg === "--no-placebo") args.placeboSeed = undefined;
    else if (arg === "--help" || arg === "-h") {
      printHelp();
      process.exit(0);
    }
  }
  return args;
}

function readExport(path: string, horizonDays: number): CongressScoreObservation[] {
  const text = readFileSync(path, "utf8").trim();
  if (!text) return [];
  const parsed = text.startsWith("[") || text.startsWith("{")
    ? JSON.parse(text)
    : text.split(/\r?\n/).filter(Boolean).map((line) => JSON.parse(line));
  assertExportValidationReady(parsed);
  const rows = Array.isArray(parsed) ? parsed : parsed.rows ?? parsed.observations ?? [];
  if (!Array.isArray(rows)) throw new Error("Expected a JSON array, JSONL rows, or { rows: [...] }.");
  return congressScoreObservationsFromExportRows(rows, { horizonDays });
}

function assertExportValidationReady(parsed: unknown): void {
  if (!parsed || Array.isArray(parsed) || typeof parsed !== "object") return;
  const readiness = (parsed as { validationReadiness?: unknown }).validationReadiness;
  if (!readiness || typeof readiness !== "object") return;
  const r = readiness as Record<string, unknown>;
  if (r.historicalValidationReady !== false) return;
  throw new CongressExportNotReadyError(
    [
      "Congress.Trade export is not historical-validation ready.",
      "validationReadiness.historicalValidationReady=false.",
      summarizeReadinessReason(r)
    ].filter(Boolean).join(" ")
  );
}

function summarizeReadinessReason(readiness: Record<string, unknown>): string {
  const values: string[] = [];
  for (const key of ["reason", "reasons", "blocker", "blockers", "missing", "notes"]) {
    const value = readiness[key];
    if (typeof value === "string" && value.trim()) values.push(value.trim());
    else if (Array.isArray(value)) values.push(...value.filter((item): item is string => typeof item === "string" && item.trim().length > 0).map((item) => item.trim()));
  }
  return values.length ? `Reason(s): ${values.join("; ")}` : "";
}

function numberArg(value: string, fallback: number): number {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function printHelp(): void {
  console.log(`Usage:
  npm run eval:congress-score
  npm run eval:congress-score -- --input congress-score-export.jsonl

Options:
  --input <file>              JSON/JSONL export from Congress.Trade. Omit to use signal_snapshot.
  --user <id>                 User id for signal_snapshot mode. Default: local
  --horizon-days <n>          Forward-return horizon for signal_snapshot mode. Default: 63
  --audit-limit <n>           Max signal_snapshot audit rows. Default: 1000
  --quantiles <n>             Quantile bucket count. Default: 5
  --min-names-per-date <n>    Minimum cross-section size for rank IC. Default: 10
  --min-observations <n>      Minimum total observations for go/no-go. Default: 500
  --min-dates <n>             Minimum contributing dates for go/no-go. Default: 60
  --min-tickers <n>           Minimum distinct tickers for go/no-go. Default: 50
  --min-top-bucket-observations <n> Minimum top-bucket rows. Default: 100
  --allow-raw-returns         Do not require benchmarkReturn/spxReturn in input rows
  --placebo-seed <n>          Deterministic per-date score rotation seed. Default: 17
  --no-placebo                Skip placebo rotation

Input rows may be flat rows with date/asOf, symbol/ticker, congressScore/compositeScore, forwardReturn,
and benchmarkReturn/spxReturn, or App A PIT rows from /api/export/congress-pit-scores with labels.horizons[].
Optional: congressSignedScore/signedScore, congressDirection/direction, and preCongressScore.
If a Congress.Trade export envelope sets validationReadiness.historicalValidationReady=false, the
command refuses to evaluate it and exits 2.
`);
}

main().catch((error) => {
  if (error instanceof CongressExportNotReadyError) {
    console.error(error.message);
    process.exit(2);
  }
  console.error(error instanceof Error ? error.stack ?? error.message : String(error));
  process.exit(1);
});

import { Project, SyntaxKind } from "ts-morph";
