/**
 * Fill in a usable price for any symbol the broker didn't quote (>0). Alpaca's latest-quote feed
 * returns 0/empty bid-ask outside market hours and on the free IEX tier, which used to leave the chat
 * with no price and the pre-trade review with a MAX_SAFE_INTEGER "can't size it" sentinel (so even a
 * 0.5-share order tripped every cap). A recent daily close (keyless Yahoo, works anytime) is a fine
 * sizing/notional anchor and lets the assistant answer price questions. Exported for testing.
 */
export async function fillMissingQuotesWithClose(
  quotes: Record<string, BrokerQuote>,
  symbols: string[],
  getFallback: (symbol: string) => Promise<{ price: number; asOf?: string } | undefined>
): Promise<Record<string, BrokerQuote>> {
  const missing = symbols.filter((s) => {
    const q = quotes[s];
    return !(q && typeof q.price === "number" && q.price > 0);
  });
  await Promise.all(
    missing.map(async (symbol) => {
      const fb = await getFallback(symbol).catch(() => undefined);
      if (fb && Number.isFinite(fb.price) && fb.price > 0) {
        quotes[symbol] = { symbol, price: fb.price, asOf: fb.asOf, provider: "yahoo-finance-delayed" };
      }
    })
  );
  return quotes;
}

export function getAlpacaGateway(userId: string = "local", connectedAccountId?: string): BrokerGateway {
  return new AlpacaBrokerGateway(userId, connectedAccountId);
}

// Re-exported for existing callers/tests that import symbol conversion from this module — the
// canonical definitions now live in ./money alongside normalizeSymbol so data-providers.ts and
// the Alpaca stream workers can share them without importing this (much heavier) gateway module.
export { toAlpacaSymbol, fromAlpacaSymbol };

export function classifyAlpacaAccountType(account: Record<string, unknown>): AccountCapabilities["accountType"] {
  const rawType = String(account.account_type ?? account.accountType ?? "").toLowerCase();
  const rawSubType = String(account.account_sub_type ?? account.account_subtype ?? account.accountSubType ?? "").toLowerCase();
  const combined = `${rawType} ${rawSubType}`;
  if (combined.includes("roth")) return "roth_ira";
  if (combined.includes("traditional") || combined.includes("trad") || combined.includes("ira")) return "traditional_ira";
  return "brokerage";
}

/**
 * Estimate an order's notional for the pre-trade review. NEVER fabricates a price:
 * a wrong notional corrupts the value persisted to `trade_proposals` and the daily
 * cap accounting (a fabricated $100 made a $50k buy count as $10k). Prefers explicit
 * order prices, then the live quote; if none is available and there's no dollar
 * amount, an un-sizable OPENING order is reported as over-cap so it is blocked.
 *
 * Side matters. The over-cap sentinel is ONLY valid for opening orders (buy/short) —
 * for those, "no price" means "can't size it, so don't let it through". For an EXIT
 * (sell/cover) the sentinel is actively harmful: exits are never notional-capped, and a
 * MAX_SAFE_INTEGER value corrupts the persisted/displayed notional AND the gross/net
 * exposure projection (a 1-share sell looked like a ~$9 quadrillion short and tripped the
 * net-exposure cap, blocking a risk-reducing exit). So for exits we fall back to the
 * captured entry anchor (`referencePrice`) and, failing that, report 0 — the exit still
 * executes and exposure caps correctly exempt it.
 */
export function estimateReviewNotional(
  input: { side?: OrderSide; dollarAmount?: number; quantity?: number; limitPrice?: number; stopPrice?: number; referencePrice?: number },
  quotePrice: number | undefined
): { estimatedNotional: number; alerts: string[] } {
  if (input.dollarAmount != null) {
    return { estimatedNotional: input.dollarAmount, alerts: [] };
  }
  const isExit = input.side === "sell" || input.side === "cover";
  // Live quote / explicit order price for either side; for an exit, also fall back to the entry anchor
  // so a missing live quote doesn't corrupt the notional (exits aren't capped, so an approximation is fine).
  const estPrice =
    input.limitPrice ??
    input.stopPrice ??
    (quotePrice && quotePrice > 0 ? quotePrice : undefined) ??
    (isExit && input.referencePrice && input.referencePrice > 0 ? input.referencePrice : undefined);
  if (estPrice != null && estPrice > 0) {
    return { estimatedNotional: (input.quantity ?? 0) * estPrice, alerts: [] };
  }
  if (isExit) {
    // Never use the over-cap sentinel for an exit — exits are exempt from notional caps, and a giant value
    // would corrupt the displayed notional and the net/gross exposure projection. 0 is safe and won't block.
    return {
      estimatedNotional: 0,
      alerts: ["Price unavailable — exit notional could not be estimated; exits are not notional-capped, so this does not block the order."],
    };
  }
  return {
    estimatedNotional: Number.MAX_SAFE_INTEGER,
    alerts: ["Price unavailable — notional could not be estimated; treating as over-cap (set a limit/stop price or dollar amount)."],
  };
}

class AlpacaBrokerGateway implements BrokerGateway {
  // getEquityOrders pages status:"all" (see below), so the returned list authoritatively includes
  // recently-terminal orders (filled/canceled/rejected/expired). This lets reconcilePlacementError
  // conclude not_placed from an absent order for Alpaca (safe: absence really means never placed).
  readonly ordersListIncludesTerminal = true;
  private alpaca: Alpaca;
  private label: string;
  private isMcp: boolean;
  private mcpUrl?: string;
  // Credential lane for health logging: a per-user connected account resolves to "user",
  // the operator env fallback (local only, no stored account) to "env".
  private keySource: string;

  constructor(private userId: string, connectedAccountId?: string) {
    const targeted = connectedAccountId ? getConnectedAccount(connectedAccountId, userId) : undefined;
    const activeAccount = getActiveConnectedAccount(userId);
    const brokerAccount = targeted ?? activeAccount;
    const accountKeys =
      brokerAccount?.broker === "alpaca" || brokerAccount?.broker === "alpaca-mcp"
        ? brokerAccount
        : undefined;
    this.keySource = accountKeys ? "user" : "env";
    this.isMcp = brokerAccount?.broker === "alpaca-mcp";
    this.label = accountKeys?.label || (accountKeys?.environment === "live" ? "Alpaca Brokerage" : "Alpaca Paper");
    // A connected-account key (per-user account data) wins. If an Alpaca account is explicitly
    // selected, never fall back to generic/operator Alpaca keys: those can belong to a different
    // account and surface as a misleading "Account Mismatch" instead of the real credential problem.
    // SECURITY: route through resolveApiKey so the env fallback is operator-only (alpaca keys are
    // a per-user-only tier). A non-`local` user with no stored key gets "" → broker construction
    // fails loudly instead of silently trading on the operator's Alpaca account via process.env.
    const keyId = accountKeys?.apiKey?.trim() || (!accountKeys ? resolveApiKey("alpaca_paper_api_key", userId) || "" : "");
    const secretKey = accountKeys?.apiSecret?.trim() || (!accountKeys ? resolveApiKey("alpaca_paper_secret_key", userId) || "" : "");

    let baseUrl = accountKeys?.baseUrl?.trim();
    if (this.isMcp) {
      this.mcpUrl = baseUrl || undefined;
    }

    if (accountKeys && !this.isMcp && !keyId) {
      throw new Error(
        `Alpaca credentials are missing for ${this.label}. Open Connections and re-save the API key.`
      );
    }
    if (accountKeys && this.isMcp && !this.mcpUrl && !keyId) {
      throw new Error(
        `Alpaca MCP credentials are missing for ${this.label}. Open Connections and re-save the MCP endpoint or API key.`
      );
    }

    if (baseUrl && !this.isMcp) {
      baseUrl = baseUrl.replace(/\/+$/, "");
      if (baseUrl.toLowerCase().endsWith("/v2")) {
        baseUrl = baseUrl.slice(0, -3);
      }
    }

    const options: any = {
      paper: accountKeys?.environment !== "live",
      usePolygon: false
    };

    if (keyId && !secretKey) {
      options.oauth = keyId;
    } else {
      options.keyId = keyId;
      options.secretKey = secretKey;
    }

    if (baseUrl && !this.isMcp) {
      options.baseUrl = baseUrl;
    }

    this.alpaca = new Alpaca(options);
  }

  // Wrap a raw Alpaca SDK call so the admin connections-health page can show whether the
  // broker gateway itself is reachable ("alpaca-broker"), distinct from the market-data
  // enrichment services. logApiHealth already swallows its own errors, but the timing/log
  // is still wrapped so a health-logging failure can never affect the real broker call.
  // The Alpaca SDK ships no types, so this.alpaca.* calls are already `any`; a constrained
  // generic here would collapse those returns to `unknown` at every call site.
  private async trackHealth(fn: () => Promise<any>): Promise<any> {
    const start = Date.now();
    try {
      const result = await fn();
      logApiHealth({ service: "alpaca-broker", ok: true, latencyMs: Date.now() - start, keySource: this.keySource, userId: this.userId });
      recordProviderCall("alpaca", { service: "broker", ok: true });
      return result;
    } catch (err) {
      logApiHealth({
        service: "alpaca-broker",
        ok: false,
        latencyMs: Date.now() - start,
        errorText: err instanceof Error ? err.message : String(err),
        keySource: this.keySource,
        userId: this.userId
      });
      recordProviderCall("alpaca", { service: "broker", ok: false });
      throw err;
    }
  }

  private async callMcp<T>(toolName: string, args: Record<string, unknown>, fallbackFn: () => Promise<T>): Promise<T> {
    if (!this.isMcp || !this.mcpUrl) {
      return fallbackFn();
    }
    try {
      const response = await fetch(this.mcpUrl, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          accept: "application/json"
        },
        body: JSON.stringify({
          jsonrpc: "2.0",
          id: crypto.randomUUID(),
          method: "tools/call",
          params: {
            name: toolName,
            arguments: args
          }
        })
      });
      if (!response.ok) {
        throw new Error(`Alpaca MCP HTTP ${response.status}`);
      }
      const body = await response.json();
      if (body.error) {
        throw new Error(body.error.message || JSON.stringify(body.error));
      }
      const content = body.result?.content;
      if (Array.isArray(content) && content[0]?.type === "text") {
        try {
          return JSON.parse(content[0].text);
        } catch {
          return content[0].text;
        }
      }
      return body.result;
    } catch (e) {
      console.warn(`Alpaca MCP tool call "${toolName}" failed, falling back to REST:`, e);
      return fallbackFn();
    }
  }


  async getAccounts(): Promise<BrokerageAccount[]> {
    const getCapabilities = (acc: any): AccountCapabilities => {
      const shortSelling = Boolean(acc.shorting_enabled);
      const rawAccountType = String(acc.account_type ?? "").toUpperCase();
      const accountType = classifyAlpacaAccountType(acc);
      const marginEnabled = accountType === "brokerage" && (shortSelling || rawAccountType === "MARGIN");
      return {
        equityTrading: true,
        shortSelling,
        optionsTrading: false,
        futuresTrading: false,
        cryptoTrading: false,
        marginEnabled,
        accountType
      };
    };

    return this.callMcp<any>("get_account_info", {}, async () => {
      const account = await this.trackHealth(() => this.alpaca.getAccount());
      return [
        {
          accountNumber: account.account_number,
          label: this.label,
          agenticAllowed: true,
          capabilities: getCapabilities(account)
        }
      ];
    }).then((res: any) => {
      if (res && res.account_number) {
        return [
          {
            accountNumber: res.account_number,
            label: this.label,
            agenticAllowed: true,
            capabilities: getCapabilities(res)
          }
        ];
      }
      return res;
    });
  }

  async getPortfolio(accountNumber: string): Promise<Portfolio> {
    return this.callMcp<any>("get_account_info", {}, async () => {
      const account = await this.trackHealth(() => this.alpaca.getAccount());
      // Alpaca API credentials are scoped to exactly one account, so getAccount() always returns THE
      // account these keys belong to. Only flag a GENUINE cross-account mismatch (both numbers present
      // and actually different, ignoring case/whitespace) — a blank configured number or a mere
      // formatting difference must never block a run. The message is actionable so the operator can
      // correct the stored number in Connections.
      const liveNum = String(account.account_number ?? "").trim();
      const wantNum = String(accountNumber ?? "").trim();
      if (wantNum && liveNum && liveNum.toLowerCase() !== wantNum.toLowerCase()) {
        throw new Error(
          `Account Mismatch: the connected Alpaca credentials are for account ${liveNum}, but this profile is configured for ${wantNum}. Update the account number in Connections.`
        );
      }
      return {
        accountNumber,
        totalMarketValue: number(account.portfolio_value),
        buyingPower: number(account.buying_power),
        equityMarketValue: number(account.equity) - number(account.cash),
        optionMarketValue: 0,
        cash: number(account.cash)
      };
    }).then((res: any) => {
      let result: Portfolio;
      if (res && res.account_number) {
        result = {
          accountNumber,
          totalMarketValue: number(res.portfolio_value),
          buyingPower: number(res.buying_power),
          equityMarketValue: number(res.equity) - number(res.cash),
          optionMarketValue: 0,
          cash: number(res.cash)
        };
      } else {
        result = res;
      }
      if (result && result.accountNumber) {
        pushBrokerBalance({
          provider: "alpaca",
          userId: this.userId,
          accountNumber: result.accountNumber,
          cash: result.cash,
          buyingPower: result.buyingPower,
          equity: result.totalMarketValue
        });
      }
      return result;
    });
  }

  async getEquityPositions(accountNumber: string): Promise<EquityPosition[]> {
    return this.callMcp<any>("get_positions", {}, async () => {
      const positions = await this.trackHealth(() => this.alpaca.getPositions());
      return positions.map(parseAlpacaPosition);
    }).then((res: any) => {
      if (Array.isArray(res)) {
        return res.map(parseAlpacaPosition);
      }
      return res;
    });
  }

  async getEquityOrders(accountNumber: string): Promise<EquityOrder[]> {
    return this.callMcp<any>("get_orders", { status: "all", limit: 500 }, async () => {
      // Paginate: Alpaca returns at most `limit` (max 500) per call, newest-first. Walk backwards via
      // `until` (the oldest created_at seen) until a short page signals the end. Without this the
      // default page silently capped history and missed older orders. Dedupe by id at page edges.
      const all: Record<string, unknown>[] = [];
      const seen = new Set<string>();
      const PAGE = 500;
      let until: string | undefined;
      for (let guard = 0; guard < 50; guard++) {
        const page = (await this.trackHealth(() => this.alpaca.getOrders({
          status: "all",
          limit: PAGE,
          direction: "desc",
          ...(until ? { until } : {})
        } as Parameters<typeof this.alpaca.getOrders>[0]))) as Record<string, unknown>[];
        if (!Array.isArray(page) || page.length === 0) break;
        let added = 0;
        let oldest: string | undefined;
        for (const o of page) {
          const id = String(o.id);
          const createdAt = String(o.created_at);
          if (!seen.has(id)) {
            seen.add(id);
            all.push(o);
            added += 1;
          }
          if (!oldest || createdAt < oldest) oldest = createdAt;
        }
        // Stop on a short page, no forward progress, or a stuck boundary.
        if (page.length < PAGE || added === 0 || !oldest || oldest === until) break;
        until = oldest;
      }
      return all;
    }).then((res: any) => (Array.isArray(res) ? res.map((o: any) => mapAlpacaOrder(o as Record<string, unknown>)) : res));
  }

  async getEquityQuotes(accountNumber: string, symbols: string[]): Promise<Record<string, BrokerQuote>> {
    // Standard quotes method: fall back to REST directly to avoid multi-ticker latency
    const aliasesByCanonical = new Map<string, Set<string>>();
    for (const rawSymbol of symbols) {
      const requested = normalizeSymbol(rawSymbol);
      const canonical = fromAlpacaSymbol(toAlpacaSymbol(requested));
      if (!canonical) continue;
      const aliases = aliasesByCanonical.get(canonical) ?? new Set<string>();
      aliases.add(canonical);
      if (requested) aliases.add(requested);
      aliasesByCanonical.set(canonical, aliases);
    }
    const normalizedSymbols = Array.from(aliasesByCanonical.keys());
    const quotes: Record<string, BrokerQuote> = {};
    try {
      const response = await this.trackHealth(() => this.alpaca.getLatestQuotes(normalizedSymbols.map(toAlpacaSymbol)));
      for (const [rawSymbol, q] of Object.entries(response)) {
        const symbol = fromAlpacaSymbol(rawSymbol);
        const anyQ = q as Record<string, number | string>;
        const bid = optionalNumber(anyQ.bp);
        const ask = optionalNumber(anyQ.ap);
        quotes[symbol] = {
          symbol,
          price: ask ?? bid ?? 0,
          bid,
          ask,
          asOf: optionalIso(anyQ.t),
          provider: "alpaca"
        };
      }
    } catch (error) {
      // Don't fail silently — a swallowed quote error is what makes the review fall through to an
      // unusable price. Surface it; the keyless fallback below still tries to price the symbols.
      console.warn(`[alpaca] getLatestQuotes failed for ${normalizedSymbols.join(",")}:`, error instanceof Error ? error.message : error);
    }
    // Keyless market-data fallback for any symbol the broker left unpriced (0/empty bid-ask — common
    // outside market hours and on the free IEX tier). A recent daily close keeps the chat quote and
    // the pre-trade notional review usable instead of failing closed to the over-cap sentinel.
    await fillMissingQuotesWithClose(quotes, normalizedSymbols, async (symbol) => {
      const bars = await fetchDailyOHLC(symbol, Date.now(), this.userId);
      const last = bars && bars.length ? bars[bars.length - 1] : undefined;
      return last && typeof last.close === "number" ? { price: last.close, asOf: last.time != null ? String(last.time) : undefined } : undefined;
    });
    for (const [canonical, aliases] of aliasesByCanonical) {
      const quote = quotes[canonical];
      if (!quote) continue;
      for (const alias of aliases) {
        if (!quotes[alias]) quotes[alias] = { ...quote, symbol: alias };
      }
    }
    return quotes;
  }

  async getEquityTradability(accountNumber: string, symbols: string[]) {
    return Object.fromEntries(symbols.map((symbol) => [normalizeSymbol(symbol), { tradable: true, fractional: true }]));
  }

  async reviewEquityOrder(input: EquityOrderInput): Promise<ReviewedOrder> {
    const quotes = await this.getEquityQuotes(input.accountNumber, [input.symbol]);
    const quotePrice = quotes[normalizeSymbol(input.symbol)]?.price;
    const { estimatedNotional, alerts } = estimateReviewNotional(input, quotePrice);
    return { estimatedNotional, alerts, raw: { alpaca: true } };
  }

  async placeEquityOrder(input: EquityOrderInput & { refId: string }): Promise<ExecutedOrder> {
    const isBracket = !!(input.bracketTakeProfit || input.bracketStopLoss);
    const isTrailing = input.trailPercent != null && input.trailPercent > 0;

    // Native trailing stop: Alpaca's `trailing_stop` order type with `trail_percent` — the broker
    // trails the high-water mark itself. Mutually exclusive with brackets (both would claim the
    // same shares), quantity-based only, and Alpaca rejects limit/stop price params on it, so any
    // caller-supplied stopPrice (a ratchet anchor meant for brokers without native trailing) is
    // deliberately dropped.
    if (isTrailing) {
      if (isBracket) {
        throw new OrderValidationError("Alpaca trailing stop cannot carry bracket legs — place one or the other.");
      }
      if (!input.quantity || !(input.quantity > 0)) {
        throw new OrderValidationError("Alpaca trailing stop requires a positive share quantity (no notional trailing stops).");
      }
      try {
        const raw = await this.trackHealth(() => this.alpaca.createOrder({
          symbol: toAlpacaSymbol(input.symbol),
          side: toBrokerSide(input.side),
          type: "trailing_stop",
          trail_percent: String(input.trailPercent),
          qty: input.quantity,
          time_in_force: input.timeInForce === "gfd" ? "day" : "gtc",
          client_order_id: input.refId
        }));
        return {
          orderId: raw.id,
          refId: input.refId,
          state: raw.status,
          filledQuantity: optionalNumber(raw.filled_qty),
          averagePrice: optionalNumber(raw.filled_avg_price),
          raw
        };
      } catch (error: unknown) {
        throw new Error(`Alpaca trailing stop order failed: ${formatAlpacaOrderError(error)}`);
      }
    }

    // Alpaca does not support notional (dollar) bracket orders — only qty-based.
    // If a bracketed dollar order reaches this gateway, it must carry a real entry
    // anchor from review/proposal enrichment. Never fall back to 1; that can turn a
    // $500 market bracket into 500 shares.
    let bracketQty: number | undefined;
    if (isBracket && input.dollarAmount && !input.quantity) {
      const estPrice = input.limitPrice ?? input.referencePrice;
      if (estPrice == null || !(estPrice > 0)) {
        throw new OrderValidationError("Alpaca bracket dollar orders require a positive limitPrice or referencePrice.");
      }
      bracketQty = Math.floor(input.dollarAmount / estPrice);
      if (bracketQty < 1) {
        throw new OrderValidationError("Alpaca bracket dollar order is too small for a whole-share bracket at the reference price.");
      }
    }

    const fallbackFn = async () => {
      try {
        const orderOptions: Record<string, unknown> = {
          symbol: toAlpacaSymbol(input.symbol),
          side: toBrokerSide(input.side), // short→sell, cover→buy; Alpaca infers open/close from position
          type: input.type,
          // Bracket orders require time_in_force="day" — Alpaca rejects "gtc" entries with brackets.
          time_in_force: isBracket ? "day" : (input.timeInForce === "gfd" ? "day" : "gtc"),
          client_order_id: input.refId
        };

        if (bracketQty != null) {
          orderOptions.qty = bracketQty;
        } else if (input.quantity) {
          orderOptions.qty = input.quantity;
        } else if (input.dollarAmount && !isBracket) {
          orderOptions.notional = input.dollarAmount;
        }

        if (input.limitPrice) orderOptions.limit_price = input.limitPrice;
        // stop_price is only legal on stop-family order types — Alpaca rejects a limit order that
        // carries one with HTTP 422 40010001 "limit orders require no stop price" (proposals may
        // carry a protective stopPrice idea; that intent rides the bracket stop_loss /
        // protective-stop systems, never this field).
        if (input.stopPrice && (input.type === "stop_market" || input.type === "stop_limit")) {
          orderOptions.stop_price = input.stopPrice;
        }
        if (input.marketHours === "extended_hours") orderOptions.extended_hours = true;

        if (isBracket) {
          orderOptions.order_class = "bracket";
          if (input.bracketTakeProfit != null) {
            orderOptions.take_profit = { limit_price: input.bracketTakeProfit };
          }
          if (input.bracketStopLoss != null) {
            orderOptions.stop_loss = {
              stop_price: input.bracketStopLoss,
              ...(input.bracketStopLimit != null ? { limit_price: input.bracketStopLimit } : {})
            };
          }
        }

        const raw = await this.trackHealth(() => this.alpaca.createOrder(orderOptions));
        return {
          orderId: raw.id,
          refId: input.refId,
          state: raw.status,
          filledQuantity: optionalNumber(raw.filled_qty),
          averagePrice: optionalNumber(raw.filled_avg_price),
          raw
        };
      } catch (error: unknown) {
        throw new Error(`Alpaca order failed: ${formatAlpacaOrderError(error)}`);
      }
    };

    if (!this.isMcp || !this.mcpUrl) {
      return fallbackFn();
    }

    const toolName = input.type === "limit"
      ? "place_limit_order"
      : (input.type === "stop_market" || input.type === "stop_limit")
        ? "place_stop_order"
        : "place_market_order";

    const orderArgs: Record<string, any> = {
      symbol: toAlpacaSymbol(input.symbol),
      side: toBrokerSide(input.side), // short→sell, cover→buy; Alpaca infers open/close from position
      type: input.type,
      // Bracket orders require time_in_force="day" — Alpaca rejects "gtc" entries with brackets.
      time_in_force: isBracket ? "day" : (input.timeInForce === "gfd" ? "day" : "gtc"),
      client_order_id: input.refId
    };

    if (bracketQty != null) orderArgs.qty = String(bracketQty);
    else if (input.quantity) orderArgs.qty = String(input.quantity);
    else if (input.dollarAmount && !isBracket) orderArgs.notional = String(input.dollarAmount);

    if (input.limitPrice) orderArgs.limit_price = String(input.limitPrice);
    // Same constraint as the REST path: stop_price only on stop-family types (Alpaca 422s a
    // limit order carrying one).
    if (input.stopPrice && (input.type === "stop_market" || input.type === "stop_limit")) {
      orderArgs.stop_price = String(input.stopPrice);
    }

    if (isBracket) {
      orderArgs.order_class = "bracket";
      if (input.bracketTakeProfit != null) {
        orderArgs.take_profit = { limit_price: input.bracketTakeProfit };
      }
      if (input.bracketStopLoss != null) {
        orderArgs.stop_loss = {
          stop_price: input.bracketStopLoss,
          ...(input.bracketStopLimit != null ? { limit_price: input.bracketStopLimit } : {})
        };
      }
    }

    return this.callMcp<any>(toolName, orderArgs, fallbackFn).then((res: any) => {
      if (res && res.id) {
        return {
          orderId: res.id,
          refId: input.refId,
          state: res.status,
          filledQuantity: optionalNumber(res.filled_qty),
          averagePrice: optionalNumber(res.filled_avg_price),
          raw: res
        };
      }
      return res;
    });
  }

  async cancelEquityOrder(accountNumber: string, orderId: string): Promise<ExecutedOrder> {
    return this.callMcp<any>("cancel_order", { order_id: orderId }, async () => {
      await this.trackHealth(() => this.alpaca.cancelOrder(orderId));
      return { orderId, refId: crypto.randomUUID(), state: "cancel_requested", raw: {} };
    }).then((res: any) => {
      if (res && typeof res === "object") {
        return { orderId, refId: crypto.randomUUID(), state: "cancel_requested", raw: res };
      }
      return res;
    });
  }

  // Identifies and cancels a bracket's still-resting sibling legs given the ORIGINAL entry order's
  // own ID. Alpaca's `GET /v2/orders/{id}?nested=true` returns the entry order with a `legs` array
  // — each leg is ALSO independently listed in the plain (non-nested) order list with its own real
  // order ID, and Alpaca cascades a cancel across the whole OCO group on its own once any one leg is
  // cancelled/filled. This always goes through native REST (this.alpaca), never the MCP tool
  // surface — this repo's alpaca-mcp integration has no documented equivalent for a nested-legs
  // fetch, and `this.alpaca` is constructed with the same REST-capable keys regardless of isMcp
  // whenever an underlying API key is configured (see the constructor) — so this degrades to a
  // best-effort no-op only on an MCP-ONLY account with no REST-capable key at all.
  async cancelBracketSiblingLegs(accountNumber: string, originalOrderId: string): Promise<{ cancelledOrderIds: string[] }> {
    let raw: any;
    try {
      raw = await this.trackHealth(() => this.alpaca.sendRequest(`/orders/${originalOrderId}`, { nested: true }, null, "GET"));
    } catch (error) {
      // A 404 means the entry order is genuinely gone (expired/purged) — nothing to tear down, safe
      // to resolve as done. Any OTHER failure (network, rate-limit, 5xx) is transient and must
      // propagate so reconcilePendingBracketTeardowns' bounded-retry sweep actually retries it,
      // instead of the row being silently and permanently dropped on the first hiccup (adversarial
      // review of PR #1661, 2026-07-16).
      if ((error as { response?: { status?: number } })?.response?.status === 404) {
        return { cancelledOrderIds: [] };
      }
      throw error;
    }
    const legs = Array.isArray(raw?.legs) ? raw.legs : [];
    const cancelledOrderIds: string[] = [];
    for (const leg of legs) {
      const legId = leg?.id != null ? String(leg.id) : undefined;
      if (!legId) continue;
      const legState = String(leg?.status ?? "");
      if (isRejectedOrCanceledState(legState) || legState.toLowerCase() === "filled") continue;
      try {
        await this.trackHealth(() => this.alpaca.cancelOrder(legId));
        cancelledOrderIds.push(legId);
      } catch {
        // best-effort — a leg that filled/cancelled between the fetch above and this cancel is fine
        // to skip; Alpaca's own OCO cascade may have already resolved it
      }
    }
    return { cancelledOrderIds };
  }
}

function optionalNumber(value: unknown): number | undefined {
  if (value === null || value === undefined || value === "") return undefined;
  const parsed = typeof value === "number" ? value : Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function number(value: unknown): number {
  return optionalNumber(value) ?? 0;
}

// Map Alpaca's raw order `type` to our OrderType union. Alpaca uses "stop" (not "stop_market") and
// "trailing_stop"; a raw `as OrderType` cast silently leaked those non-union values downstream.
export function mapAlpacaOrderType(raw: unknown): OrderType {
  switch (String(raw)) {
    case "market":
      return "market";
    case "limit":
      return "limit";
    case "stop":
      return "stop_market";
    case "stop_limit":
      return "stop_limit";
    case "trailing_stop":
      return "stop_market"; // closest representation in our union (a stop-triggered exit)
    default:
      return "market"; // unknown/absent → safe default rather than leaking an invalid value
  }
}

// Map a raw Alpaca order object (REST or MCP shape — same field names) to our EquityOrder.
export function mapAlpacaOrder(o: Record<string, unknown>): EquityOrder {
  return {
    id: String(o.id),
    symbol: fromAlpacaSymbol(String(o.symbol)),
    side: o.side as OrderSide,
    type: mapAlpacaOrderType(o.type),
    state: String(o.status),
    quantity: optionalNumber(o.qty),
    dollarAmount: optionalNumber(o.notional),
    filledQuantity: optionalNumber(o.filled_qty),
    averagePrice: optionalNumber(o.filled_avg_price),
    limitPrice: optionalNumber(o.limit_price),
    stopPrice: optionalNumber(o.stop_price),
    timeInForce: o.time_in_force ? String(o.time_in_force) : undefined,
    createdAt: String(o.created_at),
    updatedAt: o.updated_at ? String(o.updated_at) : undefined,
    clientOrderId: o.client_order_id ? String(o.client_order_id) : undefined,
    orderClass: o.order_class ? String(o.order_class) : undefined,
    placedAgent: "alpaca"
  };
}

export function parseAlpacaPosition(p: Record<string, unknown>): EquityPosition {
  return {
    symbol: fromAlpacaSymbol(String(p.symbol)),
    quantity: number(p.qty ?? p.quantity),
    averageCost: number(p.avg_entry_price ?? p.average_entry_price ?? p.averageCost),
    marketValue: number(p.market_value ?? p.marketValue),
    sector: undefined,
    industry: undefined
  };
}

function optionalIso(value: unknown): string | undefined {
  if (value === null || value === undefined || value === "") return undefined;
  const time = Date.parse(String(value));
  return Number.isFinite(time) ? new Date(time).toISOString() : undefined;
}

function formatAlpacaOrderError(error: unknown): string {
  const err = error as {
    message?: string;
    response?: { status?: number; data?: unknown };
  };
  const status = err.response?.status;
  const data = err.response?.data;
  const body = typeof data === "string"
    ? data
    : data && typeof data === "object"
      ? JSON.stringify(data)
      : "";
  const message = err.message ?? String(error);
  const detail = [status ? `HTTP ${status}` : "", message, body].filter(Boolean).join(" — ");
  if (status === 403 && !/position|short|permission|forbidden|insufficient/i.test(body)) {
    return `${detail} — broker forbade the order; verify the account has permission and a matching open position if this was a sell/cover.`;
  }
  return detail;
}

// SPY-benchmark equity-curve scoreboard.
//
// Compares the account's equity curve (from portfolio_snapshots) to a SPY buy-and-hold over the
// same window — the honest "are we beating the market net of cost" readout. Both series are
// normalized to 100 at the first common date so they overlay on one axis. SPY daily closes come
// from the same key-free history cascade every chart uses (fetchDailyOHLC). Never fabricates: if
// there isn't enough history or SPY can't be fetched, returns null and the UI degrades to "—".
//
// Deposits/withdrawals: no broker transfer ledger exists in this app, so external cash flows are
// INFERRED per snapshot gap as (cash delta) − (recorded trade cash delta), thresholded so
// dividends/fees/rounding don't register as transfers. When a material flow is detected, the
// account line is a chained time-weighted return (TWR) that neutralizes the flow, and the result
// is flagged `cashFlowAdjusted` so the UI can say so honestly. Without cash data (synthetic
// curves) behavior is unchanged: raw equity growth, `cashFlowAdjusted` false.

import { fetchDailyOHLC } from "./history";
import type { BenchmarkComparison, BenchmarkSeriesPoint, EquityCurvePoint, FillEvent } from "./types";

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

/** Normalize any timestamp (ms epoch | ISO datetime | YYYY-MM-DD) to a calendar date string. */
function isoDate(ts: string | number | undefined): string | null {
  if (ts == null) return null;
  if (typeof ts === "number") {
    const d = new Date(ts);
    return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
  }
  if (/^\d{4}-\d{2}-\d{2}/.test(ts)) return ts.slice(0, 10);
  const d = new Date(ts);
  return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
}

// ── External cash-flow inference ─────────────────────────────────────────────

/** A flow is only "external" when it clears both floors — below that, cash drift is
 *  indistinguishable from dividends/fees/rounding and must NOT be treated as a transfer. */
export const FLOW_MATERIALITY_PCT_OF_EQUITY = 0.5; // % of prior equity
export const FLOW_MATERIALITY_MIN_USD = 25;

/**
 * Infer external deposits/withdrawals per calendar date from the equity curve's cash balances
 * and the account's recorded fills. For each consecutive pair of (per-date last) snapshots:
 *
 *   externalFlow = (cash_i − cash_{i−1}) − (trade cash between the snapshots)
 *
 * where trade cash = +notional for sell/cover fills and −notional for buy/short fills. A flow
 * below the materiality floors is dropped (dividends, fees, rounding). Returns a map keyed by
 * the PERIOD-END snapshot date (the date whose period the flow landed in). Pure — exported for
 * direct unit testing. Returns an empty map when the curve carries no cash data.
 */
export function inferExternalCashFlows(
  equityCurve: EquityCurvePoint[],
  fills: FillEvent[] = []
): Map<string, number> {
  const flows = new Map<string, number>();
  // Collapse to one (last) point per calendar date, mirroring normalizeAgainstBenchmark.
  const byDate = new Map<string, { equity: number; cash: number; timestampMs: number }>();
  for (const p of equityCurve) {
    const d = isoDate(p.timestamp);
    const t = new Date(p.timestamp).getTime();
    if (!d || !Number.isFinite(t)) continue;
    if (!Number.isFinite(p.equity) || p.equity <= 0) continue;
    if (typeof p.cash !== "number" || !Number.isFinite(p.cash)) continue;
    byDate.set(d, { equity: p.equity, cash: p.cash, timestampMs: t });
  }
  const dates = [...byDate.keys()].sort();
  if (dates.length < 2) return flows;

  const sortedFills = fills
    .map((f) => ({ t: new Date(f.filledAt).getTime(), side: f.side, notional: f.notional }))
    .filter((f) => Number.isFinite(f.t) && Number.isFinite(f.notional))
    .sort((a, b) => a.t - b.t);

  for (let i = 1; i < dates.length; i++) {
    const prev = byDate.get(dates[i - 1])!;
    const cur = byDate.get(dates[i])!;
    // Trade-driven cash movement between the two snapshots (exclusive, inclusive].
    let tradeCash = 0;
    for (const f of sortedFills) {
      if (f.t <= prev.timestampMs) continue;
      if (f.t > cur.timestampMs) break;
      tradeCash += f.side === "sell" || f.side === "cover" ? f.notional : -f.notional;
    }
    const flow = cur.cash - prev.cash - tradeCash;
    const threshold = Math.max((FLOW_MATERIALITY_PCT_OF_EQUITY / 100) * prev.equity, FLOW_MATERIALITY_MIN_USD);
    if (Math.abs(flow) >= threshold) flows.set(dates[i], round2(flow));
  }
  return flows;
}

/**
 * Pure normalization: align an equity curve with a date→close benchmark series, base both to 100
 * at the first equity date that has a benchmark close on/before it. Benchmark closes are looked up
 * carry-forward (last close on/before the date) so non-trading-day snapshots still align. Returns
 * null when either series has < 2 usable points. Exported for direct unit testing (no network).
 *
 * When `flowsByDate` (external deposits/withdrawals keyed by period-end date, from
 * inferExternalCashFlows) contains a flow inside the window, the account index becomes a chained
 * time-weighted return: each period's growth is equity_i / (equity_{i−1} + flow_i), so a
 * withdrawal no longer reads as a loss and a deposit no longer reads as a gain. Without flows the
 * math is byte-identical to plain equity growth.
 */
export function normalizeAgainstBenchmark(
  equityCurve: EquityCurvePoint[],
  benchmarkCloses: Array<{ date: string; close: number }>,
  benchmarkSymbol = "SPY",
  flowsByDate?: Map<string, number>
): BenchmarkComparison | null {
  if (!equityCurve || equityCurve.length < 2 || benchmarkCloses.length < 2) return null;

  // Collapse equity to one (last) point per calendar date. The curve is chronological, so a later
  // entry for the same date overwrites an earlier one.
  const equityByDate = new Map<string, number>();
  for (const p of equityCurve) {
    const d = isoDate(p.timestamp);
    if (d && Number.isFinite(p.equity) && p.equity > 0) equityByDate.set(d, p.equity);
  }
  const equityDates = [...equityByDate.keys()].sort();
  if (equityDates.length < 2) return null;

  const bench = benchmarkCloses
    .filter((b) => Number.isFinite(b.close) && b.close > 0)
    .sort((a, b) => a.date.localeCompare(b.date));
  if (bench.length < 2) return null;

  const closeOnOrBefore = (date: string): number | null => {
    let lo = 0;
    let hi = bench.length - 1;
    let ans: number | null = null;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (bench[mid].date <= date) {
        ans = bench[mid].close;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    return ans;
  };

  let baseDate: string | null = null;
  for (const d of equityDates) {
    if (closeOnOrBefore(d) != null) {
      baseDate = d;
      break;
    }
  }
  if (!baseDate) return null;
  const baseEquity = equityByDate.get(baseDate)!;
  const baseBench = closeOnOrBefore(baseDate)!;

  const equityIndex: BenchmarkSeriesPoint[] = [];
  const benchmarkIndex: BenchmarkSeriesPoint[] = [];
  // TWR chaining state: index_i = index_{i−1} × equity_i / (equity_{i−1} + flow_i).
  let chainedIndex = 100;
  let prevEquity: number | null = null;
  let flowsApplied = 0;
  let netExternalFlows = 0;
  for (const d of equityDates) {
    if (d < baseDate) continue;
    const eq = equityByDate.get(d)!;
    const bc = closeOnOrBefore(d);
    if (bc == null) continue;
    if (prevEquity != null) {
      const flow = flowsByDate?.get(d) ?? 0;
      const denominator = prevEquity + flow;
      if (flow !== 0 && denominator > 0) {
        chainedIndex *= eq / denominator;
        flowsApplied += 1;
        netExternalFlows += flow;
      } else {
        chainedIndex *= eq / prevEquity;
      }
    }
    prevEquity = eq;
    equityIndex.push({ date: d, index: round2(chainedIndex) });
    benchmarkIndex.push({ date: d, index: round2((bc / baseBench) * 100) });
  }
  if (equityIndex.length < 2) return null;

  const accountReturnPct = equityIndex[equityIndex.length - 1].index - 100;
  const benchmarkReturnPct = benchmarkIndex[benchmarkIndex.length - 1].index - 100;
  return {
    equityIndex,
    benchmarkIndex,
    accountReturnPct: round2(accountReturnPct),
    benchmarkReturnPct: round2(benchmarkReturnPct),
    excessReturnPct: round2(accountReturnPct - benchmarkReturnPct),
    startDate: baseDate,
    endDate: equityIndex[equityIndex.length - 1].date,
    points: equityIndex.length,
    benchmarkSymbol,
    ...(flowsApplied > 0 ? { cashFlowAdjusted: true, netExternalFlows: round2(netExternalFlows) } : { cashFlowAdjusted: false })
  };
}

/**
 * Fetch SPY daily closes and compare them to the account equity curve. userId scopes the history
 * cache (consent-pooled). Optional `fills` (the same source's recorded fills) enable external
 * cash-flow inference so the account line is deposit/withdrawal-aware (TWR). Returns null on any
 * failure or insufficient data so callers degrade gracefully — never throws into the dashboard path.
 */
export async function computeSpyBenchmark(
  equityCurve: EquityCurvePoint[],
  userId?: string,
  now: number = Date.now(),
  fills?: FillEvent[]
): Promise<BenchmarkComparison | null> {
  if (!equityCurve || equityCurve.length < 2) return null;
  let bars;
  try {
    bars = await fetchDailyOHLC("SPY", now, userId);
  } catch {
    return null;
  }
  if (!bars || bars.length < 2) return null;
  const closes = bars
    .map((b) => ({ date: isoDate(b.time), close: b.close }))
    .filter((b): b is { date: string; close: number } => b.date != null && Number.isFinite(b.close));
  const flows = inferExternalCashFlows(equityCurve, fills ?? []);
  return normalizeAgainstBenchmark(equityCurve, closes, "SPY", flows.size > 0 ? flows : undefined);
}

// Persistent SSE consumer for congress.trade (App A). Connects OUT to App A's text/event-stream and
// applies pushed events (see docs/push-to-app-b.md) — the streaming counterpart to the inbound
// /api/webhooks/congress route. Must run in the persistent Node process (started from
// instrumentation.register via startStreams(), NOT a per-request handler).
//
// CONTRACT (App A's live subscription model — see Congress.Trade/app/src/delivery/{rest,sse}.ts):
//   App A's GET /api/stream REQUIRES `?subscription=<id>` and authenticates the per-subscription
//   secret (Authorization: Bearer <secret>, or ?token=). It then emits, per matching trade,
//   `id:<cursorSeq>\nevent: trade.new\ndata:<raw Transaction JSON>` plus control frames
//   (`event: cursor|ping|reconnect|error`). This consumer therefore (1) resolves a subscription —
//   operator-provisioned via env, or auto-created against App A's public POST /api/subscriptions —
//   (2) connects with `?subscription=` + the secret, (3) maps App A's raw `trade.new` Transaction into
//   a canonical `congress.trade` envelope before applyCongressEvent, and (4) treats cursor/ping/
//   reconnect/error as recognized control frames (no "dropped unparseable" noise per heartbeat).
//
// Reconnects with exponential backoff and resumes via the Last-Event-ID header so events aren't lost
// across reconnects. Opt-in (CONGRESS_STREAM_ENABLED); no-op otherwise. Fully self-guarded. IMPORTANT:
// this module is on the instrumentation import chain, which Next also bundles for the edge runtime, so
// it must NOT statically import Node-only modules (crypto, better-sqlite3/db) — keep it fetch-only.

import { applyCongressEvent, type CongressEvent } from "./congress-trade-events";
import { logApiHealth } from "./db-health";
import { CongressTradeClient, SseParser, type SseMessage, type Subscription } from "@jaywedgeworth22/congress-trading-shared";

const DEFAULT_PATH = "/api/stream";
const MAX_BACKOFF_MS = 60_000;
const INITIAL_BACKOFF_MS = 1_000;

interface StreamState {
  started: boolean;
  closing: boolean;
  backoffMs: number;
  lastEventId?: string;
  controller?: AbortController;
  /** Auto-created subscription cached for this process lifetime (env-provisioned ones aren't cached). */
  subscription?: Subscription;
}

const host = globalThis as unknown as { __congressStream?: StreamState };
const state: StreamState = host.__congressStream ?? (host.__congressStream = { started: false, closing: false, backoffMs: INITIAL_BACKOFF_MS });

function flagOn(value: string | undefined): boolean {
  return ["1", "true", "on", "yes"].includes(String(value ?? "").trim().toLowerCase());
}

export function congressStreamEnabled(): boolean {
  return flagOn(process.env.CONGRESS_STREAM_ENABLED);
}

function baseUrl(): string {
  return (process.env.CONGRESS_TRADE_BASE_URL ?? "https://congress.trade").trim().replace(/\/+$/, "");
}

/** Build App A's stream URL with the required `?subscription=<id>` query param. */
function streamUrl(subscriptionId: string): string {
  return new CongressTradeClient({ baseUrl: baseUrl() }).streamUrl(subscriptionId);
}

function envSubscriptionId(): string | undefined {
  const v = (process.env.CONGRESS_STREAM_SUBSCRIPTION_ID ?? "").trim();
  return v.length > 0 ? v : undefined;
}

function envSubscriptionToken(): string | undefined {
  // The per-subscription secret App A validates for the stream. Falls back to CONGRESS_TRADE_READ_TOKEN
  // only for backward compatibility with an operator who reused that value as the subscription secret.
  const v = (process.env.CONGRESS_STREAM_SUBSCRIPTION_TOKEN ?? process.env.CONGRESS_TRADE_READ_TOKEN ?? "").trim();
  return v.length > 0 ? v : undefined;
}

/**
 * Auto-create an SSE subscription against App A's public POST /api/subscriptions and return its
 * id + secret. Opt-in (CONGRESS_STREAM_AUTO_SUBSCRIBE); returns null on any failure so the caller
 * stays inert rather than throwing. If CONGRESS_STREAM_SUBSCRIPTION_TOKEN is set (>=16 chars) it is
 * used as the subscription secret so the same value survives a recreate.
 */
async function createSubscription(): Promise<Subscription | null> {
  const clientId = (process.env.CONGRESS_STREAM_CLIENT_ID ?? "app-b").trim() || "app-b";
  const desiredSecret = (process.env.CONGRESS_STREAM_SUBSCRIPTION_TOKEN ?? "").trim();
  try {
    const client = new CongressTradeClient({ baseUrl: baseUrl() });
    return await client.createSubscription(clientId, desiredSecret);
  } catch (err) {
    console.warn("[congress-stream] subscription create error:", err instanceof Error ? err.message : err);
    return null;
  }
}

/**
 * Resolve the subscription to connect with: operator-provisioned env id+token (preferred), then a
 * cached auto-created one, else auto-create (opt-in). Returns null when none can be resolved — the
 * push path then stays inert (documented) instead of hammering App A's /stream with a 400.
 */
export async function resolveSubscription(): Promise<Subscription | null> {
  const id = envSubscriptionId();
  const token = envSubscriptionToken();
  if (id && token) return { id, secret: token };
  if (state.subscription) return state.subscription;
  if (!flagOn(process.env.CONGRESS_STREAM_AUTO_SUBSCRIBE)) return null;
  const created = await createSubscription();
  if (created) state.subscription = created;
  return created;
}

// ── Pure SSE frame parser (unit-tested; no network) ──────────────────────────
/** App A's non-data control frames — recognized so they never log as "dropped unparseable". */
const CONTROL_EVENTS = new Set(["cursor", "ping", "reconnect", "error"]);

/**
 * Map one parsed SSE data payload into a canonical CongressEvent envelope.
 *  - App A's `event: trade.new` carries the RAW Transaction as its data — wrap it explicitly as
 *    { type:'congress.trade', id, data:{ transaction } } (applyCongressEvent reads data.transaction).
 *  - Anything else is assumed to already be a CongressEvent envelope; fill type/id from the SSE frame
 *    lines when absent (a webhook-style envelope delivered over SSE).
 * Returns null when the payload isn't an object.
 */
export function toCongressEventEnvelope(parsed: unknown, msg: SseMessage): CongressEvent | null {
  if (!parsed || typeof parsed !== "object") return null;
  const obj = parsed as Record<string, unknown>;
  if (msg.event === "trade.new") {
    const txId = typeof obj.id === "string" ? obj.id : msg.id;
    return { type: "congress.trade", id: txId, data: { transaction: obj } };
  }
  const env = obj as unknown as CongressEvent;
  if (!env.type && msg.event) env.type = msg.event;
  if (!env.id && msg.id) env.id = msg.id;
  return env;
}

/**
 * Handle one SSE message. Control frames (cursor/ping/reconnect/error) are recognized no-ops.
 * Data frames are parsed, mapped to a CongressEvent envelope, and applied. Returns false only when a
 * DATA frame can't be parsed/mapped (so the caller can log genuinely-unexpected payloads).
 */
export function applySseMessage(msg: SseMessage): boolean {
  const event = msg.event ?? "";
  if (CONTROL_EVENTS.has(event)) {
    if (event === "error") console.warn("[congress-stream] App A error frame:", (msg.data ?? "").slice(0, 200));
    return true; // recognized control frame — nothing to ingest, no warning
  }
  if (!msg.data) return false;
  let parsed: unknown;
  try {
    parsed = JSON.parse(msg.data);
  } catch {
    return false;
  }
  const env = toCongressEventEnvelope(parsed, msg);
  if (!env) return false;
  applyCongressEvent(env);
  return true;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function connectOnce(): Promise<void> {
  const sub = await resolveSubscription();
  if (!sub) {
    throw new Error(
      "no subscription configured — set CONGRESS_STREAM_SUBSCRIPTION_ID + CONGRESS_STREAM_SUBSCRIPTION_TOKEN, or enable CONGRESS_STREAM_AUTO_SUBSCRIBE"
    );
  }
  const controller = new AbortController();
  state.controller = controller;
  const startedAt = Date.now();
  const res = await fetch(streamUrl(sub.id), {
    headers: {
      accept: "text/event-stream",
      authorization: `Bearer ${sub.secret}`, // App A reads the subscription secret from Bearer or ?token
      ...(state.lastEventId ? { "last-event-id": state.lastEventId } : {})
    },
    cache: "no-store",
    signal: controller.signal
  });
  // A rejected/stale subscription (deleted, inactive, wrong secret) → drop the cached auto-created one
  // so the next attempt re-provisions; an env-provisioned subscription is left for the operator to fix.
  if (res.status === 401 || res.status === 404 || res.status === 409) {
    if (state.subscription) state.subscription = undefined;
    throw new Error(`SSE connect rejected: HTTP ${res.status} (subscription invalid?)`);
  }
  if (!res.ok || !res.body) {
    let retryMsg = "";
    if (res.status === 429) {
      const retryAfter = res.headers.get("retry-after");
      if (retryAfter) {
        // RFC 7231 §7.1.3: Retry-After can be delta-seconds or HTTP-date
        const parsed = parseInt(retryAfter, 10);
        if (!isNaN(parsed) && parsed > 0) {
          retryMsg = ` (Retry-After: ${parsed})`;
        } else {
          // Try HTTP-date format, e.g. "Wed, 21 Oct 2015 07:28:00 GMT"
          const httpDate = Date.parse(retryAfter);
          if (!isNaN(httpDate)) {
            const seconds = Math.ceil((httpDate - Date.now()) / 1000);
            if (seconds > 0) {
              retryMsg = ` (Retry-After: ${seconds})`;
            }
          }
        }
      }
    }
    throw new Error(`SSE connect failed: HTTP ${res.status}${retryMsg}`);
  }
  state.backoffMs = INITIAL_BACKOFF_MS; // healthy connection → reset backoff
  // Connection-health signal for the admin Connections page (App B's side of the App A → App B
  // real-time link). Re-fires on each (re)connect within App A's ~25min stream lifetime.
  logApiHealth({ service: "congress.trade:sse", ok: true, latencyMs: Date.now() - startedAt });

  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  const parser = new SseParser();
  for (;;) {
    const { value, done } = await reader.read();
    if (done) break;
    for (const msg of parser.push(decoder.decode(value, { stream: true }))) {
      if (msg.id) state.lastEventId = msg.id; // resume point — replayed via Last-Event-ID on reconnect
      if (!applySseMessage(msg)) {
        console.warn("[congress-stream] dropped unparseable SSE message", { event: msg.event, id: msg.id });
      }
    }
    if (state.closing) {
      try {
        await reader.cancel();
      } catch {
        /* ignore */
      }
      break;
    }
  }
}

async function runLoop(): Promise<void> {
  while (!state.closing) {
    try {
      await connectOnce();
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error("[congress-stream] connection error:", msg);

      // Do not pollute api_health_log or loop infinitely if we legitimately lack credentials
      if (msg.includes("no subscription configured")) {
        console.warn("[congress-stream] disabling stream until credentials are provided.");
        state.closing = true;
        break;
      }

      // Record ALL failures in api_health_log so the admin dashboard shows current state.
      // logApiHealth already detects 429|rate limit in error text and suppresses Sentry
      // alerts via skipSentry (see db-health.ts line 172-174), so rate-limit backpressure
      // events are recorded without noise.
      logApiHealth({
        service: "congress.trade:sse",
        ok: false,
        errorText: msg,
      });

      // Back off on 429 explicitly, using the parsed Retry-After seconds if available
      const retryMatch = msg.match(/HTTP 429 \(Retry-After: (\d+)\)/);
      if (retryMatch) {
        const sec = parseInt(retryMatch[1], 10);
        state.backoffMs = Math.max(state.backoffMs, sec * 1000);
      } else if (msg.includes("HTTP 429")) {
        // Default to a 60s backoff if 429 but no Retry-After
        state.backoffMs = Math.max(state.backoffMs, 60_000);
      }
    }
    if (state.closing) break;
    await sleep(state.backoffMs);
    state.backoffMs = Math.min(state.backoffMs * 2, MAX_BACKOFF_MS);
  }
}

/** Idempotent: start the SSE consumer once if enabled. */
export function startCongressStream(): void {
  if (state.started || state.closing) return;
  if (!congressStreamEnabled()) return;
  if (typeof fetch === "undefined") {
    console.warn("[congress-stream] global fetch unavailable; not starting.");
    return;
  }
  state.started = true;
  void runLoop();
}

/** Stop the consumer (tests / graceful shutdown). */
export function stopCongressStream(): void {
  state.closing = true;
  try {
    state.controller?.abort();
  } catch {
    /* ignore */
  }
}

import type { EquityOrder, EquityPosition, FillEvent, NotificationEvent, PendingProposal, TradeProposal } from "./types";
import { formatQuantity } from "./money";
import { isActiveBrokerOrderState } from "./broker-held-orders";
import { shortOrderLabel } from "./order-labels";

export interface SymbolMeta {
  companyName?: string;
}

export interface AuditFeedItem {
  id: string;
  createdAt: string;
  title: string;
  detail: string;
  fullText: string;
  symbol?: string;
  companyName?: string;
  connectedAccountId?: string;
  accountLabel?: string;
}

interface SourceAuditEvent {
  id: string;
  createdAt: string;
  kind: string;
  payload: unknown;
  connectedAccountId?: string;
}

export interface StrategyDecisionLike {
  runId: string;
  createdAt?: string;
  status: "completed" | "failed";
  summary: string;
  proposals: Array<{ proposal: TradeProposal; status: string; reasons: string[]; orderId?: string }>;
  marketScan?: {
    topCandidates: Array<{ symbol: string; companyName?: string }>;
    quotesBySymbol?: Record<string, { symbol: string; companyName?: string }>;
  };
}

export function buildSymbolMetaBySymbol(input: {
  positions?: EquityPosition[];
  orders?: EquityOrder[];
  pendingProposals?: PendingProposal[];
  latestStrategyRun?: StrategyDecisionLike;
}): Record<string, SymbolMeta> {
  const meta: Record<string, SymbolMeta> = {};

  const ensure = (symbol?: string, companyName?: string) => {
    const normalized = normalizeSymbol(symbol);
    if (!normalized) return;
    meta[normalized] = {
      companyName: companyName?.trim() || meta[normalized]?.companyName
    };
  };

  for (const position of input.positions ?? []) ensure(position.symbol);
  for (const order of input.orders ?? []) ensure(order.symbol);
  for (const pending of input.pendingProposals ?? []) ensure(pending.proposal.symbol);

  const decision = input.latestStrategyRun;
  for (const proposal of decision?.proposals ?? []) ensure(proposal.proposal.symbol);
  for (const quote of decision?.marketScan?.topCandidates ?? []) ensure(quote.symbol, quote.companyName);
  for (const quote of Object.values(decision?.marketScan?.quotesBySymbol ?? {})) ensure(quote.symbol, quote.companyName);

  return meta;
}

export function buildAuditFeed(input: {
  audit: SourceAuditEvent[];
  symbolMetaBySymbol?: Record<string, SymbolMeta>;
  accountLabelById?: Record<string, string>;
  getProposalById?: (proposalId: string) => { proposal: TradeProposal } | undefined;
}): AuditFeedItem[] {
  const symbolMetaBySymbol = input.symbolMetaBySymbol ?? {};
  const accountLabelById = input.accountLabelById ?? {};

  return input.audit.map((event) => {
    const payload = asRecord(event.payload);
    const proposalLookup = proposalFromPayload(payload, input.getProposalById);
    const symbol = normalizeSymbol(
      stringValue(payload.symbol) ??
        stringValue(proposalLookup?.proposal?.symbol) ??
        notificationSymbol(payload)
    );
    const side = normalizeSide(stringValue(payload.side) ?? stringValue(proposalLookup?.proposal?.side) ?? notificationSide(payload));
    const companyName = symbol ? symbolMetaBySymbol[symbol]?.companyName : undefined;

    const feed = formatAuditEvent(event.kind, payload, { symbol, side, companyName });
    return {
      id: event.id,
      createdAt: event.createdAt,
      title: feed.title,
      detail: feed.detail,
      fullText: feed.fullText ?? feed.detail,
      symbol,
      companyName,
      connectedAccountId: event.connectedAccountId,
      accountLabel: event.connectedAccountId ? accountLabelById[event.connectedAccountId] : undefined
    };
  });
}

function formatAuditEvent(
  kind: string,
  payload: Record<string, unknown>,
  context: { symbol?: string; side?: "buy" | "sell"; companyName?: string }
): { title: string; detail: string; fullText?: string } {
  if (kind === "strategy_run") {
    const llm = formatLlmSteps(payload.llmSteps);
    const summary = stringValue(payload.summary) ?? "No summary";
    return {
      title: payload.status === "failed" ? "Strategy run failed" : "Strategy run completed",
      detail: joinDetail([summary, llm]) ?? summary
    };
  }

  if (kind === "llm_step") {
    const label = stringValue(payload.label) ?? "LLM step";
    const status = stringValue(payload.status) ?? "completed";
    const provider = stringValue(payload.provider);
    const model = stringValue(payload.model);
    const proposalCount = numberValue(payload.proposalCount);
    const reason = stringValue(payload.reason);
    return {
      title: `${label} ${status}`,
      detail: joinDetail([
        model && provider ? `${model} via ${capitalize(provider)}` : model ?? provider,
        proposalCount !== undefined ? `${proposalCount} proposal${proposalCount === 1 ? "" : "s"}` : undefined,
        reason
      ]) ?? "Model step recorded"
    };
  }

  if (kind === "deterministic_bear_veto") {
    return {
      title: `Vetoed by Bear Risk: ${context.symbol ?? "Trade"}`,
      detail: stringValue(payload.reason) ?? "Market regime blocked proposal"
    };
  }

  if (kind === "red_team_veto_override_requested") {
    return {
      title: `Red Team Override Requested: ${context.symbol ?? "Trade"}`,
      detail: stringValue(payload.reason) ?? "Override request recorded"
    };
  }

  if (kind === "red_team_veto_overridden") {
    return {
      title: `Red Team Veto Overridden: ${context.symbol ?? "Trade"}`,
      detail: stringValue(payload.reason) ?? "Human override recorded"
    };
  }

  if (kind === "prompt_injection_suspected") {
    return {
      title: `Prompt Injection Suspected: ${context.symbol ?? "Trade"}`,
      detail: stringValue(payload.detail) ?? "Security anomaly logged"
    };
  }

  if (kind === "evidence_age_anomaly") {
    return {
      title: `Evidence Age Anomaly: ${context.symbol ?? "Trade"}`,
      detail: stringValue(payload.detail) ?? "Stale context recorded"
    };
  }

  if (kind === "policy_change") {
    return {
      title: "Policy updated",
      detail: `Changed ${stringValue(payload.key) ?? "settings"}`
    };
  }

  if (kind === "profile_change") {
    const action = stringValue(payload.action) ?? "updated";
    return {
      title: `Profile ${action}`,
      detail: shortText(stringValue(payload.name) ?? "Strategy profile")
    };
  }

  if (kind === "proposal_approved") {
    const result = stringValue(payload.result) ?? "approved";
    const titlePrefix = sideLabel(context.side, context.symbol) ?? "Proposal";
    const title =
      result === "blocked"
        ? `${titlePrefix} Blocked`
        : result === "filled"
          ? `${titlePrefix} Filled`
          : result === "placed" || result === "paper"
          ? `${titlePrefix} Approved`
          : `${titlePrefix} ${capitalize(result)}`;
    const orderId = stringValue(payload.orderId);
    const buildProposalApprovedDetail = (orderIdFragment: string | undefined) =>
      joinDetail([
        // "paper" here is a legacy result value from before the local-simulation execution path was
        // removed — no code path writes it anymore, but old audit rows can still carry it.
        result === "paper" ? "Local simulation (legacy)" : undefined,
        result === "filled" ? "Order filled" : undefined,
        result === "placed" && stringValue(payload.fillStatus) === "pending_reconciliation" ? "Broker accepted order; pending execution" : undefined,
        result === "placed" && stringValue(payload.fillStatus) !== "pending_reconciliation" ? "Order placed" : undefined,
        (result === "placed" || result === "filled") && stringValue(payload.brokerState) ? `Broker state ${readableBrokerState(stringValue(payload.brokerState))}` : undefined,
        orderIdFragment,
        firstReason(payload)
      ]);
    // Detail shows the short order tag ("Order 6F8A1C2E"); the full broker order id is never
    // lost — it stays available via fullText (the raw-toggle affordance) when it differs.
    const detail = buildProposalApprovedDetail(orderId ? `Order ${shortOrderLabel(orderId)}` : undefined) ?? "Awaiting next update";
    const fullDetail = orderId ? buildProposalApprovedDetail(`Order ${orderId}`) : undefined;
    return { title, detail, fullText: fullDetail && fullDetail !== detail ? fullDetail : undefined };
  }

  if (kind === "proposal_rejected") {
    return {
      title: `${sideLabel(context.side, context.symbol) ?? "Proposal"} Rejected`,
      detail: "Rejected manually"
    };
  }

  if (kind === "order_rejected_by_broker") {
    const brokerState = stringValue(payload.brokerState);
    const orderId = stringValue(payload.orderId);
    const reason = stringValue(payload.reason) ?? stringValue(payload.error);
    const buildBrokerDeclineDetail = (orderIdFragment: string | undefined) =>
      joinDetail([
        brokerState ? `Broker state ${readableBrokerState(brokerState)}` : "Broker declined the order",
        orderIdFragment,
        reason
      ]);
    const detail = buildBrokerDeclineDetail(orderId ? `Order ${shortOrderLabel(orderId)}` : undefined) ?? "Broker declined the order";
    const fullDetail = orderId ? buildBrokerDeclineDetail(`Order ${orderId}`) : undefined;
    return {
      title: `${sideLabel(context.side, context.symbol) ?? context.symbol ?? "Order"} Broker Declined`,
      detail,
      fullText: fullDetail && fullDetail !== detail ? fullDetail : undefined
    };
  }

  if (kind === "notification") {
    const notification = payload as unknown as NotificationEvent;
    const symbol = normalizeSymbol(notificationSymbol(payload)) ?? context.symbol;
    const side = normalizeSide(notificationSide(payload)) ?? context.side;
    if (notification.type === "fill") {
      return {
        title: `${sideLabel(side, symbol) ?? symbol ?? "Trade"} ${notificationStatusLabel(notification.status)}`,
        detail: notification.error ? shortText(notification.error) : shortText(notification.title)
      };
    }
    if (notification.type === "pending_approval") {
      return {
        title: `${sideLabel(side, symbol) ?? symbol ?? "Proposal"} Approval Pending`,
        detail: notification.error ? shortText(notification.error) : shortText(notification.title)
      };
    }
    if (notification.type === "block") {
      return {
        title: `${sideLabel(side, symbol) ?? symbol ?? "Proposal"} Blocked`,
        detail: notification.error ? shortText(notification.error) : shortText(firstReason(asRecord(notification.payload)) ?? notification.title)
      };
    }
    return {
      title: `${notificationTypeLabel(notification.type)} ${notificationStatusLabel(notification.status)}`,
      detail: notification.error ? shortText(notification.error) : shortText(notification.title)
    };
  }

  if (kind === "fill_reconciled") {
    const status = stringValue(payload.status);
    return {
      title: `${context.symbol ?? "Fill"} reconciled`,
      detail: joinDetail([
        status ? feedStatusLabel(status) : undefined,
        numberValue(payload.quantity) ? `Qty ${trimNumber(numberValue(payload.quantity) ?? 0)}` : undefined,
        numberValue(payload.price) ? `@ ${trimCurrency(numberValue(payload.price) ?? 0)}` : undefined
      ]) ?? "Broker state synced"
    };
  }

  if (kind === "order_cancel") {
    const orderId = stringValue(payload.orderId);
    const detail = shortText(orderId ? `Order ${shortOrderLabel(orderId)}` : "Broker request submitted");
    const fullDetail = orderId ? shortText(`Order ${orderId}`) : undefined;
    return {
      title: "Order cancel requested",
      detail,
      fullText: fullDetail && fullDetail !== detail ? fullDetail : undefined
    };
  }

  if (kind === "post_mortem_reflection") {
    const provider = stringValue(payload.provider);
    const model = stringValue(payload.model);
    const modelAttribution = model && provider ? `${model} via ${capitalize(provider)}` : model ?? provider;
    if (payload.status === "failed") {
      return {
        title: "Post-mortem reflection failed",
        detail: joinDetail([modelAttribution, stringValue(payload.reason)]) ?? "The reflection model call failed"
      };
    }
    return {
      title: "Post Mortem Reflection",
      detail: joinDetail([modelAttribution, stringValue(payload.summary)]) ?? stringValue(payload.summary) ?? "No reflection summary"
    };
  }

  if (kind === "recoverable_issue") {
    const source = stringValue(payload.source) ?? "system";
    const operation = stringValue(payload.operation) ?? "operation";
    const repeats = numberValue(payload.suppressedSinceLastAudit);
    const message = plainRecoverableMessage(stringValue(payload.message) ?? operation);
    return {
      title: `${capitalize(source)} issue`,
      detail: joinDetail([
        message,
        stringValue(payload.fallback) ? `Fallback: ${stringValue(payload.fallback) ?? ""}` : undefined,
        repeats && repeats > 0 ? `${repeats} repeat${repeats === 1 ? "" : "s"} suppressed` : undefined
      ]) ?? operation
    };
  }

  if (kind === "candidates_considered") {
    const chosen = Array.isArray(payload.chosen) ? payload.chosen : [];
    const skipped = Array.isArray(payload.topSkipped) ? payload.topSkipped : [];
    const skippedSymbols = skipped
      .map((item) => asRecord(item))
      .map((item) => {
        const symbol = stringValue(item.symbol);
        const score = numberValue(item.score);
        return symbol ? `${symbol}${score !== undefined ? ` ${Math.round(score)}` : ""}` : undefined;
      })
      .filter(Boolean)
      .slice(0, 8)
      .join(", ");
    return {
      title: "Candidates considered",
      detail: joinDetail([
        `Chosen ${chosen.length}`,
        skipped.length > 0 ? `Top skipped: ${skippedSymbols || `${skipped.length} candidates`}` : "No skipped candidates",
        formatLlmSteps(payload.llmSteps)
      ]) ?? "No candidates recorded"
    };
  }

  if (kind === "signal_snapshot") {
    const signals = Array.isArray(payload.signals) ? payload.signals : [];
    const chosen = signals.filter((item) => asRecord(item).chosen === true).length;
    const asOf = stringValue(payload.asOf);
    return {
      title: "Signal snapshot",
      detail: joinDetail([
        `${signals.length} candidate signal${signals.length === 1 ? "" : "s"}`,
        chosen > 0 ? `${chosen} chosen` : "0 chosen",
        asOf ? `as of ${asOf}` : undefined
      ]) ?? "Signal evidence captured"
    };
  }

  if (kind === "rationale_diversity") {
    const count = numberValue(payload.count) ?? 0;
    const mean = numberValue(payload.meanPairwiseSimilarity);
    return {
      title: "Rationale diversity",
      detail: joinDetail([
        `${count} rationale${count === 1 ? "" : "s"} analyzed`,
        mean !== undefined ? `mean similarity ${mean.toFixed(2)}` : undefined,
        formatLlmSteps(payload.llmSteps)
      ]) ?? "Rationale check recorded"
    };
  }

  if (kind.startsWith("run_skipped_")) {
    const detail = genericAuditDetail(payload) ?? humanizeKind(kind);
    const fullDetail = genericAuditDetail(payload, { shortIds: false });
    return {
      title: "Strategy run skipped",
      detail,
      fullText: fullDetail && fullDetail !== detail ? fullDetail : undefined
    };
  }

  if (kind === "wash_sale_ira_disregarded") {
    // IRA rebuy proceeded under taxSettings.iraWashSaleHandling = "disregard" — surface the
    // verbatim annotation + priced provenance so the acceptance is visible in Activity.
    const symbol = stringValue(payload.symbol);
    const washSale = asRecord(payload.washSale);
    const note = stringValue(washSale.note) ?? "Wash Sale (Technically, but IRA purchase unreported to IRS)";
    const cost = numberValue(washSale.estimatedTaxCostUsd);
    const account = stringValue(washSale.account);
    return {
      title: `IRA wash sale disregarded${symbol ? ` — ${symbol}` : ""}`,
      detail:
        joinDetail([
          note,
          account ? `loss in ${account}` : undefined,
          cost !== undefined ? `~$${cost.toFixed(2)} deduction technically forfeited` : undefined
        ]) ?? note,
      fullText: serializeAuditPayload(payload)
    };
  }

  // ── Ops / housekeeping events: humanized one-liners (raw JSON only in fullText) ──

  if (kind === "web_source_refresh") {
    const id = stringValue(payload.id) ?? "web source";
    const label = WEB_SOURCE_LABELS[id] ?? id;
    const ok = payload.ok === true;
    const recordCount = numberValue(payload.recordCount) ?? 0;
    const fresh = numberValue(payload.fresh);
    const warning = stringValue(payload.warning) ?? stringValue(payload.reason);
    return {
      title: "Web source refresh",
      detail: ok
        ? joinDetail([
            `Refreshed ${recordCount} ${label} ${recordCount === 1 ? "entry" : "entries"}`,
            fresh !== undefined ? `${fresh} new` : undefined,
            warning
          ]) ?? `Refreshed ${label}`
        : joinDetail([`${capitalize(label)} refresh failed`, warning]) ?? `${capitalize(label)} refresh failed`,
      fullText: serializeAuditPayload(payload)
    };
  }

  if (kind === "congress_share_daily") {
    const ok = payload.ok === true;
    const reason = stringValue(payload.reason);
    const tickers = numberValue(payload.tickers) ?? 0;
    const priced = numberValue(payload.priced) ?? 0;
    const posts = numberValue(payload.posts) ?? 0;
    const failedPosts = numberValue(payload.failedPosts) ?? 0;
    return {
      title: "Congress daily share",
      detail:
        reason === "nothing-to-send"
          ? "Nothing to send today"
          : joinDetail([
              `${priced} of ${tickers} tickers priced`,
              `${posts} post${posts === 1 ? "" : "s"} sent`,
              failedPosts > 0 ? `${failedPosts} failed` : undefined,
              !ok && failedPosts === 0 ? "did not complete" : undefined
            ]) ?? "Daily share batch recorded",
      fullText: serializeAuditPayload(payload)
    };
  }

  if (kind === "notify.bridge.error") {
    const type = stringValue(payload.type);
    const errorMessage = stringValue(payload.error);
    return {
      title: "Notification delivery failed",
      detail: joinDetail([`Could not deliver ${type ?? "a"} notification`, errorMessage]) ?? "Could not deliver a notification",
      fullText: serializeAuditPayload(payload)
    };
  }

  if (kind === "connection_health_alert") {
    // Plain English instead of the scalar dump ("Key Source: none · User Id: local"):
    // say WHICH connection is failing and why; the raw payload stays on the toggle.
    const service = stringValue(payload.service);
    const errorText = stringValue(payload.errorText);
    const keySource = stringValue(payload.keySource);
    return {
      title: service ? `${capitalize(service)} connection is failing` : "A provider connection is failing",
      detail:
        joinDetail([
          errorText,
          keySource && keySource !== "none" ? `key from ${keySource}` : "no API key configured"
        ]) ?? "The server's health check could not reach this provider.",
      fullText: serializeAuditPayload(payload)
    };
  }

  // Unknown/unhandled audit kinds NEVER render raw JSON inline — the detail is either a
  // recognized generic field, up to 3 scalar payload fields as "Key: value" fragments, or a
  // plain "Event recorded". The full JSON payload stays available via the existing
  // RawToggle/fullText affordance.
  const serializedPayload = serializeAuditPayload(payload);
  const detail = genericAuditDetail(payload) ?? scalarFieldsDetail(payload) ?? "Event recorded";
  return {
    title: humanizeKind(kind),
    detail,
    fullText: serializedPayload ?? detail
  };
}

function proposalFromPayload(
  payload: Record<string, unknown>,
  getProposalById?: (proposalId: string) => { proposal: TradeProposal } | undefined
) {
  const nested = asRecord(payload.payload);
  const proposalId = stringValue(payload.proposalId) ?? stringValue(nested.proposalId);
  return proposalId && getProposalById ? getProposalById(proposalId) : undefined;
}

function firstReason(payload: Record<string, unknown>): string | undefined {
  const reason = stringValue(payload.reason);
  if (reason) return reason;
  const reasons = payload.reasons;
  if (Array.isArray(reasons)) {
    const first = reasons.find((item) => typeof item === "string");
    if (typeof first === "string") return first;
  }
  return undefined;
}

function notificationSymbol(payload: Record<string, unknown>): string | undefined {
  const nested = asRecord(payload.payload);
  const fill = asRecord(nested.fill);
  const proposal = asRecord(nested.proposal);
  return stringValue(fill.symbol) ?? stringValue(proposal.symbol) ?? symbolFromTitle(stringValue(payload.title));
}

function notificationSide(payload: Record<string, unknown>): string | undefined {
  const nested = asRecord(payload.payload);
  const fill = asRecord(nested.fill);
  const proposal = asRecord(nested.proposal);
  return stringValue(fill.side) ?? stringValue(proposal.side);
}

function symbolFromTitle(title?: string): string | undefined {
  if (!title) return undefined;
  const match = title.match(/\b[A-Z][A-Z0-9.-]{0,9}\b/);
  return match?.[0];
}

function normalizeSymbol(symbol?: string): string | undefined {
  const value = symbol?.trim().toUpperCase();
  return value ? value : undefined;
}

function normalizeSide(side?: string): "buy" | "sell" | undefined {
  return side === "buy" || side === "sell" ? side : undefined;
}

function sideLabel(side?: "buy" | "sell", symbol?: string): string | undefined {
  if (!symbol) return undefined;
  if (!side) return symbol;
  return `${side === "buy" ? "Buy" : "Sell"} ${symbol}`;
}

function capitalize(value: string): string {
  return value.length > 0 ? `${value[0]?.toUpperCase() ?? ""}${value.slice(1)}` : value;
}

function shortText(value: string): string {
  return value;
}

function stringValue(value: unknown): string | undefined {
  return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

function numberValue(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

/** Plain-English fallback for an audit kind with no dedicated branch above (e.g.
 *  "notify.prefs.set", "run_skipped_market_closed"). De-underscores, de-dots (namespaced kinds
 *  like "notification.delivery" or "watchlist.add" must never reach the UI as a raw
 *  `Foo.bar` string), and capitalizes just the leading letter (sentence case), matching the
 *  decided-vocabulary style used elsewhere in this file ("Web source refresh", "Trade
 *  blocked", ...) rather than every-word Title Case. */
function humanizeKind(kind: string): string {
  const spaced = kind.replace(/[._]+/g, " ");
  return spaced.length > 0 ? `${spaced[0]!.toUpperCase()}${spaced.slice(1)}` : spaced;
}

/** Title-Case de-underscore/de-camelCase for a payload field NAME used in a "Key: value"
 *  fragment (see `scalarFieldsDetail`) — e.g. "recordCount" -> "Record Count". Distinct from
 *  `humanizeKind`'s sentence-case treatment: field-name labels read as short header words. */
function titleCaseFieldKey(key: string): string {
  const spaced = key
    .replace(/_/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .trim();
  return spaced.replace(/\b\w/g, (char) => char.toUpperCase());
}

/** Last-resort detail for an unrecognized audit kind: up to 3 scalar (string/number/boolean)
 *  payload fields rendered as plain "Key: value" fragments — never the raw JSON blob. The raw
 *  payload stays available via `fullText` (see the catch-all return below). */
function scalarFieldsDetail(payload: Record<string, unknown>, limit = 3): string | undefined {
  const entries = Object.entries(payload).filter(
    ([, value]) => typeof value === "string" || typeof value === "number" || typeof value === "boolean"
  );
  if (entries.length === 0) return undefined;
  const fragments = entries.slice(0, limit).map(([key, value]) => `${titleCaseFieldKey(key)}: ${String(value)}`);
  return fragments.length > 0 ? fragments.join(" · ") : undefined;
}

/** Broker order ids get shortOrderLabel (src/lib/order-labels.ts); strategy run ids get the
 *  same short-tag treatment via this local mirror — order-labels.ts is scoped to broker order
 *  ids, and run ids are a different id space, so this stays a tiny local helper rather than a
 *  cross-import. Same deterministic, stateless first-8-chars-uppercase projection. */
function shortRunLabel(id: string): string {
  const cleaned = String(id ?? "")
    .replace(/[^a-zA-Z0-9]/g, "")
    .toUpperCase();
  if (cleaned.length === 0) return "?";
  if (cleaned.length < 8) return cleaned;
  return cleaned.slice(0, 8);
}

/** OrderType labels (decided vocabulary) for order/fill detail strings. A tiny local map rather
 *  than importing app/console/orders/lib.ts's orderTypeLabel — this is a server-shared lib and
 *  must not import from app/. */
const ORDER_TYPE_LABELS: Record<string, string> = {
  market: "Market",
  limit: "Limit",
  stop_market: "Stop-market",
  stop_limit: "Stop-limit"
};

function feedOrderTypeLabel(type?: string): string {
  if (!type) return "-";
  return ORDER_TYPE_LABELS[type] ?? humanizeKind(type);
}

/** Human names for the web-source connector ids used in `web_source_refresh` audits. */
const WEB_SOURCE_LABELS: Record<string, string> = {
  congress: "congressional-trade",
  "congress-analytics": "congressional-analytics",
  insider: "insider-filing (SEC Form 4)",
  finra: "short-interest (FINRA)",
  sec8k: "SEC 8-K filing",
  technical: "technical-signal"
};

/** Pure-ops audit kinds: background data refreshes and housekeeping that are not
 *  account decisions. The console collapses these into a "System" group. */
// Housekeeping/background kinds: bundled into the collapsed System bucket instead of one card
// each. notify.sent / notify.error / notification.delivery are channel-DELIVERY mechanics — the
// `notification` panel row (which carries the alert's content + status) still renders in the
// main feed; these are the per-channel webhook/email/push plumbing that used to add 2-4 rows per
// alert. notification.delivery in particular used to render as its own standalone
// "Notification.delivery" card duplicating the alert it belongs to (it carries no proposalId/
// runId to fold into that alert's group, so it needs its own ops-kind entry rather than
// piggybacking on another group's key).
export const OPS_AUDIT_KINDS = new Set([
  "web_source_refresh",
  "congress_share_daily",
  "notify.bridge.error",
  "notify.sent",
  "notify.error",
  "notification.delivery",
  "due_jobs_intraday_sample_drain",
  "vector_store",
  "recoverable_issue",
  "llm_cache_usage"
]);

/** Audit kinds that are a one-shot settings/preference log entry, not a lifecycle action with a
 *  real completion state — the standalone-group fallback below must not paint these with a
 *  misleading "Completed" chip (e.g. "Data pool consent — Completed" implies a finished process
 *  where there is none, just a toggle that was set). These groups render with no status chip at
 *  all (the console only draws a chip when `status` is non-empty). */
const STATUS_LESS_AUDIT_KINDS = new Set(["data_pool_consent"]);

/**
 * Consolidate ANY audit event that carries a `runId` into its `run-<runId>` group (owner request
 * 2026-07-08: an hour of activity showed 30-40 separate cards because only 5 allowlisted kinds
 * joined the run group while a real run emits 15+ runId-tagged kinds — rag_retrieval_status,
 * experience_retrieval, llm_call_latency, evidence_age_anomaly, socratic_outcome_job, …).
 * Grouping is generic-by-runId, so new run-scoped audit kinds bundle automatically instead of
 * needing an allowlist entry. Proposal-linked events still take `prop-<id>` precedence at the
 * call site, and the run card's title stays anchored on the `strategy_run` summary event.
 */
function runGroupIdForAudit(_kind: string, payload: Record<string, unknown>): string | undefined {
  const runId = stringValue(payload.runId);
  return runId ? `run-${runId}` : undefined;
}

function trimNumber(value: number): string {
  const decimals = Math.abs(value) >= 1 ? 3 : 4;
  return value.toFixed(decimals).replace(/0+$/, "").replace(/\.$/, "");
}

function trimCurrency(value: number): string {
  return `$${value.toFixed(2)}`;
}

function joinDetail(parts: Array<string | undefined>): string | undefined {
  const filtered = parts.filter(Boolean);
  return filtered.length > 0 ? filtered.join(" · ") : undefined;
}

/** `shortIds: false` (default true) spells out the full raw order/run id instead of the short
 *  tag — callers use that variant to build a distinct `fullText` so the complete id is never
 *  lost when the short-tag `detail` is shown. */
function genericAuditDetail(payload: Record<string, unknown>, options?: { shortIds?: boolean }): string | undefined {
  const details = asRecord(payload.details);
  const symbol = stringValue(payload.symbol) ?? stringValue(details.symbol);
  const side = stringValue(payload.side);
  const status = stringValue(payload.status);
  const operation = stringValue(payload.operation);
  const reason = stringValue(payload.reason);
  const summary = stringValue(payload.summary);
  const message = stringValue(payload.message);
  const error = stringValue(payload.error);
  const orderId = stringValue(payload.orderId);
  const runId = stringValue(payload.runId);
  const count = numberValue(payload.count) ?? numberValue(payload.recordCount) ?? numberValue(payload.candidateCount);
  const shortIds = options?.shortIds !== false;
  return joinDetail([
    reason,
    summary,
    message,
    error,
    operation,
    symbol ? [side, symbol].filter(Boolean).join(" ") : side,
    status ? `Status: ${feedStatusLabel(status)}` : undefined,
    orderId ? `Order ${shortIds ? shortOrderLabel(orderId) : orderId}` : undefined,
    count !== undefined ? `Count ${count}` : undefined,
    runId ? `Run ${shortIds ? shortRunLabel(runId) : runId}` : undefined
  ]);
}

function serializeAuditPayload(payload: Record<string, unknown>): string | undefined {
  if (Object.keys(payload).length === 0) return undefined;
  try {
    return JSON.stringify(payload);
  } catch {
    return undefined;
  }
}

function plainRecoverableMessage(message: string): string {
  if (/unexpected additional properties/i.test(message) && /validating/i.test(message)) {
    return "Robinhood rejected the quote request parameters.";
  }
  return message;
}

function formatLlmSteps(value: unknown): string | undefined {
  if (!Array.isArray(value) || value.length === 0) return undefined;
  const parts = value
    .map((item) => {
      const step = asRecord(item);
      const label = stringValue(step.label) ?? stringValue(step.step) ?? "LLM";
      const model = stringValue(step.model);
      const provider = stringValue(step.provider);
      const status = stringValue(step.status);
      if (!model && !provider) return undefined;
      const modelPart = model && provider ? `${model} via ${capitalize(provider)}` : model ?? provider;
      return `${label}: ${modelPart}${status && status !== "completed" ? ` (${status})` : ""}`;
    })
    .filter(Boolean);
  return parts.length > 0 ? parts.join(" · ") : undefined;
}

function readableBrokerState(state?: string): string {
  if (!state) return "Pending";
  return state.replace(/_/g, " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function isTerminalBrokerState(state?: string): boolean {
  return Boolean(state && ["canceled", "cancelled", "rejected", "failed", "expired"].includes(state));
}

function isPendingBrokerState(state?: string): boolean {
  const normalized = String(state ?? "").trim().toLowerCase();
  return isActiveBrokerOrderState(normalized) || ["done_for_day", "stopped", "calculated"].includes(normalized);
}

function brokerOrderDetail(order: EquityOrder | undefined, fillStatus?: string): string {
  if (!order) {
    if (fillStatus === "pending_reconciliation") return "Broker order accepted; awaiting broker status update.";
    if (fillStatus === "filled") return "Filled by broker.";
    if (fillStatus === "partially_filled") return "Partially filled by broker.";
    if (isTerminalBrokerState(fillStatus)) return `Broker reported ${readableBrokerState(fillStatus)}.`;
    return "Awaiting broker status update.";
  }
  const formattedFilled = formatQuantity(order.filledQuantity, normalizeSymbol(order.symbol));
  const formattedTotal = formatQuantity(order.quantity, normalizeSymbol(order.symbol));
  const prefix =
    fillStatus === "pending_reconciliation" && order.state === "filled"
      ? "Filled by broker; awaiting local reconciliation"
      : order.state === "filled"
      ? "Filled by broker"
      : order.state === "partially_filled"
        ? "Partially filled by broker"
        : isTerminalBrokerState(order.state)
          ? `Broker reported ${readableBrokerState(order.state)}`
          : "Accepted by broker; awaiting fill";
  return `${prefix}: ${readableBrokerState(order.state)} · Qty ${formattedFilled} / ${formattedTotal} · ${feedOrderTypeLabel(order.type)}`;
}

function brokerOrderTitle(order: EquityOrder): string {
  const side = order.side.toUpperCase();
  const symbol = normalizeSymbol(order.symbol);
  if (order.state === "filled") return `Order Filled: ${side} ${symbol}`;

  if (order.state === "partially_filled") return `Order Partially Filled: ${side} ${symbol}`;
  if (isTerminalBrokerState(order.state)) return `Order ${readableBrokerState(order.state)}: ${side} ${symbol}`;
  return `Order Submitted: ${side} ${symbol}`;
}

import { feedStatusLabel, formatNotificationDisplay, notificationStatusLabel, notificationTypeLabel } from "./dashboard-ui";

const KNOWN_GLOBAL_AUDIT_KINDS = new Set([
  "vector_store",
  "notify.sent",
  "notify.error",
  "congress_share_daily",
  "market_scan_failed",
  "regime_flip",
  "storage_warning_alert",
  "connection_health_alert",
  "consent",
  "prefs",
  "daily_cleanup"
]);

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" ? (value as Record<string, unknown>) : {};
}

export interface UnifiedActivitySubEvent {
  id: string;
  createdAt: string;
  type: "audit" | "notification" | "fill" | "order";
  title: string;
  detail: string;
  fullText?: string;
  status?: string;
  error?: string;
  raw?: unknown;
  count?: number;
}

export interface UnifiedActivityGroup {
  id: string;
  proposalId?: string;
  createdAt: string;
  updatedAt: string;
  symbol?: string;
  side?: "buy" | "sell";
  companyName?: string;
  title: string;
  detail: string;
  fullText?: string;
  status: string;
  tags: string[];
  events: UnifiedActivitySubEvent[];
  connectedAccountId?: string;
  accountLabel?: string;
  count?: number;
}

/** Source-level cap on the PROPOSAL-LESS unified-feed tail (fills with no proposal + notifications),
 *  which is render-only (client slices the rendered feed to 50). Proposal-bearing groups are never
 *  capped — the decision ledger reconciles their statuses for up to 100 recent proposals. */
export const UNIFIED_FEED_MAX_GROUPS = 60;

export function buildUnifiedFeed(input: {
  audit: SourceAuditEvent[];
  notifications: NotificationEvent[];
  fills: FillEvent[];
  orders: EquityOrder[];
  symbolMetaBySymbol: Record<string, SymbolMeta>;
  accountLabelById?: Record<string, string>;
  getProposalById?: (proposalId: string) => { proposal: TradeProposal } | undefined;
}): UnifiedActivityGroup[] {
  const symbolMetaBySymbol = input.symbolMetaBySymbol ?? {};
  const accountLabelById = input.accountLabelById ?? {};
  const proposalIdByOrderId: Record<string, string> = {};

  // Build mapping of order_id to proposal_id from fills
  for (const fill of input.fills) {
    if (fill.proposalId && fill.brokerOrderId) {
      proposalIdByOrderId[fill.brokerOrderId] = fill.proposalId;
    }
  }

  // Build mapping from audit events
  for (const event of input.audit) {
    if (event.kind === "proposal_approved") {
      const payload = asRecord(event.payload);
      const proposalId = stringValue(payload.proposalId);
      const orderId = stringValue(payload.orderId);
      if (proposalId && orderId) {
        proposalIdByOrderId[orderId] = proposalId;
      }
    }
  }

  const groupEvents: Record<string, UnifiedActivitySubEvent[]> = {};

  const addSubEvent = (groupId: string, subEvent: UnifiedActivitySubEvent) => {
    if (!groupEvents[groupId]) groupEvents[groupId] = [];
    groupEvents[groupId].push(subEvent);
  };

  const proposalIdByGroupId = new Map<string, string>();
  const symbolByGroupId = new Map<string, string>();
  const sideByGroupId = new Map<string, "buy" | "sell" | undefined>();
  const accountIdByGroupId = new Map<string, string>();

  // Helper to extract symbol and side from a proposal lookup
  const lookupProposalInfo = (proposalId: string) => {
    if (input.getProposalById) {
      const lookup = input.getProposalById(proposalId);
      if (lookup?.proposal) {
        return {
          symbol: normalizeSymbol(lookup.proposal.symbol),
          side: normalizeSide(lookup.proposal.side)
        };
      }
    }
    return {};
  };

  // 1. Process Audit Events
  for (const event of input.audit) {
    if (event.kind === "notification") {
      continue;
    }

    const payload = asRecord(event.payload);
    const proposalId = getProposalIdFromAudit(event);

    let symbol = normalizeSymbol(stringValue(payload.symbol));
    let side = normalizeSide(stringValue(payload.side));

    if (proposalId) {
      const pInfo = lookupProposalInfo(proposalId);
      if (pInfo.symbol) symbol = pInfo.symbol;
      if (pInfo.side) side = pInfo.side;
    }

    const companyName = symbol ? symbolMetaBySymbol[symbol]?.companyName : undefined;
    const feed = formatAuditEvent(event.kind, payload, { symbol, side, companyName });

    const subEvent: UnifiedActivitySubEvent = {
      id: event.id,
      createdAt: event.createdAt,
      type: "audit",
      title: feed.title,
      detail: feed.detail,
      fullText: feed.fullText ?? feed.detail,
      raw: { kind: event.kind }
    };

    // Run-scoped events (run completed / rationale diversity / candidates considered /
    // signal snapshot / llm steps) consolidate into ONE `run-<runId>` group instead of
    // one card each (#8). Everything else without a proposal stays its own group.
    const groupId = proposalId ? `prop-${proposalId}` : runGroupIdForAudit(event.kind, payload) ?? `audit-${event.id}`;
    if (proposalId) {
      proposalIdByGroupId.set(groupId, proposalId);
    }
    if (symbol) symbolByGroupId.set(groupId, symbol);
    if (side) sideByGroupId.set(groupId, side);
    if (event.connectedAccountId) accountIdByGroupId.set(groupId, event.connectedAccountId);

    // P3 #1: Coalesce consecutive identical audit events (feed storm resilience)
    const existingGroup = groupEvents[groupId];
    const lastSubEvent = existingGroup ? existingGroup[existingGroup.length - 1] : undefined;
    if (
      lastSubEvent &&
      lastSubEvent.type === "audit" &&
      (lastSubEvent.raw as any)?.kind === event.kind &&
      lastSubEvent.detail === feed.detail
    ) {
      lastSubEvent.count = (lastSubEvent.count ?? 1) + 1;
      // Bring timestamp forward to most recent
      lastSubEvent.createdAt = event.createdAt;
      lastSubEvent.id = event.id;
    } else {
      addSubEvent(groupId, subEvent);
    }
  }

  // 2. Process Notification Events
  for (const event of input.notifications) {
    const payload = asRecord(event.payload);
    const proposalId = getProposalIdFromNotification(event);

    const display = formatNotificationDisplay(event, symbolMetaBySymbol);

    let symbol = normalizeSymbol(display.symbol);
    let side = normalizeSide(stringValue(asRecord(payload.fill).side) ?? stringValue(asRecord(payload.proposal).side));

    if (proposalId) {
      const pInfo = lookupProposalInfo(proposalId);
      if (pInfo.symbol) symbol = pInfo.symbol;
      if (pInfo.side) side = pInfo.side;
    }

    const subEvent: UnifiedActivitySubEvent = {
      id: event.id,
      createdAt: event.createdAt,
      type: "notification",
      title: display.title,
      detail: display.detail,
      status: event.status,
      error: event.error,
      raw: event.payload
    };

    // Precedence: proposal group > run group > standalone. Run-scoped alerts ("Sell MU blocked",
    // "run failed", "Red Team routed to human") carry a runId in their payload — folding them into
    // the run card removes the 2-3 sibling rows that always appeared next to every run entry.
    const notifRunId = stringValue(payload.runId);
    const groupId = proposalId ? `prop-${proposalId}` : notifRunId ? `run-${notifRunId}` : `notif-${event.id}`;
    if (proposalId) {
      proposalIdByGroupId.set(groupId, proposalId);
    }
    if (symbol) symbolByGroupId.set(groupId, symbol);
    if (side) sideByGroupId.set(groupId, side);
    // Notifications are USER-wide rows: carry their account attribution onto the group so
    // another account's proposal/fill alerts can be filtered out of this account's feed (#10).
    if (event.connectedAccountId) accountIdByGroupId.set(groupId, event.connectedAccountId);

    addSubEvent(groupId, subEvent);
  }

  // 3. Process Fill Events
  for (const fill of input.fills) {
    const proposalId = fill.proposalId ?? undefined;
    const symbol = normalizeSymbol(fill.symbol);
    const side = normalizeSide(fill.side);

    const formattedQty = formatQuantity(fill.quantity, symbol);
    const subEvent: UnifiedActivitySubEvent = {
      id: fill.id,
      createdAt: fill.filledAt,
      type: "fill",
      title: `${fill.source === "paper" ? "Paper " : ""}${fill.side.toUpperCase()} ${fill.symbol}`,
      detail: fill.status === "pending_reconciliation"
        ? `${formattedQty} shares reviewed @ ${trimCurrency(fill.price)} · broker order pending execution`
        : `${formattedQty} shares @ ${trimCurrency(fill.price)} · ${feedStatusLabel(fill.status)}`,
      status: fill.status,
      raw: fill.raw
    };

    const groupId = proposalId ? `prop-${proposalId}` : `fill-${fill.id}`;
    if (proposalId) {
      proposalIdByGroupId.set(groupId, proposalId);
    }
    if (symbol) symbolByGroupId.set(groupId, symbol);
    if (side) sideByGroupId.set(groupId, side);

    addSubEvent(groupId, subEvent);
  }

  // 4. Process Broker Orders
  for (const order of input.orders) {
    const proposalId = proposalIdByOrderId[order.id];
    const symbol = normalizeSymbol(order.symbol);
    const side = normalizeSide(order.side);

    const formattedFilled = formatQuantity(order.filledQuantity, symbol);
    const formattedTotal = formatQuantity(order.quantity, symbol);
    const subEvent: UnifiedActivitySubEvent = {
      id: order.id,
      createdAt: order.createdAt,
      type: "order",
      title: brokerOrderTitle(order),
      detail: `Broker state: ${readableBrokerState(order.state)} · Qty ${formattedFilled} / ${formattedTotal} · ${feedOrderTypeLabel(order.type)}`,
      status: order.state,
      raw: order
    };

    const groupId = proposalId ? `prop-${proposalId}` : `order-${order.id}`;
    if (proposalId) {
      proposalIdByGroupId.set(groupId, proposalId);
    }
    if (symbol) symbolByGroupId.set(groupId, symbol);
    if (side) sideByGroupId.set(groupId, side);

    addSubEvent(groupId, subEvent);
  }

  const unifiedGroups: UnifiedActivityGroup[] = [];

  for (const [groupId, events] of Object.entries(groupEvents)) {
    events.sort((a, b) => a.createdAt.localeCompare(b.createdAt));

    const earliestDate = events[0]!.createdAt;
    const latestDate = events[events.length - 1]!.createdAt;

    const proposalId = proposalIdByGroupId.get(groupId);
    const symbol = symbolByGroupId.get(groupId);
    const side = sideByGroupId.get(groupId);
    const companyName = symbol ? symbolMetaBySymbol[symbol]?.companyName : undefined;
    const connectedAccountId = accountIdByGroupId.get(groupId);
    let accountLabel = connectedAccountId ? accountLabelById[connectedAccountId] : undefined;

    const tagsSet = new Set<string>();
    for (const ev of events) {
      if (ev.count && ev.count > 1) {
        ev.title = `${ev.title} (x${ev.count})`;
      }
      if (ev.type === "audit") {
        const rawAud = asRecord(ev.raw);
        const audKind = stringValue(rawAud.kind) ?? "";
        if (!accountLabel && KNOWN_GLOBAL_AUDIT_KINDS.has(audKind)) {
          accountLabel = "System-wide";
        }
        if (audKind === "policy_change" || audKind === "profile_change") {
          tagsSet.add("policy change");
        }
        if (audKind === "fill_reconciled") {
          tagsSet.add("trade");
        }
        if (audKind === "post_mortem_reflection") {
          tagsSet.add("post mortem");
        }
      }
      if (ev.type === "fill") {
        tagsSet.add("trade");
      }
      if (ev.type === "notification") {
        const nStatus = ev.status;
        if (nStatus === "sent") {
          tagsSet.add("notification sent");
        } else if (nStatus === "failed") {
          tagsSet.add("notification failed");
        } else if (nStatus === "skipped") {
          tagsSet.add("notification disabled");
        }
        const nRaw = asRecord(ev.raw);
        if (stringValue(nRaw.type) === "fill") {
          tagsSet.add("trade");
        }
      }
    }

    if (side === "buy") { tagsSet.add("buy"); tagsSet.add("trade"); }
    if (side === "sell") { tagsSet.add("sell"); tagsSet.add("trade"); }

    let status = "unknown";
    let title = "";
    let detail = "";

    if (proposalId) {
      const hasFill = events.find(ev => ev.type === "fill");
      const hasOrder = events.find(ev => ev.type === "order") as UnifiedActivitySubEvent | undefined;
      const hasApproval = events.find(ev => ev.type === "audit" && ev.title.includes("Approved"));
      const hasBrokerRejection = events.find(ev => ev.type === "audit" && asRecord(ev.raw).kind === "order_rejected_by_broker");
      const hasRejection = events.find(ev => ev.type === "audit" && ev.title.includes("Rejected"));
      const hasBlock = events.find(ev => ev.type === "notification" && ev.title.includes("Blocked"));
      const hasPendingApproval = events.find(ev => ev.type === "notification" && ev.title.includes("Approval Pending"));
      const order = hasOrder?.raw as EquityOrder | undefined;

      if (hasFill) {
        if (hasFill.status === "filled") {
          status = "filled";
        } else if (hasFill.status === "pending_reconciliation") {
          status = "pending_order";
        } else if (order?.state === "filled") {
          status = "filled";
        } else if (order?.state === "partially_filled") {
          status = "partially_filled";
        } else if (isTerminalBrokerState(order?.state)) {
          status = order!.state;
        } else if (isPendingBrokerState(order?.state) || hasFill.status === "pending_reconciliation") {
          status = "pending_order";
        } else {
          status = hasFill.status ?? "pending_order";
        }
      } else if (order?.state === "filled") {
        status = "filled";
      } else if (order?.state === "partially_filled") {
        status = "partially_filled";
      } else if (isTerminalBrokerState(order?.state)) {
        status = order!.state;
      } else if (isPendingBrokerState(order?.state)) {
        status = "pending_order";
      } else if (hasBrokerRejection) {
        status = "rejected";
      } else if (hasRejection) {
        status = "rejected";
      } else if (hasApproval) {
        status = "approved";
      } else if (hasBlock) {
        status = "blocked";
      } else if (hasPendingApproval) {
        status = "pending_approval";
      } else {
        status = "pending";
      }

      // An account is an account: a fill's own `source` ("paper"/"live", stamped at the FillEvent
      // level — see "Process Fill Events" above) is the sole signal for whether this group is a
      // broker-paper trade. It is never rewritten to "Test" — that execution mode no longer exists,
      // and broker-paper is not "the same as Test", it is a real broker-hosted sandbox account.
      const isPaper = events.some(ev => ev.type === "fill" && ev.title.startsWith("Paper "));

      // Group title mirrors the broker-style fill/order title casing (uppercase side),
      // distinct from the title-case used by individual notification/audit sub-events.
      const displaySide = side === "buy" ? "BUY" : side === "sell" ? "SELL" : "Trade";
      title = `${isPaper ? "Paper " : ""}${displaySide} ${symbol}`;

      if (status === "filled") {

        const fillEv = events.find(ev => ev.type === "fill" && ev.status === "filled")!;
        detail = fillEv.detail;
      } else if (status === "pending_reconciliation") {
        const fillEv = events.find(ev => ev.type === "fill")!;
        detail = `Pending Broker Order: ${fillEv.detail}`;
      } else if ((hasFill || hasOrder) && (status === "pending_order" || status === "partially_filled" || isTerminalBrokerState(status))) {
        detail = brokerOrderDetail(order, hasFill?.status);
      } else if (status === "rejected" && hasBrokerRejection) {
        detail = hasBrokerRejection.detail;
      } else if (status === "rejected") {
        detail = "Rejected manually";
      } else if (status === "approved") {
        const appEv = events.find(ev => ev.type === "audit" && ev.title.includes("Approved"))!;
        detail = appEv.detail;
      } else if (status === "blocked") {
        const blkEv = events.find(ev => ev.type === "notification" && ev.title.includes("Blocked"))!;
        detail = blkEv.detail;
      } else if (status === "pending_approval") {
        detail = "Awaiting Approval";
      } else {
        detail = events[0]!.detail;
      }
    } else if (groupId.startsWith("run-")) {
      // Consolidated strategy-run card (#8): the strategy_run event is the primary
      // (title + summary rendered ONCE); diversity/candidates/signal-snapshot rows
      // stay visible as sub-rows. Falls back to the first event if the run summary
      // audit aged out of the window.
      const primary = events.find(
        (ev) => ev.type === "audit" && stringValue(asRecord(ev.raw).kind) === "strategy_run"
      );
      const anchor = primary ?? events[0]!;
      title = anchor.title;
      detail = anchor.detail;
      status = primary ? (primary.title.toLowerCase().includes("failed") ? "failed" : "completed") : events[0]!.status ?? "completed";
    } else {
      title = events[0]!.title;
      detail = events[0]!.detail;
      // Audit rows carry no status of their own; the old blanket "completed" default
      // painted a green chip on rows literally titled "Market scan failed". Derive
      // failure from the title when the event has no explicit status. A settings/preference
      // log entry (STATUS_LESS_AUDIT_KINDS) isn't a lifecycle action either way, so it gets no
      // chip at all rather than a fabricated "Completed".
      const soleAuditKind =
        events[0]!.type === "audit" ? stringValue(asRecord(events[0]!.raw).kind) ?? "" : "";
      status =
        events[0]!.status ??
        (STATUS_LESS_AUDIT_KINDS.has(soleAuditKind)
          ? ""
          : title.toLowerCase().includes("failed") || title.toLowerCase().includes("error")
            ? "failed"
            : "completed");
    }
    // Single-event groups surface the sub-event's fullText (e.g. an ops event's raw
    // JSON payload) so the client can offer a raw-data toggle; grouped cards keep the
    // summary as fullText.
    const groupFullText = proposalId || groupId.startsWith("run-") ? detail : events[0]!.fullText ?? detail;

    // Tags are ONLY what the events themselves earned. Two removed forcing blocks used
    // to blanket-push "notification failed" onto every non-policy group and a "paper"
    // tag onto EVERY group ("Live is not tested yet") — fabricated labels on real data,
    // which the product rules forbid (never mislabel real activity).
    const tagsList = Array.from(tagsSet);

    unifiedGroups.push({
      id: groupId,
      proposalId,
      createdAt: earliestDate,
      updatedAt: latestDate,
      symbol,
      side,
      companyName,
      title,
      detail,
      fullText: groupFullText,
      status,
      tags: tagsList,
      events,
      connectedAccountId,
      accountLabel
    });
  }

  // Bound the shipped payload WITHOUT changing observable output.
  const sorted = unifiedGroups.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));

  // Feed-storm coalescing: merge adjacent identical proposal-less groups
  const coalesced: UnifiedActivityGroup[] = [];
  for (const group of sorted) {
    const prev = coalesced[coalesced.length - 1];
    if (
      prev &&
      !prev.proposalId &&
      !group.proposalId &&
      prev.title === group.title &&
      prev.status === group.status &&
      prev.accountLabel === group.accountLabel &&
      Math.abs(new Date(prev.updatedAt).getTime() - new Date(group.updatedAt).getTime()) < 24 * 60 * 60 * 1000
    ) {
      prev.count = (prev.count || 1) + 1;
      prev.events.push(...group.events);
    } else {
      coalesced.push(group);
    }
  }

  for (const group of coalesced) {
    if (group.count && group.count > 1) {
      group.title = `${group.title} (x${group.count})`;
    }
  }

  const withProposal = coalesced.filter((g) => g.proposalId);
  const withoutProposal = coalesced.filter((g) => !g.proposalId).slice(0, UNIFIED_FEED_MAX_GROUPS);
  return [...withProposal, ...withoutProposal].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
}

function getProposalIdFromAudit(event: SourceAuditEvent): string | undefined {
  const payload = asRecord(event.payload);
  const nested = asRecord(payload.payload);
  return (
    stringValue(payload.proposalId) ??
    stringValue(nested.proposalId)
  );
}

function getProposalIdFromNotification(event: NotificationEvent): string | undefined {
  const payload = asRecord(event.payload);
  const fill = asRecord(payload.fill);
  const proposal = asRecord(payload.proposal);
  return (
    stringValue(payload.proposalId) ??
    stringValue(fill.proposalId) ??
    stringValue(proposal.id) ??
    stringValue(proposal.proposalId)
  );
}

