// ── Take-profit trim ratchet ────────────────────────────────────────────────
// Monotonic "band" already trimmed per open profitable position, so a partial take-profit trims once
// per take-profit band instead of laddering out every run. See take_profit_trims (db.ts migrate()).

export interface TakeProfitTrimBand {
  /** Highest take-profit band already trimmed for the lot. */
  band: number;
  /** Position cost basis when the band was recorded — ratchet resets when the live basis differs (rebuy). */
  avgCost: number;
}

/** Map of symbol → {band, avgCost} of the highest already-trimmed take-profit band (empty when none). */
export function getTakeProfitTrimBands(accountNumber: string, userId: string = "local"): Record<string, TakeProfitTrimBand> {
  const rows = getDb()
    .prepare("SELECT symbol, band, avg_cost FROM take_profit_trims WHERE user_id = ? AND account_number = ?")
    .all(userId, accountNumber) as Array<{ symbol: string; band: number; avg_cost: number }>;
  const out: Record<string, TakeProfitTrimBand> = {};
  for (const r of rows) out[r.symbol] = { band: Number(r.band) || 0, avgCost: Number(r.avg_cost) || 0 };
  return out;
}

/** Record (upsert) the highest take-profit band trimmed for a position lot (band + its cost basis). */
export function recordTakeProfitTrimBand(
  accountNumber: string,
  symbol: string,
  band: number,
  avgCost: number,
  userId: string = "local",
  now: string = new Date().toISOString()
): void {
  getDb()
    .prepare(
      `INSERT INTO take_profit_trims (user_id, account_number, symbol, band, avg_cost, updated_at)
       VALUES (?, ?, ?, ?, ?, ?)
       ON CONFLICT(user_id, account_number, symbol)
       DO UPDATE SET band = excluded.band, avg_cost = excluded.avg_cost, updated_at = excluded.updated_at`
    )
    .run(userId, accountNumber, symbol, Math.max(0, Math.floor(band)), Number.isFinite(avgCost) ? avgCost : 0, now);
}

/** Clear ratchet state for the given symbols (e.g. positions that have closed). No-op on empty input. */
export function clearTakeProfitTrimBands(accountNumber: string, symbols: string[], userId: string = "local"): void {
  if (symbols.length === 0) return;
  const placeholders = symbols.map(() => "?").join(",");
  getDb()
    .prepare(`DELETE FROM take_profit_trims WHERE user_id = ? AND account_number = ? AND symbol IN (${placeholders})`)
    .run(userId, accountNumber, ...symbols);
}

// ── Per-position stop plan ──────────────────────────────────────────────────
// The LLM's chosen stop-loss TYPE for an open position, set at opening-fill time and read by every
// stop-enforcement layer for the position's life. Modeled directly on the take-profit trim ratchet
// above. See position_stop_plans (db.ts migrate()).

export interface PositionStopPlan {
  style: StopPlanStyle;
  rationale?: string;
  /** Position cost basis when the plan was recorded — resets on a close+rebuy (different lot). */
  avgCost: number;
  /**
   * Direction of the lot the plan was recorded against — "long" for an opening buy, "short" for an
   * opening short. Compared alongside avgCost by filterFullStopPlansByLiveBasis so a long's plan can
   * never leak onto a short opened later in the same symbol at a coincidentally similar basis (or
   * vice versa) — closing a long and shorting the same name is a distinct lot, not a continuation
   * (Codex review, PR #1371). Optional only for backward-compat with rows written before this field
   * existed; such a row never matches any live position (side is undefined) and simply ages out via
   * the normal stale-plan cleanup.
   */
  side?: "long" | "short";
  /**
   * Order ID of the MOST RECENT broker-native bracket (Alpaca order_class "bracket", Tradier
   * "otoco") placed while this plan's style has sat at "fixed"/"atr" — undefined for
   * trailing/none/default, or on an account/broker without native bracket support. Display-only —
   * a same-style scale-in places an ADDITIONAL bracket without replacing an earlier one, so this
   * single field can't represent (and is not used to drive) sibling-leg teardown; that's tracked
   * separately, across ALL brackets for the symbol, in position_stop_plan_open_brackets (see
   * trackOpenBracketOrder/enqueueTeardownForAllOpenBrackets and pending_bracket_teardowns in db.ts).
   */
  openingOrderId?: string;
}

/** Map of symbol → its recorded per-position stop plan (empty when none set — every position then
 *  falls back to the account's default stop precedence, unchanged from before this feature). */
export function getStopPlans(accountNumber: string, userId: string = "local"): Record<string, PositionStopPlan> {
  const rows = getDb()
    .prepare("SELECT symbol, style, rationale, avg_cost, side, opening_order_id FROM position_stop_plans WHERE user_id = ? AND account_number = ?")
    .all(userId, accountNumber) as Array<{ symbol: string; style: string; rationale: string | null; avg_cost: number; side: string | null; opening_order_id: string | null }>;
  const out: Record<string, PositionStopPlan> = {};
  for (const r of rows) {
    const style = (STOP_PLAN_STYLES as readonly string[]).includes(r.style) ? (r.style as StopPlanStyle) : "default";
    out[r.symbol] = {
      style,
      rationale: r.rationale ?? undefined,
      avgCost: Number(r.avg_cost) || 0,
      side: r.side === "long" || r.side === "short" ? r.side : undefined,
      openingOrderId: r.opening_order_id ?? undefined
    };
  }
  return out;
}

/**
 * Filter the account's persisted per-position stop plans down to the ones that actually apply to
 * the CURRENT lot. Ratchet-style basis check (mirrors planTakeProfitTrims' lastBand-keyed-to-avgCost
 * pattern): a persisted plan only counts if its recorded avgCost still matches the LIVE position's
 * averageCost. Without this, a symbol closed and re-bought before any run ever observed it flat
 * (e.g. a fast broker/manual close+reopen the app's own clearStopPlans sweep never caught between
 * ticks) could have its stale "none"/"trailing"/fixed plan silently govern a completely different
 * lot (Codex review, PR #1371). A symbol with no CURRENT position at all has no basis to compare and
 * is skipped too — a persisted row only ever makes sense for a scale-in add to an already-open
 * position. Colocated here (not in strategy.ts, which re-exports it) so both strategy.ts and
 * synthetic-stops.ts can share it without depending on each other.
 */
export function filterStopPlansByLiveBasis(
  plans: Record<string, PositionStopPlan>,
  positions: EquityPosition[]
): Record<string, StopPlanStyle> {
  const out: Record<string, StopPlanStyle> = {};
  for (const [sym, plan] of Object.entries(filterFullStopPlansByLiveBasis(plans, positions))) {
    out[sym] = plan.style;
  }
  return out;
}

/**
 * Same live-basis filter as `filterStopPlansByLiveBasis`, but preserves the FULL `PositionStopPlan`
 * (rationale + avgCost included) rather than narrowing to just the style — for a display-only
 * consumer (the dashboard/Positions table) that needs the rationale text too, not just the
 * enforcement-relevant style (Codex review, PR #1371: the dashboard read `getStopPlans` directly,
 * unfiltered, so it could still label a closed-and-rebought symbol's NEW position with the OLD
 * lot's plan).
 */
export function filterFullStopPlansByLiveBasis(
  plans: Record<string, PositionStopPlan>,
  positions: EquityPosition[]
): Record<string, PositionStopPlan> {
  const liveBySymbol = new Map(
    positions
      .filter((p) => Math.abs(p.quantity) > 0.000001)
      .map((p) => [normalizeSymbol(p.symbol), { avgCost: p.averageCost, side: (p.quantity > 0 ? "long" : "short") as "long" | "short" }])
  );
  const out: Record<string, PositionStopPlan> = {};
  for (const [sym, plan] of Object.entries(plans)) {
    if (plan.style === "default") continue;
    const s = normalizeSymbol(sym);
    const live = liveBySymbol.get(s);
    if (!live) continue;
    if (Math.abs(plan.avgCost - live.avgCost) >= 0.005) continue;
    // A plan recorded before the `side` field existed (undefined) can't be verified against the
    // live position's direction — treat as a mismatch (skip) rather than assume a match, since a
    // false "match" is exactly the stale-plan-leak this filter exists to prevent.
    if (plan.side !== live.side) continue;
    out[s] = plan;
  }
  return out;
}

/**
 * Track a broker-native bracket order placed while a "fixed"/"atr" plan is active for a symbol —
 * appended to `position_stop_plan_open_brackets`, NOT overwriting anything. A same-style scale-in
 * (e.g. "fixed" -> "fixed") places a BRAND-NEW, independently-resting bracket sized ONLY to its own
 * added shares (Alpaca: orderArgs.qty from that order's own quantity; Tradier: each exit leg sized
 * to that order's wholeQty) — it does NOT replace or resize the PRIOR bracket, which is still the
 * genuine, still-needed protection for the pre-existing lot. So every distinct bracket order id gets
 * its own row here, and NONE of them are torn down until the whole family is (see
 * enqueueTeardownForAllOpenBrackets) — tearing down a same-style scale-in's prior bracket would
 * cancel a live, correct stop-loss/take-profit and leave that earlier lot with NO protection at all
 * (Codex review, PR #1667, catching an incomplete first attempt at this same fix). Never throws:
 * plan bookkeeping must never block the write that's actually recording the plan. De-duplicates on
 * (symbol, order_id) so a retried/replayed fill-recording call can't double-track the same bracket.
 */
function trackOpenBracketOrder(accountNumber: string, symbol: string, userId: string, orderId: string): void {
  try {
    const already = getDb()
      .prepare(
        `SELECT 1 FROM position_stop_plan_open_brackets WHERE user_id = ? AND account_number = ? AND symbol = ? AND order_id = ?`
      )
      .get(userId, accountNumber, symbol, orderId);
    if (already) return;
    getDb()
      .prepare(
        `INSERT INTO position_stop_plan_open_brackets (id, user_id, account_number, symbol, order_id, created_at)
         VALUES (?, ?, ?, ?, ?, ?)`
      )
      .run(crypto.randomUUID(), userId, accountNumber, symbol, orderId, new Date().toISOString());
  } catch {
    // best-effort — a missed tracking row leaves that one bracket forever untracked for future
    // teardown, but never breaks the plan write itself
  }
}

/**
 * Enqueues a teardown (via pending_bracket_teardowns, reconciler in broker-protective-stops.ts) for
 * EVERY broker-native bracket ever tracked for this symbol while it sat in the fixed/atr family — not
 * just the latest — then clears the tracking rows. Called ONLY when the plan genuinely LEAVES the
 * fixed/atr family entirely (a real style change to trailing/none/default, or the position closes),
 * never on a same-style scale-in (see trackOpenBracketOrder's doc comment for why). Never throws.
 */
function enqueueTeardownForAllOpenBrackets(accountNumber: string, symbol: string, userId: string): void {
  try {
    const rows = getDb()
      .prepare(`SELECT order_id FROM position_stop_plan_open_brackets WHERE user_id = ? AND account_number = ? AND symbol = ?`)
      .all(userId, accountNumber, symbol) as Array<{ order_id: string }>;
    if (rows.length === 0) return;
    const db = getDb();
    const insertTeardown = db.prepare(
      `INSERT INTO pending_bracket_teardowns (id, user_id, account_number, symbol, order_id, created_at, attempts)
       VALUES (?, ?, ?, ?, ?, ?, 0)`
    );
    const now = new Date().toISOString();
    for (const row of rows) {
      insertTeardown.run(crypto.randomUUID(), userId, accountNumber, symbol, row.order_id, now);
    }
    db.prepare(`DELETE FROM position_stop_plan_open_brackets WHERE user_id = ? AND account_number = ? AND symbol = ?`)
      .run(userId, accountNumber, symbol);
  } catch {
    // best-effort — a missed teardown enqueue leaves resting bracket legs for a human/later sweep
    // to notice, never breaks the plan write itself
  }
}

/**
 * Record (upsert) the stop plan for a position lot. Invalid/unrecognized styles fall back to
 * "default". `openingOrderId` should be set ONLY when this write is establishing a fresh "fixed"/
 * "atr" plan whose opening fill placed a broker-native bracket (Alpaca/Tradier) — omitted for
 * trailing/none/default, or when no bracket was placed. When this write is landing IN the
 * fixed/atr family, the bracket order id is tracked (never torn down by itself — see
 * trackOpenBracketOrder). When this write is a genuine transition OUT of the fixed/atr family,
 * every bracket ever tracked for this symbol is enqueued for teardown together (see
 * enqueueTeardownForAllOpenBrackets).
 */
export function recordStopPlan(
  accountNumber: string,
  symbol: string,
  style: string,
  rationale: string | undefined,
  avgCost: number,
  userId: string = "local",
  now: string = new Date().toISOString(),
  side: "long" | "short" = "long",
  openingOrderId?: string
): void {
  const safeStyle = (STOP_PLAN_STYLES as readonly string[]).includes(style) ? style : "default";
  if (safeStyle === "fixed" || safeStyle === "atr") {
    // A "fixed" <-> "atr" transition is DELIBERATELY treated the same as a same-style scale-in —
    // never torn down here. A codex-autofix run on this PR briefly added a teardown for exactly
    // this transition (mirroring Codex's own suggested remedy), but that's a real regression, not
    // a fix: a fixed and an atr bracket are computed differently, but mechanically they're the
    // SAME kind of thing — an independent broker-native bracket sized ONLY to its own lot's
    // quantity, with nothing else ever recreating equivalent protection for an earlier lot.
    // Tearing down the earlier tracked bracket on a fixed<->atr transition would cancel a still-
    // resting, still-valid stop-loss/take-profit for the pre-existing shares, leaving them with NO
    // protection at all — reintroducing the exact P1 this whole redesign exists to prevent. See the
    // reasoning posted on PR #1667's review thread. Teardown fires ONLY when the plan genuinely
    // LEAVES the whole distance-bracket family (trailing/none/default, or close) — that's the only
    // time nothing else is still relying on the old brackets.
    if (openingOrderId) trackOpenBracketOrder(accountNumber, symbol, userId, openingOrderId);
  } else {
    enqueueTeardownForAllOpenBrackets(accountNumber, symbol, userId);
  }
  getDb()
    .prepare(
      `INSERT INTO position_stop_plans (user_id, account_number, symbol, style, rationale, avg_cost, updated_at, side, opening_order_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(user_id, account_number, symbol)
       DO UPDATE SET style = excluded.style, rationale = excluded.rationale, avg_cost = excluded.avg_cost, updated_at = excluded.updated_at, side = excluded.side, opening_order_id = excluded.opening_order_id`
    )
    .run(userId, accountNumber, symbol, safeStyle, rationale ?? null, Number.isFinite(avgCost) ? avgCost : 0, now, side, openingOrderId ?? null);
}

/** Clear stop plans for the given symbols (e.g. positions that have closed). No-op on empty input.
 *  A closed position needs every bracket ever tracked for it torn down (see
 *  enqueueTeardownForAllOpenBrackets), regardless of what style it was last recorded at. */
export function clearStopPlans(accountNumber: string, symbols: string[], userId: string = "local"): void {
  if (symbols.length === 0) return;
  const placeholders = symbols.map(() => "?").join(",");
  for (const symbol of symbols) {
    enqueueTeardownForAllOpenBrackets(accountNumber, symbol, userId);
  }
  getDb()
    .prepare(`DELETE FROM position_stop_plans WHERE user_id = ? AND account_number = ? AND symbol IN (${placeholders})`)
    .run(userId, accountNumber, ...symbols);
}

/** A bracket teardown queued by enqueueTeardownForAllOpenBrackets, awaiting the sweep. */
export interface PendingBracketTeardown {
  id: string;
  accountNumber: string;
  symbol: string;
  orderId: string;
  createdAt: string;
  attempts: number;
}

/** List pending bracket teardowns for an account (oldest first). */
export function listPendingBracketTeardowns(accountNumber: string, userId: string = "local"): PendingBracketTeardown[] {
  const rows = getDb()
    .prepare(
      `SELECT id, account_number, symbol, order_id, created_at, attempts
       FROM pending_bracket_teardowns WHERE user_id = ? AND account_number = ? ORDER BY created_at ASC`
    )
    .all(userId, accountNumber) as Array<{ id: string; account_number: string; symbol: string; order_id: string; created_at: string; attempts: number }>;
  return rows.map((r) => ({ id: r.id, accountNumber: r.account_number, symbol: r.symbol, orderId: r.order_id, createdAt: r.created_at, attempts: r.attempts }));
}

/** Remove a pending bracket teardown once resolved (legs cancelled, already terminal, or aged out). */
export function removePendingBracketTeardown(id: string): void {
  getDb().prepare("DELETE FROM pending_bracket_teardowns WHERE id = ?").run(id);
}

/** Record a failed/inconclusive teardown attempt (bumps the retry counter the sweep uses to age out). */
export function bumpPendingBracketTeardownAttempts(id: string): void {
  getDb().prepare("UPDATE pending_bracket_teardowns SET attempts = attempts + 1 WHERE id = ?").run(id);
}

/** A broker-native bracket order tracked by trackOpenBracketOrder, not yet torn down. */
export interface OpenBracketOrder {
  id: string;
  accountNumber: string;
  symbol: string;
  orderId: string;
  createdAt: string;
}

/** List every bracket order still tracked (not yet torn down) for a symbol, oldest first. Test/
 *  observability accessor — production code drives entirely off trackOpenBracketOrder/
 *  enqueueTeardownForAllOpenBrackets. */
export function listOpenBracketOrders(accountNumber: string, symbol: string, userId: string = "local"): OpenBracketOrder[] {
  const rows = getDb()
    .prepare(
      `SELECT id, account_number, symbol, order_id, created_at
       FROM position_stop_plan_open_brackets WHERE user_id = ? AND account_number = ? AND symbol = ? ORDER BY created_at ASC`
    )
    .all(userId, accountNumber, symbol) as Array<{ id: string; account_number: string; symbol: string; order_id: string; created_at: string }>;
  return rows.map((r) => ({ id: r.id, accountNumber: r.account_number, symbol: r.symbol, orderId: r.order_id, createdAt: r.created_at }));
}

import { createHash, randomUUID } from "crypto";
import { getDb } from "./db";

// `stoppedWorking` is set for a few distinct reasons (see getServiceHealthSummaries). This one is the
// "5 consecutive failures" condition — the only one strong enough to act on automatically (e.g. the
// enrichment circuit breaker), as opposed to the softer "no success yet this hour" heuristics that a
// single cold failure can trip. Exported so consumers key off the condition, not a brittle string.
export const HEALTH_REASON_CONSECUTIVE_FAILURES = "Last 5 consecutive calls all failed";

// RAG services (Pinecone, Voyage embed, Voyage rerank) already get their OWN explicit,
// operation-scoped alert from vector-db.ts's withRagApiHealth -> alertRagConnectionFailure (richer
// message: which operation failed, usage-limit escalation via alertUsageLimitHit, its own 1h
// cooldown). Without this exclusion, logApiHealth's automatic alertConnectionFailure below ALSO
// fires for the same failure (generic "<service> connection failed" text, its own separate 6h
// cooldown clock) — two uncoordinated alerts, ~1s apart, for one underlying event (confirmed
// 2026-07-07T14:01Z and 22:01Z in prod). Keep the richer vector-db.ts alert as the single source of
// truth for these three lanes; every OTHER provider (finnhub, tiingo, twelvedata, etc.) has no
// dedicated alerter, so it still needs this generic automatic path.
const RAG_SERVICES_WITH_OWN_ALERTING = new Set(["pinecone", "voyage", "voyage-rerank"]);

/**
 * Per-credential-lane health for the API circuit breaker. A "lane" is (service, keySource) — the SAME
 * granularity `getServiceHealthSummaries` and the whole health store already use — NOT per-user, so a
 * globally-dead env key trips once (not per user) and a user's own bad key trips only that user's lane
 * without stopping the shared env lane. `stoppedWorking` reuses the exact predicate below (kept in sync
 * with getServiceHealthSummaries): the last 5 calls all failed, or active-this-hour with no recent
 * success. Read-only; never throws (returns a not-stopped default on any DB error).
 */
export function getLaneHealth(
  service: string,
  keySource: string | null,
  userId?: string | null
): { stoppedWorking: boolean; reason: string | null; lastFailureTs: string | null } {
  try {
    const db = getDb();
    const hourAgo = new Date(Date.now() - 60 * 60 * 1000).toISOString();
    // For a per-USER credential lane (keySource "user"), scope the failure streak to THIS user's own
    // history — otherwise one tenant's 5 failures would trip a provider-degraded alert for every other
    // user sharing the (service, "user") lane. Global/env/none lanes stay aggregate (no user predicate).
    const scopeUser = keySource === "user" && userId != null;
    const userClause = scopeUser ? " AND user_id IS ?" : "";
    const withUser = (params: unknown[]): unknown[] => (scopeUser ? [...params, userId] : params);
    const last5 = db
      .prepare(`SELECT ok FROM api_health_log WHERE service = ? AND key_source IS ?${userClause} ORDER BY ts DESC, rowid DESC LIMIT 5`)
      .all(...withUser([service, keySource])) as Array<{ ok: number }>;
    const lastSuccess = db
      .prepare(`SELECT ts FROM api_health_log WHERE service = ? AND key_source IS ?${userClause} AND ok = 1 ORDER BY ts DESC, rowid DESC LIMIT 1`)
      .get(...withUser([service, keySource])) as { ts: string } | undefined;
    const lastFailure = db
      .prepare(`SELECT ts FROM api_health_log WHERE service = ? AND key_source IS ?${userClause} AND ok = 0 ORDER BY ts DESC, rowid DESC LIMIT 1`)
      .get(...withUser([service, keySource])) as { ts: string } | undefined;
    const callsLastHour = (
      db.prepare(`SELECT COUNT(*) as cnt FROM api_health_log WHERE service = ? AND key_source IS ?${userClause} AND ts >= ?`).get(...withUser([service, keySource]), hourAgo) as { cnt: number }
    ).cnt;

    let stoppedWorking = false;
    let reason: string | null = null;
    if (last5.length >= 5 && last5.every((r) => r.ok === 0)) {
      stoppedWorking = true;
      reason = HEALTH_REASON_CONSECUTIVE_FAILURES;
    } else if (callsLastHour > 0 && !lastSuccess) {
      stoppedWorking = true;
      reason = "Active in past hour but no successful call ever";
    } else if (callsLastHour > 0 && lastSuccess && lastSuccess.ts < hourAgo) {
      stoppedWorking = true;
      reason = "Active in past hour but no success in 60 min";
    }
    return { stoppedWorking, reason, lastFailureTs: lastFailure?.ts ?? null };
  } catch {
    return { stoppedWorking: false, reason: null, lastFailureTs: null };
  }
}

// ── Types ─────────────────────────────────────────────────────────────────────

export interface ServiceHealthSummary {
  service: string;
  keySource: string | null;
  lastSuccessTs: string | null;
  lastSuccessLatencyMs: number | null;
  lastFailureTs: string | null;
  lastFailureError: string | null;
  callsLastHour: number;
  callsLast24h: number;
  stoppedWorking: boolean;
  stoppedReason: string | null;
}

export interface HealthLogRow {
  id: string;
  service: string;
  ts: string;
  ok: number;
  latency_ms: number | null;
  error_text: string | null;
  key_source: string | null;
  user_id: string | null;
}

export interface ErrorPatternRow {
  id: string;
  service: string;
  fingerprint: string;
  error_text: string;
  first_seen: string;
  last_seen: string;
  count: number;
  key_source: string | null;
}

// ── Write ──────────────────────────────────────────────────────────────────────

export function logApiHealth(opts: {
  service: string;
  ok: boolean;
  latencyMs?: number;
  errorText?: string;
  keySource?: string;
  userId?: string;
  // Set ONLY by a caller that knows this failure is a daily-quota exhaustion which cannot
  // recover before a known instant (e.g. Alpha Vantage's 25/day cap resets at midnight
  // America/New_York) — an ISO timestamp of that reset. db-health never derives this itself
  // (no string-matching error text here); it just threads whatever the call site passes
  // through to alertConnectionFailure's cooldown. Omit for ordinary transient failures, which
  // keep the generic fixed-duration cooldown.
  quotaResetAt?: string;
}): void {
  try {
    const db = getDb();
    const now = new Date().toISOString();
    const id = randomUUID();
    const keySource = opts.keySource ?? null;
    const userId = opts.userId ?? null;

    db.transaction(() => {
      // Insert log row
      db.prepare(
        `INSERT INTO api_health_log (id, service, ts, ok, latency_ms, error_text, key_source, user_id)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
      ).run(id, opts.service, now, opts.ok ? 1 : 0, opts.latencyMs ?? null, opts.errorText ?? null, keySource, userId);

      // Enforce FIFO cap of 500 rows per (service, key_source) credential lane
      db.prepare(
        `DELETE FROM api_health_log
         WHERE service = ? AND key_source IS ?
           AND id NOT IN (
             SELECT id FROM api_health_log
             WHERE service = ? AND key_source IS ?
             ORDER BY ts DESC, rowid DESC
             LIMIT 500
           )`
      ).run(opts.service, keySource, opts.service, keySource);

      // Update error pattern if this is a failure.
      // Use "" (not NULL) as the key_source sentinel so UNIQUE(service,fingerprint,key_source)
      // deduplicates correctly — SQLite NULL values never collide in UNIQUE constraints.
      if (!opts.ok && opts.errorText) {
        const normalized = opts.errorText.trim().toLowerCase().replace(/\s+/g, " ");
        const fingerprint = createHash("sha256").update(normalized).digest("hex").slice(0, 12);
        const patternId = randomUUID();
        const patternKeySource = keySource ?? "";

        db.prepare(
          `INSERT INTO api_health_error_patterns
             (id, service, fingerprint, error_text, first_seen, last_seen, count, key_source)
           VALUES (?, ?, ?, ?, ?, ?, 1, ?)
           ON CONFLICT(service, fingerprint, key_source) DO UPDATE SET
             last_seen = excluded.last_seen,
             count = count + 1`
        ).run(patternId, opts.service, fingerprint, opts.errorText, now, now, patternKeySource);
      }
    })();

    if (!opts.ok && opts.errorText && !RAG_SERVICES_WITH_OWN_ALERTING.has(opts.service)) {
      const keySource = opts.keySource ?? null;
      // Scope the streak that gates the alert to this user's own history for user-key lanes, so
      // tenant A's failures don't fire a provider-degraded alert to tenant B on the shared lane.
      const lane = getLaneHealth(opts.service, keySource, opts.userId ?? null);
      const isRateLimit = /429|rate limit/i.test(opts.errorText);
      if (lane.stoppedWorking) {
        void alertConnectionFailure(opts.service, keySource, opts.userId ?? null, opts.errorText, {
          skipSentry: isRateLimit,
          cooldownUntil: opts.quotaResetAt
        });
      }
    }
  } catch {
    // Health logging must never throw — swallow all errors
  }
}

// ── Read ───────────────────────────────────────────────────────────────────────

interface ServiceKeyLane { service: string; key_source: string | null }

function listHealthLanes(): ServiceKeyLane[] {
  try {
    const db = getDb();
    return db
      .prepare(`SELECT DISTINCT service, key_source FROM api_health_log ORDER BY service, key_source`)
      .all() as ServiceKeyLane[];
  } catch {
    return [];
  }
}

export function listHealthServices(): string[] {
  try {
    const db = getDb();
    const rows = db
      .prepare(`SELECT DISTINCT service FROM api_health_log ORDER BY service`)
      .all() as Array<{ service: string }>;
    return rows.map((r) => r.service);
  } catch {
    return [];
  }
}

export function getServiceHealthSummaries(): ServiceHealthSummary[] {
  try {
    const db = getDb();
    const lanes = listHealthLanes();
    const now = Date.now();
    const hourAgo = new Date(now - 60 * 60 * 1000).toISOString();
    const dayAgo = new Date(now - 24 * 60 * 60 * 1000).toISOString();

    return lanes.map(({ service, key_source: ks }) => {
      const lastSuccess = db
        .prepare(
          `SELECT ts, latency_ms FROM api_health_log
           WHERE service = ? AND key_source IS ? AND ok = 1
           ORDER BY ts DESC, rowid DESC LIMIT 1`
        )
        .get(service, ks) as { ts: string; latency_ms: number | null } | undefined;

      const lastFailure = db
        .prepare(
          `SELECT ts, error_text FROM api_health_log
           WHERE service = ? AND key_source IS ? AND ok = 0
           ORDER BY ts DESC, rowid DESC LIMIT 1`
        )
        .get(service, ks) as { ts: string; error_text: string | null } | undefined;

      const callsLastHour = (
        db
          .prepare(
            `SELECT COUNT(*) as cnt FROM api_health_log
             WHERE service = ? AND key_source IS ? AND ts >= ?`
          )
          .get(service, ks, hourAgo) as { cnt: number }
      ).cnt;

      const callsLast24h = (
        db
          .prepare(
            `SELECT COUNT(*) as cnt FROM api_health_log
             WHERE service = ? AND key_source IS ? AND ts >= ?`
          )
          .get(service, ks, dayAgo) as { cnt: number }
      ).cnt;

      // "Stopped working" detection — scoped per credential lane
      const last5 = db
        .prepare(
          `SELECT ok FROM api_health_log
           WHERE service = ? AND key_source IS ?
           ORDER BY ts DESC, rowid DESC LIMIT 5`
        )
        .all(service, ks) as Array<{ ok: number }>;

      let stoppedWorking = false;
      let stoppedReason: string | null = null;

      if (last5.length >= 5 && last5.every((r) => r.ok === 0)) {
        stoppedWorking = true;
        stoppedReason = HEALTH_REASON_CONSECUTIVE_FAILURES;
      } else if (callsLastHour > 0 && !lastSuccess) {
        stoppedWorking = true;
        stoppedReason = "Active in past hour but no successful call ever";
      } else if (callsLastHour > 0 && lastSuccess && lastSuccess.ts < hourAgo) {
        stoppedWorking = true;
        stoppedReason = "Active in past hour but no success in 60 min";
      }

      return {
        service,
        keySource: ks,
        lastSuccessTs: lastSuccess?.ts ?? null,
        lastSuccessLatencyMs: lastSuccess?.latency_ms ?? null,
        lastFailureTs: lastFailure?.ts ?? null,
        lastFailureError: lastFailure?.error_text ?? null,
        callsLastHour,
        callsLast24h,
        stoppedWorking,
        stoppedReason,
      };
    });
  } catch {
    return [];
  }
}

// NOTE: `rowid DESC` tiebreaker — `ts` is ms-resolution, so rows written in the same millisecond
// otherwise return in arbitrary order and "the newest row" reads become nondeterministic (bit
// test/data-providers.test.ts's newest-row assertion, 2026-07-10). It must be `rowid` (implicit
// monotonic insertion order; `id TEXT PRIMARY KEY` does not alias it): `id` is a randomUUID, so
// ordering by it is a per-run coin flip, not a tiebreak.
export function getServiceHealthLog(
  service: string,
  limit = 100,
  offset = 0,
  keySource?: string | null
): HealthLogRow[] {
  try {
    const db = getDb();
    if (keySource !== undefined) {
      return db
        .prepare(
          `SELECT id, service, ts, ok, latency_ms, error_text, key_source, user_id
           FROM api_health_log
           WHERE service = ? AND key_source IS ?
           ORDER BY ts DESC, rowid DESC
           LIMIT ? OFFSET ?`
        )
        .all(service, keySource ?? null, limit, offset) as HealthLogRow[];
    }
    return db
      .prepare(
        `SELECT id, service, ts, ok, latency_ms, error_text, key_source, user_id
         FROM api_health_log
         WHERE service = ?
         ORDER BY ts DESC, rowid DESC
         LIMIT ? OFFSET ?`
      )
      .all(service, limit, offset) as HealthLogRow[];
  } catch {
    return [];
  }
}

export function getServiceErrorPatterns(
  service: string,
  keySource?: string | null
): ErrorPatternRow[] {
  try {
    const db = getDb();
    if (keySource !== undefined) {
      // Error patterns use "" sentinel (not NULL) so UNIQUE dedup works; map null → ""
      return db
        .prepare(
          `SELECT id, service, fingerprint, error_text, first_seen, last_seen, count, key_source
           FROM api_health_error_patterns
           WHERE service = ? AND key_source = ?
           ORDER BY last_seen DESC`
        )
        .all(service, keySource ?? "") as ErrorPatternRow[];
    }
    return db
      .prepare(
        `SELECT id, service, fingerprint, error_text, first_seen, last_seen, count, key_source
         FROM api_health_error_patterns
         WHERE service = ?
         ORDER BY last_seen DESC`
      )
      .all(service) as ErrorPatternRow[];
  } catch {
    return [];
  }
}

export function getAllErrorPatterns(): Record<string, ErrorPatternRow[]> {
  try {
    const db = getDb();
    const rows = db
      .prepare(
        `SELECT id, service, fingerprint, error_text, first_seen, last_seen, count, key_source
         FROM api_health_error_patterns
         ORDER BY last_seen DESC`
      )
      .all() as ErrorPatternRow[];
    const result: Record<string, ErrorPatternRow[]> = {};
    for (const row of rows) {
      // key_source is "" for no-key services (sentinel), never NULL in error_patterns
      const lane = `${row.service}:${row.key_source ?? ""}`;
      if (!result[lane]) result[lane] = [];
      result[lane].push(row);
    }
    return result;
  } catch {
    return {};
  }
}

// ── Connection Health & Storage Alerts ────────────────────────────────────────

const HEALTH_ALERT_COOLDOWN_PREFIX = "healthAlertSent";
// Default cooldown for an ordinary transient failure. A caller that knows the failure is a
// daily-quota exhaustion (persists until a known reset instant, not just "some hours") overrides
// this per-call via alertConnectionFailure's `opts.cooldownUntil` — see its doc comment.
const HEALTH_ALERT_COOLDOWN_MS = 6 * 60 * 60_000; // 6 hours

const STORAGE_ALERT_COOLDOWN_PREFIX = "storageAlertSent";
const STORAGE_ALERT_COOLDOWN_MS = 12 * 60 * 60_000; // 12 hours

function operatorAlertEmail(): string | undefined {
  return (
    process.env.USAGE_LIMIT_ALERT_EMAIL?.trim() ||
    process.env.ADMIN_ALERT_EMAIL?.trim() ||
    process.env.PRIMARY_USER_EMAIL?.trim() ||
    undefined
  );
}

async function captureHealthSentryMessage(
  level: "warning" | "error",
  message: string,
  context: Record<string, string | number | boolean | null | undefined>
): Promise<void> {
  if (!process.env.SENTRY_DSN) return;
  try {
    const mod = (await import("@sentry/nextjs")) as typeof import("@sentry/nextjs") & {
      default?: typeof import("@sentry/nextjs");
    };
    const captureMessage = mod.captureMessage ?? mod.default?.captureMessage;
    const withScope = mod.withScope ?? mod.default?.withScope;
    if (typeof captureMessage !== "function" || typeof withScope !== "function") return;
    withScope((scope) => {
      scope.setLevel(level);
      scope.setTag("component", "api-health");
      if (context.service) scope.setTag("health.service", String(context.service));
      if (context.keySource) scope.setTag("health.key_source", String(context.keySource));
      scope.setContext("api-health", context);
      captureMessage(message);
    });
  } catch {
    // Observability must not affect trading control flow.
  }
}

export async function alertConnectionFailure(
  service: string,
  keySource: string | null,
  userId: string | null,
  errorText: string,
  // `cooldownUntil`: an ISO instant a caller passes when it KNOWS this failure won't clear
  // before then (e.g. Alpha Vantage's daily-quota exhaustion, cooldownUntil = next
  // America/New_York midnight reset) — the alert is suppressed until that instant instead of
  // the generic HEALTH_ALERT_COOLDOWN_MS window. Falls back to the generic window when absent,
  // unparsable, or already in the past, so a bad/stale value never shortens the cooldown to
  // "always re-alert" or silences alerts forever.
  opts?: { skipSentry?: boolean; cooldownUntil?: string }
): Promise<void> {
  try {
    const targetUserId = userId || "local";
    const actualKeySource = keySource || "none";
    // Cool down GLOBAL lanes (env/none) by service+source only — NOT per-user. In a multi-user outage
    // each tenant's failure hits the SAME global dependency, so a userId-scoped cooldown key would let
    // every tenant mint its own cooldown row and re-alert the admin every 6h for the one shared outage.
    // Only per-USER credential lanes ("user") key the cooldown by userId (each user's own key/alert).
    const key =
      actualKeySource === "user"
        ? `${HEALTH_ALERT_COOLDOWN_PREFIX}:${service}:${actualKeySource}:${targetUserId}`
        : `${HEALTH_ALERT_COOLDOWN_PREFIX}:${service}:${actualKeySource}`;

    // Cooldown check. The stored setting value is the "suppressed until" instant (not "last sent
    // at"): this lets a quota-exhaustion caller stretch the window arbitrarily far (to the
    // provider's actual daily reset) while an ordinary transient failure keeps the fixed 6h
    // window, using the exact same comparison. Audit + Sentry stay gated behind this SAME check
    // as the notification (not split into an always-fires audit path) — the per-request
    // api_health_log/error-pattern rows above already record every occurrence for forensics, so
    // an audit row per occurrence here would just duplicate that without adding signal; only the
    // repeat-alert noise is the target of this cooldown.
    const { getInternalSetting, setInternalSetting, audit } = await import("./db");
    const now = Date.now();
    const last = getInternalSetting<string>(key);
    if (last) {
      const suppressedUntilMs = Date.parse(last);
      if (Number.isFinite(suppressedUntilMs) && now < suppressedUntilMs) return;
    }
    const requestedCooldownMs = opts?.cooldownUntil ? Date.parse(opts.cooldownUntil) : NaN;
    const cooldownUntilMs =
      Number.isFinite(requestedCooldownMs) && requestedCooldownMs > now
        ? requestedCooldownMs
        : now + HEALTH_ALERT_COOLDOWN_MS;
    setInternalSetting(key, new Date(cooldownUntilMs).toISOString());

    const isGlobal = actualKeySource !== "user";
    const title = `${service} connection failed`;
    const body = `Connection to ${service} (${actualKeySource} lane) failed: ${errorText}`;

    const payload = {
      service,
      keySource: actualKeySource,
      userId: targetUserId,
      errorText,
      global: isGlobal
    };

    // Log audit event
    audit("connection_health_alert", payload, targetUserId);

    // Send Sentry event
    if (!opts?.skipSentry) {
      await captureHealthSentryMessage(isGlobal ? "error" : "warning", title, {
        service,
        keySource: actualKeySource,
        userSpecific: !isGlobal,
        reason: errorText
      });
    }

    if (isGlobal) {
      // Global failures: Route to admin email and health.
      const { getNotifyPrefs } = await import("./db");
      const prefs = getNotifyPrefs("local");
      const { loadNotifyConfig, notify } = await import("./notify");

      const fallbackEmail = operatorAlertEmail();
      const config = loadNotifyConfig();

      // The operator's own channels are delivered by sendNotification inside the enabled-event
      // gate. The fallback email remains an EXTRA lazy lane when the operator has no usable email
      // preference, so it cannot double-send or bypass that gate.
      const additionalDelivery =
        fallbackEmail && config.email.resendKey && config.email.from && (!prefs.channels.includes("email") || !prefs.email.trim())
          ? () =>
              notify(
                "local",
                { title, body, kind: "provider_degraded", data: payload },
                {
                  config,
                  prefs: {
                    ...prefs,
                    channels: ["email" as any],
                    email: fallbackEmail,
                    updatedAt: prefs.updatedAt
                  }
                }
              )
          : undefined;

      // Also send standard notification
      const { sendNotification } = await import("./notifications");
      const { getPolicy } = await import("./db");
      const policy = getPolicy("local");
      const forcedPolicy = {
        ...policy,
        notificationSettings: {
          ...policy.notificationSettings,
          enabledEvents: Array.from(new Set([...policy.notificationSettings.enabledEvents, "provider_degraded" as const])) as any
        }
      };
      await sendNotification(
        { type: "provider_degraded", title, payload },
        { userId: "local", policy: forcedPolicy as any, directBody: body, notifyDeps: { config }, additionalDelivery }
      ).catch(() => {});
    } else {
      // User-key failures: Route to user notifications only
      const { sendNotification } = await import("./notifications");
      const { getPolicy } = await import("./db");
      const policy = getPolicy(targetUserId);
      const forcedPolicy = {
        ...policy,
        notificationSettings: {
          ...policy.notificationSettings,
          enabledEvents: Array.from(new Set([...policy.notificationSettings.enabledEvents, "provider_degraded" as const])) as any
        }
      };
      await sendNotification(
        { type: "provider_degraded", title, payload },
        { userId: targetUserId, policy: forcedPolicy as any, directBody: body }
      ).catch(() => {});
    }
  } catch {
    // Health alerts must never throw
  }
}

export async function alertStorageWarning(warningType: string, message: string): Promise<void> {
  try {
    const key = `${STORAGE_ALERT_COOLDOWN_PREFIX}:${warningType}`;
    const { getInternalSetting, setInternalSetting, audit } = await import("./db");
    const last = getInternalSetting<string>(key);
    if (last && Date.now() - Date.parse(last) < STORAGE_ALERT_COOLDOWN_MS) return;
    setInternalSetting(key, new Date().toISOString());

    const title = `Storage Warning: ${warningType.replace(/_/g, " ")}`;
    const body = message;
    const payload = { warningType, message };

    audit("storage_warning_alert", payload, "local");

    // Route to admin email
    const { getNotifyPrefs } = await import("./db");
    const prefs = getNotifyPrefs("local");
    const { loadNotifyConfig, notify } = await import("./notify");

    const fallbackEmail = operatorAlertEmail();
    const config = loadNotifyConfig();

    const additionalDelivery =
      fallbackEmail && config.email.resendKey && config.email.from && (!prefs.channels.includes("email") || !prefs.email.trim())
        ? () =>
            notify(
              "local",
              { title, body, kind: "storage_warning", data: payload },
              {
                config,
                prefs: {
                  ...prefs,
                  channels: ["email" as any],
                  email: fallbackEmail,
                  updatedAt: prefs.updatedAt
                }
              }
            )
        : undefined;

    // Also send standard notification
    const { sendNotification } = await import("./notifications");
    const { getPolicy } = await import("./db");
    const policy = getPolicy("local");
    const forcedPolicy = {
      ...policy,
      notificationSettings: {
        ...policy.notificationSettings,
        enabledEvents: Array.from(new Set([...policy.notificationSettings.enabledEvents, "storage_warning" as const])) as any
      }
    };
    await sendNotification(
      { type: "storage_warning", title, payload },
      { userId: "local", policy: forcedPolicy as any, directBody: body, notifyDeps: { config }, additionalDelivery }
    ).catch(() => {});
  } catch {
    // never throw on warnings
  }
}

// db-learning.ts — audit-event helpers, counterfactual learning watermarks/candidates,
// learned-context fact-tier functions, and RAG ingestion (ingested_accessions).
import { getDb } from "./db";
import { mergeHorizonRows } from "./outcome-horizons";
import type { LearnedContextRow, LearnedContextPendingRow, LearnedContextPendingStatus, SocraticOutcomeHorizonRow } from "./types";

// ── Audit-event helpers ────────────────────────────────────────────────────────

export function listAudit(
  limit = 100,
  userId: string = "local",
  connectedAccountId?: string,
  includeUserWide = false
): Array<{ id: string; createdAt: string; kind: string; payload: unknown; connectedAccountId?: string }> {
  const rows = (connectedAccountId
    ? getDb()
      .prepare(
        `SELECT id, connected_account_id, created_at, kind, payload
         FROM audit_events
         WHERE user_id = ? AND (connected_account_id = ?${includeUserWide ? " OR connected_account_id IS NULL" : ""})
         ORDER BY created_at DESC
         LIMIT ?`
      )
      .all(userId, connectedAccountId, limit)
    : getDb()
      .prepare("SELECT id, connected_account_id, created_at, kind, payload FROM audit_events WHERE user_id = ? ORDER BY created_at DESC LIMIT ?")
      .all(userId, limit)) as Array<{ id: string; connected_account_id: string | null; created_at: string; kind: string; payload: string }>;
  return rows.map((row) => ({
    id: row.id,
    createdAt: row.created_at,
    kind: row.kind,
    payload: JSON.parse(row.payload),
    connectedAccountId: row.connected_account_id ?? undefined
  }));
}

export function latestAuditByKind(
  kind: string,
  userId: string = "local",
  connectedAccountId?: string
): { id: string; createdAt: string; kind: string; payload: unknown; connectedAccountId?: string } | undefined {
  const row = (connectedAccountId
    ? getDb()
      .prepare("SELECT id, connected_account_id, created_at, kind, payload FROM audit_events WHERE kind = ? AND user_id = ? AND connected_account_id = ? ORDER BY created_at DESC LIMIT 1")
      .get(kind, userId, connectedAccountId)
    : getDb()
      .prepare("SELECT id, connected_account_id, created_at, kind, payload FROM audit_events WHERE kind = ? AND user_id = ? ORDER BY created_at DESC LIMIT 1")
      .get(kind, userId)) as { id: string; connected_account_id: string | null; created_at: string; kind: string; payload: string } | undefined;
  if (!row) return undefined;
  return {
    id: row.id,
    createdAt: row.created_at,
    kind: row.kind,
    payload: JSON.parse(row.payload),
    connectedAccountId: row.connected_account_id ?? undefined
  };
}

/**
 * Recent audit events of ONE kind, newest first. Unlike `listAudit` (all kinds, then the
 * caller filters), the LIMIT applies AFTER the kind filter — so a flood of newer audit rows
 * of other kinds can never push the requested kind's history out of the window (Codex review
 * on PR #365: `getRedTeamEfficacy` scanned the all-kind feed and could report zero/partial
 * veto history in busy accounts). When `connectedAccountId` is given, user-wide rows
 * (connected_account_id IS NULL) are included too: veto audits were historically written
 * user-wide, so an account-scoped query must not silently drop that legacy history.
 */
export function listAuditByKind(
  kind: string,
  limit = 100,
  userId: string = "local",
  connectedAccountId?: string
): Array<{ id: string; createdAt: string; kind: string; payload: unknown; connectedAccountId?: string }> {
  const rows = (connectedAccountId
    ? getDb()
      .prepare(
        `SELECT id, connected_account_id, created_at, kind, payload
         FROM audit_events
         WHERE kind = ? AND user_id = ? AND (connected_account_id = ? OR connected_account_id IS NULL)
         ORDER BY created_at DESC
         LIMIT ?`
      )
      .all(kind, userId, connectedAccountId, limit)
    : getDb()
      .prepare(
        `SELECT id, connected_account_id, created_at, kind, payload
         FROM audit_events
         WHERE kind = ? AND user_id = ?
         ORDER BY created_at DESC
         LIMIT ?`
      )
      .all(kind, userId, limit)) as Array<{ id: string; connected_account_id: string | null; created_at: string; kind: string; payload: string }>;
  return rows.map((row) => ({
    id: row.id,
    createdAt: row.created_at,
    kind: row.kind,
    payload: JSON.parse(row.payload),
    connectedAccountId: row.connected_account_id ?? undefined
  }));
}

/**
 * Fast count of recent audit events of a specific kind, without loading JSON payloads.
 * Used for real-time error rate gating (e.g. order_placement_uncertain checks).
 */
export function countRecentAuditEvents(
  kind: string,
  connectedAccountId: string,
  minutes: number,
  userId: string = "local"
): number {
  const sinceIso = new Date(Date.now() - minutes * 60000).toISOString();

  const row = getDb().prepare(
    `SELECT COUNT(*) as count 
     FROM audit_events 
     WHERE kind = ? AND user_id = ? AND (connected_account_id = ? OR connected_account_id IS NULL)
     AND created_at >= ?`
  ).get(kind, userId, connectedAccountId, sinceIso) as { count: number };

  return row.count;
}

/**
 * Recent audit rows of ANY of `kinds` created at/after `sinceIso`, newest first. One IN-query
 * (not N listAuditByKind calls) so the daily learning review's system-history digest — the set of
 * execution-failure kinds it checks lesson evidence against — is a single cheap read.
 */
export function listAuditByKindsSince(
  kinds: string[],
  sinceIso: string,
  userId: string = "local",
  limit = 200
): Array<{ id: string; createdAt: string; kind: string; payload: unknown }> {
  if (kinds.length === 0) return [];
  const placeholders = kinds.map(() => "?").join(",");
  const rows = getDb()
    .prepare(
      `SELECT id, created_at, kind, payload
       FROM audit_events
       WHERE user_id = ? AND kind IN (${placeholders}) AND created_at >= ?
       ORDER BY created_at DESC
       LIMIT ?`
    )
    .all(userId, ...kinds, sinceIso, limit) as Array<{ id: string; created_at: string; kind: string; payload: string }>;
  return rows.map((row) => ({ id: row.id, createdAt: row.created_at, kind: row.kind, payload: JSON.parse(row.payload) }));
}

export interface SignalSnapshotAuditRow {
  rowid: number;
  id: string;
  createdAt: string;
  payload: unknown;
}

export function listSignalSnapshotAuditAfter(
  userId: string = "local",
  watermark?: { lastAuditRowid?: number },
  limit = 100,
  connectedAccountId?: string
): SignalSnapshotAuditRow[] {
  const hasWatermark = typeof watermark?.lastAuditRowid === "number";
  // Per-account scoping: when an account id is given, only that account's snapshots count toward
  // its learning. rowid is globally monotonic, so `rowid > lastAuditRowid AND account = ?` advances
  // each account's watermark over its own rows independently.
  const accountClause = connectedAccountId ? " AND connected_account_id = ?" : "";
  const rows = hasWatermark
    ? (getDb()
        .prepare(
          `SELECT rowid, id, created_at, payload
           FROM audit_events
           WHERE user_id = ?
            AND kind = 'signal_snapshot'
            AND rowid > ?${accountClause}
           ORDER BY rowid ASC
           LIMIT ?`
        )
        .all(...(connectedAccountId
          ? [userId, watermark!.lastAuditRowid, connectedAccountId, limit]
          : [userId, watermark!.lastAuditRowid, limit])) as Array<{ rowid: number; id: string; created_at: string; payload: string }>)
    : (getDb()
        .prepare(
          `SELECT rowid, id, created_at, payload
           FROM audit_events
           WHERE user_id = ? AND kind = 'signal_snapshot'${accountClause}
           ORDER BY rowid ASC
           LIMIT ?`
        )
        .all(...(connectedAccountId ? [userId, connectedAccountId, limit] : [userId, limit])) as Array<{ rowid: number; id: string; created_at: string; payload: string }>);

  return rows.map((row) => ({ rowid: row.rowid, id: row.id, createdAt: row.created_at, payload: JSON.parse(row.payload) }));
}

// ── Counterfactual learning watermarks ────────────────────────────────────────

export interface CounterfactualLearningWatermark {
  userId: string;
  lastAuditRowid?: number;
  lastAuditCreatedAt?: string;
  lastAuditId?: string;
  updatedAt: string;
}

// Per-account watermarks: the table's PK is (user_id, connected_account_id). The account-agnostic
// (user-wide) watermark is stored with connected_account_id = '' (empty string, never NULL) so the
// composite PK stays well-defined — SQLite would treat multiple NULLs as distinct, breaking upserts.
export function getCounterfactualLearningWatermark(
  userId: string = "local",
  connectedAccountId?: string
): CounterfactualLearningWatermark | undefined {
  const row = getDb()
    .prepare("SELECT user_id, last_audit_rowid, last_audit_created_at, last_audit_id, updated_at FROM counterfactual_learning_watermarks WHERE user_id = ? AND connected_account_id = ?")
    .get(userId, connectedAccountId ?? "") as { user_id: string; last_audit_rowid: number | null; last_audit_created_at: string | null; last_audit_id: string | null; updated_at: string } | undefined;
  if (!row) return undefined;
  return {
    userId: row.user_id,
    lastAuditRowid: row.last_audit_rowid ?? undefined,
    lastAuditCreatedAt: row.last_audit_created_at ?? undefined,
    lastAuditId: row.last_audit_id ?? undefined,
    updatedAt: row.updated_at
  };
}

export function setCounterfactualLearningWatermark(input: {
  userId?: string;
  connectedAccountId?: string;
  lastAuditRowid?: number;
  lastAuditCreatedAt?: string;
  lastAuditId?: string;
  updatedAt?: string;
}): void {
  const userId = input.userId ?? "local";
  const connectedAccountId = input.connectedAccountId ?? "";
  const updatedAt = input.updatedAt ?? new Date().toISOString();
  getDb()
    .prepare(
      `INSERT INTO counterfactual_learning_watermarks (user_id, connected_account_id, last_audit_rowid, last_audit_created_at, last_audit_id, updated_at)
       VALUES (?, ?, ?, ?, ?, ?)
       ON CONFLICT(user_id, connected_account_id) DO UPDATE SET
        last_audit_rowid = excluded.last_audit_rowid,
        last_audit_created_at = excluded.last_audit_created_at,
        last_audit_id = excluded.last_audit_id,
        updated_at = excluded.updated_at`
    )
    .run(userId, connectedAccountId, input.lastAuditRowid ?? null, input.lastAuditCreatedAt ?? null, input.lastAuditId ?? null, updatedAt);
}

// ── Skipped-candidate counterfactuals ─────────────────────────────────────────

export interface SkippedCounterfactualCandidateInput {
  userId?: string;
  connectedAccountId?: string;
  runId: string;
  symbol: string;
  snapshotAt: string;
  refPrice: number;
  horizonDays: number;
  targetDate: string;
  score?: number;
  sector?: string;
  regime?: string;
  dominantFactor?: string;
  bulletins?: string[];
  now?: string;
}

export interface SkippedCounterfactualRow {
  id: string;
  userId: string;
  runId: string;
  symbol: string;
  snapshotAt: string;
  refPrice: number;
  horizonDays: number;
  targetDate: string;
  status: "pending" | "matured" | "unresolvable";
  exitDate?: string;
  exitPrice?: number;
  returnPct?: number;
  score?: number;
  sector?: string;
  regime?: string;
  dominantFactor?: string;
  bulletins?: string[];
  /** Multi-horizon outcome rows (15m/1h/1d/1w) written at maturation; each row is individually
   * 'ok' or honestly 'unresolvable'. Absent on rows matured before the multi-horizon schema. */
  outcomes?: SocraticOutcomeHorizonRow[];
  /** Terminal reason when status === 'unresolvable' (e.g. "no_price_series",
   * "no_bar_at_or_after_target" — delisted/renamed symbols land here after the bounded recheck window). */
  resolutionReason?: string;
  lastCheckedAt?: string;
  createdAt: string;
  updatedAt: string;
}

type RawSkippedCounterfactualRow = {
  id: string;
  user_id: string;
  run_id: string;
  symbol: string;
  snapshot_at: string;
  ref_price: number;
  horizon_days: number;
  target_date: string;
  status: string;
  exit_date: string | null;
  exit_price: number | null;
  return_pct: number | null;
  score: number | null;
  sector: string | null;
  regime: string | null;
  dominant_factor: string | null;
  bulletins: string | null;
  outcomes: string | null;
  resolution_reason: string | null;
  last_checked_at: string | null;
  created_at: string;
  updated_at: string;
};

function toSkippedCounterfactualRow(row: RawSkippedCounterfactualRow): SkippedCounterfactualRow {
  return {
    id: row.id,
    userId: row.user_id,
    runId: row.run_id,
    symbol: row.symbol,
    snapshotAt: row.snapshot_at,
    refPrice: row.ref_price,
    horizonDays: row.horizon_days,
    targetDate: row.target_date,
    status: row.status === "matured" ? "matured" : row.status === "unresolvable" ? "unresolvable" : "pending",
    exitDate: row.exit_date ?? undefined,
    exitPrice: row.exit_price ?? undefined,
    returnPct: row.return_pct ?? undefined,
    score: row.score ?? undefined,
    sector: row.sector ?? undefined,
    regime: row.regime ?? undefined,
    dominantFactor: row.dominant_factor ?? undefined,
    bulletins: row.bulletins ? JSON.parse(row.bulletins) as string[] : undefined,
    outcomes: row.outcomes ? JSON.parse(row.outcomes) as SocraticOutcomeHorizonRow[] : undefined,
    resolutionReason: row.resolution_reason ?? undefined,
    lastCheckedAt: row.last_checked_at ?? undefined,
    createdAt: row.created_at,
    updatedAt: row.updated_at
  };
}

/** Deterministic skipped-candidate-counterfactual row id — single-sourced here so callers that need
 * to reference the row before/without re-reading it (e.g. enqueueing its intraday sample due-jobs
 * right after insert) can derive the same id rather than duplicating the format. */
export function skippedCounterfactualId(userId: string, runId: string, symbol: string, horizonDays: number): string {
  return `${userId}:${runId}:${symbol}:${horizonDays}`;
}

export function insertSkippedCounterfactualCandidate(input: SkippedCounterfactualCandidateInput): boolean {
  const userId = input.userId ?? "local";
  const now = input.now ?? new Date().toISOString();
  const id = skippedCounterfactualId(userId, input.runId, input.symbol, input.horizonDays);
  const db = getDb();
  const existing = db
    .prepare("SELECT id FROM skipped_candidate_counterfactuals WHERE id = ? AND user_id = ?")
    .get(id, userId);
  if (existing) {
    // A row for this (runId, symbol, horizon) already exists — e.g. a Bear-veto/policy-block
    // early insert that carried only `regime`, later followed by the run's richer
    // signal_snapshot ingestion carrying score/sector/dominant-factor/bulletin evidence
    // (Codex review on PR #365: pure INSERT OR IGNORE let the early bare insert permanently
    // strip the matured row of the evidence metadata missed-opportunity analytics/tuning read).
    // Backfill ONLY evidence columns that are still NULL: the first write stays authoritative
    // for pricing/snapshot/status (never re-priced), existing evidence is never overwritten,
    // and updated_at is left alone so metadata backfill can't reorder maturation listings.
    if (
      input.score !== undefined ||
      input.sector !== undefined ||
      input.regime !== undefined ||
      input.dominantFactor !== undefined ||
      (input.bulletins && input.bulletins.length > 0)
    ) {
      db.prepare(
        `UPDATE skipped_candidate_counterfactuals SET
          score = COALESCE(score, ?),
          sector = COALESCE(sector, ?),
          regime = COALESCE(regime, ?),
          dominant_factor = COALESCE(dominant_factor, ?),
          bulletins = COALESCE(bulletins, ?)
         WHERE id = ? AND user_id = ?`
      ).run(
        input.score ?? null,
        input.sector ?? null,
        input.regime ?? null,
        input.dominantFactor ?? null,
        input.bulletins && input.bulletins.length > 0 ? JSON.stringify(input.bulletins) : null,
        id,
        userId
      );
    }
    return false;
  }
  const result = db
    .prepare(
      `INSERT OR IGNORE INTO skipped_candidate_counterfactuals (
        id, user_id, connected_account_id, run_id, symbol, snapshot_at, ref_price, horizon_days,
        target_date, status, score, sector, regime, dominant_factor, bulletins,
        created_at, updated_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?, ?, ?, ?, ?, ?)`
    )
    .run(
      id,
      userId,
      input.connectedAccountId ?? null,
      input.runId,
      input.symbol,
      input.snapshotAt,
      input.refPrice,
      input.horizonDays,
      input.targetDate,
      input.score ?? null,
      input.sector ?? null,
      input.regime ?? null,
      input.dominantFactor ?? null,
      input.bulletins ? JSON.stringify(input.bulletins) : null,
      now,
      now
    );
  return result.changes > 0;
}

export function listPendingSkippedCounterfactuals(input: {
  userId?: string;
  nowDate: string;
  checkedBefore?: string;
  limit?: number;
}): SkippedCounterfactualRow[] {
  const userId = input.userId ?? "local";
  const limit = input.limit ?? 50;
  const rows = getDb()
    .prepare(
      `SELECT *
       FROM skipped_candidate_counterfactuals
       WHERE user_id = ?
        AND status = 'pending'
        AND target_date <= ?
        AND (last_checked_at IS NULL OR last_checked_at <= ?)
       ORDER BY target_date ASC, snapshot_at ASC, symbol ASC
       LIMIT ?`
    )
    .all(userId, input.nowDate, input.checkedBefore ?? new Date(0).toISOString(), limit) as RawSkippedCounterfactualRow[];
  return rows.map(toSkippedCounterfactualRow);
}

export function markSkippedCounterfactualChecked(id: string, userId: string = "local", checkedAt: string = new Date().toISOString()): void {
  getDb()
    .prepare("UPDATE skipped_candidate_counterfactuals SET last_checked_at = ?, updated_at = ? WHERE id = ? AND user_id = ? AND status = 'pending'")
    .run(checkedAt, checkedAt, id, userId);
}

/** Fresh (uncached) read of just the persisted `outcomes` column for one counterfactual row — used
 * immediately before a terminal write to re-merge against whatever a concurrent worker may have
 * already written (see the lost-update guard note on markSkippedCounterfactualMatured). */
function readPersistedCounterfactualOutcomes(id: string, userId: string): SocraticOutcomeHorizonRow[] | undefined {
  const row = getDb()
    .prepare("SELECT outcomes FROM skipped_candidate_counterfactuals WHERE id = ? AND user_id = ?")
    .get(id, userId) as { outcomes: string | null } | undefined;
  if (!row?.outcomes) return undefined;
  try {
    return JSON.parse(row.outcomes) as SocraticOutcomeHorizonRow[];
  } catch {
    return undefined;
  }
}

/**
 * Lost-update guard: `input.outcomes` may have been built from a pass-start snapshot held across
 * awaits (materializeSkippedCandidateCounterfactuals / outcome-engine's counterfactual worker path),
 * so a worker-sampled 15m/1h row written concurrently could otherwise be erased by this stale write.
 * Re-merge against the FRESH persisted row right before persisting — mergeHorizonRows'
 * existing-terminal-wins semantics make this idempotent/first-writer-wins regardless of write order.
 */
export function markSkippedCounterfactualMatured(input: {
  id: string;
  userId?: string;
  exitDate: string;
  exitPrice: number;
  returnPct: number;
  /** Multi-horizon outcome rows (15m/1h/1d/1w) measured alongside the headline horizon return. */
  outcomes?: SocraticOutcomeHorizonRow[];
  checkedAt?: string;
}): boolean {
  const userId = input.userId ?? "local";
  const checkedAt = input.checkedAt ?? new Date().toISOString();
  const mergedOutcomes = mergeHorizonRows(readPersistedCounterfactualOutcomes(input.id, userId), input.outcomes ?? []);
  const result = getDb()
    .prepare(
      `UPDATE skipped_candidate_counterfactuals
       SET status = 'matured',
        exit_date = ?,
        exit_price = ?,
        return_pct = ?,
        outcomes = ?,
        last_checked_at = ?,
        updated_at = ?
       WHERE id = ? AND user_id = ? AND status = 'pending'`
    )
    .run(
      input.exitDate,
      input.exitPrice,
      input.returnPct,
      mergedOutcomes.length > 0 ? JSON.stringify(mergedOutcomes) : null,
      checkedAt,
      checkedAt,
      input.id,
      userId
    );
  return result.changes > 0;
}

/**
 * Terminal kill-survivorship transition: a pending counterfactual whose price series never resolved
 * within the bounded recheck window (delisted / renamed / no provider coverage) becomes
 * status='unresolvable' WITH a reason, instead of sitting 'pending' forever and silently dropping
 * out of every matured-outcome denominator. Unresolvable rows keep their optional multi-horizon
 * outcome rows (each marked unresolvable with its own reason) so coverage math can count them.
 *
 * Lost-update guard: same re-merge-at-write-time treatment as markSkippedCounterfactualMatured above
 * — a worker-sampled 15m/1h row must survive this terminal write even if `input.outcomes` is stale.
 */
export function markSkippedCounterfactualUnresolvable(input: {
  id: string;
  userId?: string;
  reason: string;
  outcomes?: SocraticOutcomeHorizonRow[];
  checkedAt?: string;
}): boolean {
  const userId = input.userId ?? "local";
  const checkedAt = input.checkedAt ?? new Date().toISOString();
  const mergedOutcomes = mergeHorizonRows(readPersistedCounterfactualOutcomes(input.id, userId), input.outcomes ?? []);
  const result = getDb()
    .prepare(
      `UPDATE skipped_candidate_counterfactuals
       SET status = 'unresolvable',
        resolution_reason = ?,
        outcomes = ?,
        last_checked_at = ?,
        updated_at = ?
       WHERE id = ? AND user_id = ? AND status = 'pending'`
    )
    .run(input.reason, mergedOutcomes.length > 0 ? JSON.stringify(mergedOutcomes) : null, checkedAt, checkedAt, input.id, userId);
  return result.changes > 0;
}

/** Counterfactual rows by terminal/pending status — used to join unresolvable rows into scorecard
 * denominators (getRedTeamEfficacy, coverage disclosure). */
export function listSkippedCounterfactualsByStatus(
  userId: string = "local",
  status: "pending" | "matured" | "unresolvable",
  limit = 200,
  connectedAccountId?: string
): SkippedCounterfactualRow[] {
  const rows = (connectedAccountId
    ? getDb()
        .prepare(
          `SELECT * FROM skipped_candidate_counterfactuals
           WHERE user_id = ? AND status = ? AND connected_account_id = ?
           ORDER BY updated_at DESC LIMIT ?`
        )
        .all(userId, status, connectedAccountId, limit)
    : getDb()
        .prepare(
          `SELECT * FROM skipped_candidate_counterfactuals
           WHERE user_id = ? AND status = ?
           ORDER BY updated_at DESC LIMIT ?`
        )
        .all(userId, status, limit)) as RawSkippedCounterfactualRow[];
  return rows.map(toSkippedCounterfactualRow);
}

/** Status counts for the skipped-counterfactual pipeline. Unresolvable rows count in the total
 * denominator (kill-survivorship): resolvedPct = matured / (matured + unresolvable + due-pending
 * excluded — pending rows whose target date hasn't arrived are NOT "unresolved", just immature). */
export interface SkippedCounterfactualCoverage {
  total: number;
  matured: number;
  pending: number;
  unresolvable: number;
  /** matured / (matured + unresolvable) as a %, 0 when nothing terminal yet. */
  resolvedPct: number;
  /** Human disclosure line, e.g. "12/15 resolved (80%) — 3 unresolvable; may be survivor-biased". */
  disclosure: string;
}

export function getSkippedCounterfactualCoverage(
  userId: string = "local",
  connectedAccountId?: string
): SkippedCounterfactualCoverage {
  const rows = (connectedAccountId
    ? getDb()
        .prepare(
          `SELECT status, COUNT(*) AS n FROM skipped_candidate_counterfactuals
           WHERE user_id = ? AND connected_account_id = ? GROUP BY status`
        )
        .all(userId, connectedAccountId)
    : getDb()
        .prepare("SELECT status, COUNT(*) AS n FROM skipped_candidate_counterfactuals WHERE user_id = ? GROUP BY status")
        .all(userId)) as Array<{ status: string; n: number }>;
  const count = (status: string) => rows.find((r) => r.status === status)?.n ?? 0;
  const matured = count("matured");
  const pending = count("pending");
  const unresolvable = count("unresolvable");
  const terminal = matured + unresolvable;
  const resolvedPct = terminal > 0 ? Number(((matured / terminal) * 100).toFixed(1)) : 0;
  const disclosure =
    terminal > 0
      ? `${matured}/${terminal} resolved (${resolvedPct}%)${unresolvable > 0 ? ` — ${unresolvable} unresolvable; may be survivor-biased` : ""}${pending > 0 ? `; ${pending} still maturing` : ""}`
      : `0 resolved${pending > 0 ? `; ${pending} still maturing` : ""}`;
  return { total: matured + pending + unresolvable, matured, pending, unresolvable, resolvedPct, disclosure };
}

/**
 * Merge freshly-sampled intraday (15m/1h) horizon rows into a still-'pending' counterfactual's
 * `outcomes` column WITHOUT touching status/exit fields — used by the due-jobs intraday sampler
 * (outcome-engine.ts's drainDueIntradaySampleJobs), which resolves one horizon at a time and is not
 * the pipeline that closes the whole counterfactual (that's markSkippedCounterfactualMatured /
 * markSkippedCounterfactualUnresolvable, both status='pending'-gated same as this). A no-op once the
 * row has already gone terminal (matured/unresolvable) — those rows' outcomes are owned by their own
 * terminal writer, not by a late-arriving intraday sample.
 */
export function updateSkippedCounterfactualOutcomes(
  id: string,
  userId: string,
  outcomes: SocraticOutcomeHorizonRow[],
  updatedAt: string = new Date().toISOString()
): boolean {
  const result = getDb()
    .prepare(
      `UPDATE skipped_candidate_counterfactuals
       SET outcomes = ?, updated_at = ?
       WHERE id = ? AND user_id = ? AND status = 'pending'`
    )
    .run(JSON.stringify(outcomes), updatedAt, id, userId);
  return result.changes > 0;
}

/** One counterfactual row by its natural join key (runId, symbol) — the outcome engine joins
 * blocked/rejected/vetoed decision cases to their forward returns through this. */
export function getSkippedCounterfactualByRunSymbol(
  userId: string,
  runId: string,
  symbol: string
): SkippedCounterfactualRow | undefined {
  const row = getDb()
    .prepare(
      `SELECT * FROM skipped_candidate_counterfactuals
       WHERE user_id = ? AND run_id = ? AND symbol = ?
       ORDER BY horizon_days ASC LIMIT 1`
    )
    .get(userId, runId, symbol) as RawSkippedCounterfactualRow | undefined;
  return row ? toSkippedCounterfactualRow(row) : undefined;
}

/** Exact counterfactual row by its full natural key (runId, symbol, horizonDays) — used by the
 * durable due-jobs intraday sampler (outcome-engine.ts's drainDueIntradaySampleJobs), which carries
 * horizonDays explicitly in its job payload rather than guessing via min(horizon_days) the way
 * getSkippedCounterfactualByRunSymbol does. A (runId, symbol) pair can have more than one row across
 * different horizons (e.g. a Bear-veto early insert vs. the run's own signal-snapshot ingestion using
 * a different configured horizonDays) — this disambiguates to the exact owning row instead of always
 * picking the shortest horizon. */
export function getSkippedCounterfactualByRunSymbolHorizon(
  userId: string,
  runId: string,
  symbol: string,
  horizonDays: number
): SkippedCounterfactualRow | undefined {
  const row = getDb()
    .prepare(
      `SELECT * FROM skipped_candidate_counterfactuals
       WHERE user_id = ? AND run_id = ? AND symbol = ? AND horizon_days = ?
       LIMIT 1`
    )
    .get(userId, runId, symbol, horizonDays) as RawSkippedCounterfactualRow | undefined;
  return row ? toSkippedCounterfactualRow(row) : undefined;
}

export function listMaturedSkippedCounterfactuals(
  userId: string = "local",
  limit = 50,
  connectedAccountId?: string
): SkippedCounterfactualRow[] {
  const rows = (connectedAccountId
    ? getDb()
        .prepare(
          `SELECT *
           FROM skipped_candidate_counterfactuals
           WHERE user_id = ? AND status = 'matured' AND connected_account_id = ?
           ORDER BY return_pct DESC, updated_at DESC
           LIMIT ?`
        )
        .all(userId, connectedAccountId, limit)
    : getDb()
        .prepare(
          `SELECT *
           FROM skipped_candidate_counterfactuals
           WHERE user_id = ? AND status = 'matured'
           ORDER BY return_pct DESC, updated_at DESC
           LIMIT ?`
        )
        .all(userId, limit)) as RawSkippedCounterfactualRow[];
  return rows.map(toSkippedCounterfactualRow);
}

/**
 * Unbiased recent matured counterfactuals for source/factor evaluation. Unlike the dashboard helper
 * above, this orders by decision time rather than return, so negative outcomes cannot fall out of a
 * top-return slice and make a provider look better than it was. Multiple horizons remain explicit;
 * analysis callers choose one deterministically for each (run, symbol).
 */
export function listRecentMaturedSkippedCounterfactuals(
  userId: string = "local",
  limit = 500,
  connectedAccountId?: string
): SkippedCounterfactualRow[] {
  const rows = (connectedAccountId
    ? getDb()
        .prepare(
          `SELECT *
           FROM skipped_candidate_counterfactuals
           WHERE user_id = ? AND status = 'matured' AND connected_account_id = ?
           ORDER BY snapshot_at DESC, horizon_days ASC
           LIMIT ?`
        )
        .all(userId, connectedAccountId, limit)
    : getDb()
        .prepare(
          `SELECT *
           FROM skipped_candidate_counterfactuals
           WHERE user_id = ? AND status = 'matured'
           ORDER BY snapshot_at DESC, horizon_days ASC
           LIMIT ?`
        )
        .all(userId, limit)) as RawSkippedCounterfactualRow[];
  return rows.map(toSkippedCounterfactualRow);
}

/**
 * The MATURED counterfactual row for one (runId, symbol) veto key — the precise join input
 * for the Red Team efficacy scorecard. Unlike joining against `listMaturedSkippedCounterfactuals`
 * (a return_pct-DESC top slice), a keyed lookup can never drop the low/negative-return rows —
 * the exact avoided-loss cases `vetoValueAddRate` exists to count (Codex review on PR #365).
 * Multiple horizons can exist per key; the shortest horizon wins deterministically.
 */
export function getMaturedSkippedCounterfactualByRunSymbol(
  userId: string,
  runId: string,
  symbol: string
): SkippedCounterfactualRow | undefined {
  const row = getDb()
    .prepare(
      `SELECT *
       FROM skipped_candidate_counterfactuals
       WHERE user_id = ? AND run_id = ? AND symbol = ? AND status = 'matured'
       ORDER BY horizon_days ASC
       LIMIT 1`
    )
    .get(userId, runId, symbol) as RawSkippedCounterfactualRow | undefined;
  return row ? toSkippedCounterfactualRow(row) : undefined;
}

// ── Learned-context fact-tier CRUD ────────────────────────────────────────────

interface RawLearnedContextRow {
  id: string;
  user_id: string;
  scope: string;
  kind: string;
  subject: string;
  symbol: string | null;
  value: string;
  source: string;
  origin: string;
  risk_tier: string;
  confidence: number;
  contributor_user_id: string | null;
  connected_account_id: string | null;
  account_environment: string | null;
  learning_scope: string;
  transfer_state: string;
  asserted_at: string;
  superseded_by: string | null;
  expires_at: string | null;
}

export function mapLearnedContext(row: RawLearnedContextRow): LearnedContextRow {
  return {
    id: row.id,
    userId: row.user_id,
    scope: row.scope as LearnedContextRow["scope"],
    kind: row.kind as LearnedContextRow["kind"],
    subject: row.subject,
    symbol: row.symbol,
    value: row.value,
    source: row.source,
    origin: row.origin as LearnedContextRow["origin"],
    riskTier: row.risk_tier as LearnedContextRow["riskTier"],
    confidence: row.confidence,
    contributorUserId: row.contributor_user_id,
    connectedAccountId: row.connected_account_id,
    accountEnvironment: row.account_environment as LearnedContextRow["accountEnvironment"],
    learningScope: row.learning_scope as LearnedContextRow["learningScope"],
    transferState: row.transfer_state as LearnedContextRow["transferState"],
    assertedAt: row.asserted_at,
    supersededBy: row.superseded_by,
    expiresAt: row.expires_at
  };
}

export function insertLearnedContext(row: LearnedContextRow): LearnedContextRow {
  getDb()
    .prepare(
      `INSERT INTO learned_context
        (id, user_id, scope, kind, subject, symbol, value, source, origin, risk_tier, confidence, contributor_user_id,
         connected_account_id, account_environment, learning_scope, transfer_state, asserted_at, superseded_by, expires_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    )
    .run(
      row.id,
      row.userId,
      row.scope,
      row.kind,
      row.subject,
      row.symbol,
      row.value,
      row.source,
      row.origin,
      row.riskTier,
      row.confidence,
      row.contributorUserId,
      row.connectedAccountId,
      row.accountEnvironment,
      row.learningScope,
      row.transferState,
      row.assertedAt,
      row.supersededBy,
      row.expiresAt
    );
  return row;
}

export function findLiveLearnedContextBySubject(
  userId: string,
  kind: string,
  subject: string,
  symbol: string | null,
  connectedAccountId: string | null = null,
  learningScope: LearnedContextRow["learningScope"] = "portfolio"
): LearnedContextRow | null {
  const row = getDb()
    .prepare(
      `SELECT * FROM learned_context
       WHERE user_id = ? AND kind = ? AND subject = ? AND ((symbol IS NULL AND ? IS NULL) OR symbol = ?)
         AND learning_scope = ?
         AND ((connected_account_id IS NULL AND ? IS NULL) OR connected_account_id = ?)
         AND superseded_by IS NULL
       ORDER BY asserted_at DESC LIMIT 1`
    )
    .get(userId, kind, subject, symbol, symbol, learningScope, connectedAccountId, connectedAccountId) as
      | RawLearnedContextRow
      | undefined;
  return row ? mapLearnedContext(row) : null;
}

/**
 * Live FACT rows for a decision: the user's own private rows plus, when includeShared is set,
 * other contributors' opted-in shared rows. Filtered to the given symbols (plus symbol-less
 * rows, which are general facts) and to non-expired rows. READ-ONLY — never mutates.
 */
export function listLearnedContextForDecision(
  userId: string,
  symbols: string[],
  includeShared = false,
  connectedAccountId?: string
): LearnedContextRow[] {
  const nowIso = new Date().toISOString();
  const normalizedSymbols = new Set(symbols.map((s) => s.toUpperCase()));
  const rows = includeShared
    ? (getDb()
        .prepare(
          `SELECT * FROM learned_context
           WHERE superseded_by IS NULL AND risk_tier = 'fact'
             AND (user_id = ? OR scope = 'shared')`
        )
        .all(userId) as RawLearnedContextRow[])
    : (getDb()
        .prepare(
          `SELECT * FROM learned_context
           WHERE superseded_by IS NULL AND risk_tier = 'fact' AND user_id = ?`
        )
        .all(userId) as RawLearnedContextRow[]);
  return rows
    .map(mapLearnedContext)
    .filter((r) => {
      if (r.learningScope === "legacy") return false;
      if (r.userId === userId) {
        if (r.learningScope === "portfolio") return true;
        if (r.learningScope === "research") return r.transferState === "validated";
        return Boolean(connectedAccountId) && r.connectedAccountId === connectedAccountId;
      }
      if (!includeShared || r.scope !== "shared") return false;
      // Shared portfolio facts retain the user's explicit sharing behavior. Account-derived rows
      // never cross a user/account boundary; shared research must pass transfer validation first.
      return r.learningScope === "portfolio" ||
        (r.learningScope === "research" && r.transferState === "validated");
    })
    .filter((r) => r.expiresAt === null || r.expiresAt > nowIso)
    .filter((r) => r.symbol === null || normalizedSymbols.has(r.symbol.toUpperCase()));
}

export function listLearnedContext(userId: string): LearnedContextRow[] {
  const rows = getDb()
    .prepare("SELECT * FROM learned_context WHERE user_id = ? AND superseded_by IS NULL ORDER BY asserted_at DESC")
    .all(userId) as RawLearnedContextRow[];
  return rows.map(mapLearnedContext);
}

export function supersedeLearnedContext(oldId: string, newId: string): void {
  getDb().prepare("UPDATE learned_context SET superseded_by = ? WHERE id = ?").run(newId, oldId);
}

/**
 * Set an expiry on a live learned_context row (the daily learning review's 'expire' verdict:
 * "was true, no longer is"). Expired rows stop informing decisions via the existing
 * `expiresAt` filter in listLearnedContextForDecision but remain in the table for provenance —
 * softer than deleteLearnedContext. Ownership-scoped; returns false on a no-op.
 */
export function expireLearnedContext(id: string, userId: string, expiresAtIso: string = new Date().toISOString()): boolean {
  const result = getDb()
    .prepare("UPDATE learned_context SET expires_at = ? WHERE id = ? AND user_id = ?")
    .run(expiresAtIso, id, userId);
  return result.changes > 0;
}

/**
 * Erase a learned-context row the user no longer wants remembered. Scoped to `user_id` — the
 * ORIGINAL contributor, never a reader — so this also serves as the erasure path for a user's own
 * shared-scope contributions (a shared row's `user_id` stays its author; another user who merely
 * reads it via `includeShared` can never delete it). Returns false on a no-op (missing id or
 * foreign ownership) so the route can 404 instead of silently succeeding.
 */
export function deleteLearnedContext(id: string, userId: string): boolean {
  const result = getDb().prepare("DELETE FROM learned_context WHERE id = ? AND user_id = ?").run(id, userId);
  return result.changes > 0;
}

// ── RAG ingestion de-dup helpers ──────────────────────────────────────────────
// Keyed by (accession, doc_type) — globally unique for SEC filings, so no user scoping needed.

export interface IngestedAccessionRow {
  accession: string;
  docType: string;
  ticker: string;
  indexedAt: string;
  chunkCount: number;
}

/** Return true if this (accession, docType) pair has already been embedded. */
export function hasIngestedAccession(accession: string, docType: string): boolean {
  const row = getDb()
    .prepare("SELECT 1 FROM sec_filings WHERE accession = ? AND form = ? AND status = 'complete'")
    .get(accession, docType);
  if (row != null) return true;

  const legacyRow = getDb()
    .prepare("SELECT 1 FROM ingested_accessions WHERE accession = ? AND doc_type = ?")
    .get(accession, docType);
  return legacyRow != null;
}

/** Record a successfully-ingested accession so it is never re-embedded. */
export function insertIngestedAccession(accession: string, docType: string, ticker: string, chunkCount: number): void {
  const now = new Date().toISOString();
  getDb()
    .prepare(
      "INSERT OR IGNORE INTO ingested_accessions (accession, doc_type, ticker, indexed_at, chunk_count) VALUES (?, ?, ?, ?, ?)"
    )
    .run(accession, docType, ticker, now, chunkCount);

  // Preserve the original SEC filed_at/accepted_at from the scraper (if the row already
  // exists) rather than overwriting every field via insertSecFiling, which sets both
  // to 'now' from this code path.  The clearCache admin route (§ reindex-10k/route.ts)
  // orders the latest-10-per-form query by sec_filings.filed_at to match the set that
  // refreshFilingBodies will refetch from SEC, so losing the real SEC dates would make
  // the cache-clearing query select the wrong accessions and leave cleared-but-not-rebuilt
  // filings permanently missing from the vector store.
  const existing = getSecFiling(accession);
  if (existing) {
    getDb().prepare(
      "UPDATE sec_filings SET status = 'complete', chunk_count = ?, updated_at = ? WHERE accession = ?"
    ).run(chunkCount, now, accession);
  } else {
    insertSecFiling({
      accession,
      cik: "",
      ticker,
      form: docType,
      filedAt: now,
      acceptedAt: now,
      status: "complete",
      chunkCount,
    });
  }
}

/** List all ingested accessions (admin/diagnostic). */
export function listIngestedAccessions(limit = 200): IngestedAccessionRow[] {
  const rows = getDb()
    .prepare("SELECT accession, doc_type, ticker, indexed_at, chunk_count FROM ingested_accessions ORDER BY indexed_at DESC LIMIT ?")
    .all(limit) as Array<{ accession: string; doc_type: string; ticker: string; indexed_at: string; chunk_count: number }>;
  return rows.map((r) => ({ accession: r.accession, docType: r.doc_type, ticker: r.ticker, indexedAt: r.indexed_at, chunkCount: r.chunk_count }));
}

/**
 * Count ever-ingested `ingested_accessions` rows per doc type (all tickers, all time), keyed by a
 * LOWERCASED doc type — cheap single GROUP BY, no new table/migration. Raw counts only; see
 * `ingestedAccessionCountForDocType` for the prefix-tolerant lookup callers should actually use.
 */
export function ingestedAccessionCountsByDocType(): Record<string, number> {
  const rows = getDb()
    .prepare("SELECT LOWER(doc_type) AS doc_type, COUNT(*) AS n FROM ingested_accessions GROUP BY LOWER(doc_type)")
    .all() as Array<{ doc_type: string; n: number }>;
  const counts: Record<string, number> = {};
  for (const row of rows) counts[row.doc_type] = row.n;
  return counts;
}

/**
 * Count ever-ingested rows for ONE requested doc type (all tickers, all time).
 *
 * `doc_type` casing/naming in `ingested_accessions` is NOT uniform across writers — see
 * src/lib/web-sources/sec-filings.ts (stores the raw SEC form letter, e.g. "10-K"/"10-Q") vs.
 * src/lib/web-sources/sec8k.ts's FULL-BODY writer (stores the sentinel "8-K-body", not "8-K").
 * The prefix-tolerant lookup below (any stored type whose lowercased form starts with the
 * requested lowercased type) reconciles that split — e.g. "8-k-body" counts toward requested
 * "8-k"; "10-k" counts toward requested "10-k" exactly (no other stored type shares that prefix).
 *
 * IMPORTANT CAVEAT (found 2026-07-06, see docs/rollouts/2026-07-06-corpus-coverage-receipt.md):
 * this table is NOT a complete producer-existence signal for "8-k". The default-ON 8-K SUMMARY
 * writer (`refreshEightK`'s `storeContexts` call in sec8k.ts) writes retrievable "8-k" chunks to
 * the vector corpus but never calls `insertIngestedAccession` at all — only the default-OFF
 * full-body writer (`ingestEightKBody`) does. So in the default config this function returns 0 for
 * "8-k" even when the corpus has real, retrievable 8-K chunks. That is exactly why
 * `COVERAGE_CHECKED_DOC_TYPES` in strategy.ts (the corpus-coverage receipt's allowlist) EXCLUDES
 * "8-k" — the receipt only both-conditions-checks doc types (currently 10-k/10-q) whose ledger IS
 * complete. strategy.ts builds its own in-memory prefix lookup on top of the bulk
 * `ingestedAccessionCountsByDocType()` (rather than calling this function once per type) and feeds
 * it into `computeEmptyDocTypes` (prompt-safety.ts) as a `hasProducerForDocType` predicate. This
 * function itself remains a correct, useful admin/diagnostic "how many accessions has this
 * pipeline recorded for doc type X" count — including for "8-k", where it still answers "how many
 * full-body accessions" correctly, just not "does 8-k coverage exist at all."
 */
export function ingestedAccessionCountForDocType(requestedDocType: string): number {
  const counts = ingestedAccessionCountsByDocType();
  const requested = requestedDocType.toLowerCase();
  let total = 0;
  for (const [storedType, n] of Object.entries(counts)) {
    if (storedType.startsWith(requested)) total += n;
  }
  return total;
}

// ── document_chunks content-hash dedup ─────────────────────────────────────

/** Check whether a chunk with this content_hash has already been embedded. */
export function hasDocumentChunk(contentHash: string): boolean {
  const row = getDb()
    .prepare("SELECT 1 FROM document_chunks WHERE content_hash = ?")
    .get(contentHash);
  return row != null;
}

/** Batch-check which content_hashes are new (not yet stored). Returns the set of NEW hashes. */
export function filterNewDocumentChunks(
  hashes: Array<{ content_hash: string; symbol: string; source: string; chunk_id: string }>
): typeof hashes {
  if (hashes.length === 0) return [];
  // Build placeholders for IN clause — SQLite max is 999, well above any chunk batch.
  const placeholders = hashes.map(() => "?").join(",");
  const flatHashes = hashes.map((h) => h.content_hash);
  const existing = new Set<string>();
  const rows = getDb()
    .prepare(`SELECT content_hash FROM document_chunks WHERE content_hash IN (${placeholders})`)
    .all(...flatHashes) as Array<{ content_hash: string }>;
  for (const row of rows) existing.add(row.content_hash);
  return hashes.filter((h) => !existing.has(h.content_hash));
}

/** Record successfully-embedded chunks so their content_hash is never re-embedded. */
export function insertDocumentChunks(
  chunks: Array<{ content_hash: string; symbol: string; source: string; chunk_id: string }>
): void {
  if (chunks.length === 0) return;
  const stmt = getDb().prepare(
    "INSERT OR IGNORE INTO document_chunks (content_hash, symbol, source, chunk_id, created_at) VALUES (?, ?, ?, ?, ?)"
  );
  const now = new Date().toISOString();
  const insertMany = getDb().transaction((rows: typeof chunks) => {
    for (const c of rows) stmt.run(c.content_hash, c.symbol, c.source, c.chunk_id, now);
  });
  insertMany(chunks);
}

/** Per-symbol chunk coverage stats (admin/diagnostic). */
export interface ChunkCoverageRow {
  symbol: string;
  chunkCount: number;
  latestAt: string;
}

export function getChunkCoverage(): ChunkCoverageRow[] {
  const rows = getDb()
    .prepare(`
      SELECT symbol, COUNT(*) as chunk_count, MAX(created_at) as latest_at
      FROM (
        SELECT symbol, content_hash, created_at FROM chunk_occurrences
        UNION ALL
        SELECT symbol, content_hash, created_at FROM document_chunks
        WHERE content_hash NOT IN (SELECT DISTINCT content_hash FROM chunk_occurrences)
      )
      GROUP BY symbol
      ORDER BY chunk_count DESC
    `)
    .all() as Array<{ symbol: string; chunk_count: number; latest_at: string }>;
  return rows.map((r) => ({ symbol: r.symbol, chunkCount: r.chunk_count, latestAt: r.latest_at }));
}

export interface ChunkSourceBreakdownRow {
  symbol: string;
  source: string;
  chunkCount: number;
}

export function getChunkSourceBreakdown(): ChunkSourceBreakdownRow[] {
  const rows = getDb()
    .prepare(`
      SELECT symbol, source, COUNT(*) as chunk_count
      FROM (
        SELECT symbol, source, content_hash FROM chunk_occurrences
        UNION ALL
        SELECT symbol, source, content_hash FROM document_chunks
        WHERE content_hash NOT IN (SELECT DISTINCT content_hash FROM chunk_occurrences)
      )
      GROUP BY symbol, source
    `)
    .all() as Array<{ symbol: string; source: string; chunk_count: number }>;
  return rows.map((r) => ({ symbol: r.symbol, source: r.source, chunkCount: r.chunk_count }));
}

