    -- reconciler ratchets upward each tick (trail_percent records the configured trail distance).
    CREATE TABLE IF NOT EXISTS broker_protective_stops (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      account_number TEXT NOT NULL,
