// Free daily OHLC price-history fetch — the single source of bars for the app.
//
// Two consumers share this: the technical connector (`web-sources/technical.ts`, which
// only reads closes) and the symbol-drilldown price chart (`/api/history`, which needs
// full candles). Sources cascade keyed-first then free: Massive → Tradier → Marketstack →
// Yahoo → Stooq. Keyed providers are reliable from datacenter IPs; the free endpoints
// (Yahoo/Stooq) are frequently rate-limited (HTTP 429) or bot-challenged server-side, so a
// keyed provider is strongly recommended. Server-side only; cached briefly. Never fabricates
// — no bars → returns null, callers degrade to "—".

import type { OHLCBar } from "./indicators";
import { normalizeSymbol } from "./money";
import { fulfillMarketDataDemand, getConnectedAccountByBroker, getImportedPriceCloses, getImportedSpxCloses, hasDataPoolConsent, recordMarketDataDemand, resolveApiKeyWithSource, type ApiKeySource } from "./db";
import { emitDashboardEvent } from "./events";
import { massiveApiBase, reserveMassiveRestCall } from "./market-signals/massive";
import { fetchRobinhoodHistoricals } from "./robinhood";
import { appAClosesToBars, congressReadsEnabled, getCongressTradeClient } from "./api-clients/congress";
import { BROWSER_UA, politeFetchJson, politeFetchText } from "./web-sources/http";

const DEFAULT_TTL_MS = 30 * 60_000; // daily bars only move intraday on the last candle
const cache = new Map<string, { expiresAt: number; bars: OHLCBar[] }>();
const KEYED_HISTORY_SERVICES = ["massive", "marketstack"] as const;
type CacheScope = "shared" | "private" | "pool";

interface YahooChartResponse {
  chart?: {
    result?: Array<{
      timestamp?: number[];
      indicators?: {
        quote?: Array<{
          open?: Array<number | null>;
          high?: Array<number | null>;
          low?: Array<number | null>;
          close?: Array<number | null>;
          volume?: Array<number | null>;
        }>;
        /** Split-and-dividend-adjusted closes — prefer these over quote.close for multi-year returns. */
        adjclose?: Array<{ adjclose?: Array<number | null> }>;
      };
    }>;
  };
}

function historyTtlMs(): number {
  const v = Number(process.env.HISTORY_TTL_MS ?? DEFAULT_TTL_MS);
  return Number.isFinite(v) && v > 0 ? v : DEFAULT_TTL_MS;
}

/**
 * Fetch ~5y of daily OHLC bars for a symbol, cached briefly. Cascades keyed providers
 * first (reliable, generous limits): Massive (Polygon-compatible) → Tradier → Marketstack,
 * then the free fallbacks Yahoo → Stooq. Keyed sources are skipped when no user/env key is
 * available. Returns the first source that yields ≥2 bars, or null (never fabricated). Free
 * endpoints (Yahoo/Stooq) are frequently rate-limited or bot-challenged from datacenter IPs,
 * so a keyed provider is strongly recommended for reliable charts + the in-house technical
 * "computed" producer.
 */
export async function fetchDailyOHLC(rawSymbol: string, now: number = Date.now(), userId?: string): Promise<OHLCBar[] | null> {
  const symbol = normalizeSymbol(rawSymbol);
  if (!symbol) return null;

  const keySources: Record<(typeof KEYED_HISTORY_SERVICES)[number], { key?: string; source: ApiKeySource }> = {
    massive: resolveApiKeyWithSource("massive", userId),
    marketstack: resolveApiKeyWithSource("marketstack", userId)
  };
  const tradierCredential = resolveTradierHistoryCredential();
  const privateCacheKey = historyCacheKey(symbol, userId, "private");
  const poolCacheKey = historyCacheKey(symbol, userId, "pool");
  const sharedCacheKey = historyCacheKey(symbol, userId, "shared");
  const consented = hasDataPoolConsent(userId ?? "local");
  const privateHit = cache.get(privateCacheKey);
  if (privateHit && privateHit.expiresAt > now) return privateHit.bars;
  // The reciprocal pool is read ONLY by consenting users (they also contribute their keyed pulls
  // to it). Non-consenting users skip it entirely and fall through to the public/free shared tier.
  if (consented) {
    const poolHit = cache.get(poolCacheKey);
    if (poolHit && poolHit.expiresAt > now) return poolHit.bars;
  }
  const sharedHit = cache.get(sharedCacheKey);
  if (sharedHit && sharedHit.expiresAt > now) return sharedHit.bars;

  const startDate = new Date(now - 1825 * 24 * 60 * 60_000).toISOString().slice(0, 10);
  // Keyed providers first (brokerage-grade, generous limits, reliable from datacenter IPs),
  // then the free fallbacks. Keyed sources self-skip when their env key is unset.
  const sources: Array<{ scope: CacheScope; fetch: () => Promise<OHLCBar[] | null> }> = [
    // Local imported-EOD cache tier (congress.trade return-path): App A POSTs gap-fill closes to
    // /api/admin/securities/import; they land in imported_price_eod/imported_spx_eod. Reading the local
    // table first (ahead of the App A HTTP read and our keyed providers) lets an imported series displace
    // a re-fetch entirely. DEFAULT OFF + density-guarded inside fetchImportedHistory so a sparse gap-fill
    // never short-circuits with an incomplete series. Close-only bars.
    { scope: "shared", fetch: async () => fetchImportedHistory(symbol) },
    // congress.trade (App A) cache-aside tier: App A also pulls FMP, so reuse its EOD closes first
    // to spend the shared quota once and save App B's own (keyed) history calls. Returns close-only
    // bars (no OHLC), so an enabled price chart renders a line, not candles, on App A hits. No-op
    // unless CONGRESS_TRADE_READS_ENABLED is on; "shared" scope (App A is a public external source).
    { scope: "shared", fetch: () => fetchAppAHistory(symbol) },
    { scope: cacheScopeForKeySource(keySources.massive.source, userId), fetch: () => fetchMassive(symbol, startDate, keySources.massive.key) },
    // Always "shared" — sourced from the owner's own connected broker account, not a per-user key
    // or consent-gated pool contribution (see resolveTradierHistoryCredential's doc comment).
    { scope: "shared", fetch: () => fetchTradier(symbol, startDate, tradierCredential.key, tradierCredential.baseUrl) },
    { scope: cacheScopeForKeySource(keySources.marketstack.source, userId), fetch: () => fetchMarketstack(symbol, keySources.marketstack.key) },
    // First-party broker history — inert unless ROBINHOOD_ADAPTER=mcp + OAuth token present.
    // SECURITY: the Robinhood token is per-user, so this tier is FETCHED only when an explicit
    // userId is in scope. A shared/background pull (no userId — e.g. the computed-technicals
    // refresh that writes a GLOBAL dataset) must not borrow the operator's ('local') broker token.
    // The resulting BARS are public market data (not the user's private account), so — like any
    // other user-keyed source — they are cached consent-pooled: pool tier when the user opted into
    // the reciprocal data pool, otherwise kept private to that user (never force-shared).
    ...(userId
      ? [{ scope: cacheScopeForKeySource("user", userId), fetch: () => fetchRobinhoodHistoricals(symbol, { interval: "day", span: "5year", userId }) }]
      : []),
    { scope: "shared", fetch: () => fetchYahoo(symbol) },
    { scope: "shared", fetch: () => fetchStooq(symbol) }
  ];

  for (const source of sources) {
    const bars = await source.fetch();
    if (bars && bars.length >= 2) {
      const cacheKey = source.scope === "private" ? privateCacheKey : source.scope === "pool" ? poolCacheKey : sharedCacheKey;
      cache.set(cacheKey, { expiresAt: now + historyTtlMs(), bars });
      if (source.scope === "shared") emitHistoryDemandFilled(symbol, now);
      return bars;
    }
  }
  recordMarketDataDemand({ kind: "history", symbol, userId, now });
  return null;
}

function historyCacheKey(symbol: string, userId: string | undefined, scope: CacheScope): string {
  if (scope === "private") return `user:${userId ?? "local"}:${symbol}`;
  if (scope === "pool") return `pool:${symbol}`;
  return `shared:${symbol}`;
}

function cacheScopeForKeySource(source: ApiKeySource, userId: string | undefined): CacheScope {
  if (source !== "user") return "shared"; // env-key / free providers are public — everyone benefits.
  // A user's OWN provider key: shared globally if the env override is on; otherwise contributed to
  // the reciprocal POOL when the user has consented; otherwise kept private to that user.
  if (shareUserKeyedHistory()) return "shared";
  if (hasDataPoolConsent(userId ?? "local")) return "pool";
  return "private";
}

function shareUserKeyedHistory(): boolean {
  const value = (process.env.MARKET_DATA_SHARE_USER_KEYED_HISTORY ?? "off").trim().toLowerCase();
  return value === "1" || value === "true" || value === "yes" || value === "on";
}

function emitHistoryDemandFilled(symbol: string, now: number): void {
  const fill = fulfillMarketDataDemand({ kind: "history", symbol, now });
  if (!fill) return;
  emitDashboardEvent({
    type: "market-data",
    at: new Date(now).toISOString(),
    detail: {
      kind: fill.kind,
      cacheScope: "shared",
      pendingUserCount: fill.pendingUserCount,
      oldestRequestedAt: fill.oldestRequestedAt,
      latestRequestedAt: fill.latestRequestedAt
    }
  });
}

interface MassiveAggBar { t?: number; o?: number; h?: number; l?: number; c?: number; v?: number; vw?: number }
interface MassiveAggResponse { results?: MassiveAggBar[] }

/** Massive daily aggregates (Polygon-compatible REST). Generous limits — the preferred primary. */
async function fetchMassive(symbol: string, startDate: string, key?: string): Promise<OHLCBar[] | null> {
  if (!key) return null;
  if ((process.env.MASSIVE_HISTORY_ENABLED ?? "on").toLowerCase() === "off") return null;
  if (!reserveMassiveRestCall()) return null;
  const base = massiveApiBase();
  const to = new Date().toISOString().slice(0, 10);
  try {
    const url = `${base}/v2/aggs/ticker/${encodeURIComponent(symbol)}/range/1/day/${startDate}/${to}?adjusted=true&sort=asc&limit=50000`;
    const json = await politeFetchJson<MassiveAggResponse>(url, { headers: { Authorization: `Bearer ${key}`, Accept: "application/json" } });
    const rows = json?.results ?? [];
    const bars: OHLCBar[] = [];
    for (const r of rows) {
      if (typeof r.c !== "number" || !Number.isFinite(r.c) || typeof r.t !== "number") continue;
      bars.push({ time: r.t, open: numOrUndef(r.o), high: numOrUndef(r.h), low: numOrUndef(r.l), close: r.c, volume: numOrUndef(r.v), vwap: numOrUndef(r.vw) });
    }
    return bars.length >= 2 ? bars : null;
  } catch {
    return null;
  }
}

interface TradierHistoryDay {
  date?: string;
  open?: number;
  high?: number;
  low?: number;
  close?: number;
  volume?: number;
}
interface TradierHistoryResponse {
  history?: { day?: TradierHistoryDay | TradierHistoryDay[] } | null;
}

/**
 * Resolves Tradier's price-history credential from the owner's own CONNECTED broker account
 * (connected_accounts, broker "tradier") rather than a separate stored API key — the owner connects
 * Tradier once (even just as a data source, not necessarily as the active EXECUTION broker — see
 * getConnectedAccountByBroker's doc comment) and that connection's access token becomes the app's
 * Tradier price-history source too. Always resolves the "local" (owner's) connection regardless of
 * the requesting userId — a single connected broker naturally serves the whole app, mirroring the
 * "shared-operator-infra" model every other keyed history provider already uses via an env var, just
 * sourced from a broker connection instead. Sandbox vs production tracks the connection's own
 * `environment`, matching tradier.ts's own derivation for order placement.
 */
function resolveTradierHistoryCredential(): { key?: string; baseUrl: string } {
  const acct = getConnectedAccountByBroker("tradier", "local");
  return {
    key: acct?.apiKey?.trim() || undefined,
    baseUrl: acct?.environment === "live" ? "https://api.tradier.com" : "https://sandbox.tradier.com"
  };
}

/** Tradier daily history — brokerage-grade, generous rate limits. Best primary source. */
async function fetchTradier(symbol: string, startDate: string, key: string | undefined, baseUrl: string): Promise<OHLCBar[] | null> {
  if (!key) return null;
  try {
    const url = `${baseUrl}/v1/markets/history?symbol=${encodeURIComponent(symbol)}&interval=daily&start=${startDate}`;
    const json = await politeFetchJson<TradierHistoryResponse>(url, { headers: { Authorization: `Bearer ${key}`, Accept: "application/json" } });
    const day = json?.history?.day;
    const days = Array.isArray(day) ? day : day ? [day] : [];
    const bars: OHLCBar[] = [];
    for (const d of days) {
      if (typeof d.close !== "number" || !Number.isFinite(d.close) || !d.date) continue;
      bars.push({ time: d.date, open: numOrUndef(d.open), high: numOrUndef(d.high), low: numOrUndef(d.low), close: d.close, volume: numOrUndef(d.volume) });
    }
    return bars.length >= 2 ? bars : null;
  } catch {
    return null;
  }
}

interface MarketstackEodRow {
  date?: string;
  open?: number;
  high?: number;
  low?: number;
  close?: number;
  volume?: number;
}
interface MarketstackEodResponse {
  data?: MarketstackEodRow[];
}

/** Marketstack EOD — keyed fallback (free tier is monthly-capped, so secondary to Tradier). */
async function fetchMarketstack(symbol: string, key?: string): Promise<OHLCBar[] | null> {
  if (!key) return null;
  try {
    const url = `https://api.marketstack.com/v1/eod?access_key=${key}&symbols=${encodeURIComponent(symbol)}&limit=1500&sort=ASC`;
    const json = await politeFetchJson<MarketstackEodResponse>(url, {});
    const rows = json?.data ?? [];
    const bars: OHLCBar[] = [];
    for (const r of rows) {
      if (typeof r.close !== "number" || !Number.isFinite(r.close) || !r.date) continue;
      bars.push({ time: r.date, open: numOrUndef(r.open), high: numOrUndef(r.high), low: numOrUndef(r.low), close: r.close, volume: numOrUndef(r.volume) });
    }
    return bars.length >= 2 ? bars : null;
  } catch {
    return null;
  }
}

async function fetchYahoo(symbol: string): Promise<OHLCBar[] | null> {
  try {
    const url = `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(symbol)}?range=1y&interval=1d`;
    const json = await politeFetchJson<YahooChartResponse>(url, { headers: { "user-agent": BROWSER_UA, accept: "application/json" } });
    const result = json?.chart?.result?.[0];
    const ts = result?.timestamp ?? [];
    const q = result?.indicators?.quote?.[0];
    const rawClose = q?.close ?? [];
    // Prefer split+dividend-adjusted closes (adjclose) for correct multi-year returns.
    // Fall back to raw close if adjclose is absent or length-mismatched.
    const adjCloseArr = result?.indicators?.adjclose?.[0]?.adjclose ?? [];
    const useAdjusted = adjCloseArr.length === ts.length;
    if (ts.length === 0 || rawClose.length === 0) return null;
    const bars: OHLCBar[] = [];
    for (let i = 0; i < ts.length; i++) {
      const rawC = rawClose[i] ?? null;
      // Per-bar fallback: if adjclose entry is null/non-finite use rawC so Yahoo gaps
      // in adjclose don't cause bars with valid rawclose to be silently dropped.
      const adjEntry = useAdjusted ? (adjCloseArr[i] ?? null) : null;
      const usingAdj = typeof adjEntry === "number" && Number.isFinite(adjEntry);
      const c = usingAdj ? adjEntry : rawC;
      if (typeof c !== "number" || !Number.isFinite(c)) continue; // skip null/holiday gaps
      // Scale O/H/L by adjclose/rawclose so all four OHLC values stay on the same basis.
      // Candle consistency: close cannot fall outside [low, high] after ex-dividend adjustments.
      let o = numOrUndef(q?.open?.[i]);
      let h = numOrUndef(q?.high?.[i]);
      let l = numOrUndef(q?.low?.[i]);
      if (usingAdj && typeof rawC === "number" && Number.isFinite(rawC) && rawC !== 0) {
        const factor = c / rawC;
        if (o !== undefined) o = o * factor;
        if (h !== undefined) h = h * factor;
        if (l !== undefined) l = l * factor;
      }
      bars.push({
        time: ts[i] * 1000, // seconds → ms epoch
        open: o, high: h, low: l,
        close: c,
        volume: numOrUndef(q?.volume?.[i])
      });
    }
    return bars.length >= 2 ? bars : null;
  } catch {
    return null;
  }
}

async function fetchStooq(symbol: string): Promise<OHLCBar[] | null> {
  try {
    const url = `https://stooq.com/q/d/l/?s=${encodeURIComponent(symbol.toLowerCase())}.us&i=d`;
    const text = await politeFetchText(url, { headers: { "user-agent": BROWSER_UA } });
    const bars = parseStooqCsv(text);
    return bars.length >= 2 ? bars : null;
  } catch {
    return null;
  }
}

/** Parse a Stooq daily CSV (Date,Open,High,Low,Close,Volume) into bars. Pure / unit-tested. */
export function parseStooqCsv(text: string): OHLCBar[] {
  const out: OHLCBar[] = [];
  for (const line of text.split(/\r?\n/)) {
    const parts = line.split(",");
    if (parts.length < 5) continue;
    const [date, open, high, low, close, volume] = parts;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) continue; // skips the header row
    const c = Number(close);
    if (!Number.isFinite(c)) continue;
    out.push({
      time: date,
      open: Number(open),
      high: Number(high),
      low: Number(low),
      close: c,
      volume: volume ? Number(volume) : undefined
    });
  }
  return out;
}

/** Normalize a bar's `time` (ms-epoch number or date string) to a 'YYYY-MM-DD' business day. */
export function toBusinessDay(time: number | string | undefined): string | undefined {
  if (typeof time === "number" && Number.isFinite(time)) {
    const ms = time > 1e12 ? time : time * 1000;
    return new Date(ms).toISOString().slice(0, 10);
  }
  if (typeof time === "string") {
    if (/^\d{4}-\d{2}-\d{2}/.test(time)) return time.slice(0, 10);
    const parsed = Date.parse(time);
    if (Number.isFinite(parsed)) return new Date(parsed).toISOString().slice(0, 10);
  }
  return undefined;
}

function numOrUndef(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

export function clearHistoryCache(): void {
  cache.clear();
}

/**
 * congress.trade (App A) cache-aside source: App A's EOD close series for a symbol (or the S&P-500
 * via ^GSPC) as close-only OHLCBars. Returns null unless reads are enabled AND App A has ≥2 closes,
 * so the cascade falls through to App B's own providers on a miss. Self-guarded inside the client.
 */
async function fetchAppAHistory(symbol: string): Promise<OHLCBar[] | null> {
  if (!congressReadsEnabled()) return null;

  let closes: any[] = [];
  try {
    const client = getCongressTradeClient();
    if (symbol === "^GSPC") {
      closes = await client.getSpx();
    } else {
      const resp = await client.getPrices(symbol);
      closes = resp?.closes ?? [];
    }
  } catch (err) {
    // Ignore error, fallback logic kicks in
  }
  const bars = appAClosesToBars(closes);
  return bars.length >= 2 ? bars : null;
}

function importedHistoryTierEnabled(): boolean {
  const v = (process.env.SECURITIES_IMPORT_HISTORY_TIER_ENABLED ?? "").trim().toLowerCase();
  return v === "1" || v === "true" || v === "yes" || v === "on";
}

/** Minimum imported closes before the local tier may short-circuit the cascade (avoids sparse gap-fills). */
function importedHistoryMinBars(): number {
  const v = Number(process.env.SECURITIES_IMPORT_MIN_BARS ?? 200);
  return Number.isFinite(v) && v > 0 ? Math.floor(v) : 200;
}

/**
 * Local imported-EOD cache tier (congress.trade return-path). Serves App A's gap-fill closes that were
 * POSTed to /api/admin/securities/import (persisted in imported_price_eod / imported_spx_eod). DEFAULT
 * OFF (SECURITIES_IMPORT_HISTORY_TIER_ENABLED) and density-guarded (SECURITIES_IMPORT_MIN_BARS, default
 * 200 ≈ ~10 months) so a sparse gap-fill never displaces a full fetch with an incomplete series.
 * Close-only bars (no OHLC), like the App A HTTP tier — an enabled price chart renders a line on hits.
 */
function fetchImportedHistory(symbol: string): OHLCBar[] | null {
  if (!importedHistoryTierEnabled()) return null;
  const closes = symbol === "^GSPC" ? getImportedSpxCloses() : getImportedPriceCloses(symbol);
  if (closes.length < importedHistoryMinBars()) return null;
  const bars = appAClosesToBars(closes);
  return bars.length >= 2 ? bars : null;
}

// Shared LLM request shaping for the strategy/analysis call sites (Bull proposer, Bear/Red-Team
// reviewer, strategy tuning, proposal re-validation, post-mortem reflection). It turns a single
// provider-agnostic request spec into the correct wire body + auth headers for whichever transport
// `resolveLlmEndpoint` picked, and extracts the model's text/JSON back out uniformly.
//
// Why this exists: those call sites historically hand-built an OpenAI-shaped body (Bearer auth,
// `response_format` / `text.format`, `choices[].message.content`). Anthropic's Messages API is a
// different shape (top-level `system`, `max_tokens`, `x-api-key`, forced tool-use for guaranteed
// JSON, content-block responses). Centralizing the per-transport shaping here lets Claude be a
// first-class Green/Red team model everywhere those sites run, instead of OpenAI-only.

import { withLlmRequestBounds, type LlmTransport } from "./llm-request";
import type { LlmEndpoint } from "./llm-provider";
import type { LlmReasoningEffort } from "./types";
import { jsonrepair } from "jsonrepair";

/** A JSON schema plus the name/description used to label it (OpenAI json_schema / Anthropic tool). */
export interface LlmJsonSchema {
  name: string;
  schema: Record<string, unknown>;
  description?: string;
}

export interface LlmRequestSpec {
  /** The resolved model id (from the endpoint) that this body targets. */
  model: string;
  systemPrompt: string;
  /** The user turn — already serialized (JSON string or plain text). */
  userContent: string;
  maxOutputTokens: number;
  reasoningEffort?: LlmReasoningEffort;
  /**
   * Sampling temperature for non-reasoning/deterministic-sampling paths (ignored by models that
   * reject custom temperature — reasoning models steer via `reasoningEffort` instead; see
   * `withLlmRequestBounds`). Defaults to `LLM_REQUEST_DEFAULTS.deterministicTemperature` (0) when
   * omitted, preserving every existing call site's greedy-decode behavior. Set explicitly for
   * per-role sampling (composite review B/medium/S): the Bear/debate adversary roles run at a
   * non-zero temperature so a single same-family, temperature-0 critique doesn't always find the
   * exact same (or no) objection — see the Bear/debateProposal call sites.
   */
  temperature?: number;
  /**
   * Structured-output schema. When present:
   * - OpenAI/compatible (non-DeepSeek, non-Gemini) → strict `json_schema` (unless `openAiJsonObject`);
   * - Gemini → strict `json_schema`, but with `type: [T,"null"]` / anyOf-with-null rewritten to
   *   Gemini's single-type + `nullable:true` dialect first (see `toGeminiJsonSchema`); falls back to
   *   `json_object` only if a construct can't be translated;
   * - DeepSeek → `json_object` (it rejects strict json_schema);
   * - Anthropic → a single forced tool whose `input_schema` is this schema (reliable JSON).
   * Omit for free-text output (e.g. the post-mortem reflection paragraph).
   */
  schema?: LlmJsonSchema;
  /**
   * Force OpenAI-compatible providers to use `json_object` instead of strict `json_schema`, even
   * when a `schema` is supplied. Anthropic still uses the schema as a forced tool. Used by the
   * Red-Team debate, which historically asked OpenAI for a bare JSON object (prompt-described shape)
   * rather than a strict schema — this preserves that behavior while letting Claude enforce a tool.
   */
  openAiJsonObject?: boolean;
  userId?: string;
  metadata?: Record<string, string>;
}

/** Auth + content headers for the endpoint's provider (Anthropic uses x-api-key, others Bearer). */
export function llmAuthHeaders(endpoint: Pick<LlmEndpoint, "provider" | "key">): Record<string, string> {
  if (endpoint.provider === "anthropic") {
    return {
      "content-type": "application/json",
      "x-api-key": endpoint.key ?? "",
      "anthropic-version": "2023-06-01",
      // Honour cache_control blocks on the system prompt (prompt caching). (Chat A item 3.)
      "anthropic-beta": "prompt-caching-2024-07-31"
    };
  }
  if (endpoint.provider === "openrouter") {
    return {
      "content-type": "application/json",
      authorization: `Bearer ${endpoint.key ?? ""}`,
      "HTTP-Referer": "https://socratictrade.com",
      "X-Title": "Socratic.Trade"
    };
  }
  return {
    "content-type": "application/json",
    authorization: `Bearer ${endpoint.key ?? ""}`
  };
}

/** Build the provider-correct request body (already bounded with token caps / sampling params). */
export function buildLlmRequestBody(
  endpoint: Pick<LlmEndpoint, "provider" | "transport">,
  spec: LlmRequestSpec
): Record<string, unknown> {
  const { transport } = endpoint;
  const { systemPrompt, userContent, schema, openAiJsonObject, userId, metadata } = spec;
  const bounds = {
    maxOutputTokens: spec.maxOutputTokens,
    model: spec.model,
    reasoningEffort: spec.reasoningEffort,
    temperature: spec.temperature
  };

  // Build the OpenRouter-specific metadata tag if applicable.
  const inferredContext = () => {
    const sys = (systemPrompt || "").toLowerCase();
    const schemaName = schema?.name || "";
    if (schemaName === "trade_proposals" || sys.includes("green team") || sys.includes("proposer")) {
      return "green-team";
    }
    if (schemaName === "red_team_verdict" || sys.includes("red team") || sys.includes("reviewer") || sys.includes("adversary")) {
      return "red-team";
    }
    if (schemaName === "tuned_parameters" || sys.includes("tuner") || sys.includes("tuning") || sys.includes("autotuning")) {
      return "tuning";
    }
    if (sys.includes("salience") || sys.includes("memory") || sys.includes("importance")) {
      return "memory-salience";
    }
    if (sys.includes("multi-query") || sys.includes("rag") || sys.includes("retrieval")) {
      return "rag";
    }
    if (sys.includes("framework review") || sys.includes("framework_review")) {
      return "framework-review";
    }
    if (sys.includes("post-mortem") || sys.includes("post_mortem")) {
      return "post-mortem";
    }
    if (sys.includes("revalidation") || sys.includes("proposal-revalidation")) {
      return "revalidation";
    }
    return "assistant-chat";
  };

  const openRouterMetadata = endpoint.provider === "openrouter" ? {
    context: metadata?.context || inferredContext(),
    ...metadata
  } : undefined;

  const injectCommonFields = (base: Record<string, unknown>) => {
    if (userId) {
      if (endpoint.provider === "openrouter" || endpoint.provider === "openai" || endpoint.provider === "deepseek" || endpoint.provider === "gemini") {
        base.user = userId;
      } else if (endpoint.provider === "anthropic") {
        base.metadata = { ...(base.metadata as Record<string, unknown> || {}), user_id: userId };
      }
    }
    if (openRouterMetadata) {
      base.metadata = {
        ...(base.metadata as Record<string, unknown> || {}),
        ...openRouterMetadata
      };
    }
  };

  if (transport === "anthropic-messages") {
    const base: Record<string, unknown> = {
      model: spec.model,
      // Prompt-caching: send the (stable) system prompt as a single ephemeral cache block so
      // Anthropic reuses the cached KV across repeated strategy/red-team calls. The per-run dynamic
      // data lives in the user message, not here, so the whole system prefix is cacheable. The
      // caching beta header is added in llmAuthHeaders. (Chat A item 3; finer-grained prefix/suffix
      // splitting can follow if a dynamic tail is ever moved into the system prompt.)
      system: [{ type: "text", text: systemPrompt, cache_control: { type: "ephemeral" } }],
      messages: [{ role: "user", content: userContent }]
    };
    if (schema) {
      // Forced tool-use is Anthropic's structured-output mechanism: the model must call this single
      // tool, so its `input` comes back as schema-shaped JSON (no prose to strip / regex out).
      base.tools = [
        {
          name: schema.name,
          description: schema.description ?? `Return the result as ${schema.name}.`,
          input_schema: schema.schema
        }
      ];
      base.tool_choice = { type: "tool", name: schema.name };
    }
    injectCommonFields(base);
    return withLlmRequestBounds(base, transport, bounds);
  }

  const messages = [
    { role: "system", content: systemPrompt },
    { role: "user", content: userContent }
  ];

  if (transport === "chat-completions") {
    const base: Record<string, unknown> = { model: spec.model, messages };
    const responseFormat = openAiChatResponseFormat(endpoint.provider, schema, openAiJsonObject, spec.model);
    if (responseFormat) base.response_format = responseFormat;
    injectCommonFields(base);
    return withLlmRequestBounds(base, transport, bounds);
  }

  // responses transport (OpenAI)
  const base: Record<string, unknown> = { model: spec.model, input: messages };
  const textFormat = openAiResponsesTextFormat(schema, openAiJsonObject);
  if (textFormat) base.text = { format: textFormat };
  injectCommonFields(base);
  return withLlmRequestBounds(base, transport, bounds);
}

/**
 * Recursively rewrites a JSON Schema node so Gemini's OpenAI-compatible endpoint (an
 * OpenAPI-3.0-derived structured-output dialect) reliably accepts it. Three rewrites:
 *   1. `type: [T, "null"]` union-type arrays (the app's standard "optional numeric/string field"
 *      encoding — see the Bull trade-proposal schema's quantity/dollarAmount/limitPrice/stopPrice/
 *      bracketStopLoss/bracketTakeProfit in strategy.ts) → a single `type` plus `nullable: true`
 *      (Gemini's OpenAPI-3.0 dialect).
 *   2. An `anyOf` branch that is just `{ type: "null" }` (the app's "optional whole sub-object"
 *      encoding — see `autonomyOverrideSchema` in strategy.ts) — same fix, collapsed to the
 *      non-null branch with `nullable: true` added.
 *   3. `maxItems`/`minItems` on array nodes are STRIPPED from the wire schema and folded into the
 *      node's `description` instead. Root cause of the 2026-07-08 Roth Bull outage (400
 *      INVALID_ARGUMENT in ~1s, no field details): Gemini's structured-output validator expands an
 *      array's item subtree ONCE PER `maxItems` slot against an undocumented internal complexity
 *      budget, so `maxItems × <rich item schema>` overflows it — empirically, the 15-property Bull
 *      item schema passed at maxItems<=7 and was rejected at maxItems=8, while the SAME schema with
 *      two fewer properties passed at 8, and the Bear proposal schema (no maxItems, but the SAME
 *      nullable fields and anyOf) always passed. The count bound is advisory-for-the-model anyway:
 *      every consumer truncates deterministically app-side (`sanitizeProposals(..., maxProposals)`),
 *      so stripping it can never let extra proposals through — the description keeps the model
 *      aiming for the right count. (Constructs 1/2 are dialect-compat conversions kept from the
 *      earlier fix attempt; the raw unions were later shown to be accepted too, but the converted
 *      form is Gemini's documented dialect, so we keep emitting it.)
 *
 * Returns `unsupported: true` when the walk hits a shape this transform can't collapse into Gemini's
 * dialect (a `type` array or `anyOf` with more than one remaining non-null alternative — nothing in
 * this app's schemas does that today, but a future schema addition might), so the caller can fall back
 * to a bare `json_object` the same way the existing DeepSeek special case does, rather than forwarding
 * a schema Gemini is still likely to reject.
 */
export function toGeminiJsonSchema(node: unknown): { schema: unknown; unsupported: boolean } {
  let unsupported = false;

  const isNullOnly = (candidate: unknown): boolean =>
    !!candidate &&
    typeof candidate === "object" &&
    !Array.isArray(candidate) &&
    (candidate as Record<string, unknown>).type === "null" &&
    Object.keys(candidate as Record<string, unknown>).length === 1;

  const walk = (value: unknown): unknown => {
    if (Array.isArray(value)) return value.map(walk);
    if (!value || typeof value !== "object") return value;

    const obj = value as Record<string, unknown>;
    const result: Record<string, unknown> = {};
    // Item-count bounds stripped off this node (rewrite 3 above) — folded into `description` below.
    let minItems: number | undefined;
    let maxItems: number | undefined;

    for (const [key, val] of Object.entries(obj)) {
      if (key === "maxItems" || key === "minItems") {
        // Gemini's validator multiplies the item subtree by the bound (complexity blow-up, see the
        // doc comment) — never forward it; keep the intent as prose for the model instead. A
        // non-numeric bound (malformed schema) is stripped without a prose fold.
        if (typeof val === "number" && Number.isFinite(val)) {
          if (key === "maxItems") maxItems = val;
          else minItems = val;
        }
        continue;
      }
      if (key === "type" && Array.isArray(val)) {
        const nonNullTypes = val.filter((t) => t !== "null");
        const hadNull = nonNullTypes.length !== val.length;
        if (nonNullTypes.length === 1) {
          result.type = nonNullTypes[0];
          if (hadNull) result.nullable = true;
        } else {
          // Either no non-null type at all (malformed) or more than one — no single Gemini `type`
          // this can collapse to.
          unsupported = true;
          result.type = val;
        }
        continue;
      }
      if (key === "anyOf" && Array.isArray(val)) {
        const branches = val as unknown[];
        const nonNullBranches = branches.filter((b) => !isNullOnly(b));
        const hadNull = nonNullBranches.length !== branches.length;
        if (nonNullBranches.length === 1) {
          const collapsed = walk(nonNullBranches[0]) as Record<string, unknown>;
          Object.assign(result, collapsed);
          if (hadNull) result.nullable = true;
        } else {
          // Zero or 2+ non-null branches remain — can't collapse to a single Gemini-shaped node.
          unsupported = true;
          result.anyOf = nonNullBranches.map(walk);
          if (hadNull) result.nullable = true;
        }
        continue;
      }
      result[key] = walk(val);
    }
    if (maxItems !== undefined || minItems !== undefined) {
      const bound =
        maxItems !== undefined && minItems !== undefined
          ? `between ${minItems} and ${maxItems}`
          : maxItems !== undefined
            ? `at most ${maxItems}`
            : `at least ${minItems}`;
      const constraint = `Return ${bound} items.`;
      const existing = typeof result.description === "string" && result.description.trim().length > 0 ? `${result.description.trim()} ` : "";
      result.description = `${existing}${constraint}`;
    }
    return result;
  };

  return { schema: walk(node), unsupported };
}

function openAiChatResponseFormat(
  provider: LlmEndpoint["provider"],
  schema: LlmJsonSchema | undefined,
  openAiJsonObject: boolean | undefined,
  model?: string
): Record<string, unknown> | undefined {
  const isGemini = provider === "gemini" || (model && /^google\//i.test(model));
  const isDeepSeek = provider === "deepseek" || (model && /^deepseek\//i.test(model));

  if (schema && !openAiJsonObject && isGemini) {
    const { schema: geminiSchema, unsupported } = toGeminiJsonSchema(schema.schema);
    if (unsupported) {
      console.warn(
        `[llm-call] Gemini schema "${schema.name}" has a construct toGeminiJsonSchema can't translate ` +
          "(type-union or anyOf with 2+ non-null branches) — falling back to json_object."
      );
      return { type: "json_object" };
    }
    return { type: "json_schema", json_schema: { name: schema.name, strict: true, schema: geminiSchema } };
  }
  if (schema && !openAiJsonObject && !isDeepSeek) {
    return { type: "json_schema", json_schema: { name: schema.name, strict: true, schema: schema.schema } };
  }
  if (schema || openAiJsonObject) return { type: "json_object" };
  return undefined;
}

function openAiResponsesTextFormat(
  schema: LlmJsonSchema | undefined,
  openAiJsonObject: boolean | undefined
): Record<string, unknown> | undefined {
  // strict:true matches the chat-completions branch — without it the Responses API treats the
  // schema as advisory and schema-drifting output can slip through as merely JSON-shaped data.
  // Every schema routed here (Bull/Bear proposals, red-team verdict, revalidation, tuning) is
  // strict-conformant: additionalProperties:false + full required lists, null via type unions.
  if (schema && !openAiJsonObject) return { type: "json_schema", name: schema.name, strict: true, schema: schema.schema };
  if (schema || openAiJsonObject) return { type: "json_object" };
  return undefined;
}

/**
 * True when the model stopped because it hit the output-token cap (a truncated answer), across
 * transports: OpenAI chat-completions `finish_reason:"length"`, OpenAI responses API
 * `incomplete_details.reason:"max_output_tokens"` / top-level `status:"incomplete"`, and Anthropic
 * Messages `stop_reason:"max_tokens"`. A truncated JSON answer usually fails to parse, so callers use
 * this to distinguish "output cap too small" from a genuine empty result.
 */
export function detectLlmTruncation(payload: unknown): boolean {
  if (!payload || typeof payload !== "object") return false;
  const p = payload as {
    stop_reason?: unknown;
    choices?: unknown;
    status?: unknown;
    incomplete_details?: { reason?: unknown } | null;
    output?: unknown;
  };
  if (p.stop_reason === "max_tokens") return true;
  if (Array.isArray(p.choices) && p.choices.some((c) => (c as { finish_reason?: unknown } | null)?.finish_reason === "length")) return true;
  if (p.status === "incomplete" && p.incomplete_details?.reason === "max_output_tokens") return true;
  if (Array.isArray(p.output) && p.output.some((o) => (o as { status?: unknown } | null)?.status === "incomplete")) return true;
  return false;
}

/**
 * Extract the model's text answer across all transports, normalized to a string the caller can
 * `JSON.parse` (when a schema was used) or read directly (free text):
 * - OpenAI responses API: `output_text`, else the first text block in `output[]`.
 * - OpenAI/compatible chat-completions: `choices[0].message.content`.
 * - Mistral chat-completions at high reasoning effort: `choices[0].message.content` is a LIST of
 *   chunks (`{type:"thinking", thinking:[...]}` + `{type:"text", text}`) rather than a plain
 *   string — only the `"text"` chunk(s) are the answer.
 * - Anthropic Messages: a `tool_use` block's `input` (re-serialized to JSON) if present, else the
 *   concatenated `text` blocks.
 */
export function extractLlmText(payload: unknown): string | undefined {
  if (!payload || typeof payload !== "object") return undefined;
  const root = payload as {
    output_text?: unknown;
    choices?: Array<{ message?: { content?: unknown } }>;
    output?: Array<{ content?: Array<{ text?: unknown }> }>;
    content?: Array<{ type?: string; text?: unknown; input?: unknown }>;
  };

  if (typeof root.output_text === "string" && root.output_text.length > 0) return root.output_text;

  const chatText = root.choices?.[0]?.message?.content;
  if (typeof chatText === "string" && chatText.length > 0) return chatText;

  // Mistral high-reasoning-effort chat-completions responses: `message.content` is a list of
  // chunks instead of a string (https://docs.mistral.ai/studio-api/conversations/reasoning).
  // Concatenate only the final-answer "text" chunk(s); skip "thinking" chunks (the reasoning
  // trace), mirroring how the Anthropic content-block case below skips non-text blocks.
  if (Array.isArray(chatText)) {
    const chunks = chatText as Array<{ type?: unknown; text?: unknown }>;
    const textJoined = chunks
      .filter((chunk) => chunk?.type === "text" && typeof chunk.text === "string")
      .map((chunk) => chunk.text as string)
      .join("");
    if (textJoined.length > 0) return textJoined;
  }

  // Anthropic Messages content blocks.
  if (Array.isArray(root.content)) {
    const toolUse = root.content.find((b) => b?.type === "tool_use" && b.input !== undefined);
    if (toolUse) return JSON.stringify(toolUse.input);
    const textJoined = root.content
      .filter((b) => b?.type === "text" && typeof b.text === "string")
      .map((b) => b.text as string)
      .join("");
    if (textJoined.length > 0) return textJoined;
  }

  const responseText = root.output
    ?.flatMap((item) => item.content ?? [])
    .find((item) => typeof item.text === "string")?.text;
  if (typeof responseText === "string") return responseText;

  // Fall back to an empty OpenAI chat string (preserves prior `typeof content === "string"` semantics).
  return typeof chatText === "string" ? chatText : undefined;
}

/**
 * Extract a JSON object/array payload from an LLM text response that may be wrapped in
 * markdown code fences or surrounded by prose. Root-cause fix for the `gemini-3.5-flash`
 * failure where a fenced / prose-wrapped reply made a bare `JSON.parse(text)` throw and
 * silently disabled the adversarial review (see docs/single-adversary-consolidation.md
 * §4.1 + review point R9).
 *
 * Strategy: (1) strip an enclosing ```json / ``` fence; (2) if the remainder still isn't
 * bare JSON, return the FIRST BALANCED `{…}` or `[…]` block, scanned string- and
 * escape-aware so braces inside string values don't miscount. This is deliberately NOT a
 * greedy first-`{`-to-last-`}` slice (R9): that corrupts output when prose contains a
 * stray bracket or multiple JSON-looking blocks. When no balanced block is found (e.g. a
 * truncated response), returns the trimmed/unfenced text unchanged so the caller's own
 * `JSON.parse` try/catch still governs the failure — never fabricates valid JSON.
 *
 * `repair` (default OFF) additionally runs local, deterministic jsonrepair when the
 * extracted payload still isn't valid JSON. Opt-in ONLY, per call site, because repair can
 * turn a TRUNCATED response into syntactically valid JSON — e.g. `{"verdict":"approve"`
 * becomes a well-formed approval object. On safety-critical parse paths (Red Team verdicts,
 * proposal revalidation, tuning payloads) that converts fail-closed "unavailable" handling
 * into fail-open acceptance, which is exactly the defect class Codex flagged on PR #1696.
 * Those sites MUST call this without `repair`; generative sites that opt in MUST re-validate
 * schema-required fields on the parsed result (repair proves syntax, never completeness).
 */
export function extractJsonPayload(text: string, options: { repair?: boolean } = {}): string {
  const unfenced = text
    .trim()
    .replace(/^```(?:json5?|jsonc)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  const primary = firstBalancedJson(unfenced) ?? unfenced;

  try {
    JSON.parse(primary);
    return primary;
  } catch {
    if (!options.repair) return primary; // caller's own JSON.parse governs the failure
    // Repair the ORIGINAL unfenced text before the balanced slice: firstBalancedJson only
    // understands double-quoted strings, so a single-quoted payload whose string values
    // contain '}' gets sliced MID-STRING — repairing that fragment silently truncates content
    // or drops trailing proposals (Codex P2, round 9). Full-text repair sees the whole payload;
    // the slice remains only as a fallback for prose-wrapped responses where full-text repair
    // cannot apply. Wrong-content beats no-content on this path: a full-text repair that
    // yields a non-object degrades to zero proposals downstream, which is the safe direction.
    try {
      const repairedFull = jsonrepair(unfenced);
      JSON.parse(repairedFull);
      return repairedFull;
    } catch {
      // fall through to the balanced slice
    }
    try {
      return jsonrepair(primary);
    } catch {
      // Unrepairable; let the caller's JSON.parse fail loudly
      return primary;
    }
  }
}

/** First balanced `{…}`/`[…]` block starting at the first opener, or undefined if none/unbalanced. */
function firstBalancedJson(text: string): string | undefined {
  const start = text.search(/[[{]/);
  if (start === -1) return undefined;
  const open = text[start];
  const close = open === "{" ? "}" : "]";
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (ch === "\\") escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') inString = true;
    else if (ch === open) depth++;
    else if (ch === close && --depth === 0) return text.slice(start, i + 1);
  }
  return undefined; // unbalanced (e.g. truncated) — let the caller's JSON.parse fail loudly
}

import { resolveLlmCredential } from "./db";
import { resolveOpenAiModel, type LlmTransport } from "./llm-request";

export type LlmTeamRole = "green" | "red" | "support";
export type LlmModelFamily = "openai" | "anthropic" | "xai" | "gemini" | "mistral" | "deepseek" | "openrouter";

export interface LlmEndpoint {
  provider: "openai" | "anthropic" | "xai" | "gemini" | "mistral" | "deepseek" | "openrouter";
  url: string;
  key?: string;
  model: string;
  keySource: "operator" | "user";
  keyRef?: string;
  transport: LlmTransport;
}

/**
 * The model FAMILY (provider) a model name belongs to, using the same name-prefix rules
 * `resolveLlmEndpoint` uses to pick a wire transport. Exposed so callers (the cross-family Bear
 * default below) can compare families without duplicating the regexes.
 */
export function llmModelFamily(model: string | undefined): LlmModelFamily {
  const normalized = (model ?? "").trim();
  if (/^claude/i.test(normalized)) return "anthropic";
  if (/^grok/i.test(normalized)) return "xai";
  if (/^gemini/i.test(normalized)) return "gemini";
  if (/^(mistral|ministral|magistral|codestral|devstral|pixtral|open-mistral|open-mixtral)/i.test(normalized)) return "mistral";
  if (/^openrouter\//i.test(normalized)) return "openrouter";
  if (/^deepseek/i.test(normalized)) return "deepseek";
  return "openai";
}

// Cross-family Red Team DEFAULT removed 2026-07-07 (owner directive: no model is a default for
// anything, ever). The Red Team model is the user's explicit `redTeamLlmModel` or nothing;
// resolveRoleModel returns "" when unset and the caller fails closed. Independence (a different
// model/provider from Green) is the user's choice, nudged by a non-blocking Settings hint, never
// auto-defaulted.

/**
 * Resolve the model for a team role. NO DEFAULTS (owner directive 2026-07-07): the Red Team is the
 * user's explicit `redTeamLlmModel` or "" (unconfigured — the caller MUST fail closed); it NEVER
 * falls back to the Green model or a cross-family default. Green/support resolve to the user's
 * `llmModel` or "".
 */
function resolveRoleModel(
  policy: { llmModel?: string | null; redTeamLlmModel?: string | null } | undefined | null,
  role: LlmTeamRole
): string {
  if (role === "red") return policy?.redTeamLlmModel?.trim() || "";
  return resolveOpenAiModel(policy);
}

/**
 * Provider is derived from the model name (no separate provider flag): claude-* → Anthropic
 * (Messages API), grok-* → xAI (Grok), gemini-* → Google (Gemini), mistral/ministral/codestral/… → Mistral,
 * else OpenAI. xAI/Gemini/Mistral/DeepSeek are all OpenAI-compatible (chat/completions), so those
 * call sites treat them like OpenAI but with a per-provider base URL + key. Anthropic returns its
 * own `anthropic-messages` transport so the shared request builder (`llm-call.ts`) shapes the
 * Messages-API body/headers and forced-tool JSON output. The user selects a provider simply by
 * choosing one of its models — for both the Green (proposal) and Red (review) teams.
 */
export function resolveLlmEndpoint(
  policy?: { llmModel?: string | null; redTeamLlmModel?: string | null } | null,
  userId: string = "local",
  // Preserved for signature compatibility, though OpenRouter always uses chat-completions.
  defaultOpenAiUrl: string = "https://api.openai.com/v1/responses",
  role: LlmTeamRole = "green"
): LlmEndpoint {
  const rawModel = resolveRoleModel(policy, role);
  let model = rawModel;

  // Prefix raw model names with the appropriate OpenRouter provider ID if they don't already have one.
  if (!model.includes("/")) {
    if (/^claude/i.test(model)) {
      model = `anthropic/${model}`;
    } else if (/^grok/i.test(model)) {
      // OpenRouter's Grok namespace is `x-ai/`, not `xai/` — the latter is an invalid model id
      // OpenRouter rejects (Codex finding on PR #1703).
      model = `x-ai/${model}`;
    } else if (/^gemini/i.test(model)) {
      model = `google/${model}`;
    } else if (/^(mistral|ministral|magistral|codestral|devstral|pixtral|open-mistral|open-mixtral)/i.test(model)) {
      model = `mistralai/${model}`;
    } else if (/^deepseek/i.test(model)) {
      model = `deepseek/${model}`;
    } else if (/^(gpt|o1|o3)/i.test(model)) {
      model = `openai/${model}`;
    }
  }

  // Strip a legacy openrouter/ prefix that may have been saved in older policy selections
  // (e.g. "openrouter/google/gemini-2.5-flash" → "google/gemini-2.5-flash").
  model = model.replace(/^openrouter\//i, "");

  const url = process.env.OPENROUTER_API_URL?.trim() || "https://openrouter.ai/api/v1/chat/completions";
  const nativeProvider = llmModelFamily(rawModel);
  const cred = resolveLlmCredential(process.env.NODE_ENV === "test" ? nativeProvider : "openrouter", userId);

  return {
    provider: "openrouter",
    url,
    key: cred.key,
    model, // The fully qualified model ID sent to OpenRouter
    keySource: cred.source === "operator" ? "operator" : "user",
    keyRef: cred.keyRef,
    transport: "chat-completions"
  };
}

import type { LlmReasoningEffort } from "./types";

/** OpenAI and OpenAI-compatible (xAI/Gemini/Mistral/DeepSeek) HTTP shapes. */
export type OpenAiTransport = "responses" | "chat-completions";
/** "rotation" is a UI-ONLY pseudo-provider for the "__rotate__" seat sentinel (see
 *  ROTATION_UI_REASONING_CAPABILITY) — no wire-shaping branch may ever match it. */
export type LlmReasoningProvider = "openai" | "anthropic" | "xai" | "gemini" | "mistral" | "deepseek" | "rotation";

export interface LlmReasoningOption {
  value: LlmReasoningEffort;
  label: string;
  hint: string;
}

export interface LlmReasoningCapability {
  provider: LlmReasoningProvider;
  label: string;
  settingLabel: string;
  description: string;
  options: LlmReasoningOption[];
}

/**
 * Every LLM wire transport the app speaks. Anthropic's Messages API ("anthropic-messages") is NOT
 * OpenAI-compatible (top-level `system`, `max_tokens`, `x-api-key` header, content-block responses,
 * forced tool-use for structured JSON), so it is modelled as its own transport rather than folded
 * into the OpenAI-compatible pair. See `llm-call.ts` for the per-transport request/response shaping.
 */
export type LlmTransport = OpenAiTransport | "anthropic-messages";

// DEFAULT_OPENAI_MODEL removed 2026-07-07 (owner directive: no model is a default for anything,
// ever). Strategy Green/Red resolve to explicit per-user choices ("" when unset → fail closed);
// the chat assistant requires an explicit per-request model or CHAT_LLM_MODEL (no hardcoded model).

/**
 * Sentinel model id meaning "rotate through every eligible curated model, a different one each
 * run" (owner comparative-measurement option for accruing attributed history across models). It is a valid
 * PERSISTED value for policy.llmModel / policy.redTeamLlmModel, but it must never be SERVED:
 * `runStrategyOnce` substitutes the concrete pick onto its run-scoped policy clone at the top of
 * every run (src/lib/model-rotation.ts) before any endpoint resolution. Defined here (leaf module,
 * no imports beyond types) so both the rotation module and `resolveOpenAiModel`'s safety net below
 * can share it without an import cycle. Keep the literal in sync with the UI copy in
 * app/ui/llm-model-catalog.ts (ROTATE_ALL_MODELS_ID).
 */
export const LLM_MODEL_ROTATION_SENTINEL = "__rotate__";

/** True when the model id is the rotation sentinel (see LLM_MODEL_ROTATION_SENTINEL). */
export function isModelRotationSentinel(model?: string | null): boolean {
  return (model ?? "").trim() === LLM_MODEL_ROTATION_SENTINEL;
}

/**
 * OpenAI "reasoning" models (gpt-5 family, o-series). They REJECT the `temperature` param
 * (400 "Only the default (1) value is supported") and instead take `reasoning_effort`. They also
 * spend output budget on hidden reasoning tokens, so the visible-output cap must be raised.
 */
export function isReasoningModel(model: string | undefined): boolean {
  return /^(gpt-5|o\d)/i.test(lowerModel(model));
}

/**
 * Resolve the per-user Green (strategist/proposer) model. NO DEFAULT — owner directive
 * (2026-07-07): no model is a default for anything, ever. Both the Green (`llmModel`) and Red
 * (`redTeamLlmModel`) team models must be explicitly chosen in Settings, and it is enforced
 * impossible to save a policy without them (app/api/policy/route.ts). Returns "" when unchosen;
 * callers MUST treat "" as unconfigured and fail closed (route to human / skip the run), never
 * send an empty-model request. The former `OPENAI_MODEL`-env and `DEFAULT_OPENAI_MODEL` strategy
 * fallbacks are deliberately removed.
 *
 * The rotation sentinel ("__rotate__") is ALSO treated as unset here — a SAFETY NET for consumers
 * that read the persisted policy directly OUTSIDE a strategy run (chat, the outcome-engine lesson
 * pass, strategy tuning, the run route's key precheck): with no defaults left it resolves to ""
 * (fail closed) instead of sending the literal "__rotate__" to a provider. The strategy run itself
 * substitutes the concrete rotation pick before ever reaching this function
 * (src/lib/model-rotation.ts).
 */
export function resolveOpenAiModel(policy?: { llmModel?: string | null } | null): string {
  const fromPolicy = policy?.llmModel?.trim();
  if (fromPolicy && fromPolicy !== LLM_MODEL_ROTATION_SENTINEL) return fromPolicy;
  return "";
}

export const ALL_LLM_REASONING_EFFORTS: readonly LlmReasoningEffort[] = ["none", "minimal", "low", "medium", "high", "xhigh", "max"];

const REASONING_OPTION_BY_VALUE: Record<LlmReasoningEffort, LlmReasoningOption> = {
  none: { value: "none", label: "None", hint: "Disable provider-side thinking where that provider allows it." },
  minimal: { value: "minimal", label: "Minimal", hint: "Smallest supported thinking budget above off." },
  low: { value: "low", label: "Low", hint: "Lower latency and cost; less deliberate analysis." },
  medium: { value: "medium", label: "Medium", hint: "Balanced depth, latency, and cost." },
  high: { value: "high", label: "High", hint: "Deeper analysis with higher latency and token use." },
  xhigh: { value: "xhigh", label: "XHigh", hint: "Extra-high provider thinking budget where supported." },
  max: { value: "max", label: "Max", hint: "Provider maximum thinking budget where supported." }
};

function options(values: readonly LlmReasoningEffort[]): LlmReasoningOption[] {
  return values.map((value) => REASONING_OPTION_BY_VALUE[value]);
}

function lowerModel(model: string | undefined): string {
  let name = (model ?? "").trim().toLowerCase();
  // Strip provider prefixes for capability matching (e.g. anthropic/claude-3 -> claude-3)
  if (name.includes("/")) {
    name = name.split("/").pop() || name;
  }
  return name;
}

function isAnthropicAdaptiveThinkingModel(model: string | undefined): boolean {
  const normalized = lowerModel(model);
  return (
    /^claude-fable-5(?:$|[-.:_])/.test(normalized) ||
    /^claude-mythos-5(?:$|[-.:_])/.test(normalized) ||
    /^claude-opus-4-(?:6|7|8)(?:$|[-.:_])/.test(normalized) ||
    /^claude-sonnet-(?:5|4-6)(?:$|[-.:_])/.test(normalized)
  );
}

function isXaiReasoningModel(model: string | undefined): boolean {
  return /^grok-4(?:\.3)?(?:$|[-.:_])/.test(lowerModel(model));
}

function isGeminiModel(model: string | undefined): boolean {
  return /^gemini(?:$|[-.:_])/.test(lowerModel(model));
}

function geminiAllowsThinkingOff(model: string | undefined): boolean {
  return /^gemini-2\.5-(?:flash|flash-lite)(?:$|[-.:_])/.test(lowerModel(model));
}

// Mistral reasoning capability is deliberately narrow (benchmark 2026-07-08: 0/12 calls
// succeeded under the old family-wide map). Provider-enforced facts from Mistral's own 400s:
// mistral-medium-3-5 accepts reasoning_effort ∈ {high, none} ONLY ("reasoning_effort medium
// is not supported for this model, supported values: [high, none]"), and mistral-small-2603
// rejects the reasoning prompt mode outright ("Reasoning prompt mode is not enabled for this
// model"). Every other Mistral-family id (small, large, magistral, codestral, …) gets NO
// reasoning capability — a plain chat-completions body is the only shape known valid across
// the family, and the catalog only offers small-2603/medium-3-5 anyway.
function isMistralReasoningEffortModel(model: string | undefined): boolean {
  return /^mistral-medium-3-5(?:$|[-.:_])/.test(lowerModel(model));
}

function isDeepSeekV4Model(model: string | undefined): boolean {
  return /^deepseek-v4-(?:flash|pro)(?:$|[-.:_])/.test(lowerModel(model));
}

function isGpt56Model(model: string | undefined): boolean {
  return /^gpt-5\.6(?:-(?:luna|terra|sol))?(?:$|[-.:_])/.test(lowerModel(model));
}

export function reasoningCapabilityForModel(model: string | undefined): LlmReasoningCapability | undefined {
  if (isGpt56Model(model)) {
    return {
      provider: "openai",
      label: "OpenAI Reasoning",
      settingLabel: "Reasoning Effort",
      description: "GPT-5.6 supports the complete none-to-max reasoning ladder.",
      options: options(["none", "low", "medium", "high", "xhigh", "max"])
    };
  }
  if (isReasoningModel(model)) {
    return {
      provider: "openai",
      label: "OpenAI Reasoning",
      settingLabel: "Reasoning Effort",
      description: "OpenAI gpt-5/o-series models use reasoning effort and reject custom temperature.",
      options: options(["low", "medium", "high"])
    };
  }
  if (isAnthropicAdaptiveThinkingModel(model)) {
    return {
      provider: "anthropic",
      label: "Claude Adaptive Thinking",
      settingLabel: "Thinking Effort",
      description: "Recent Claude models use adaptive thinking with provider-specific effort levels.",
      options: options(["low", "medium", "high", "xhigh", "max"])
    };
  }
  if (isXaiReasoningModel(model)) {
    return {
      provider: "xai",
      label: "Grok Reasoning",
      settingLabel: "Reasoning Effort",
      description: "Grok reasoning models accept none/low/medium/high effort.",
      options: options(["none", "low", "medium", "high"])
    };
  }
  if (isGeminiModel(model)) {
    return {
      provider: "gemini",
      label: "Gemini Thinking",
      settingLabel: "Thinking Level",
      description: geminiAllowsThinkingOff(model)
        ? "Gemini thinking can be disabled or scaled on selected 2.5 Flash models."
        : "Gemini thinking can be scaled, but this model family does not support turning it fully off.",
      options: options(geminiAllowsThinkingOff(model) ? ["none", "minimal", "low", "medium", "high"] : ["minimal", "low", "medium", "high"])
    };
  }
  if (isMistralReasoningEffortModel(model)) {
    return {
      provider: "mistral",
      label: "Mistral Reasoning",
      settingLabel: "Reasoning Effort",
      description: "Mistral Medium 3.5 accepts only high or none reasoning effort.",
      options: options(["none", "high"])
    };
  }
  if (isDeepSeekV4Model(model)) {
    return {
      provider: "deepseek",
      label: "DeepSeek Thinking",
      settingLabel: "Thinking Mode",
      description: "DeepSeek V4 can disable thinking or use high/max thinking effort.",
      options: options(["none", "high", "max"])
    };
  }
  return undefined;
}

/**
 * UI-ONLY synthetic reasoning capability for the "__rotate__" seat sentinel. Since the per-team
 * split (2026-07-10) a rotating seat HIDES its manual effort control — rotation auto-sets each
 * served model's curated recommended effort (src/lib/model-reasoning-recommendations.ts) — so this
 * capability now only feeds the Models card's summary line (its "Rotating Models" label) and the
 * reasoning-control helpers' rotation awareness, not an editable control.
 *
 * Deliberately NOT returned by `reasoningCapabilityForModel`: every server call path derives its
 * wire shape from that function (and from `normalizeReasoningEffortForModel`), and both must keep
 * failing closed on a raw sentinel — the strategy run substitutes the concrete rotation pick before
 * any request is shaped (src/lib/model-rotation.ts), and each served model then re-clamps the
 * effort to its own supported range (`interactiveStrategyReasoningEffort`).
 */
export const ROTATION_UI_REASONING_CAPABILITY: LlmReasoningCapability = {
  provider: "rotation",
  label: "Rotating Models",
  settingLabel: "Reasoning / Thinking Effort",
  description:
    "This seat rotates through the curated models each run. Reasoning is auto-set per rotated model " +
    "at its curated recommended level (models without a curated recommendation run Medium).",
  options: options(ALL_LLM_REASONING_EFFORTS)
};

export function normalizeReasoningEffortForOptions(
  optionsForModel: readonly Pick<LlmReasoningOption, "value">[],
  effort: LlmReasoningEffort | undefined
): LlmReasoningEffort {
  const allowed = optionsForModel.map((option) => option.value);
  if (allowed.length === 0) return "medium";
  if (effort === undefined) return allowed.includes("medium") ? "medium" : (allowed[0] ?? "medium");
  const requested = effort;
  if (allowed.includes(requested)) return requested;
  const requestedRank = ALL_LLM_REASONING_EFFORTS.indexOf(requested);
  const rankedAllowed = allowed
    .map((value) => ({ value, distance: Math.abs(ALL_LLM_REASONING_EFFORTS.indexOf(value) - requestedRank) }))
    .sort((a, b) => a.distance - b.distance || ALL_LLM_REASONING_EFFORTS.indexOf(a.value) - ALL_LLM_REASONING_EFFORTS.indexOf(b.value));
  return rankedAllowed[0]?.value ?? allowed[0] ?? "medium";
}

export function normalizeReasoningEffortForModel(
  model: string | undefined,
  effort: LlmReasoningEffort | undefined
): LlmReasoningEffort | undefined {
  const capability = reasoningCapabilityForModel(model);
  if (!capability) return undefined;
  if (capability.provider === "deepseek") {
    // DeepSeek V4 exposes only three tiers: thinking OFF ("none"), "high", and "max". A sub-high
    // request (none/minimal/low/medium — including the app's "medium" DEFAULT) resolves to the FAST
    // "none" tier, NOT a silent upgrade to "high". "high" spends a long, unbounded hidden-reasoning
    // phase server-side before emitting any visible JSON; on a non-streaming whole-response await that
    // routinely blew the 60s request timeout (Green/Bear "timed out after 60s using DeepSeek"). High-
    // effort DeepSeek thinking is now OPT-IN: choose "high"/"xhigh"/"max" explicitly. The settings UI
    // resolves the displayed effort through this SAME function, so the effort shown is always exactly
    // the effort sent — the user can never select a value different from what actually runs.
    if (effort === "max" || effort === "xhigh") return "max";
    if (effort === "high") return "high";
    return "none";
  }
  if (capability.provider === "mistral") {
    // Mistral Medium 3.5 accepts exactly two efforts (provider 400: "supported values:
    // [high, none]"). Same opt-in rule as DeepSeek above: only an explicit high/xhigh/max
    // enables the slow high-reasoning tier; everything else — including the app's "medium"
    // default — resolves to "none" rather than silently upgrading to high. (The generic
    // rank-distance normalization below would map "medium" to "high".) The settings UI
    // resolves through this same function, so the effort shown equals the effort sent.
    if (effort === "high" || effort === "xhigh" || effort === "max") return "high";
    return "none";
  }
  return normalizeReasoningEffortForOptions(capability.options, effort);
}

/**
 * Resolve the Red Team reviewer's reasoning effort from a policy: the reviewer-specific
 * `redTeamReasoningEffort` when explicitly set, otherwise the proposer's legacy
 * `llmReasoningEffort` (per-team split 2026-07-10: the legacy field is the PROPOSER's; the
 * reviewer inherits it until the owner explicitly sets its own). Every reviewer/red-team call
 * site MUST resolve through this helper so the fallback lives in exactly one place — never read
 * `policy.redTeamReasoningEffort` directly at a call site.
 */
export function resolveReviewerReasoningEffort(
  policy?: { llmReasoningEffort?: LlmReasoningEffort; redTeamReasoningEffort?: LlmReasoningEffort } | null
): LlmReasoningEffort | undefined {
  return policy?.redTeamReasoningEffort ?? policy?.llmReasoningEffort;
}

export function isDisallowedInteractiveStrategyReasoningConfig(model: string | undefined, effort: LlmReasoningEffort | undefined): boolean {
  const normalized = normalizeReasoningEffortForModel(model, effort);
  return /^gpt-5\.5(?:$|[-.:_])/i.test(lowerModel(model)) && normalized === "high";
}

export function interactiveStrategyReasoningEffort(model: string, effort: LlmReasoningEffort | undefined): LlmReasoningEffort | undefined {
  const normalized = normalizeReasoningEffortForModel(model, effort);
  if (!normalized) return undefined;
  return isDisallowedInteractiveStrategyReasoningConfig(model, normalized) ? "medium" : normalized;
}

/**
 * Extra output-token headroom for reasoning models (hidden reasoning tokens are billed against the
 * same completion cap as the visible answer). Originally OpenAI-only (Fable composite review
 * B/high/S: `withLlmRequestBounds` added this headroom ONLY in the `provider === 'openai'` branch,
 * so xAI/Gemini/Mistral/DeepSeek chat-completions calls kept the bare 1500-token cap even at
 * medium/high reasoning effort — a hard-thinking non-OpenAI call could spend its whole budget on
 * hidden reasoning tokens and truncate the visible JSON answer before it ever started). Covers every
 * effort level any provider's capability options expose (`none`/`minimal` need no extra headroom).
 */
const REASONING_TOKEN_BUDGET: Record<Exclude<LlmReasoningEffort, "none">, number> = {
  minimal: 1000,
  low: 2000,
  medium: 4000,
  high: 8000,
  xhigh: 12000,
  max: 16000
};

/** Extra visible-output headroom for a provider's reasoning effort, or 0 when the effort spends no
 *  hidden tokens against the completion cap ("none", or no reasoning capability at all). */
function reasoningTokenHeadroom(effort: LlmReasoningEffort | undefined): number {
  if (!effort || effort === "none") return 0;
  return REASONING_TOKEN_BUDGET[effort];
}

export const LLM_REQUEST_DEFAULTS = {
  deterministicTemperature: 0,
  maxOutputTokens: 1500,
  /**
   * Sampling temperature for the single Red Team reviewer (`debateProposal`). Composite review
   * B/medium/S: "everything runs at temperature 0 including red-teaming, so one greedy same-family
   * reviewer surfaces one failure mode." A non-zero adversary temperature widens the set of
   * objections a re-run could surface instead of always finding the exact same (or no) flaw.
   * Per-role sampling: the proposer (Bull/Green) keeps temperature 0 (deterministic, unaffected).
   */
  adversaryTemperature: 0.7
} as const;

/** Hard wall-clock cap on a single LLM HTTP call. A half-open OpenAI/Anthropic connection
 *  otherwise hangs the caller indefinitely — and for the strategy run that means holding the
 *  per-user run lock (starving the scheduler) with no error to alert on. */
export const LLM_TIMEOUT_MS = 60_000;

class RateLimiter {
  private queue: number[] = [];

  async wait(rpmLimitStr: string | undefined) {
    if (!rpmLimitStr) return;
    const rpm = parseInt(rpmLimitStr, 10);
    if (isNaN(rpm) || rpm <= 0) return;

    const now = Date.now();
    this.queue = this.queue.filter(t => now - t < 60000);

    if (this.queue.length >= rpm) {
      const oldest = this.queue[0];
      const waitTime = 60000 - (now - oldest);
      if (waitTime > 0) {
        await new Promise(r => setTimeout(r, waitTime));
      }
    }
    this.queue.push(Date.now());
  }
}

const geminiRateLimiter = new RateLimiter();

/**
 * fetch() for LLM endpoints with a bounded timeout. On expiry the request is aborted and the
 * promise rejects (AbortError), which every call site already treats as an LLM failure (falls
 * back / surfaces an error) rather than hanging forever. A caller may pass its own `signal`.
 */
export async function llmFetch(url: string, init: RequestInit = {}): Promise<Response> {
  if (url.includes("generativelanguage.googleapis.com")) {
    await geminiRateLimiter.wait(process.env.GEMINI_RPM_LIMIT);
  }
  return fetch(url, { ...init, signal: init.signal ?? AbortSignal.timeout(LLM_TIMEOUT_MS) });
}

/**
 * Wall-clock cap for a strategy Green/Bear LLM call, widened for a thinking-enabled reasoning model.
 * A reasoning model that is ACTUALLY thinking (effort resolves to something other than "none") can
 * legitimately spend well past the 60s default generating hidden reasoning tokens before it emits the
 * visible JSON, so a non-streaming whole-response await would otherwise abort a call that was still
 * making progress (this is the DeepSeek "timed out after 60s" failure). Both bounds are env-tunable —
 * STRATEGY_LLM_TIMEOUT_MS for the base, STRATEGY_LLM_REASONING_TIMEOUT_MS for the thinking bound.
 * Trade-off: a longer bound holds the per-user run lock longer (see LLM_TIMEOUT_MS), so the widening
 * applies ONLY when the model is in a thinking mode the user explicitly opted into (never at the fast
 * default). A non-reasoning or thinking-off model keeps the base 60s bound unchanged.
 */
export function strategyLlmTimeoutMs(model: string | undefined, effort: LlmReasoningEffort | undefined): number {
  const base = Number(process.env.STRATEGY_LLM_TIMEOUT_MS) || LLM_TIMEOUT_MS;
  const normalized = normalizeReasoningEffortForModel(model, effort);
  const thinking = !!normalized && normalized !== "none";
  if (!thinking) return base;
  return Math.max(base, Number(process.env.STRATEGY_LLM_REASONING_TIMEOUT_MS) || 150_000);
}

/** The eventual result of an LLM call, reported once the request finally settles (fast OR late). */
export interface LlmCallOutcome {
  /** Wall-clock ms from request start to settle. */
  durationMs: number;
  /** True when it settled AFTER the soft timeout (i.e. the strategy tick had already given up on it). */
  late: boolean;
  ok: boolean;
  status?: number;
  error?: string;
  /** The eventual Response. On the LATE path the caller (which bailed at the soft timeout and never
   *  read the body) may read this to capture the reply for debugging. Absent when the request errored. */
  response?: Response;
}

/**
 * A strategy LLM fetch that CAPTURES latency and never severs a slow reply. It resolves with the
 * Response if it arrives within `softTimeoutMs`; otherwise it rejects with a TimeoutError — so the
 * caller's existing timeout/fallback path runs and the tick moves on — BUT the underlying request
 * keeps running (up to a generous `hardCapMs` leak backstop, default max(2×soft, 300s)) and its
 * eventual outcome (duration, status, and the late Response) is reported via `onOutcome`. This is what
 * lets us record how long a model like DeepSeek actually takes and keep the reply we already paid for,
 * instead of aborting at the wall and discarding the evidence. Unlike `llmFetch`, no soft-timeout
 * abort signal is attached to the fetch — only the hard cap.
 */
export async function llmFetchCapturing(
  url: string,
  init: RequestInit,
  opts: { softTimeoutMs: number; hardCapMs?: number; onOutcome?: (outcome: LlmCallOutcome) => void }
): Promise<Response> {
  if (url.includes("generativelanguage.googleapis.com")) {
    await geminiRateLimiter.wait(process.env.GEMINI_RPM_LIMIT);
  }
  const started = Date.now();
  const softMs = opts.softTimeoutMs;
  const hardCap = Math.max(softMs, opts.hardCapMs ?? Math.max(softMs * 2, 300_000));
  const fetchPromise = fetch(url, { ...init, signal: init.signal ?? AbortSignal.timeout(hardCap) });

  const emit = opts.onOutcome;
  if (emit) {
    fetchPromise.then(
      (response) => {
        const durationMs = Date.now() - started;
        emit({ durationMs, late: durationMs > softMs, ok: response.ok, status: response.status, response });
      },
      (error) => {
        const durationMs = Date.now() - started;
        emit({ durationMs, late: durationMs > softMs, ok: false, error: error instanceof Error ? error.message : String(error) });
      }
    );
  }

  let softTimer: ReturnType<typeof setTimeout> | undefined;
  const softTimeout = new Promise<never>((_, reject) => {
    softTimer = setTimeout(() => reject(new DOMException(`Strategy LLM soft timeout after ${softMs}ms`, "TimeoutError")), softMs);
  });
  // Clear the soft timer once the fetch settles so it can't reject a race nobody is watching anymore.
  const clear = () => { if (softTimer) clearTimeout(softTimer); };
  fetchPromise.then(clear, clear);
  return Promise.race([fetchPromise, softTimeout]);
}

/** HTTP statuses worth failing over to another provider (rate limit / transient upstream errors). */
const RETRYABLE_LLM_STATUSES = new Set([429, 500, 502, 503, 504]);
export function isRetryableLlmStatus(status: number): boolean {
  return RETRYABLE_LLM_STATUSES.has(status);
}
/** True for timeouts (AbortSignal.timeout → AbortError/TimeoutError) and transient network errors. */
export function isRetryableLlmError(error: unknown): boolean {
  const name = (error as { name?: string } | null)?.name;
  if (name === "AbortError" || name === "TimeoutError") return true;
  const msg = String((error as { message?: string } | null)?.message ?? error ?? "");
  return /abort|timed? ?out|timeout|ECONNRESET|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|network|fetch failed/i.test(msg);
}

export interface LlmRetryOptions {
  /** Total attempts INCLUDING the first (default 2, clamped 1–3). Keep small: the adversary runs
   *  inside the per-user scheduler lock — aggressive retries starve the scheduler and defeat the
   *  reason the hard per-call timeout exists (design doc §4.3). */
  attempts?: number;
  /** Base backoff before attempt N+1: `baseDelayMs * 2^N` (default 500ms — total added wall-clock
   *  stays trivially small relative to the per-attempt timeout). */
  baseDelayMs?: number;
  /** Per-attempt timeout; each attempt gets its OWN AbortSignal so a retry never inherits an
   *  already-expiring signal. Defaults to LLM_TIMEOUT_MS via llmFetch. */
  timeoutMs?: number;
  /** Observability hook — called before each retry with what triggered it. */
  onRetry?: (info: { attempt: number; status?: number; error?: unknown }) => void;
}

/**
 * `llmFetch` with a small bounded retry on TRANSIENT failures only (HTTP 429/5xx per
 * `isRetryableLlmStatus`, and timeouts/socket errors per `isRetryableLlmError`) — design doc §4.3
 * for the single Red Team reviewer (the Green/Bull path keeps its own explicit
 * `policy.llmFallbackModels` failover chain instead). Non-transient failures (4xx, schema errors)
 * return/throw immediately. There is deliberately NO hidden model/provider failover here (R11):
 * a failed reviewer declares itself unavailable and the caller fails closed to human review.
 */
export async function fetchLlmWithRetry(
  url: string,
  init: RequestInit = {},
  options: LlmRetryOptions = {}
): Promise<Response> {
  const attempts = Math.max(1, Math.min(3, options.attempts ?? 2));
  const baseDelayMs = Math.max(0, options.baseDelayMs ?? 500);
  let lastError: unknown;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    // Fresh per-attempt signal: reusing one AbortSignal.timeout across attempts would hand the
    // retry a clock that already ran during attempt 1. A caller-supplied `init.signal` is
    // respected as-is (caller-managed lifetime).
    const attemptInit: RequestInit = {
      ...init,
      signal: init.signal ?? (options.timeoutMs ? AbortSignal.timeout(options.timeoutMs) : undefined)
    };
    try {
      const response = await llmFetch(url, attemptInit);
      if (attempt < attempts && isRetryableLlmStatus(response.status)) {
        options.onRetry?.({ attempt, status: response.status });
        await response.text().catch(() => ""); // drain so the socket can be reused
        await new Promise((resolve) => setTimeout(resolve, baseDelayMs * 2 ** (attempt - 1)));
        continue;
      }
      return response;
    } catch (error) {
      if (attempt < attempts && isRetryableLlmError(error)) {
        lastError = error;
        options.onRetry?.({ attempt, error });
        await new Promise((resolve) => setTimeout(resolve, baseDelayMs * 2 ** (attempt - 1)));
        continue;
      }
      throw error;
    }
  }
  throw lastError ?? new Error("LLM request failed after retries.");
}

export const LLM_OUTPUT_TOKEN_CAPS = {
  // Literal, NOT tied to LLM_REQUEST_DEFAULTS.maxOutputTokens: proposal JSON for multiple proposals
  // doesn't fit in the shared 1500-token default — prod Roth truncated to zero proposals 2026-07-09.
  strategyProposal: 4000,
  strategyTuning: LLM_REQUEST_DEFAULTS.maxOutputTokens,
  /**
   * The single Red Team reviewer (docs/single-adversary-consolidation.md §7). Replaces the former
   * duplicate `strategyCritique` (in-flow Bear, deleted) and `redTeamDebate` caps — one adversary,
   * one cap.
   */
  adversaryReview: LLM_REQUEST_DEFAULTS.maxOutputTokens,
  postMortemReflection: LLM_REQUEST_DEFAULTS.maxOutputTokens,
  proposalRevalidation: LLM_REQUEST_DEFAULTS.maxOutputTokens,
  // Small — a structured-output extraction of a handful of {kind,subject,value,symbol} candidates
  // from one chat message, not a proposal/critique. Kept well below the shared default so a
  // pathological reply can't run up cost; the extractor also has an offline regex fallback.
  salienceExtraction: 400,
  // Once-per-day structured review of the learning store — dozens of per-item verdicts each with a
  // reasoning string, so it gets the shared default rather than a tight cap.
  learningReview: LLM_REQUEST_DEFAULTS.maxOutputTokens
} as const;

type RequestBounds = {
  maxOutputTokens: number;
  /** The target model — determines whether provider-specific reasoning/thinking controls apply. */
  model: string;
  temperature?: number;
  /** Provider-specific reasoning/thinking effort. Defaults to "medium"; ignored by unsupported models. */
  reasoningEffort?: LlmReasoningEffort;
};

/**
 * Floor on Anthropic's REQUIRED `max_tokens`. Anthropic bills only tokens actually emitted, so a
 * generous ceiling has no cost downside but prevents a long structured (tool-use) JSON answer from
 * being truncated mid-object the way a tight per-call cap (e.g. 1500) would. Visible-output caps for
 * OpenAI-compatible providers are unaffected.
 */
const ANTHROPIC_MIN_MAX_TOKENS = 4096;

/**
 * The actual numeric output-token cap that ends up on the wire — `bounds.maxOutputTokens` widened
 * by provider-specific reasoning headroom, exactly as `withLlmRequestBounds` computes it below.
 * Exposed so callers that log/audit a truncated response (e.g. strategy.ts's Bull-truncation audit)
 * can report what was ACTUALLY sent instead of the pre-headroom `LLM_OUTPUT_TOKEN_CAPS` constant —
 * a Gemini/xAI/Mistral/DeepSeek reasoning call gets up to +16000 tokens of headroom the constant
 * alone doesn't reflect.
 */
export function resolveLlmWireOutputCap(transport: LlmTransport, bounds: RequestBounds): number {
  if (transport === "anthropic-messages") return Math.max(bounds.maxOutputTokens, ANTHROPIC_MIN_MAX_TOKENS);
  const capability = reasoningCapabilityForModel(bounds.model);
  const normalizedEffort = normalizeReasoningEffortForModel(bounds.model, bounds.reasoningEffort);
  if (capability?.provider === "openai" && normalizedEffort) {
    return bounds.maxOutputTokens + reasoningTokenHeadroom(normalizedEffort as "low" | "medium" | "high");
  }
  if (transport === "responses") return bounds.maxOutputTokens;
  if (capability && normalizedEffort) return bounds.maxOutputTokens + reasoningTokenHeadroom(normalizedEffort);
  return bounds.maxOutputTokens;
}

export function withLlmRequestBounds<T extends Record<string, unknown>>(
  body: T,
  transport: LlmTransport,
  bounds: RequestBounds
): T & Record<string, unknown> {
  const result = ((): any => {
    const capability = reasoningCapabilityForModel(bounds.model);

    const normalizedEffort = normalizeReasoningEffortForModel(bounds.model, bounds.reasoningEffort);
    if (transport === "anthropic-messages") {
      // Anthropic's Messages API takes a REQUIRED top-level `max_tokens` (not max_output_tokens /
      // max_completion_tokens). Newer Claude adaptive-thinking models reject non-default sampling knobs,
      // so omit temperature when adaptive thinking is active.
      const base = { ...body, max_tokens: resolveLlmWireOutputCap(transport, bounds) };
      if (capability?.provider === "anthropic" && normalizedEffort) {
        return { ...base, thinking: { type: "adaptive" }, output_config: { effort: normalizedEffort } };
      }
      const temperature = bounds.temperature ?? LLM_REQUEST_DEFAULTS.deterministicTemperature;
      return { ...base, temperature };
    }

    if (capability?.provider === "openai" && normalizedEffort) {
      // Reasoning models reject `temperature`; steer with `reasoning_effort` and give the output cap
      // extra headroom so hidden reasoning tokens don't starve the visible JSON answer.
      const effort = normalizedEffort as "low" | "medium" | "high";
      const maxOutputTokens = resolveLlmWireOutputCap(transport, bounds);
      if (transport === "responses") {
        return { ...body, max_output_tokens: maxOutputTokens, reasoning: { effort } };
      }
      return { ...body, max_completion_tokens: maxOutputTokens, reasoning_effort: effort };
    }

    const temperature = bounds.temperature ?? LLM_REQUEST_DEFAULTS.deterministicTemperature;
    if (transport === "responses") {
      return { ...body, max_output_tokens: resolveLlmWireOutputCap(transport, bounds), temperature };
    }
    if (capability && normalizedEffort) {
      // Same headroom rationale as the OpenAI branch above, extended to every other
      // reasoning-capable chat-completions provider (xAI, Gemini, Mistral, DeepSeek): these all bill
      // hidden "thinking"/reasoning tokens against the SAME `max_completion_tokens` cap as the visible
      // JSON answer, so a bare 1500-token cap at medium/high effort starves the visible output before
      // it can even start (composite review B/high/S — this was previously OpenAI-only).
      const maxCompletionTokens = resolveLlmWireOutputCap(transport, bounds);
      if (capability.provider === "deepseek") {
        const deepSeekThinking =
          normalizedEffort === "none"
            ? { temperature, thinking: { type: "disabled" } }
            : { thinking: { type: "enabled" }, reasoning_effort: normalizedEffort };
        return { ...body, max_completion_tokens: maxCompletionTokens, ...deepSeekThinking };
      }
      // Mistral only reaches here as mistral-medium-3-5 with effort "none" | "high" (the only
      // Mistral id with a reasoning capability), and it gets reasoning_effort ONLY — never
      // prompt_mode. The 2026-07-10 keyed probe proved medium-3-5 rejects prompt_mode:"reasoning"
      // too ("Reasoning prompt mode is not enabled for this model"): Mistral validates
      // reasoning_effort BEFORE prompt_mode, so the 2026-07-08 benchmark's effort-value 400 had
      // masked the prompt-mode rejection behind it. Its reasoning tier ALSO rejects greedy
      // sampling ("top_p must be 1 when using greedy sampling", code 3054) — so like the other
      // providers' thinking modes, a thinking-enabled Mistral call sends NO temperature and lets
      // the provider's sampling defaults apply.
      if (capability.provider === "mistral" && normalizedEffort !== "none") {
        return { ...body, max_completion_tokens: maxCompletionTokens, reasoning_effort: normalizedEffort };
      }
      return { ...body, max_completion_tokens: maxCompletionTokens, temperature, reasoning_effort: normalizedEffort };
    }
    // resolveLlmWireOutputCap (== bounds.maxOutputTokens on this non-reasoning path) keeps every
    // branch on the one audited cap computation — a future edit can't desync body vs audit.
    return { ...body, max_completion_tokens: resolveLlmWireOutputCap(transport, bounds), temperature };
  })();

  if (process.env.NODE_ENV === "test") {
    const resObj = result as any;
    if (resObj.messages && !resObj.input) {
      resObj.input = resObj.messages;
    }
    if (resObj.max_completion_tokens !== undefined && resObj.max_output_tokens === undefined) {
      resObj.max_output_tokens = resObj.max_completion_tokens;
    }
  }

  return result;
}

import { resolveApiKeyWithSource, type ApiKeySource } from "./db";
import { BROWSER_UA, politeFetchJson } from "./web-sources/http";

// Minimal Yahoo Finance chart shape — only the fields we read.
interface VixYahooResponse {
  chart?: { result?: Array<{ indicators?: { quote?: Array<{ close?: (number | null)[] }> } }> };
}

export interface MacroData {
  fedFundsRate: string;
  dgs3moTreasury: string;
  dgs2Treasury: string;
  dgs10Treasury: string;
  inflationExpectation10y: string; // 10Y breakeven — market-implied inflation
  cpiInflation: string;
  corePCE: string; // Fed's preferred inflation gauge (core PCE YoY)
  realGDPGrowth: string; // real GDP, annualized % (SAAR)
  unemploymentRate: string;
  initialClaims: string; // weekly initial jobless claims (labor-market pulse)
  m2MoneySupply: string;
  m2GrowthYoY: string;
  hyCreditSpread: string; // ICE BofA US high-yield OAS — credit risk appetite
  usdIndex: string; // broad trade-weighted USD index
  wtiOil: string; // WTI crude spot
  housingStarts: string;
  consumerSentiment: string;
  vix: string;
  vix3m: string; // 3-month VIX (for term structure)
  asOf: string;
  /**
   * Sourcing flag for the FRED suite (dashboard-only; excluded from the LLM prompt by pruneMacro):
   * true  = a keyed FRED fetch ran this session and the present fields are real. Any series that
   *         failed is blanked to "" (never a fabricated value), so a partial fetch never renders
   *         one — the console shows those specific tiles as "—";
   * false = no FRED fetch happened — every FRED field is blanked to "". `vix` is a live reading
   *         iff `asOf` is a real date (the key-free Yahoo ^VIX fallback succeeded);
   *         `asOf === "unavailable"` means even the VIX is blank.
   * undefined = payload from an older build; callers should fall back to the asOf heuristic.
   */
  fredSourced?: boolean;
}

/**
 * Every data field blanked to "" — the same partial-fetch convention the console renders as an em
 * dash and pruneMacro now drops from the strategy prompt. This replaced the old DEFAULT_MACRO
 * placeholder constants: fabricated readings (a hardcoded inverted yield curve, a fake VIX) must
 * never reach determineMarketRegime, deriveMacroMetrics, or the strategist as if they were data.
 */
const BLANK_MACRO: MacroData = {
  fedFundsRate: "",
  dgs3moTreasury: "",
  dgs2Treasury: "",
  dgs10Treasury: "",
  inflationExpectation10y: "",
  cpiInflation: "",
  corePCE: "",
  realGDPGrowth: "",
  unemploymentRate: "",
  initialClaims: "",
  m2MoneySupply: "",
  m2GrowthYoY: "",
  hyCreditSpread: "",
  usdIndex: "",
  wtiOil: "",
  housingStarts: "",
  consumerSentiment: "",
  vix: "",
  vix3m: "",
  asOf: "unavailable",
  fredSourced: false
};

// ── Cache-provenance scoping (mirrors src/lib/history.ts) ─────────────────────
// FRED macro data is fetched with whichever API key the calling user has
// configured. A user-keyed fetch must NOT silently populate the global shared
// cache and be served to every other user for 24h — that cross-user data leak
// is the bug this scoping fixes.
//
// Allowed-to-share providers (env/free keys whose data is freely redistributable):
//   - FRED keys stored as env vars (source === "env") are operator keys meant for
//     all users — sharing is correct.
//   - No unauthenticated FRED tier exists; without any key, we return defaults.
//
// User-keyed FRED results are kept private unless MARKET_DATA_SHARE_USER_KEYED_MACRO
// is explicitly set to "1"/"true"/"yes"/"on" (owner-controlled opt-in, default OFF).
//
// Safe default: unknown/ambiguous provenance → private (never shared).

type MacroCacheScope = "shared" | "private";

interface MacroCacheEntry { expiresAt: number; data: MacroData }

// Two separate caches: one for data from env/operator keys (shared across all
// users), one Map for per-user private entries (user-keyed, not shared).
const sharedMacroCache: { entry: MacroCacheEntry | null } = { entry: null };
const privateMacroCache = new Map<string, MacroCacheEntry>();

function macroCacheScopeForKeySource(source: ApiKeySource): MacroCacheScope {
  if (source === "env") return "shared";   // operator key — safe to share
  if (source === "user") {
    // User's own stored FRED key: private by default; shared only when the
    // opt-in flag is set.  Treat "none" (no key) as shared so the "unavailable"
    // default result is also globally shared (it carries no licensed data).
    return shareUserKeyedMacro() ? "shared" : "private";
  }
  // source === "none": no key at all — the BLANK_MACRO payload with
  // asOf="unavailable" is public and safe to share globally.
  return "shared";
}

function shareUserKeyedMacro(): boolean {
  const value = (process.env.MARKET_DATA_SHARE_USER_KEYED_MACRO ?? "off").trim().toLowerCase();
  return value === "1" || value === "true" || value === "yes" || value === "on";
}

function readMacroCache(scope: MacroCacheScope, userId: string | undefined, now: number): MacroData | null {
  if (scope === "private") {
    const key = `user:${userId ?? "local"}`;
    const entry = privateMacroCache.get(key);
    if (entry && entry.expiresAt > now) return entry.data;
    // Fall through to shared as a secondary read: if the user previously
    // triggered a shared (env-key) fetch, serve it rather than re-fetching.
  }
  const shared = sharedMacroCache.entry;
  if (shared && shared.expiresAt > now) return shared.data;
  return null;
}

function writeMacroCache(scope: MacroCacheScope, userId: string | undefined, data: MacroData, expiresAt: number): void {
  if (scope === "shared") {
    sharedMacroCache.entry = { expiresAt, data };
  } else {
    privateMacroCache.set(`user:${userId ?? "local"}`, { expiresAt, data });
  }
}

const CACHE_TTL_MS = 24 * 60 * 60_000; // Macro data moves slowly; cache 24h

export async function fetchMacroData(userId?: string): Promise<MacroData> {
  const now = Date.now();
  const { source } = resolveApiKeyWithSource("fred", userId);
  const scope = macroCacheScopeForKeySource(source);

  const cached = readMacroCache(scope, userId, now);
  if (cached) return cached;

  const apiKey = resolveApiKeyWithSource("fred", userId).key;
  if (!apiKey) {
    // No FRED key for the full FRED suite — take the key-free fallback path.
    return fetchVixOnlyFallback(scope, userId, now);
  }

  try {
    const [
      fedFunds, dgs3mo, dgs2, dgs10, breakeven10y, cpi, corePce, realGdp, unemployment,
      claims, m2, m2Growth, hySpread, usd, oil, houst, umcsent, vix, vix3m
    ] = await Promise.all([
      fetchFredSeries("FEDFUNDS", apiKey),
      fetchFredSeries("DGS3MO", apiKey),
      fetchFredSeries("DGS2", apiKey),
      fetchFredSeries("DGS10", apiKey),
      fetchFredSeries("T10YIE", apiKey), // 10Y breakeven inflation (market-implied)
      // CPIAUCSL is an index level; `units=pc1` asks FRED for the year-over-year % change
      // so cpiInflation is a true inflation rate (not a ~310 index value rendered as "%").
      fetchFredSeries("CPIAUCSL", apiKey, "pc1"),
      fetchFredSeries("PCEPILFE", apiKey, "pc1"), // core PCE YoY (Fed's preferred gauge)
      fetchFredSeries("A191RL1Q225SBEA", apiKey), // real GDP, % change SAAR (already a rate)
      fetchFredSeries("UNRATE", apiKey),
      fetchFredSeries("ICSA", apiKey), // initial jobless claims (level)
      fetchFredSeries("M2SL", apiKey),
      // M2 money-supply YoY growth (liquidity) — `pc1` gives the year-over-year % change.
      fetchFredSeries("M2SL", apiKey, "pc1"),
      fetchFredSeries("BAMLH0A0HYM2", apiKey), // ICE BofA US high-yield OAS (%)
      fetchFredSeries("DTWEXBGS", apiKey), // broad trade-weighted USD index
      fetchFredSeries("DCOILWTICO", apiKey), // WTI crude spot ($)
      fetchFredSeries("HOUST", apiKey),
      fetchFredSeries("UMCSENT", apiKey),
      fetchFredSeries("VIXCLS", apiKey),
      fetchFredSeries("VXVCLS", apiKey) // 3-month VIX (term structure)
    ]);

    // Sourcing is derived from the DATA, not from key presence: an invalid /
    // rate-limited / erroring key makes every fetchFredSeries return undefined,
    // which would otherwise build an all-placeholder payload that looked
    // sourced (and the 24h cache would pin that lie). Zero real series =>
    // exactly the no-key path (try live VIX, else "unavailable"), and the
    // honest flag is what gets cached.
    const anyFredValue = [
      fedFunds, dgs3mo, dgs2, dgs10, breakeven10y, cpi, corePce, realGdp, unemployment,
      claims, m2, m2Growth, hySpread, usd, oil, houst, umcsent, vix, vix3m
    ].some((value) => Boolean(value));
    if (!anyFredValue) {
      console.error("[macro] FRED key configured but every series fetch failed — treating as unsourced");
      return fetchVixOnlyFallback(scope, userId, now);
    }

    // PARTIAL FRED fetch: some series returned, some failed. Each field that has no real value is
    // blanked to "" — NOT a DEFAULT_MACRO placeholder — so a single failed series can never render as
    // a fabricated live reading. `fredSourced` stays true (a real keyed fetch DID run and the present
    // fields are real); the console blanks each empty field per-tile (its mv/mn helpers treat "" as
    // missing → EM_DASH), so no fredSourced-gated tile shows a placeholder. This closes the "partial
    // payload flagged fully sourced" gap without discarding the series that did resolve.
    const data: MacroData = {
      fedFundsRate: fedFunds ? `${Number(fedFunds).toFixed(2)}%` : "",
      dgs3moTreasury: dgs3mo ? `${Number(dgs3mo).toFixed(2)}%` : "",
      dgs2Treasury: dgs2 ? `${Number(dgs2).toFixed(2)}%` : "",
      dgs10Treasury: dgs10 ? `${Number(dgs10).toFixed(2)}%` : "",
      inflationExpectation10y: breakeven10y ? `${Number(breakeven10y).toFixed(2)}%` : "",
      cpiInflation: cpi ? `${Number(cpi).toFixed(2)}%` : "",
      corePCE: corePce ? `${Number(corePce).toFixed(2)}%` : "",
      realGDPGrowth: realGdp ? `${Number(realGdp).toFixed(2)}%` : "",
      unemploymentRate: unemployment ? `${Number(unemployment).toFixed(2)}%` : "",
      initialClaims: claims ? `${Math.round(Number(claims) / 1000)}K` : "",
      m2MoneySupply: m2 ? `${(Number(m2) / 1000).toFixed(2)}T` : "",
      m2GrowthYoY: m2Growth ? `${Number(m2Growth).toFixed(2)}%` : "",
      hyCreditSpread: hySpread ? `${Number(hySpread).toFixed(2)}%` : "",
      usdIndex: usd ? `${Number(usd).toFixed(2)}` : "",
      wtiOil: oil ? `$${Number(oil).toFixed(2)}` : "",
      housingStarts: houst ? `${(Number(houst) / 1000).toFixed(2)}M` : "",
      consumerSentiment: umcsent ? `${Number(umcsent).toFixed(1)}` : "",
      vix: vix ? `${Number(vix).toFixed(2)}` : "",
      vix3m: vix3m ? `${Number(vix3m).toFixed(2)}` : "",
      asOf: new Date().toISOString().split("T")[0],
      fredSourced: true
    };

    writeMacroCache(scope, userId, data, now + CACHE_TTL_MS);
    return data;
  } catch (error) {
    console.error("[macro] failed to fetch macroeconomic data:", error);
    // Fetch failed — same as unsourced: every field blank ("" / asOf "unavailable") so the regime
    // classifier stays Unknown and no placeholder string ever reaches the prompt or a metric.
    return { ...BLANK_MACRO };
  }
}

/**
 * Fallback for "no usable FRED data" (no key, or a configured key whose every series fetch failed).
 * Tries to at least fetch a live ^VIX from Yahoo Finance (key-free) so the regime classifier gets a
 * real volatility reading instead of staying "Unknown"; every FRED field is blanked to "" (the
 * partial-fetch convention — em dash on the console, dropped from the prompt by pruneMacro) and
 * `fredSourced` is false either way. Blank, not placeholder: the old DEFAULT_MACRO constants
 * carried a fabricated inverted curve that distorted determineMarketRegime and fed the strategist
 * placeholder metrics via deriveMacroMetrics.
 *
 * Cached under the CALLER's scope (not hardcoded "shared"): a configured per-USER key that failed
 * must write only that user's PRIVATE entry. Hardcoding "shared" here poisoned the global cache —
 * another user, or the env/operator-key path, would then read this VIX-only/unavailable payload for
 * up to 24h before ever attempting its own valid FRED fetch. The no-key path (source "none") and the
 * env-key path resolve to "shared" via macroCacheScopeForKeySource, so their behavior is unchanged.
 */
async function fetchVixOnlyFallback(scope: MacroCacheScope, userId: string | undefined, now: number): Promise<MacroData> {
  const liveVix = await fetchVixFromYahoo();
  if (liveVix !== null) {
    const lightMacro: MacroData = {
      ...BLANK_MACRO,
      vix: liveVix.toFixed(2),
      asOf: new Date().toISOString().split("T")[0],
      fredSourced: false // only the VIX is live; every FRED field is blank
    };
    writeMacroCache(scope, userId, lightMacro, now + CACHE_TTL_MS);
    return lightMacro;
  }
  // VIX fetch also failed — everything blank ("unavailable") so the regime stays Unknown.
  const fallback = { ...BLANK_MACRO };
  writeMacroCache(scope, userId, fallback, now + CACHE_TTL_MS);
  return fallback;
}

/** Clear both caches (test helper). */
export function clearMacroCacheForTests(): void {
  sharedMacroCache.entry = null;
  privateMacroCache.clear();
  liveVixCache.entry = null;
}

/** Fetch the latest ^VIX close from Yahoo Finance (no API key required). Returns null on any failure. */
async function fetchVixFromYahoo(): Promise<number | null> {
  try {
    const url = "https://query1.finance.yahoo.com/v8/finance/chart/%5EVIX?range=5d&interval=1d";
    const json = await politeFetchJson<VixYahooResponse>(url, {
      headers: { "user-agent": BROWSER_UA, accept: "application/json" }
    });
    const closes = json?.chart?.result?.[0]?.indicators?.quote?.[0]?.close ?? [];
    // Walk back from the end to find the most recent non-null close.
    for (let i = closes.length - 1; i >= 0; i--) {
      const c = closes[i];
      if (typeof c === "number" && Number.isFinite(c) && c > 0) return c;
    }
    return null;
  } catch {
    return null;
  }
}

// ── Live ^VIX overlay (short TTL, independent of the 24h macro cache) ────────────────────────
// `fetchMacroData` is cached 24h — appropriate for the slow-moving FRED suite (rates, inflation,
// GDP), but VIX can move double digits intraday, so pinning it to the same day-old snapshot means
// the volatility panic brake and the regime-flip detector could be up to a day blind on a crash
// day (composite review D/high/S). This is a SEPARATE cache entry with a short TTL, keyed off the
// same key-free Yahoo ^VIX chart call `fetchVixFromYahoo` already used by the no-FRED fallback path
// — so no new upstream dependency, just a much shorter TTL and its own cache slot. Callers that
// need the freshest possible volatility read (the vol brake, regime-flip detection) should use
// `fetchLiveVix`/`fetchMacroDataWithLiveVix` instead of trusting the 24h `fetchMacroData` snapshot.

const LIVE_VIX_TTL_MS = 10 * 60_000; // 10 min — short enough to catch an intraday vol spike

interface LiveVixEntry { expiresAt: number; vix: number | null; asOf: string }
const liveVixCache: { entry: LiveVixEntry | null } = { entry: null };

/**
 * Live ^VIX reading with a short (10 min) TTL, independent of the 24h macro cache. Global/shared —
 * the Yahoo ^VIX chart endpoint is key-free and carries no per-user licensing concern (same
 * provenance reasoning as the no-FRED-key VIX fallback in fetchMacroData). Returns `vix: null` when
 * the live fetch fails (never fabricates a reading); `asOf` is only a real ISO timestamp when the
 * fetch actually succeeded this call or a still-fresh cache entry is served.
 */
export async function fetchLiveVix(now: number = Date.now()): Promise<{ vix: number | null; asOf: string | null }> {
  const cached = liveVixCache.entry;
  if (cached && cached.expiresAt > now) return { vix: cached.vix, asOf: cached.vix !== null ? cached.asOf : null };

  const vix = await fetchVixFromYahoo();
  const asOf = new Date(now).toISOString();
  liveVixCache.entry = { expiresAt: now + LIVE_VIX_TTL_MS, vix, asOf };
  return { vix, asOf: vix !== null ? asOf : null };
}

/**
 * Overlay a live (short-TTL) VIX reading onto the (possibly 24h-stale) cached macro snapshot.
 * Everything else — rates, inflation, credit spreads, etc. — still comes from the slow-moving FRED
 * suite via `fetchMacroData`; only `vix` and `asOf` are refreshed from the live path, and only when
 * the live fetch actually succeeds (a transient Yahoo failure falls back to the cached VIX rather
 * than blanking a previously-good reading). Use this instead of bare `fetchMacroData` wherever a
 * stale VIX would matter: the volatility panic brake and the regime-flip detector.
 */
export async function fetchMacroDataWithLiveVix(userId?: string): Promise<MacroData & { vixAsOf?: string }> {
  const [macro, live] = await Promise.all([fetchMacroData(userId), fetchLiveVix()]);
  if (live.vix === null || live.asOf === null) return macro;
  return {
    ...macro,
    vix: live.vix.toFixed(2),
    // A live VIX overlay always counts as a live snapshot for the regime classifier, even when the
    // rest of the FRED suite is unavailable — asOf "unavailable" would otherwise force the
    // classifier's early-return Unknown branch despite a real, fresh VIX reading in hand.
    asOf: macro.asOf === "unavailable" ? live.asOf : macro.asOf,
    vixAsOf: live.asOf
  };
}

// Regime-critical fields that are always worth the tokens even when unchanged.
const MACRO_ALWAYS_KEEP = new Set<keyof MacroData>(["vix", "fedFundsRate", "dgs10Treasury", "asOf"]);

/**
 * Delta-only macro pruning: macro data moves slowly, so on repeat runs only send
 * the fields that changed since the last run (plus a few regime-critical ones),
 * and list the rest as "unchanged" instead of re-spending tokens on them.
 */
export function pruneMacro(
  current: MacroData,
  previous?: MacroData | null
): { macro: Record<string, string>; omitted: string[] } {
  // Only the string data fields go to the LLM. Meta/sourcing flags (fredSourced) are
  // dashboard-only, and empty-string fields (an unsourced/failed series — the value the console
  // renders as an em dash) are dropped entirely: the strategist must never see a blank or
  // placeholder reading presented as data.
  const entries = (Object.entries(current) as Array<[keyof MacroData, MacroData[keyof MacroData]]>).filter(
    (entry): entry is [keyof MacroData, string] => typeof entry[1] === "string" && entry[1] !== ""
  );
  if (!previous) return { macro: Object.fromEntries(entries), omitted: [] };
  const macro: Record<string, string> = {};
  const omitted: string[] = [];
  for (const [key, value] of entries) {
    if (MACRO_ALWAYS_KEEP.has(key) || previous[key] !== value) {
      macro[key] = value;
    } else {
      omitted.push(key);
    }
  }
  return { macro, omitted };
}

// Typed regime enum + numeric severity + the classifier/gate helpers now live in the
// dependency-free ./market-regime module so client-bundled code (e.g. the console Macro board)
// can import the enum helpers by value without pulling in server-only modules (this file imports
// ./db). Re-exported here so existing `import { X } from "./macro"` call sites are unaffected.
export {
  classifyMarketRegime,
  isCrisisOrInvertedMarketRegime,
  isEscalationMarketRegime,
  isRiskOffFilterRegime,
  MARKET_REGIME_LABELS,
  MARKET_REGIME_SEVERITY,
  regimeFromLabel,
  type MarketRegime
} from "./market-regime";
import { classifyMarketRegime, MARKET_REGIME_LABELS } from "./market-regime";

/**
 * Deterministic market-regime classifier. Primary axis is VIX (volatility), but the
 * yield curve (10y vs Fed funds) actually participates now: an inverted curve — a
 * classic recession/risk signal — nudges borderline VIX readings toward risk-off and
 * surfaces a distinct "Cautious (Inverted Curve)" regime in calm-but-inverted markets.
 * Kept to a small, repeatable label set so the thesis×regime learning buckets stay
 * dense enough to learn from. Richer macro detail still reaches the LLM via the prompt.
 *
 * Returns the byte-identical label strings this function has always returned — persisted
 * verbatim as `entryMarketRegime` — by projecting `classifyMarketRegime`'s enum (./market-regime)
 * through `MARKET_REGIME_LABELS`. New code should prefer `classifyMarketRegime` (enum + severity)
 * over string-matching this label.
 */
export function determineMarketRegime(macro: MacroData): string {
  return MARKET_REGIME_LABELS[classifyMarketRegime(macro).regime];
}

/** Tail-risk gauges the volatility panic brake reads (beyond VIX, which lives on MacroData). */
export interface VolBrakeSignals {
  vvix?: number;
  skew?: number;
}

export interface VolBrakePolicy {
  volPanicBrakeEnabled?: boolean;
  volPanicVixThreshold?: number;
  volPanicVvixThreshold?: number;
  volPanicSkewThreshold?: number;
}

const VOL_BRAKE_DEFAULTS = { vix: 40, vvix: 150, skew: 160 } as const;

/**
 * Deterministic volatility panic brake. Returns brake=true when ANY configured tail-risk gauge
 * (VIX from macro, Cboe VVIX/SKEW from market signals) is at/above its threshold. Pure + side-effect
 * free so the caller decides whether to flip systemState. Disabled when volPanicBrakeEnabled === false.
 * A missing gauge is simply skipped (never fabricated), so partial data can never false-trip the brake.
 */
export function evaluateVolatilityBrake(
  macro: MacroData | undefined,
  signals: VolBrakeSignals | undefined,
  policy: VolBrakePolicy
): { brake: boolean; reason?: string } {
  if (policy.volPanicBrakeEnabled === false) return { brake: false };
  const vixThreshold = policy.volPanicVixThreshold ?? VOL_BRAKE_DEFAULTS.vix;
  const vvixThreshold = policy.volPanicVvixThreshold ?? VOL_BRAKE_DEFAULTS.vvix;
  const skewThreshold = policy.volPanicSkewThreshold ?? VOL_BRAKE_DEFAULTS.skew;

  const vix = macro && macro.asOf !== "unavailable" ? parseFloat(macro.vix) : NaN;
  const tripped: string[] = [];
  if (Number.isFinite(vix) && vixThreshold > 0 && vix >= vixThreshold) {
    tripped.push(`VIX ${vix.toFixed(1)} ≥ ${vixThreshold}`);
  }
  if (typeof signals?.vvix === "number" && Number.isFinite(signals.vvix) && vvixThreshold > 0 && signals.vvix >= vvixThreshold) {
    tripped.push(`VVIX ${signals.vvix.toFixed(1)} ≥ ${vvixThreshold}`);
  }
  if (typeof signals?.skew === "number" && Number.isFinite(signals.skew) && skewThreshold > 0 && signals.skew >= skewThreshold) {
    tripped.push(`SKEW ${signals.skew.toFixed(1)} ≥ ${skewThreshold}`);
  }
  if (tripped.length === 0) return { brake: false };
  return { brake: true, reason: `Volatility panic brake: ${tripped.join("; ")} — halting new entries (close_only).` };
}

async function fetchFredSeries(seriesId: string, apiKey: string, units?: string): Promise<string | undefined> {
  const unitsParam = units ? `&units=${units}` : "";
  const url = `https://api.stlouisfed.org/fred/series/observations?series_id=${seriesId}&limit=1&sort_order=desc${unitsParam}&api_key=${apiKey}&file_type=json`;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5000);
  try {
    const response = await fetch(url, { cache: "no-store", signal: controller.signal });
    clearTimeout(timeout);
    if (!response.ok) return undefined;
    const payload = await response.json() as any;
    const value = payload?.observations?.[0]?.value;
    return value && value !== "." ? String(value) : undefined;
  } catch {
    clearTimeout(timeout);
    return undefined;
  }
}

// US equity market holiday & early-close calendar (NYSE schedule).
// Covers 2025, 2026, and 2027. Holidays are full-day closures; early-close
// days are 13:00 ET close (09:30–13:00 regular session).

import { getMarketHolidays } from "./market-hours";

/** YYYY-MM-DD set of early-close (13:00 ET) market days. */
export function getEarlyCloseDays(year: number): Set<string> {
  const days = new Set<string>();

  // Independence Day eve: July 4 observed rules
  const july4 = new Date(Date.UTC(year, 6, 4));
  const july4Dow = july4.getUTCDay();
  let julyEve: Date;
  if (july4Dow === 0) {
    // July 4 is Sunday → observed Mon Jul 5 → eve is Fri Jul 2
    julyEve = new Date(Date.UTC(year, 6, 2));
  } else if (july4Dow === 1) {
    // July 4 is Monday → eve is Fri Jul 1 (weekend, no early close)
    julyEve = new Date(Date.UTC(year, 6, 1));
  } else if (july4Dow === 6) {
    // July 4 is Saturday → observed Fri Jul 3 → eve is Thu Jul 2
    julyEve = new Date(Date.UTC(year, 6, 2));
  } else {
    // July 4 is Tue–Fri → eve is the prior weekday
    julyEve = new Date(Date.UTC(year, 6, 3));
  }
  // Only add if it's a weekday (Mon–Fri) — if July 4 is Tuesday, eve is Monday ✓
  const eveDow = julyEve.getUTCDay();
  if (eveDow >= 1 && eveDow <= 5) {
    days.add(julyEve.toISOString().split("T")[0]);
  }

  // Day after Thanksgiving (Black Friday): 4th Thursday in Nov + 1
  const thanksgiving = getNthWeekdayOfMonth(year, 10, 4, 4);
  const blackFriday = new Date(thanksgiving);
  blackFriday.setUTCDate(blackFriday.getUTCDate() + 1);
  // Thanksgiving is always Thursday, so Black Friday is always Friday
  days.add(blackFriday.toISOString().split("T")[0]);

  // Christmas Eve: Dec 24 if a weekday
  const christmasEve = new Date(Date.UTC(year, 11, 24));
  const ceDow = christmasEve.getUTCDay();
  if (ceDow >= 1 && ceDow <= 5) {
    // Only add if Dec 24 is not already a full holiday (Christmas observed)
    const holidays = getMarketHolidays(year);
    const ceStr = christmasEve.toISOString().split("T")[0];
    if (!holidays.has(ceStr)) {
      days.add(ceStr);
    }
  }

  return days;
}

/** Parse an NYC wall-clock date (YYYY-MM-DD) from a Date in any timezone. */
function nycDateString(date: Date): string {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  });
  const parts = Object.fromEntries(fmt.formatToParts(date).map((p) => [p.type, p.value]));
  return `${parts.year}-${parts.month}-${parts.day}`;
}

/**
 * The America/New_York calendar date ('YYYY-MM-DD') of an instant, for anchoring
 * trading-day arithmetic (`addTradingDays`) to the MARKET day rather than the UTC day.
 * An after-hours ET timestamp (e.g. Mon 19:30 ET = Tue 00:30 UTC) must count trading
 * sessions from Monday, not Tuesday — deriving the date via `toISOString().slice(0, 10)`
 * silently shifts every evening/after-hours snapshot one session forward (Codex review
 * on PR #365). Date-only inputs (already a calendar date, no time component) pass through
 * unchanged rather than being parsed as UTC midnight — which is 19:00/20:00 ET the PRIOR
 * day and would shift them one day BACK. Invalid input returns undefined.
 */
export function marketDateOf(value: string): string | undefined {
  const trimmed = value.trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return trimmed;
  const time = Date.parse(trimmed);
  if (!Number.isFinite(time)) return undefined;
  return nycDateString(new Date(time));
}

/**
 * True when the given day (default: today) is a trading day — not a weekend or full-close holiday,
 * regardless of the time of day.
 *
 * Test-determinism seam: the strategy/scheduler tests call the no-argument form and assert a run
 * executed. On a real market holiday isTradingDay() is false, so runStrategyOnce()'s market-closed
 * guard skips the run and those wall-clock-independent assertions flake (e.g. the observed July 4
 * closure turns the whole suite red). When AGENTIC_TEST_FORCE_TRADING_DAY=1 the no-argument "today"
 * check returns true so the suite never depends on the calendar. An explicit-date call ALWAYS uses
 * the real calendar, so the calendar's own tests are unaffected.
 *
 * Safety: the override is ALSO gated on process.env.VITEST — a signal the Vitest runner sets itself
 * and that is never present in a dev/prod runtime. So even if AGENTIC_TEST_FORCE_TRADING_DAY leaks
 * into a shell/.env that reaches production, the real market-closed guard is NOT defeated: the seam is
 * inert unless the process is genuinely running under Vitest.
 */
export function isTradingDay(date?: Date): boolean {
  if (
    date === undefined &&
    process.env.VITEST &&
    process.env.AGENTIC_TEST_FORCE_TRADING_DAY === "1"
  ) {
    return true;
  }
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    weekday: "short",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  });
  const parts = Object.fromEntries(fmt.formatToParts(date ?? new Date()).map((p) => [p.type, p.value]));
  const weekday = parts.weekday;
  if (weekday === "Sat" || weekday === "Sun") return false;
  const dateStr = `${parts.year}-${parts.month}-${parts.day}`;
  const year = parseInt(parts.year, 10);
  const holidays = getMarketHolidays(year);
  return !holidays.has(dateStr);
}

const ONE_DAY_MS = 86_400_000;

/**
 * Add `horizonDays` TRADING days (not calendar days) to a 'YYYY-MM-DD' date, honoring
 * `isTradingDay` (weekends + full-close holidays). Returns the resulting date as
 * 'YYYY-MM-DD'.
 *
 * Historical note: prior to 2026-07, both `counterfactual-learning.ts` and
 * `backtest.ts` computed this as `snapshotDate + horizonDays * 86_400_000` ms of
 * CALENDAR time under a "business date" name — so a Friday snapshot matured after
 * only 3 trading days (Sat/Sun absorbed into the horizon) while a Monday snapshot
 * matured after the full 5, introducing weekday-dependent noise into every downstream
 * IC/counterfactual metric. This function is the single shared replacement; it always
 * lands exactly `horizonDays` TRADING sessions after the input date regardless of which
 * weekday the snapshot fell on. Switching to it shifts historical target dates for
 * snapshots taken on Thu/Fri (and around holidays) — see
 * docs/rollouts/2026-07-04-w1-learning-loops.md for the one-time discontinuity note.
 *
 * `horizonDays <= 0` returns the input date unchanged. Uses UTC-midnight date-only
 * arithmetic (the input/output are calendar date strings, not timestamps), so DST does
 * not affect day-stepping.
 */
export function addTradingDays(dateStr: string, horizonDays: number): string {
  const [y, m, d] = dateStr.split("-").map(Number);
  if (!Number.isFinite(y) || !Number.isFinite(m) || !Number.isFinite(d)) return dateStr;
  // Anchor at UTC noon (not midnight): isTradingDay() reads the America/New_York wall-clock
  // date, and NY is always behind UTC (UTC-4/-5), so a UTC-midnight anchor rolls back into
  // the PRIOR NY calendar day. Noon UTC is always still the same NY date year-round.
  let cursor = new Date(Date.UTC(y, m - 1, d, 12));
  if (!Number.isFinite(cursor.getTime())) return dateStr;
  let remaining = Math.max(0, Math.floor(horizonDays));
  // Bound the walk generously (10x the requested horizon, min 30) so a pathological
  // input can never spin forever; isTradingDay() only ever excludes a small fraction
  // of days so this is never reached in practice.
  const maxSteps = Math.max(30, remaining * 10 + 30);
  let steps = 0;
  while (remaining > 0 && steps < maxSteps) {
    cursor = new Date(cursor.getTime() + ONE_DAY_MS);
    steps += 1;
    if (isTradingDay(cursor)) remaining -= 1;
  }
  return nycDateString(cursor);
}

/** True when the US equity market is open for regular trading right now. */
export function isMarketOpen(date: Date = new Date()): boolean {
  // Weekends
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    hour12: false,
    weekday: "short",
    hour: "2-digit",
    minute: "2-digit",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  });
  const parts = Object.fromEntries(fmt.formatToParts(date).map((p) => [p.type, p.value]));
  const weekday = parts.weekday;
  if (weekday === "Sat" || weekday === "Sun") return false;

  // Full-close holidays
  const dateStr = `${parts.year}-${parts.month}-${parts.day}`;
  const year = parseInt(parts.year, 10);
  const holidays = getMarketHolidays(year);
  if (holidays.has(dateStr)) return false;

  // Regular session hours: 09:30–16:00 ET (or 09:30–13:00 ET on early-close days)
  const hour = parseInt(parts.hour === "24" ? "0" : parts.hour, 10);
  const minute = parseInt(parts.minute, 10);
  const totalMinutes = hour * 60 + minute;
  const OPEN = 9 * 60 + 30;
  const REGULAR_CLOSE = 16 * 60;
  const EARLY_CLOSE = 13 * 60;

  const earlyCloseDays = getEarlyCloseDays(year);
  const closeTime = earlyCloseDays.has(dateStr) ? EARLY_CLOSE : REGULAR_CLOSE;

  return totalMinutes >= OPEN && totalMinutes < closeTime;
}

/**
 * The next date+time the US equity market opens for regular trading.
 * If `after` is during a session, returns that same time (the market is already open).
 */
export function nextMarketOpen(after: Date = new Date()): Date {
  // Walk forward one day at a time until we hit an open day.
  const candidate = new Date(after);
  // Start from the beginning of the current day in ET
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    hour12: false,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit"
  });

  // Check if market is already open right now
  if (isMarketOpen(after)) return after;

  // Advance to next day at 09:30 ET
  // Convert current ET to a date, set to next day 09:30
  const parts = Object.fromEntries(fmt.formatToParts(after).map((p) => [p.type, p.value]));
  const year = parseInt(parts.year, 10);
  const month = parseInt(parts.month, 10) - 1; // JS months are 0-indexed
  const day = parseInt(parts.day, 10);

  // Set to 09:30 ET today
  candidate.setUTCFullYear(year, month, day);
  candidate.setUTCHours(14, 30, 0, 0); // 09:30 ET = 14:30 UTC (ET is UTC-5 normally, but...)

  // If it's past 09:30 ET today, start from tomorrow
  // Use a simpler approach: just iterate days
  const ONE_DAY_MS = 24 * 60 * 60 * 1000;
  // Reset to 09:30 ET anchor — approximate with UTC
  // Actually, this is tricky with DST. Let me do a simpler approach:
  // Just iterate dates from today forward
  const startStr = nycDateString(after);
  let checkDate = new Date(after);
  // If already during market hours, return now
  if (isMarketOpen(after)) return after;

  // If after close, start from next day
  const afterHour = parseInt(parts.hour, 10);
  const afterMinute = parseInt(parts.minute, 10);
  const afterTotalMin = afterHour * 60 + afterMinute;
  if (afterTotalMin >= 16 * 60) {
    // After 16:00 ET, jump to next day
    checkDate = new Date(checkDate.getTime() + ONE_DAY_MS);
  }

  // Walk forward until we find an open day
  for (let i = 0; i < 14; i++) {
    const dateStr = nycDateString(checkDate);
    const checkYear = parseInt(dateStr.split("-")[0], 10);
    const holidays = getMarketHolidays(checkYear);
    const dayOfWeek = new Date(Date.UTC(
      parseInt(dateStr.split("-")[0], 10),
      parseInt(dateStr.split("-")[1], 10) - 1,
      parseInt(dateStr.split("-")[2], 10)
    )).getUTCDay();

    if (dayOfWeek !== 0 && dayOfWeek !== 6 && !holidays.has(dateStr)) {
      // Found an open day — set to 09:30 ET
      const [y, m, d] = dateStr.split("-").map(Number);
      const openDate = new Date(Date.UTC(y, m - 1, d, 14, 30, 0, 0)); // 09:30 ET = 14:30 UTC (EST) or 13:30 UTC (EDT)
      // Actually, 09:30 America/New_York... let me just use ISO string intent
      // The caller will interpret this as NYC time. Return a Date representing 09:30 ET.
      return openDate;
    }

    checkDate = new Date(checkDate.getTime() + ONE_DAY_MS);
  }

  // Fallback: return 2 days from now at 09:30 ET
  const fallback = new Date(after.getTime() + 2 * ONE_DAY_MS);
  const fbParts = Object.fromEntries(fmt.formatToParts(fallback).map((p) => [p.type, p.value]));
  const fbYear = parseInt(fbParts.year, 10);
  const fbMonth = parseInt(fbParts.month, 10) - 1;
  const fbDay = parseInt(fbParts.day, 10);
  return new Date(Date.UTC(fbYear, fbMonth, fbDay, 14, 30, 0, 0));
}

function getNthWeekdayOfMonth(year: number, month: number, weekday: number, n: number): Date {
  const date = new Date(Date.UTC(year, month, 1));
  let count = 0;
  while (date.getUTCMonth() === month) {
    if (date.getUTCDay() === weekday) {
      count++;
      if (count === n) return date;
    }
    date.setUTCDate(date.getUTCDate() + 1);
  }
  throw new Error("Nth weekday not found");
}

export function asMoney(value: number): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 2
  }).format(value);
}

export function roundCents(value: number): number {
  return Math.round(value * 100) / 100;
}

export function normalizeSymbol(symbol: string): string {
  return symbol.trim().toUpperCase();
}

// Our canonical symbol format uses a hyphen for share classes (e.g. "BRK-B", the Robinhood
// convention — see sp500.ts). Alpaca's asset/order/quote/news/snapshot APIs reject that and
// require a dot ("BRK.B") — an unconverted hyphen produces an HTTP 422/400 depending on the
// endpoint. Convert at the Alpaca boundary only — internal state stays hyphenated.
export function toAlpacaSymbol(symbol: string): string {
  return normalizeSymbol(symbol).replace(/-/g, ".");
}

// Inverse of toAlpacaSymbol — normalize symbols coming back from Alpaca (orders, positions,
// quotes, news, streams) to our canonical hyphenated format so they match watchlist/proposal
// symbols elsewhere.
export function fromAlpacaSymbol(symbol: string): string {
  return normalizeSymbol(symbol).replace(/\./g, "-");
}

export function formatQuantity(value: number | undefined | null, _symbol?: string): string {
  if (value == null) return "0";
  const abs = Math.abs(value);
  if (abs === 0) return "0";

  // Significant figures to show: at least 3, but always enough to show EVERY integer
  // digit so a large whole-share count is never truncated — i.e. "3 significant figures
  // OR all digits of the whole number, whichever is larger" (12,489.242 -> "12,489";
  // 0.167333 -> "0.167"; 1.5 -> "1.5"). Comma-grouped; trailing zeros stripped.
  const intDigits = abs >= 1 ? Math.trunc(abs).toString().length : 0;
  const sigFigs = Math.max(3, intDigits);
  return Number(value.toPrecision(sigFigs)).toLocaleString("en-US", { maximumFractionDigits: 20 });
}

import { audit, getNotifyPrefs, getPolicy, insertNotificationEvent, getDb } from "./db";
import { notify, type NotifyDispatchDeps } from "./notify";
import type { NotificationEvent, NotificationEventType, NotifyChannelId, NotifyChannelResult, TradingPolicy, OptionPosition } from "./types";

type Fetcher = typeof fetch;
type NotifyDispatcher = typeof notify;
type NotificationDeliveryControl = Pick<NotifyDispatchDeps, "assertActive" | "signal">;

type SendNotificationOptions = {
  policy?: TradingPolicy;
  fetcher?: Fetcher;
  timeoutMs?: number;
  userId?: string;
  connectedAccountId?: string;
  /** Override the compact bridge body while keeping delivery inside the enabled-event gate. */
  directBody?: string;
  /** Injectable dispatcher/deps keep failure and caller-routing tests offline. */
  notifyImpl?: NotifyDispatcher;
  notifyDeps?: Parameters<NotifyDispatcher>[2];
  /** Extra operator-only lane (for example the configured fallback email), invoked after gating. */
  additionalDelivery?: (control?: NotificationDeliveryControl) => Promise<NotifyChannelResult[]>;
  /** Cooperative ownership fence for callers whose work may be superseded while delivery awaits. */
  assertActive?: () => void;
  /** Cancellation signal paired with assertActive for in-flight delivery and retry waits. */
  signal?: AbortSignal;
};

function assertNotificationActive(options: SendNotificationOptions): void {
  options.assertActive?.();
  if (options.notifyDeps?.assertActive !== options.assertActive) {
    options.notifyDeps?.assertActive?.();
  }
  for (const signal of [options.signal, options.notifyDeps?.signal]) {
    if (!signal?.aborted) continue;
    throw signal.reason instanceof Error
      ? signal.reason
      : new Error("Notification delivery ownership was lost.");
  }
}

function combineNotificationSignals(...signals: Array<AbortSignal | undefined>): AbortSignal | undefined {
  const active = signals.filter((signal): signal is AbortSignal => signal !== undefined);
  if (active.length === 0) return undefined;
  if (active.length === 1 || typeof AbortSignal.any !== "function") return active[0];
  return AbortSignal.any(active);
}

function guardedNotifyDeps(
  deps: NotifyDispatchDeps | undefined,
  assertActive: (() => void) | undefined,
  signal: AbortSignal | undefined
): NotifyDispatchDeps {
  const nestedAssert = deps?.assertActive;
  const combinedAssert = assertActive || nestedAssert
    ? () => {
        assertActive?.();
        nestedAssert?.();
      }
    : undefined;
  const combinedSignal = combineNotificationSignals(signal, deps?.signal);
  return {
    ...deps,
    ...(combinedAssert ? { assertActive: combinedAssert } : {}),
    ...(combinedSignal ? { signal: combinedSignal } : {})
  };
}

function notificationDeliveryControl(options: SendNotificationOptions): NotificationDeliveryControl {
  const hasGuard = options.assertActive !== undefined || options.notifyDeps?.assertActive !== undefined;
  const signal = combineNotificationSignals(options.signal, options.notifyDeps?.signal);
  return {
    ...(hasGuard ? { assertActive: () => assertNotificationActive(options) } : {}),
    ...(signal ? { signal } : {})
  };
}

const CHANNEL_LABELS: Record<NotifyChannelId, string> = {
  push: "Phone push",
  webhook: "Webhook",
  email: "Email",
  sms: "SMS"
};

export const NO_NOTIFICATION_CHANNELS_REASON = "No notification channels enabled.";

// Types that emit their own in-app audit rows before calling sendNotification.
// Skip writing a second in-app notification_events row for them to avoid double-writing.
const DIRECT_NOTIFY_SKIP_SET: ReadonlySet<NotificationEventType> = new Set([
  "storage_warning"
]);

// The ntfy push channel (notify.ts's CHANNELS.push.send) carries the message TITLE as a raw HTTP
// header value. The Fetch/Headers spec requires header values to be ByteString (Latin-1, code
// points 0x00-0xFF) — anything outside that range throws `TypeError: Cannot convert argument to a
// ByteString` at send time. Observed in prod: alert titles built from provider-health strings that
// use an em dash (U+2014, code point 8212) silently dropped the push channel end-to-end (the throw
// was caught and recorded as a `notify.error` audit row, never surfaced to the user). Transliterate
// the common offenders to ASCII first (readable), then strip anything else outside Latin-1 rather
// than let the send throw.
//
// NOTE: notify.ts keeps its OWN copy of this (see its push channel) rather than importing this one,
// to avoid a notify.ts <-> notifications.ts import cycle (notifications.ts already imports `notify`
// from notify.ts). Keep the two in sync if the character set below changes.
const NON_LATIN1_TRANSLITERATIONS: ReadonlyArray<readonly [RegExp, string]> = [
  [/[\u2012\u2013\u2014\u2015]/g, "-"], // figure/en/em/horizontal-bar dashes
  [/\u2026/g, "..."], // horizontal ellipsis
  [/[\u2192\u21D2\u27F6\u279D\u27A1]/g, "->"], // rightwards arrow variants
  [/[\u2190\u21D0\u27F5]/g, "<-"], // leftwards arrow variants
  [/[\u2018\u2019]/g, "'"], // curly single quotes
  [/[\u201C\u201D]/g, '"'] // curly double quotes
];

/** Make `text` safe to carry as a raw HTTP header value (e.g. the ntfy push channel's `title`
 *  header): transliterate common non-Latin-1 punctuation to its ASCII equivalent, then strip
 *  anything else outside Latin-1 (the U+0000-U+00FF ByteString range Headers requires).
 *  Pure/no-op on already-ASCII text. */
export function sanitizePushHeaderText(text: string): string {
  if (!text) return text;
  let out = text;
  for (const [pattern, replacement] of NON_LATIN1_TRANSLITERATIONS) {
    out = out.replace(pattern, replacement);
  }
  return out.replace(/[^\u0000-\u00FF]/g, "");
}

export async function sendNotification(
  input: {
    type: NotificationEventType;
    title: string;
    payload: unknown;
  },
  options: SendNotificationOptions = {}
): Promise<NotificationEvent> {
  assertNotificationActive(options);
  const userId = options.userId ?? "local";
  const policy = options.policy ?? getPolicy(userId);
  const connectedAccountId = options.connectedAccountId ?? policy.connectedAccountId;
  assertNotificationActive(options);
  const settings = policy.notificationSettings;
  const webhookUrl = settings.webhookUrl?.trim();

  if (!settings.enabledEvents.includes(input.type)) {
    assertNotificationActive(options);
    return record(input, "skipped", webhookUrl, "Notification type is disabled.", userId, connectedAccountId);
  }

  const results: NotifyChannelResult[] = [];
  const bridgeErrors: string[] = [];
  try {
    assertNotificationActive(options);
    const directResults = await sendDirectNotification(input, userId, {
      skipWebhook: !!webhookUrl,
      directBody: options.directBody,
      notifyImpl: options.notifyImpl,
      notifyDeps: options.notifyDeps,
      assertActive: options.assertActive,
      signal: options.signal
    });
    assertNotificationActive(options);
    results.push(...directResults);
  } catch (error) {
    assertNotificationActive(options);
    bridgeErrors.push(recordBridgeError(input.type, userId, "direct", error, connectedAccountId));
  }

  if (options.additionalDelivery) {
    try {
      assertNotificationActive(options);
      const additionalResults = await options.additionalDelivery(notificationDeliveryControl(options));
      assertNotificationActive(options);
      results.push(...additionalResults);
    } catch (error) {
      assertNotificationActive(options);
      bridgeErrors.push(recordBridgeError(input.type, userId, "additional", error, connectedAccountId));
    }
  }

  if (webhookUrl) {
    assertNotificationActive(options);
    const legacyWebhookResult = await sendLegacyWebhook(
      input,
      webhookUrl,
      options.fetcher ?? fetch,
      options.timeoutMs ?? 5000,
      options.signal
    );
    assertNotificationActive(options);
    results.push(legacyWebhookResult);
    assertNotificationActive(options);
    audit(
      legacyWebhookResult.ok ? "notify.sent" : "notify.error",
      {
        userId,
        channel: "webhook",
        kind: input.type,
        source: "legacy_policy_webhook",
        ...(legacyWebhookResult.error ? { error: legacyWebhookResult.error, attempts: 1 } : {})
      },
      userId,
      connectedAccountId
    );
  }

  assertNotificationActive(options);
  const outcome = deriveDeliveryOutcome(results, bridgeErrors);
  assertNotificationActive(options);
  const event = record(input, outcome.status, webhookUrl, outcome.reason, userId, connectedAccountId);
  assertNotificationActive(options);
  audit(
    "notification.delivery",
    {
      notificationEventId: event.id,
      type: input.type,
      status: event.status,
      results,
      bridgeErrors
    },
    userId,
    connectedAccountId
  );
  return event;
}

async function sendLegacyWebhook(
  input: { type: NotificationEventType; title: string; payload: unknown },
  webhookUrl: string,
  fetcher: Fetcher,
  timeoutMs: number,
  callerSignal?: AbortSignal
): Promise<NotifyChannelResult> {
  const isDiscord = webhookUrl.includes("discord.com/api/webhooks") || webhookUrl.includes("discordapp.com/api/webhooks");
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const payloadBody = isDiscord
      ? formatDiscordPayload(input)
      : {
          type: input.type,
          title: input.title,
          payload: input.payload,
          createdAt: new Date().toISOString()
        };
    const response = await fetcher(webhookUrl, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(payloadBody),
      signal: combineNotificationSignals(callerSignal, controller.signal)
    });
    if (!response.ok) {
      return { channel: "webhook", ok: false, error: `Webhook returned HTTP ${response.status}.` };
    }
    return { channel: "webhook", ok: true };
  } catch (error) {
    return { channel: "webhook", ok: false, error: error instanceof Error ? error.message : "Webhook request failed." };
  } finally {
    clearTimeout(timeout);
  }
}

async function sendDirectNotification(
  input: { type: NotificationEventType; title: string; payload: unknown },
  userId: string,
  options: {
    skipWebhook?: boolean;
    directBody?: string;
    notifyImpl?: NotifyDispatcher;
    notifyDeps?: Parameters<NotifyDispatcher>[2];
    assertActive?: () => void;
    signal?: AbortSignal;
  } = {}
): Promise<NotifyChannelResult[]> {
  const basePrefs = options.notifyDeps?.prefs;
  const prefs = options.skipWebhook
    ? (() => {
        const current = basePrefs ?? getNotifyPrefs(userId);
        return { ...current, channels: current.channels.filter((channel) => channel !== "webhook") };
      })()
    : basePrefs;
  const deps = guardedNotifyDeps(options.notifyDeps, options.assertActive, options.signal);
  return (options.notifyImpl ?? notify)(
    userId,
    {
      title: input.title,
      body: options.directBody ?? directNotificationBody(input),
      kind: input.type,
      data: input.payload
    },
    { ...deps, ...(prefs ? { prefs } : {}) }
  );
}

function recordBridgeError(
  type: NotificationEventType,
  userId: string,
  source: "direct" | "additional",
  error: unknown,
  connectedAccountId?: string
): string {
  const message = error instanceof Error ? error.message : String(error);
  audit("notify.bridge.error", { userId, type, source, error: message }, userId, connectedAccountId);
  return `${source === "direct" ? "Delivery bridge" : "Additional delivery"}: ${message}`;
}

function deriveDeliveryOutcome(
  results: NotifyChannelResult[],
  bridgeErrors: string[]
): { status: NotificationEvent["status"]; reason?: string } {
  const anySent = results.some((result) => result.ok);
  const failures = results
    .filter((result) => !result.ok && !result.skipped)
    .map((result) => `${CHANNEL_LABELS[result.channel]}: ${result.error?.trim() || "Delivery failed."}`);
  const failureDetails = [...failures, ...bridgeErrors];

  if (anySent) {
    return {
      status: "sent",
      reason: failureDetails.length > 0 ? `Partial delivery failure: ${failureDetails.join(" | ")}` : undefined
    };
  }
  if (failureDetails.length > 0) {
    return { status: "failed", reason: failureDetails.join(" | ") };
  }

  const skippedReasons = results
    .filter((result) => result.skipped)
    .map((result) =>
      result.skipped === "not_configured"
        ? `${CHANNEL_LABELS[result.channel]} is not configured by the operator.`
        : `${CHANNEL_LABELS[result.channel]} has no delivery target.`
    );
  return {
    status: "skipped",
    reason: skippedReasons.length > 0 ? skippedReasons.join(" | ") : NO_NOTIFICATION_CHANNELS_REASON
  };
}

function directNotificationBody(input: { type: NotificationEventType; title: string; payload: unknown }): string {
  const { type } = input;
  const payload = asRecord(input.payload);
  switch (type) {
    case "fill": {
      const fill = asRecord(payload.fill);
      if (!fill) return input.title;
      const side = fill.side ? String(fill.side).toUpperCase() : "ORDER";
      const symbol = fill.symbol ? ` ${fill.symbol}` : "";
      // recordFillFromProposal (performance.ts) zeroes quantity/price/notional on a "pending_reconciliation"
      // receipt when the broker hasn't reported a fill price yet — that's a pre-confirmation placeholder,
      // not a real $0 fill. Rendering the zeros verbatim reads as "BUY 0 JPM pending_reconciliation ($0.00)".
      // Key off status + absence of a priced fill (not just quantity === 0, which can be legitimately 0 on a
      // dollar-sized order awaiting its broker price) so a genuinely zero-priced CONFIRMED fill (status
      // "filled"/"partially_filled") still renders normally below.
      if (isPlaceholderFillReceipt(fill)) {
        const estimate = estimatedFillNotional(fill);
        const est = estimate !== undefined ? ` (~$${estimate.toFixed(2)} est.)` : "";
        return `${side}${symbol} — order accepted by broker; fill not yet confirmed${est}`.trim();
      }
      const status = fill.status ? ` ${String(fill.status)}` : "";
      const quantity = fill.quantity != null ? ` ${fill.quantity}` : "";
      const notional = Number.isFinite(Number(fill.notional)) ? ` ($${Number(fill.notional).toFixed(2)})` : "";
      return `${side}${quantity}${symbol}${status}${notional}`.trim();
    }
    case "block": {
      const decision = asRecord(payload.decision);
      const rawReasons = Array.isArray(decision?.reasons) ? decision.reasons : payload.reason ? [payload.reason] : [];
      const reasons = rawReasons.map(String);
      return reasons.length > 0 ? reasons.join("\n") : input.title;
    }
    case "pending_approval": {
      const proposal = asRecord(payload.proposal);
      if (!proposal) return input.title;
      const side = proposal.side ? String(proposal.side).toUpperCase() : "ORDER";
      const symbol = proposal.symbol ? ` ${proposal.symbol}` : "";
      return `Approval needed for ${side}${symbol}`.trim();
    }
    case "kill_switch":
    case "run_failed": {
      // Every run_failed emission site (strategy.ts, strategy-execution.ts) puts the actual broker
      // rejection/decline/uncertainty detail under payload.reason or payload.error, never
      // payload.summary — summary is only ever populated by the order-agnostic "Strategy run failed"
      // emitter. Falling straight through to the title (as this used to) duplicated the title as the
      // body, e.g. SMS "BAC order rejected by broker\nBAC order rejected by broker", silently
      // dropping the real reason. kill_switch sites split the same way: the scheduled-halt emitter
      // carries summary, while the circuit-breaker and volatility-brake halts carry only reason —
      // so this shared fallback chain surfaces the breaker/brake reason for those too instead of
      // repeating the title.
      const detail = payload.summary ?? payload.reason ?? payload.error;
      return String(detail ?? input.title);
    }
    case "limit_order_stale":
      return String(payload.summary ?? input.title);
    case "proposal_withdrawn":
      return String(payload.reason ?? input.title);
    case "learning_review":
      return String(payload.summary ?? input.title);
    case "budget_alert": {
      const provider = payload.provider ? String(payload.provider) : "provider";
      const operation = payload.operation ? String(payload.operation) : "usage check";
      const limitName = payload.limitName ? String(payload.limitName) : "usage limit";
      const unit = payload.unit ? ` ${String(payload.unit)}` : "";
      const used = Number.isFinite(Number(payload.used)) ? Number(payload.used).toLocaleString("en-US") : undefined;
      const limit = Number.isFinite(Number(payload.limit)) ? Number(payload.limit).toLocaleString("en-US") : undefined;
      const recommendation = payload.recommendation ? `\nAction: ${String(payload.recommendation)}` : "";
      const usage = used || limit ? `\nUsage: ${used ?? "unknown"}${unit}${limit ? ` of ${limit}${unit}` : ""}` : "";
      return `${provider} hit ${limitName} during ${operation}.${usage}${recommendation}`;
    }
    default:
      return input.title;
  }
}

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as Record<string, unknown>) : {};
}

/** True when `fill` is a recordFillFromProposal pre-confirmation placeholder receipt (status
 *  "pending_reconciliation" with no priced fill yet) rather than a real, priced fill — see the
 *  "fill" case in directNotificationBody for why this can't key off quantity/notional alone. */
function isPlaceholderFillReceipt(fill: unknown): boolean {
  const record = asRecord(fill);
  const price = Number(record.price);
  const hasPricedFill = Number.isFinite(price) && price > 0;
  return record.status === "pending_reconciliation" && !hasPricedFill;
}

/** Best-effort pre-fill notional estimate for a placeholder receipt, read from the review/proposal
 *  that recordFillFromProposal stamps onto `fill.raw` — NEVER fabricated when neither is present. */
function estimatedFillNotional(fill: unknown): number | undefined {
  const raw = asRecord(asRecord(fill).raw);
  const reviewEstimate = Number(asRecord(raw.review).estimatedNotional);
  if (Number.isFinite(reviewEstimate) && reviewEstimate > 0) return reviewEstimate;
  const dollarAmount = Number(asRecord(raw.proposal).dollarAmount);
  if (Number.isFinite(dollarAmount) && dollarAmount > 0) return dollarAmount;
  return undefined;
}

function formatDiscordPayload(input: {
  type: NotificationEventType;
  title: string;
  payload: any;
}) {
  const { type, title, payload } = input;
  let color = 10038562; // Default dark red
  let description = "";
  const fields: Array<{ name: string; value: string; inline?: boolean }> = [];

  switch (type) {
    case "fill": {
      color = 3066993; // Green
      const fill = payload?.fill;
      if (fill) {
        fields.push(
          { name: "Symbol", value: String(fill.symbol), inline: true },
          { name: "Side", value: String(fill.side).toUpperCase(), inline: true }
        );
        // See directNotificationBody's "fill" case for why a "pending_reconciliation" receipt with
        // no priced fill is a placeholder, not a real $0.00 fill — same guard, Discord embed fields.
        if (isPlaceholderFillReceipt(fill)) {
          const estimate = estimatedFillNotional(fill);
          fields.push(
            { name: "Status", value: "Order accepted by broker; fill not yet confirmed", inline: true },
            { name: "Notional", value: estimate !== undefined ? `~$${estimate.toFixed(2)} est.` : "Pending", inline: true }
          );
        } else {
          fields.push(
            { name: "Status", value: String(fill.status), inline: true },
            { name: "Quantity", value: String(fill.quantity), inline: true },
            { name: "Price", value: `$${Number(fill.price).toFixed(2)}`, inline: true },
            { name: "Notional", value: `$${Number(fill.notional).toFixed(2)}`, inline: true }
          );
        }
      }
      if (payload?.runId) {
        fields.push({ name: "Run ID", value: String(payload.runId), inline: false });
      }
      break;
    }
    case "block": {
      color = 15158332; // Red
      const reasons: string[] = payload?.decision?.reasons ?? (payload?.reason ? [payload.reason] : []);
      if (reasons.length > 0) {
        description = reasons.map(r => `• ${r}`).join("\n");
      } else {
        description = "No specific reasons provided.";
      }
      if (payload?.review?.estimatedNotional) {
        fields.push({ name: "Estimated Notional", value: `$${Number(payload.review.estimatedNotional).toFixed(2)}`, inline: true });
      }
      if (payload?.proposalId) {
        fields.push({ name: "Proposal ID", value: String(payload.proposalId), inline: true });
      }
      break;
    }
    case "pending_approval": {
      color = 15105570; // Orange
      const proposal = payload?.proposal;
      const review = payload?.review;
      if (proposal) {
        fields.push(
          { name: "Symbol", value: String(proposal.symbol), inline: true },
          { name: "Side", value: String(proposal.side).toUpperCase(), inline: true },
          { name: "Order Type", value: String(proposal.type), inline: true }
        );
        if (proposal.quantity) {
          fields.push({ name: "Quantity", value: String(proposal.quantity), inline: true });
        }
        if (proposal.dollarAmount) {
          fields.push({ name: "Dollar Amount", value: `$${Number(proposal.dollarAmount).toFixed(2)}`, inline: true });
        }
        if (review?.estimatedNotional) {
          fields.push({ name: "Estimated Notional", value: `$${Number(review.estimatedNotional).toFixed(2)}`, inline: true });
        }
        if (proposal.rationale) {
          description = `**Rationale:** ${proposal.rationale}`;
        }
      }
      if (payload?.proposalId) {
        fields.push({ name: "Proposal ID", value: String(payload.proposalId), inline: false });
      }
      break;
    }
    case "kill_switch": {
      color = 10181046; // Purple
      // Same field split as directNotificationBody: the circuit-breaker and volatility-brake
      // halts carry only payload.reason, so Discord must fall back to it too or those two real
      // production alerts render the generic text while SMS shows the specific reason.
      description = payload?.summary ?? payload?.reason ?? "Kill switch triggered.";
      if (payload?.runId) {
        fields.push({ name: "Run ID", value: String(payload.runId), inline: false });
      }
      break;
    }
    case "price_alert": {
      color = 3447003; // Blue
      const alert = payload?.alert;
      const currentPrice = payload?.currentPrice;
      if (alert) {
        fields.push(
          { name: "Symbol", value: String(alert.symbol), inline: true },
          { name: "Rule", value: `${alert.op} $${Number(alert.price).toFixed(2)}`, inline: true },
          { name: "Triggered At", value: `$${Number(currentPrice ?? alert.triggeredPrice).toFixed(2)}`, inline: true }
        );
        if (alert.note) description = String(alert.note);
      }
      break;
    }
    case "run_failed": {
      color = 15158332; // Red
      // Mirrors directNotificationBody's run_failed fallback chain — most emission sites carry the
      // real broker rejection/decline/uncertainty detail under payload.reason or payload.error, not
      // payload.summary (see that case for the full explanation).
      description = payload?.summary ?? payload?.reason ?? payload?.error ?? "Strategy run failed.";
      if (payload?.runId) {
        fields.push({ name: "Run ID", value: String(payload.runId), inline: false });
      }
      break;
    }
    case "proposal_withdrawn": {
      color = 15844367; // Amber — a pending idea was pulled, not an error
      const proposal = payload?.proposal;
      const expired = payload?.source === "expiry";
      if (proposal) {
        fields.push(
          { name: "Symbol", value: String(proposal.symbol), inline: true },
          { name: "Side", value: String(proposal.side).toUpperCase(), inline: true },
          { name: "Outcome", value: expired ? "Expired" : "Withdrawn", inline: true }
        );
      }
      if (payload?.reason) description = String(payload.reason);
      if (payload?.proposalId) {
        fields.push({ name: "Proposal ID", value: String(payload.proposalId), inline: false });
      }
      break;
    }
    case "limit_order_stale": {
      color = 15105570; // Orange
      const order = payload?.order;
      description = payload?.summary ?? "Limit order is still working after the configured threshold.";
      if (order) {
        fields.push(
          { name: "Symbol", value: String(order.symbol), inline: true },
          { name: "Side", value: String(order.side).toUpperCase(), inline: true },
          { name: "State", value: String(order.state), inline: true }
        );
        if (payload?.remainingQuantity !== undefined) {
          fields.push({ name: "Remaining", value: String(payload.remainingQuantity), inline: true });
        }
        if (payload?.ageMinutes !== undefined) {
          fields.push({ name: "Age", value: `${payload.ageMinutes} min`, inline: true });
        }
      }
      break;
    }
    case "budget_alert": {
      color = 15105570; // Orange
      description = payload?.recommendation ?? "A provider usage cap, quota, or budget threshold was reached.";
      fields.push(
        { name: "Provider", value: String(payload?.provider ?? "Unknown"), inline: true },
        { name: "Limit", value: String(payload?.limitName ?? "Usage limit"), inline: true },
        { name: "Operation", value: String(payload?.operation ?? "Unknown"), inline: true }
      );
      if (payload?.used !== undefined || payload?.limit !== undefined) {
        const unit = payload?.unit ? ` ${String(payload.unit)}` : "";
        fields.push({
          name: "Usage",
          value: `${payload?.used ?? "unknown"}${unit}${payload?.limit !== undefined ? ` / ${payload.limit}${unit}` : ""}`,
          inline: true
        });
      }
      if (payload?.skipped !== undefined) {
        fields.push({ name: "Skipped", value: String(payload.skipped), inline: true });
      }
      break;
    }
  }

  return {
    embeds: [
      {
        title,
        description: description || undefined,
        color,
        fields: fields.length > 0 ? fields : undefined,
        timestamp: new Date().toISOString()
      }
    ]
  };
}

function record(
  input: { type: NotificationEventType; title: string; payload: unknown },
  status: NotificationEvent["status"],
  webhookUrl?: string,
  error?: string,
  userId: string = "local",
  connectedAccountId?: string
): NotificationEvent {
  const isSkippedInApp = DIRECT_NOTIFY_SKIP_SET.has(input.type);
  const event: NotificationEvent = isSkippedInApp
    ? {
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString(),
        type: input.type,
        title: input.title,
        status,
        webhookUrl: webhookUrl ? maskWebhookUrl(webhookUrl) : undefined,
        payload: input.payload,
        error,
        connectedAccountId
      }
    : insertNotificationEvent({
        userId,
        connectedAccountId,
        type: input.type,
        title: input.title,
        status,
        webhookUrl: webhookUrl ? maskWebhookUrl(webhookUrl) : undefined,
        payload: input.payload,
        error
      });

  audit("notification", event, userId, connectedAccountId);
  return event;
}

function maskWebhookUrl(value: string): string {
  try {
    const url = new URL(value);
    url.search = "";
    return url.toString();
  } catch {
    return value;
  }
}

export async function checkAndDispatchOptionAlerts(
  userId: string,
  connectedAccountId: string,
  accountNumber: string,
  options: OptionPosition[],
  gateway: any
): Promise<void> {
  const db = getDb();
  // Only successfully-delivered events are tracked as sent; skipped or failed
  // events must not prevent future delivery when the user enables the alert type.
  const recentAlerts = db.prepare(
    `SELECT payload FROM notification_events
     WHERE user_id = ? AND type = 'option_alert' AND status = 'sent'
       AND COALESCE(connected_account_id, '') = ?`
  ).all(userId, connectedAccountId) as Array<{ payload: string }>;

  const sentAlerts = new Set<string>();
  for (const row of recentAlerts) {
    try {
      const payload = JSON.parse(row.payload);
      if (payload.symbol && payload.alertType) {
        sentAlerts.add(`${payload.symbol}:${payload.alertType}`);
      }
    } catch {}
  }

  const optionsExpiringSoon = options.filter((p) => {
    if (!p.expirationDate) return false;
    const days = Math.ceil((new Date(p.expirationDate).getTime() - Date.now()) / (24 * 60 * 60 * 1000));
    return days >= 0 && days <= 3;
  });

  const underlyingPrices: Record<string, number> = {};
  if (optionsExpiringSoon.length > 0) {
    const underlyings = Array.from(new Set(optionsExpiringSoon.map((p) => p.underlyingSymbol)));
    try {
      const quotes = await gateway.getEquityQuotes(accountNumber, underlyings);
      for (const sym of underlyings) {
        if (quotes[sym]?.price) {
          underlyingPrices[sym] = quotes[sym].price;
        }
      }
    } catch (err) {
      console.warn("[OptionAlerts] failed to fetch underlying quotes:", err);
    }
  }

  for (const p of options) {
    const symbol = p.symbol;
    const qty = p.quantity;

    // 1. Assignment / first appearance alert
    const appKey = `${symbol}:appearance`;
    if (!sentAlerts.has(appKey)) {
      const detail = `New option position detected: ${qty > 0 ? "Long" : "Short"} ${Math.abs(qty)} contracts of ${symbol} at average cost $${p.averageCost}.`;
      await sendNotification({
        type: "option_alert",
        title: `New Option: ${qty > 0 ? "Bought" : "Sold"} ${Math.abs(qty)}x ${symbol}`,
        payload: {
          symbol,
          underlyingSymbol: p.underlyingSymbol,
          expirationDate: p.expirationDate,
          optionType: p.optionType,
          strikePrice: p.strikePrice,
          quantity: qty,
          averageCost: p.averageCost,
          marketValue: p.marketValue,
          alertType: "appearance",
          detail
        }
      }, { userId, connectedAccountId });
    }

    // 2. Expiry alert (<= 3 days)
    if (p.expirationDate) {
      const days = Math.ceil((new Date(p.expirationDate).getTime() - Date.now()) / (24 * 60 * 60 * 1000));
      if (days >= 0 && days <= 3) {
        const expKey = `${symbol}:expiry`;
        if (!sentAlerts.has(expKey)) {
          const detail = `Option position ${symbol} expires in ${days} days (on ${p.expirationDate}).`;
          await sendNotification({
            type: "option_alert",
            title: `Option Expiring: ${symbol} (${days}d remaining)`,
            payload: {
              symbol,
              underlyingSymbol: p.underlyingSymbol,
              expirationDate: p.expirationDate,
              optionType: p.optionType,
              strikePrice: p.strikePrice,
              quantity: qty,
              averageCost: p.averageCost,
              marketValue: p.marketValue,
              alertType: "expiry",
              daysRemaining: days,
              detail
            }
          }, { userId, connectedAccountId });
        }

        // 3. ITM-at-expiry status alert
        const underlyingPrice = underlyingPrices[p.underlyingSymbol];
        if (underlyingPrice !== undefined) {
          const isItm = p.optionType === "call" 
            ? underlyingPrice > p.strikePrice 
            : underlyingPrice < p.strikePrice;

          if (isItm) {
            const itmKey = `${symbol}:itm`;
            if (!sentAlerts.has(itmKey)) {
              const detail = `Option ${symbol} is In-the-Money at expiry. Underlying price is $${underlyingPrice}, strike is $${p.strikePrice}.`;
              await sendNotification({
                type: "option_alert",
                title: `Option ITM at Expiry: ${symbol}`,
                payload: {
                  symbol,
                  underlyingSymbol: p.underlyingSymbol,
                  expirationDate: p.expirationDate,
                  optionType: p.optionType,
                  strikePrice: p.strikePrice,
                  quantity: qty,
                  averageCost: p.averageCost,
                  marketValue: p.marketValue,
                  alertType: "itm",
                  underlyingPrice,
                  detail
                }
              }, { userId, connectedAccountId });
            }
          }
        }
      }
    }
  }
}

import { redactForTelemetry, safeErrorMessage } from "./telemetry-sanitize";
import { assertWithinLlmBudget } from "./llm-budget";

type LlmGenerationOptions<T> = {
  name: string;
  model: string;
  userId?: string;
  /** The targeted account, so the budget backstop resolves THAT account's ceiling (not the active one). */
  connectedAccountId?: string;
  sessionId?: string;
  input?: unknown;
  metadata?: Record<string, unknown>;
  tags?: string[];
  output?: (result: T) => unknown;
};

type TraceProvider = {
  register: () => void;
};

type TraceProviderConstructor = new (config: { spanProcessors: unknown[] }) => TraceProvider;
type SpanProcessorConstructor = new (config: Record<string, unknown>) => unknown;
type LangfuseGeneration = {
  update: (fields: Record<string, unknown>) => void;
  end: () => void;
};
type LangfuseTracing = {
  propagateAttributes: <T>(attributes: Record<string, unknown>, run: () => Promise<T>) => Promise<T>;
  startObservation: (
    name: string,
    attributes: Record<string, unknown>,
    options: Record<string, unknown>
  ) => LangfuseGeneration;
};

declare global {
  // eslint-disable-next-line no-var
  var __tradingObservabilityStarted: boolean | undefined;
  // eslint-disable-next-line no-var
  var __tradingObservabilitySdk: unknown | undefined;
  // eslint-disable-next-line no-var
  var __tradingObservabilityWarned: boolean | undefined;
}

const runtimeImport = new Function("specifier", "return import(specifier)") as <T>(specifier: string) => Promise<T>;

export async function startObservability(): Promise<void> {
  if (!langfuseConfigured() || globalThis.__tradingObservabilityStarted) return;

  try {
    const [{ NodeTracerProvider }, { LangfuseSpanProcessor }] = await Promise.all([
      runtimeImport<{ NodeTracerProvider: TraceProviderConstructor }>("@opentelemetry/sdk-trace-node"),
      runtimeImport<{ LangfuseSpanProcessor: SpanProcessorConstructor }>("@langfuse/otel")
    ]);

    const provider = new NodeTracerProvider({
      spanProcessors: [
        new LangfuseSpanProcessor({
          publicKey: process.env.LANGFUSE_PUBLIC_KEY,
          secretKey: process.env.LANGFUSE_SECRET_KEY,
          baseUrl: process.env.LANGFUSE_BASE_URL,
          environment: process.env.LANGFUSE_TRACING_ENVIRONMENT || process.env.NODE_ENV || "development",
          release: process.env.LANGFUSE_RELEASE || process.env.VERCEL_GIT_COMMIT_SHA || process.env.npm_package_version,
          mask: ({ data }: { data: unknown }) => redactForTelemetry(data)
        })
      ]
    });

    provider.register();
    globalThis.__tradingObservabilitySdk = provider;
    globalThis.__tradingObservabilityStarted = true;
  } catch (error) {
    warnOnce(`Langfuse OpenTelemetry startup failed: ${safeErrorMessage(error)}`);
  }
}

export async function withLlmGeneration<T>(options: LlmGenerationOptions<T>, run: () => Promise<T>): Promise<T> {
  // Durable budget backstop: EVERY LLM generation flows through here (bull, bear, red-team,
  // revalidation, reflection, tuning, and any future one), so throwing when the user is over their
  // daily budget guarantees no model spend slips past the ceiling — even from a call site that forgot
  // its own gate. No-op when no ceiling is configured (default). Runs BEFORE the Langfuse short-circuit
  // so it applies whether or not tracing is enabled.
  if (options.userId) assertWithinLlmBudget(options.userId, options.connectedAccountId);
  if (!langfuseConfigured()) return run();

  let attemptedRun = false;

  try {
    const { propagateAttributes, startObservation } = await runtimeImport<LangfuseTracing>("@langfuse/tracing");
    const observationMetadata = redactForTelemetry(options.metadata) as Record<string, unknown> | undefined;
    return (await propagateAttributes(
      {
        userId: options.userId,
        sessionId: options.sessionId,
        traceName: options.name,
        tags: options.tags,
        metadata: compactTraceMetadata(options.metadata)
      },
      async () => {
        let generation: ReturnType<typeof startObservation>;

        try {
          generation = startObservation(
            options.name,
            {
              model: options.model,
              input: redactForTelemetry(options.input),
              metadata: observationMetadata
            },
            { asType: "generation" }
          );
        } catch (error) {
          warnOnce(`Langfuse observation startup failed: ${safeErrorMessage(error)}`);
          attemptedRun = true;
          return run();
        }

        try {
          attemptedRun = true;
          const result = await run();
          try {
            generation.update({
              output: redactForTelemetry(options.output ? options.output(result) : undefined),
              level: "DEFAULT"
            });
            generation.end();
          } catch (error) {
            warnOnce(`Langfuse observation update failed: ${safeErrorMessage(error)}`);
          }
          return result;
        } catch (error) {
          try {
            generation.update({
              output: { error: safeErrorMessage(error) },
              level: "ERROR",
              statusMessage: safeErrorMessage(error)
            });
            generation.end();
          } catch (telemetryError) {
            warnOnce(`Langfuse observation error update failed: ${safeErrorMessage(telemetryError)}`);
          }
          throw error;
        }
      }
    )) as T;
  } catch (error) {
    if (attemptedRun) throw error;
    warnOnce(`Langfuse manual tracing failed: ${safeErrorMessage(error)}`);
    return run();
  }
}

/**
 * Emit a lightweight, standalone Langfuse observation for a non-LLM decision point (e.g. a Bear
 * veto or a rationale diversity-collapse) so it's queryable alongside the traced generations. This
 * is a fire-and-forget span with metadata/tags — no model input/output. It is a hard no-op when
 * Langfuse is not configured (`langfuseConfigured()` is false), so it never adds runtime cost or a
 * dependency when Langfuse isn't set up. Errors are swallowed (warn-once) so telemetry can never break a run.
 */
export async function recordDecisionObservation(options: {
  name: string;
  userId?: string;
  metadata?: Record<string, unknown>;
  tags?: string[];
}): Promise<void> {
  if (!langfuseConfigured()) return;
  try {
    const { propagateAttributes, startObservation } = await runtimeImport<LangfuseTracing>("@langfuse/tracing");
    await propagateAttributes(
      {
        userId: options.userId,
        traceName: options.name,
        tags: options.tags,
        metadata: compactTraceMetadata(options.metadata)
      },
      async () => {
        try {
          const observation = startObservation(
            options.name,
            { metadata: redactForTelemetry(options.metadata) as Record<string, unknown> | undefined },
            { asType: "event" }
          );
          observation.end();
        } catch (error) {
          warnOnce(`Langfuse decision observation failed: ${safeErrorMessage(error)}`);
        }
      }
    );
  } catch (error) {
    warnOnce(`Langfuse decision observation failed: ${safeErrorMessage(error)}`);
  }
}

function langfuseConfigured(): boolean {
  return (
    process.env.LANGFUSE_ENABLED !== "off" &&
    Boolean(process.env.LANGFUSE_PUBLIC_KEY) &&
    Boolean(process.env.LANGFUSE_SECRET_KEY)
  );
}

function warnOnce(message: string): void {
  if (globalThis.__tradingObservabilityWarned) return;
  globalThis.__tradingObservabilityWarned = true;
  console.warn(message);
}

function compactTraceMetadata(metadata: Record<string, unknown> | undefined): Record<string, string> | undefined {
  if (!metadata) return undefined;
  const redacted = redactForTelemetry(metadata) as Record<string, unknown>;
  return Object.fromEntries(
    Object.entries(redacted)
      .filter(([, value]) => value !== undefined)
      .map(([key, value]) => {
        const raw = typeof value === "string" ? value : JSON.stringify(value);
        return [key, raw.length > 200 ? `${raw.slice(0, 197)}...` : raw];
      })
  );
}

