import * as cheerio from "cheerio";
import { getDb } from "../db";
import { politeFetch } from "./http";
import { padCik } from "./sec-filings";
import crypto from "crypto";

const SEC_DATA_BASE = "https://data.sec.gov";

// High-yield GAAP concepts for scanning
const targetConcepts = new Set([
  "Assets",
  "Liabilities",
  "AssetsCurrent",
  "LiabilitiesCurrent",
  "Revenues",
  "SalesRevenueNet",
  "RevenueFromContractWithCustomerExcludingAssessedTax",
  "NetIncomeLoss",
  "OperatingIncomeLoss",
  "LongTermDebt",
  "ShortTermBorrowings"
]);

// IFRS equivalents for admitted foreign-issuer forms (20-F/40-F report under `facts.ifrs-full`,
// not `facts.us-gaap`). Concept names differ from US-GAAP; this is the ifrs-full counterpart set.
const ifrsTargetConcepts = new Set([
  "Assets",
  "Liabilities",
  "CurrentAssets",
  "CurrentLiabilities",
  "Revenue",
  "ProfitLoss",
  "ProfitLossFromOperatingActivities"
]);

/** SEC XML encodes booleans as either "true"/"false" or the equally valid "1"/"0". */
function xmlBoolean(value: string): boolean {
  const v = value.trim().toLowerCase();
  return v === "true" || v === "1";
}

/**
 * Ingest all facts for a CIK from data.sec.gov/api/xbrl/companyfacts
 * and store them inside SQLite `sec_facts`.
 */
export async function ingestCompanyFacts(cik: string): Promise<void> {
  const db = getDb();
  const paddedCik = padCik(cik);
  const url = `${SEC_DATA_BASE}/api/xbrl/companyfacts/CIK${paddedCik}.json`;

  try {
    const res = await politeFetch(url, {
      headers: { "User-Agent": "Antigravity/1.0 (jay@socratic.trade)" }
    });
    if (!res.ok) {
      if (res.status === 404) return; // No facts available for CIK
      throw new Error(`Failed to fetch company facts: ${res.statusText}`);
    }

    const data = await res.json() as any;
    // 20-F/40-F issuers reporting under IFRS expose concepts under `facts.ifrs-full` rather than
    // `facts.us-gaap` — both taxonomies are supported inputs (the periodic-form allowlist below
    // admits 20-F/40-F), so a missing US-GAAP namespace alone is not "no data".
    const taxonomies: Array<{ name: string; facts: Record<string, unknown>; targets: Set<string> }> = [];
    if (data?.facts?.["us-gaap"]) taxonomies.push({ name: "us-gaap", facts: data.facts["us-gaap"], targets: targetConcepts });
    if (data?.facts?.["ifrs-full"]) taxonomies.push({ name: "ifrs-full", facts: data.facts["ifrs-full"], targets: ifrsTargetConcepts });
    if (taxonomies.length === 0) {
      return; // genuinely no supported taxonomy — expected no-data case
    }

    const insertStmt = db.prepare(`
      INSERT OR REPLACE INTO sec_facts (
        id, cik, accession, concept, value, unit, period, start_date, end_date, accepted_at, segment
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    db.transaction(() => {
      for (const { name: taxonomyName, facts: taxonomyFacts, targets } of taxonomies) {
      for (const [concept, conceptData] of Object.entries(taxonomyFacts)) {
        if (!targets.has(concept)) continue;
        const units = (conceptData as any).units;
        if (!units || typeof units !== "object") continue;

        for (const [unitName, unitEntries] of Object.entries(units)) {
          if (!Array.isArray(unitEntries)) {
            continue;
          }

          for (const entry of unitEntries) {
            if (!entry || typeof entry !== "object") {
              continue;
            }
            const val = (entry as any).val;
            const accession = (entry as any).accn;
            const end = (entry as any).end;
            const form = (entry as any).form;
            const filed = (entry as any).filed;

            // Only care about periodic forms
            if (!form || !["10-K", "10-Q", "20-F", "40-F"].includes(form)) {
              continue;
            }
            if (typeof val !== "number" || !accession || !end) {
              continue;
            }

            const period = (entry as any).frame || `${(entry as any).fy || ""}-${(entry as any).fp || ""}`;
            const start = (entry as any).start || null;
            const accepted = (entry as any).filed || new Date().toISOString();
            const segment = (entry as any).segment ? JSON.stringify((entry as any).segment) : null;

            // Generate deterministic ID
            const id = crypto.createHash("sha256")
              .update(`${paddedCik}:${accession}:${taxonomyName}:${concept}:${period}:${segment || ""}`)
              .digest("hex");

            insertStmt.run(
              id,
              paddedCik,
              accession,
              concept,
              val,
              unitName,
              period,
              start,
              end,
              accepted,
              segment
            );
          }
        }
      }
      }
    })();
  } catch (err: any) {
    // Only the explicit 404 no-data path above is swallowed. Operational failures — transient
    // SEC 429/500s, JSON parse errors, SQLite insert failures — must PROPAGATE so the ingest
    // worker's lease/retry (and eventually dead-letter) path re-runs this stage, instead of the
    // task silently advancing past facts extraction with no structured facts forever.
    console.error(`[sec-facts] Failed to ingest facts for CIK ${cik}:`, err?.message ?? err);
    throw err;
  }
}

/**
 * Parses Form 4 XML string using cheerio and writes entries into `sec_insider_transactions`.
 */
export function parseAndSaveForm4(xmlContent: string, cik: string, accession: string): number {
  const db = getDb();
  const $ = cheerio.load(xmlContent, { xmlMode: true });
  const paddedCik = padCik(cik);

  // Jointly filed Form 4s (trusts, funds, co-reporting insiders) carry multiple <reportingOwner>
  // elements — record every owner and attribute each transaction to each of them, with the owner
  // identity part of the row identity. SEC XML booleans are validly "1"/"0" as well as
  // "true"/"false" (xmlBoolean accepts both).
  const owners = $("reportingOwner").toArray().map((ownerEl) => {
    const name = $(ownerEl).find("reportingOwnerId > rptOwnerName").first().text().trim();
    const isOfficer = xmlBoolean($(ownerEl).find("reportingOwnerRelationship > isOfficer").first().text());
    const officerTitle = $(ownerEl).find("reportingOwnerRelationship > officerTitle").first().text().trim();
    const isDirector = xmlBoolean($(ownerEl).find("reportingOwnerRelationship > isDirector").first().text());
    const relationship = officerTitle || (isOfficer ? "Officer" : isDirector ? "Director" : "Ten Percent Owner");
    return { name, relationship };
  });
  if (owners.length === 0) {
    owners.push({ name: "", relationship: "Ten Percent Owner" });
  }

  // Real ownership XML encodes periodOfReport as direct element text; synthetic fixtures may nest
  // a <value> child. `.text()` covers both (it concatenates descendant text), trimmed.
  const periodOfReport = $("periodOfReport").first().text().trim();

  // Document-level Rule 10b5-1 checkbox (<aff10b5One>, present since the 2023 amendments) — used
  // as the fallback when a transaction carries no transaction-level indicator.
  const docLevel10b51 = xmlBoolean($("aff10b5One").first().text());

  let count = 0;

  const insertStmt = db.prepare(`
    INSERT OR REPLACE INTO sec_insider_transactions (
      id, cik, accession, insider_name, relationship, side, shares, price, period_of_report, is_10b5_1, transaction_code
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);

  db.transaction(() => {
    $("nonDerivativeTransaction, derivativeTransaction").each((_, el) => {
      const sharesVal = $(el).find("transactionAmounts > transactionShares > value").text().trim();
      const priceVal = $(el).find("transactionAmounts > transactionPricePerShare > value").text().trim();
      const ad = $(el).find("transactionAmounts > transactionAcquiredDisposedCode > value").text().trim(); // A or D
      // Preserve the SEC transaction code (P/S = open-market trades; A/M/G/F/... = grants,
      // exercises, gifts, tax withholding). side below is only the acquired/disposed axis, so
      // downstream insider evidence needs this code to distinguish real trades from non-trade
      // events (the legacy sec.ts parser limits trading signals to codes P and S).
      const transactionCode = $(el).find("transactionCoding > transactionCode").first().text().trim();
      const tx10b51Raw = $(el).find("transactionCoding > rule10b51Transaction").first().text().trim();
      const is10b5_1 = (tx10b51Raw ? xmlBoolean(tx10b51Raw) : docLevel10b51) ? 1 : 0;

      if (!sharesVal || !ad) return;

      const shares = parseFloat(sharesVal);
      const price = priceVal ? parseFloat(priceVal) : 0;
      const side = ad === "D" ? "sell" : "buy";

      for (const owner of owners) {
        // deterministic ID for duplicate prevention — includes the owner so jointly filed
        // transactions keep one row per reporting owner.
        const id = crypto.createHash("sha256")
          .update(`${accession}:${owner.name}:${count}:${shares}:${price}:${side}`)
          .digest("hex");

        insertStmt.run(
          id,
          paddedCik,
          accession,
          owner.name,
          owner.relationship,
          side,
          shares,
          price,
          periodOfReport,
          is10b5_1,
          transactionCode
        );
      }
      count++;
    });
  })();

  return count;
}

/**
 * Format structured facts for a symbol into a clean narrative Evidence Card for the LLM prompt.
 */
export function formatCompanyFactsEvidenceCard(cik: string): string {
  const db = getDb();
  const paddedCik = padCik(cik);

  const facts = db.prepare(`
    SELECT concept, value, unit, period, end_date, accepted_at
    FROM sec_facts
    WHERE cik = ?
    ORDER BY end_date DESC, accepted_at DESC
    LIMIT 50
  `).all(paddedCik) as Array<{
    concept: string;
    value: number;
    unit: string;
    period: string;
    end_date: string;
    accepted_at: string;
  }>;

  if (facts.length === 0) return "";

  const lines = [`[SEC Structured Financial Facts for CIK ${paddedCik}]`];
  for (const f of facts) {
    lines.push(`- ${f.concept}: ${f.value.toLocaleString()} ${f.unit} (${f.period || f.end_date}) [filed: ${f.accepted_at}]`);
  }
  return lines.join("\n");
}

/**
 * Format structured Form 4 insider transactions for a symbol into a clean narrative Evidence Card.
 */
export function formatInsiderTransactionsEvidenceCard(cik: string): string {
  const db = getDb();
  const paddedCik = padCik(cik);

  const txs = db.prepare(`
    SELECT insider_name, relationship, side, shares, price, period_of_report, is_10b5_1, transaction_code, accession
    FROM sec_insider_transactions
    WHERE cik = ? AND transaction_code IN ('P', 'S')
    ORDER BY period_of_report DESC, price DESC
    LIMIT 30
  `).all(paddedCik) as Array<{
    insider_name: string;
    relationship: string;
    side: string;
    shares: number;
    price: number;
    period_of_report: string;
    is_10b5_1: number;
    transaction_code: string;
    accession: string;
  }>;

  if (txs.length === 0) return "";

  const lines = [`[SEC Insider Transactions (Form 4) for CIK ${paddedCik}]`];
  for (const t of txs) {
    const codeLabel = t.transaction_code || "?";
    lines.push(
      `- ${t.period_of_report}: ${t.insider_name} (${t.relationship}) ${t.side.toUpperCase()} ${t.shares.toLocaleString()} shares @ $${t.price.toFixed(2)} [code: ${codeLabel}] (10b5-1: ${t.is_10b5_1 ? "Yes" : "No"}) [acc: ${t.accession}]`
    );
  }
  return lines.join("\n");
}

// SEC EDGAR full-filing body ingestion (10-K / 10-Q) → storeDocument → ingested_accessions de-dup.
//
// This is the "analytical body" layer that complements the existing 8-K "catalyst flag" layer
// (sec8k.ts). The 8-K path writes 6-line summaries; this path chunks and embeds the full risk
// sections, MD&A, and financial notes for RAG-grounded reasoning.
//
// KEY DESIGN DECISIONS (owner-resolved 2026-06-21):
//  • Incremental ingest only: 1 filing per scheduler tick on free tier (VECTOR_EMBED_BATCH_DELAY_MS > 5000).
//  • Recency window: 1 most-recent 10-K + 2 most-recent 10-Qs per symbol.
//  • De-dup: ingested_accessions (accession + doc_type) is the sole gate — never re-embed.
//  • All corpus writes use userId='local' (cleanMetadata → scope:'shared', app-funded).
//  • CIK map: reused from sec8k.ts loadCikMap (named export).
//  • Gate: only ingest bodies when VECTOR_EMBED_BATCH_DELAY_MS ≤ 5000 (paid-key signal).
//    Free-tier keeps the existing 8-K-summary path UNCHANGED and skips body ingest.
//  • Errors: surface via returned error field and audit log — never swallowed silently.

import {
  audit,
  getInternalSetting,
  hasIngestedAccession,
  insertIngestedAccession,
  runWithActiveVectorCommitProof,
  setInternalSetting,
  getDb,
  insertSecFiling
} from "../db";
import {
  assertOperationLeaseOwnership,
  OPERATION_LEASE_GROUPS,
  runWithOperationLease,
  throwIfOperationLeaseCancelled,
  type OperationLeaseAware,
  type OperationLeaseClaim
} from "../operation-lease";
import { politeFetchText, runRateLimited, secUserAgent, sleep } from "./http";
import { loadCikMap } from "./sec8k";
import { parseFilingHtml } from "./sec-parser";
import * as fs from "fs";
import * as path from "path";

function getLocalArtifactPath(cik: string, accession: string, sequence: number, documentName: string): string {
  const paddedCik = padCik(cik);
  const cleanDocName = documentName.replace(/[^a-zA-Z0-9._-]/g, "_");
  const dataDir = process.env.DATA_DIR ?? "data";
  return path.join(dataDir, "sec-artifacts", paddedCik, accession, `${sequence}-${cleanDocName}`);
}

export async function readLocalArtifact(cik: string, accession: string, sequence: number, documentName: string): Promise<string | null> {
  const filePath = getLocalArtifactPath(cik, accession, sequence, documentName);
  try {
    if (fs.existsSync(filePath)) {
      return await fs.promises.readFile(filePath, "utf8");
    }
  } catch (err) {
    console.warn(`[sec-filings] readLocalArtifact failed for ${filePath}:`, err);
  }
  return null;
}

export async function writeLocalArtifact(cik: string, accession: string, sequence: number, documentName: string, content: string): Promise<void> {
  const filePath = getLocalArtifactPath(cik, accession, sequence, documentName);
  try {
    await fs.promises.mkdir(path.dirname(filePath), { recursive: true });
    await fs.promises.writeFile(filePath, content, "utf8");
  } catch (err) {
    console.warn(`[sec-filings] writeLocalArtifact failed for ${filePath}:`, err);
  }
}

async function getCikForTicker(ticker: string): Promise<string> {
  try {
    const cikMap = await loadCikMap(Date.now());
    if (cikMap && typeof cikMap === "object") {
      for (const [cik, tick] of Object.entries(cikMap)) {
        if (tick && tick.toUpperCase() === ticker.toUpperCase()) {
          return cik;
        }
      }
    }
  } catch (err) {
    console.warn(`[sec-filings] getCikForTicker failed for ${ticker}:`, err);
  }
  return "0000000000";
}

const SEC_BASE = "https://www.sec.gov";
const EDGAR_DATA_BASE = "https://data.sec.gov";

// The TTL for the per-symbol "last attempted filing ingest" stamp.
// Weekly by default: 10-K/10-Q cadence is quarterly, so a free-tier corpus doesn't need
// re-checking sooner. Operators draining the ingest backlog (paid Voyage key) lower it via
// SEC_FILING_INGEST_TTL_HOURS (e.g. 24) so the capped per-run ingest runs daily instead.
const DEFAULT_FILING_INGEST_TTL_HOURS = 7 * 24;
function filingIngestTtlMs(): number {
  const hours = Number(process.env.SEC_FILING_INGEST_TTL_HOURS ?? DEFAULT_FILING_INGEST_TTL_HOURS);
  return (Number.isFinite(hours) && hours > 0 ? hours : DEFAULT_FILING_INGEST_TTL_HOURS) * 60 * 60_000;
}
const ATTEMPT_KEY = "webSource:sec10k:lastAttempt";

function isValidPersistedTimestamp(value: unknown): value is string {
  return typeof value === "string" && value.length > 0 && Number.isFinite(Date.parse(value));
}

// Polite delay between per-CIK submissions-JSON fetches (300 ms per EDGAR fair-use guidance).
const CIK_POLITE_DELAY_MS = 300;

// Threshold above which we treat VECTOR_EMBED_BATCH_DELAY_MS as free-tier (unpaid Voyage).
// Default is 21_000 ms; operators with a paid key set this to 0 (or very low).
const PAID_KEY_THRESHOLD_MS = 5_000;
// Free tier: 1 filing/run — at 21s per 8-chunk embed batch a single 10-K takes minutes, so a
// bigger cap would stall the scheduler tick for hours. Paid tier: a cap of 1 made the ~2,000
// filing backlog take decades (prod 2026-07-09: two filings ever ingested); 25/run at the paid
// embed pace is minutes of work, and RAG_INGEST_MAX_TEXTS_PER_DAY still bounds daily spend.
const DEFAULT_MAX_FILINGS_PER_RUN = 1;
const DEFAULT_PAID_MAX_FILINGS_PER_RUN = 200;

export interface FilingRef {
  accession: string;   // dashed form: NNNNNNNNNN-YY-NNNNNN
  docType: "10-K" | "10-Q";
  filedAt: string;           // ISO date (YYYY-MM-DD)
  acceptanceDateTime: string; // ISO datetime
  primaryDoc: string;         // filename inside the filing (e.g. "aapl-20231231.htm")
  url: string;                // full EDGAR archive URL to the primary document
}

export interface IngestResult {
  skipped: boolean;
  chunks: number;
  error?: string;
  /** The embed layer has no capacity left (daily text budget exhausted or vector store
   *  unconfigured) — every later filing in this run would meet the same fate, so bulk
   *  loops should stop instead of fetching/chunking documents that cannot embed. */
  budgetExhausted?: boolean;
}

export interface RefreshFilingBodiesResult {
  attempted: number;
  ingested: number;
  skipped: number;
  /** Filings within this run's cap left un-attempted because the embed budget ran out
   *  mid-run; they are NOT recorded as ingested and retry at the next tick. */
  deferredForBudget: number;
  errors: string[];
}

type SecFilingLeaseGuard = { assertOwnership: () => void; signal?: AbortSignal };

function assertSecFilingLease(leaseGuard?: SecFilingLeaseGuard): void {
  if (leaseGuard?.signal) throwIfOperationLeaseCancelled(leaseGuard.signal);
  leaseGuard?.assertOwnership();
}

// ── Submission JSON parsing ──────────────────────────────────────────────────

/** Normalise a CIK to a 10-digit zero-padded string (for EDGAR submission URL). */
export function padCik(cik: string | number): string {
  return String(cik).replace(/\D/g, "").padStart(10, "0");
}

/** Normalise accession number: strip dashes → re-add in standard NNNNNNNNNN-YY-NNNNNN form. */
export function normalizeAccession(raw: string): string {
  const stripped = raw.replace(/-/g, "");
  if (stripped.length !== 18) return raw; // pass-through if already unusual
  return `${stripped.slice(0, 10)}-${stripped.slice(10, 12)}-${stripped.slice(12)}`;
}

/** Convert dashed accession to the no-dash form used in EDGAR archive paths. */
export function accessionNoDashes(acc: string): string {
  return acc.replace(/-/g, "");
}

interface SubmissionsRecent {
  accessionNumber?: string[];
  form?: string[];
  filingDate?: string[];
  acceptanceDateTime?: string[];
  primaryDocument?: string[];
}

interface SubmissionsJson {
  cik?: string | number;
  filings?: {
    recent?: SubmissionsRecent;
    files?: Array<{ name: string; filingCount: number; filingStart: string; filingEnd: string }>;
  };
}

/** Helper to parse a flat block of filings (recent or a submissions shard). */
function parseFilingBlock(
  recent: SubmissionsRecent | undefined,
  cik: string,
  docTypes: Array<"10-K" | "10-Q">,
  limitPerType: number,
  countPerType: Record<string, number>
): FilingRef[] {
  if (!recent) return [];

  const accessions = recent.accessionNumber ?? [];
  const forms = recent.form ?? [];
  const dates = recent.filingDate ?? [];
  const acceptances = recent.acceptanceDateTime ?? [];
  const primaries = recent.primaryDocument ?? [];

  const out: FilingRef[] = [];
  for (let i = 0; i < accessions.length; i++) {
    const form = forms[i] as "10-K" | "10-Q" | undefined;
    if (!form || !docTypes.includes(form)) continue;
    if ((countPerType[form] ?? 0) >= limitPerType) continue;

    const acc = normalizeAccession(accessions[i] ?? "");
    if (!acc) continue;

    const filedAt = dates[i] ?? new Date().toISOString().slice(0, 10);
    const acceptanceDateTime = acceptances[i] ?? filedAt;
    const primaryDoc = primaries[i] ?? "";
    const paddedCik = padCik(cik);
    const noSlashAcc = accessionNoDashes(acc);
    const url = primaryDoc
      ? `${SEC_BASE}/Archives/edgar/data/${paddedCik}/${noSlashAcc}/${primaryDoc}`
      : `${SEC_BASE}/cgi-bin/browse-edgar?action=getcompany&CIK=${paddedCik}&type=${form}&dateb=&owner=include&count=40`;

    out.push({ accession: acc, docType: form, filedAt, acceptanceDateTime, primaryDoc, url });
    countPerType[form] = (countPerType[form] ?? 0) + 1;
  }

  return out;
}

/**
 * Parse a EDGAR submissions JSON blob into FilingRef entries, filtering to the requested
 * docTypes and returning at most `limit` per docType (newest-first).
 */
export function parseRecentFilings(
  json: SubmissionsJson,
  cik: string,
  docTypes: Array<"10-K" | "10-Q">,
  limitPerType: number
): FilingRef[] {
  const countPerType: Record<string, number> = {};
  for (const dt of docTypes) countPerType[dt] = 0;
  return parseFilingBlock(json?.filings?.recent, cik, docTypes, limitPerType, countPerType);
}

// ── Network helpers ──────────────────────────────────────────────────────────

/**
 * Fetch the SEC EDGAR submissions JSON for a single CIK, including historical shards if needed.
 * Returns undefined (does NOT throw) if the network call fails — let callers decide.
 */
export async function fetchRecentFilings(
  cik: string,
  docTypes: Array<"10-K" | "10-Q"> = ["10-K", "10-Q"],
  limitPerType = 2
): Promise<FilingRef[]> {
  const padded = padCik(cik);
  const url = `${EDGAR_DATA_BASE}/submissions/CIK${padded}.json`;
  let raw: string;
  try {
    raw = await politeFetchText(url, {
      headers: { "user-agent": secUserAgent(), accept: "application/json" },
      timeoutMs: 15_000
    });
  } catch (err) {
    console.warn(`[sec-filings] failed to fetch submissions for CIK ${padded}:`, err);
    return [];
  }

  const json = JSON.parse(raw) as SubmissionsJson;
  const countPerType: Record<string, number> = {};
  for (const dt of docTypes) countPerType[dt] = 0;

  const out = parseFilingBlock(json?.filings?.recent, cik, docTypes, limitPerType, countPerType);

  // Check if we need more filings and have shards available
  const needsMore = docTypes.some(dt => (countPerType[dt] ?? 0) < limitPerType);
  const files = json?.filings?.files;
  if (needsMore && Array.isArray(files) && files.length > 0) {
    // Sort shards in reverse chronological order (newest date first)
    const sortedFiles = [...files].sort((a, b) => b.filingEnd.localeCompare(a.filingEnd));
    for (const file of sortedFiles) {
      const stillNeeds = docTypes.some(dt => (countPerType[dt] ?? 0) < limitPerType);
      if (!stillNeeds) break;

      try {
        const shardUrl = `${EDGAR_DATA_BASE}/submissions/${file.name}`;
        const shardRaw = await politeFetchText(shardUrl, {
          headers: { "user-agent": secUserAgent(), accept: "application/json" },
          timeoutMs: 15_000
        });
        const shardJson = JSON.parse(shardRaw) as SubmissionsRecent;
        const shardRefs = parseFilingBlock(shardJson, cik, docTypes, limitPerType, countPerType);
        out.push(...shardRefs);
      } catch (err) {
        console.warn(`[sec-filings] failed to fetch/parse shard ${file.name}:`, err);
      }
    }
  }

  return out;
}

/**
 * Fetch the primary HTM document for a single filing from EDGAR.
 * Uses a raised timeout (30s) because 10-K bodies can be 2–10 MB.
 */
export async function fetchFilingHtml(url: string): Promise<string> {
  return politeFetchText(url, {
    headers: { "user-agent": secUserAgent(), accept: "text/html,application/xhtml+xml" },
    timeoutMs: 30_000
  });
}

export interface FilingDirectoryItem {
  name: string;
  type?: string;
  size?: number;
}

/**
 * Fetch and parse index.json for a specific filing accession to discover all documents/exhibits.
 */
export async function fetchFilingDirectory(cik: string, accession: string): Promise<FilingDirectoryItem[]> {
  const paddedCik = padCik(cik);
  const noSlashAcc = accessionNoDashes(accession);
  const url = `${SEC_BASE}/Archives/edgar/data/${paddedCik}/${noSlashAcc}/index.json`;

  try {
    const raw = await politeFetchText(url, {
      headers: { "user-agent": secUserAgent(), accept: "application/json" },
      timeoutMs: 15_000
    });
    const parsed = JSON.parse(raw) as {
      directory?: { item?: Array<{ name?: string; type?: string; size?: string | number }> };
    };
    const items = parsed?.directory?.item;
    if (!Array.isArray(items)) return [];

    return items
      .map((item) => ({
        name: item.name ?? "",
        type: item.type,
        size: item.size ? Number(item.size) : undefined
      }))
      .filter((item) => item.name !== "");
  } catch (err) {
    console.warn(`[sec-filings] fetchFilingDirectory failed for CIK ${paddedCik} accession ${accession}:`, err);
    return [];
  }
}


// ── HTML → plain text ────────────────────────────────────────────────────────

/**
 * Strip an EDGAR HTM filing down to plain text, preserving structural whitespace
 * so the chunker's blockDocument() receives well-separated paragraphs and headings.
 *
 * Pipeline:
 *  1. Strip <script> and <style> blocks entirely.
 *  2. Inject newlines around block elements so headings/paragraphs split cleanly.
 *  3. Decode XML/HTML entities.
 *  4. Strip remaining tags.
 *  5. Collapse whitespace runs.
 */
export function extractFilingText(html: string): string {
  // 1, 2, 4. Unified tag extraction in a single pass to minimize massive intermediate string allocations
  let text = html.replace(
    /(<script[\s\S]*?<\/script>)|(<style[\s\S]*?<\/style>)|(<\/?(?:div|p|h[1-6]|li|tr|td|th|table|thead|tbody|tfoot|blockquote|article|section|header|footer|main|aside|figure|figcaption|pre|hr|br)[^>]*>)|(<[^>]+>)/gi,
    (match, script, style, blockTag) => {
      if (script || style) return " ";
      if (blockTag) return "\n";
      return " ";
    }
  );

  // 3. Decode XML entities (mirrors sec8k.ts decodeXmlEntities)
  text = text
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&nbsp;/g, " ")
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)));

  // 5. Collapse whitespace: replace runs of spaces/tabs with a single space,
  //    preserve structural newlines (collapse 3+ newlines to 2).
  text = text
    .replace(/[ \t]+/g, " ")
    .replace(/\n[ \t]+/g, "\n")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  return text;
}

// ── Core ingest ──────────────────────────────────────────────────────────────

/**
 * Ingest a single filing body into the vector store.
 * - Checks ingested_accessions de-dup table first (skips if already indexed).
 * - Fetches + strips the HTM body.
 * - Calls storeDocument (which routes through chunkDocument → storeContexts).
 * - On success, records the accession in ingested_accessions.
 * - On failure, returns the error string rather than swallowing it.
 * - Always writes with userId='local' so cleanMetadata → scope:'shared'.
 */
export async function ingestFiling(
  ticker: string,
  filingRef: FilingRef,
  userId: string = "local",
  leaseGuard?: SecFilingLeaseGuard
): Promise<IngestResult> {
  assertSecFilingLease(leaseGuard);
  // Parser-revision note (deliberate, low-risk choice — PR #1669): this accession
  // ledger is intentionally NOT versioned by parser revision. Filings ingested under
  // the v1 parser keep their v1 (flattened) chunks; only filings not yet in the ledger
  // get the v2 (Cheerio, section-aware) treatment tagged `sec-edgar-filing-v2` below.
  // Re-embedding the existing corpus was considered and rejected: the embed-budget and
  // Pinecone-write cost of a full backfill outweighs the retrieval gain on old filings.
  // If a corpus-wide re-parse is ever wanted, do it as an explicit one-time invalidation
  // (clear ingested_accessions rows for the affected docTypes), not by weakening this
  // sole-gate skip.
  if (hasIngestedAccession(filingRef.accession, filingRef.docType)) {
    return { skipped: true, chunks: 0 };
  }

  // Budget pre-flight BEFORE the EDGAR fetch: a filing body is 2–10 MB and chunking it is
  // pure waste when the daily embed budget is already spent — storeDocument would only
  // budget-skip it (and emit a budget warning per filing; prod 2026-07-10 saw a 20-event
  // burst from exactly this). Deferring here costs nothing: the accession stays
  // un-recorded and retries at the next tick.
  const { hasIngestTextBudget } = await import("../vector-db");
  assertSecFilingLease(leaseGuard);
  if (!hasIngestTextBudget(userId)) {
    return { skipped: true, chunks: 0, budgetExhausted: true };
  }

  let html: string | null = null;
  const cik = await getCikForTicker(ticker);
  try {
    assertSecFilingLease(leaseGuard);
    html = await readLocalArtifact(cik, filingRef.accession, 1, filingRef.primaryDoc || "main.html");
    if (html === null) {
      html = await fetchFilingHtml(filingRef.url);
      await writeLocalArtifact(cik, filingRef.accession, 1, filingRef.primaryDoc || "main.html", html);
    }
    assertSecFilingLease(leaseGuard);
  } catch (err) {
    // A stale owner must never turn lease loss into an ordinary provider warning and continue
    // into artifact/vector writes. Re-assert first; normal network errors still return below.
    assertSecFilingLease(leaseGuard);
    const error = err instanceof Error ? err.message : String(err);
    return { skipped: false, chunks: 0, error: `fetch failed: ${error}` };
  }

  // Pass the form type so Item-title canonicalization is form-aware (the 10-K
  // Item-1 -> "Business" mapping must not be applied to 10-Q filings).
  const { text, sections } = parseFilingHtml(html, { formType: filingRef.docType });
  if (text.length < 100) {
    return { skipped: false, chunks: 0, error: "extracted text too short (possible XBRL viewer redirect)" };
  }

  // Insert into sec_artifacts
  try {
    assertSecFilingLease(leaseGuard);
    const { createHash } = await import("crypto");
    assertSecFilingLease(leaseGuard);
    const sha256 = createHash("sha256").update(html).digest("hex");
    const byteCount = Buffer.byteLength(html, "utf8");
    const { insertSecArtifact } = await import("../db");
    assertSecFilingLease(leaseGuard);
    insertSecArtifact({
      accession: filingRef.accession,
      sequence: 1,
      documentName: filingRef.primaryDoc || "main.html",
      sha256,
      type: "html",
      byteCount,
      rawUri: filingRef.url,
      parserVersion: "v2"
    });
    assertSecFilingLease(leaseGuard);
  } catch (err) {
    // Artifact persistence is otherwise best-effort, but ownership loss is terminal.
    assertSecFilingLease(leaseGuard);
    console.warn(`[sec-filings] insertSecArtifact failed for ${filingRef.accession} (non-fatal):`, err instanceof Error ? err.message : String(err));
  }

  assertSecFilingLease(leaseGuard);
  const { storeDocument } = await import("../vector-db");
  assertSecFilingLease(leaseGuard);
  const document = {
      text,
      sections,
      doc_id: `${ticker}:${filingRef.accession}:${filingRef.docType}`,
      ticker,
      title: `${ticker} ${filingRef.docType} (${filingRef.filedAt})`,
      doc_type: filingRef.docType.toLowerCase(),
      published_at: filingRef.filedAt,
      acceptance_datetime: filingRef.acceptanceDateTime,
      source: "sec-edgar",
      url: filingRef.url
    };
  const result = await storeDocument(document, userId, {
    parserRevision: "sec-edgar-filing-v2",
    ...(leaseGuard ? { leaseGuard } : {})
  });
  assertSecFilingLease(leaseGuard);

  if (result.error) {
    return { skipped: false, chunks: result.indexed, error: result.error };
  }

  // storeDocument can come back with indexed: 0 (or a truncated count with budgetSkipped > 0)
  // and NO error — daily chunk budget (RAG_INGEST_MAX_TEXTS_PER_DAY) crossed mid-document or
  // vector keys unconfigured. Recording the accession then would mark the filing "ingested"
  // forever with zero/partial retrievable chunks, inflate the ingested-count receipts, and
  // suppress the corpus-coverage receipt while retrieval finds nothing. Budget exhaustion
  // mid-run is an EXPECTED state during the backlog drain — leave the filing un-recorded so
  // a later run retries it (content-hash dedup makes the re-embed cheap), and flag
  // budgetExhausted so the bulk loop stops instead of grinding through doomed filings.
  // budgetExhausted only on genuine capacity signals — the explicit budget counters or the
  // store's keys-unconfigured skip. A single pathological document that chunks to nothing
  // must not stop the whole run.
  const outOfCapacity =
    (result.budgetSkipped ?? 0) > 0 || (result.writeUnitBudgetSkipped ?? 0) > 0 || result.unconfigured === true;
  const reusedCommitted =
    result.reusedCommitted === true && result.documentComplete === true && result.attempted > 0;
  if ((result.indexed <= 0 && !reusedCommitted) || outOfCapacity) {
    return { skipped: true, chunks: result.indexed, ...(outOfCapacity ? { budgetExhausted: true } : {}) };
  }
  if (result.documentComplete !== true || (!reusedCommitted && result.indexed !== result.attempted)) {
    // A content-only dedup receipt or partial Pinecone write cannot complete an accession. Every
    // occurrence must have its own queryable vector and the required local receipt transaction.
    return { skipped: true, chunks: result.indexed };
  }
  if (!result.managedCommitProof) {
    return { skipped: true, chunks: result.indexed, error: "document-commit-proof-missing" };
  }

  try {
    const { chunkDocument } = await import("../rag/chunk");
    const { insertDocumentChunkFts } = await import("../db");
    runWithActiveVectorCommitProof(result.managedCommitProof, () => {
      // Mirror the committed chunks into the local FTS table so hybrid/lexical retrieval covers the
      // PRODUCTION filing-body path. Must run inside the transaction so FTS failures rollback
      // and allow the filing ingestion to be retried on subsequent ticks.
      for (const chunk of chunkDocument(document, {})) {
        insertDocumentChunkFts(
          chunk.content_hash,
          chunk.ticker[0] ?? ticker,
          "sec-edgar",
          filingRef.accession,
          chunk.text
        );
      }
      insertIngestedAccession(filingRef.accession, filingRef.docType, ticker, result.attempted);
      audit("sec_filing_ingest", {
        ticker,
        accession: filingRef.accession,
        docType: filingRef.docType,
        filedAt: filingRef.filedAt,
        chunks: result.attempted,
        attempted: result.attempted
      });
    });
  } catch (err) {
    return { skipped: true, chunks: result.indexed, error: err instanceof Error ? err.message : "document-commit-proof-lost" };
  }

  return { skipped: false, chunks: result.attempted };
}

// ── Scheduler-facing refresh ─────────────────────────────────────────────────

/** Whether the free-tier cap applies (VECTOR_EMBED_BATCH_DELAY_MS > 5000 = free/default). */
function isFreeTier(): boolean {
  const delay = Number(process.env.VECTOR_EMBED_BATCH_DELAY_MS ?? 21_000);
  return !Number.isFinite(delay) || delay > PAID_KEY_THRESHOLD_MS;
}

function maxFilingsPerRunFromEnv(): number {
  const parsed = Number(process.env.SEC_FILING_RAG_MAX_PER_RUN);
  if (Number.isFinite(parsed) && parsed > 0) return Math.floor(parsed);
  return isFreeTier() ? DEFAULT_MAX_FILINGS_PER_RUN : DEFAULT_PAID_MAX_FILINGS_PER_RUN;
}

/** Whether we're due for a filing ingest check (TTL per SEC_FILING_INGEST_TTL_HOURS, default weekly). */
export function isFilingIngestDue(now: number = Date.now()): boolean {
  const last = getInternalSetting<unknown>(ATTEMPT_KEY);
  if (!isValidPersistedTimestamp(last)) return true;
  return now - Date.parse(last) >= filingIngestTtlMs();
}

/**
 * Refresh 10-K/10-Q body ingestion for the given symbol list. Symbols are processed in the
 * order given — callers put the highest-demand names (held positions, watchlists) FIRST so a
 * capped run ingests the filings decisions actually retrieve against.
 *
 * Free-tier (VECTOR_EMBED_BATCH_DELAY_MS > 5000): processes at most 1 filing total per
 * invocation to avoid multi-hour scheduler stalls. The function is still called every tick but
 * the TTL gate (isFilingIngestDue) means it's a no-op until the TTL has passed.
 *
 * Paid-tier (VECTOR_EMBED_BATCH_DELAY_MS <= 5000): processes up to SEC_FILING_RAG_MAX_PER_RUN
 * filings per invocation (default 25).
 *
 * An EXPLICIT `maxPerRun` (the admin backfill route's `limit`) is an operator decision and wins
 * outright — including on free-tier env, where the caller is accepting the slow embed pacing.
 * `opts.force` skips the TTL gate (again: the admin backfill route, which used to silently
 * no-op for up to a week after any scheduler attempt).
 *
 * Provider/data errors are captured in the returned result and the audit log. Lease loss is
 * intentionally re-thrown so a stale scheduler owner cannot continue into the next EDGAR call.
 */
export async function refreshFilingBodies(
  symbols: string[],
  now: number = Date.now(),
  maxPerRun?: number,
  opts?: { force?: boolean; operationLeaseClaim?: OperationLeaseClaim }
): Promise<OperationLeaseAware<RefreshFilingBodiesResult>> {
  const empty: RefreshFilingBodiesResult = {
    attempted: 0,
    ingested: 0,
    skipped: 0,
    deferredForBudget: 0,
    errors: []
  };
  if (symbols.length === 0) return empty;
  if (!opts?.force && !isFilingIngestDue(now)) return empty;

  const guarded = await runWithOperationLease(
    {
      group: OPERATION_LEASE_GROUPS.RAG_REINDEX,
      operation: opts?.force ? "reindex-10k" : "scheduled-filing-ingest",
      claim: opts?.operationLeaseClaim
    },
    async (claim, signal) => refreshFilingBodiesUnlocked(symbols, now, maxPerRun, opts, claim, signal)
  );
  if (!guarded.acquired) return { ...empty, operationLease: guarded.busy };
  return guarded.value;
}

async function refreshFilingBodiesUnlocked(
  symbols: string[],
  now: number,
  maxPerRun: number | undefined,
  opts: { force?: boolean } | undefined,
  operationLeaseClaim: OperationLeaseClaim,
  operationLeaseSignal: AbortSignal
): Promise<RefreshFilingBodiesResult> {
  const result: RefreshFilingBodiesResult = { attempted: 0, ingested: 0, skipped: 0, deferredForBudget: 0, errors: [] };

  // Recheck after durable acquisition so a delayed scheduler process cannot repeat work after the
  // prior owner completed and advanced the cadence stamp.
  if (!opts?.force && !isFilingIngestDue(now)) return result;
  assertOperationLeaseOwnership(operationLeaseClaim);
  const leaseGuard = {
    signal: operationLeaseSignal,
    assertOwnership: () => {
      throwIfOperationLeaseCancelled(operationLeaseSignal);
      assertOperationLeaseOwnership(operationLeaseClaim);
    }
  };

  // Mark attempt so the next tick won't immediately retry. Forced runs (admin backfill)
  // deliberately do NOT touch the stamp — a targeted backfill must not push the scheduled
  // corpus-wide demand-first ingest back by a full TTL window.
  if (!opts?.force) setInternalSetting(ATTEMPT_KEY, new Date(now).toISOString());

  const freeTier = isFreeTier();
  const cap =
    typeof maxPerRun === "number" && Number.isFinite(maxPerRun) && maxPerRun > 0
      ? Math.floor(maxPerRun)
      : freeTier
        ? DEFAULT_MAX_FILINGS_PER_RUN
        : maxFilingsPerRunFromEnv();

  let cikMap: Record<string, string>;
  try {
    throwIfOperationLeaseCancelled(operationLeaseSignal);
    cikMap = await loadCikMap(now);
  } catch (err) {
    throwIfOperationLeaseCancelled(operationLeaseSignal);
    const msg = err instanceof Error ? err.message : String(err);
    result.errors.push(`loadCikMap failed: ${msg}`);
    return result;
  }

  // Build a reverse map: ticker → CIK
  const tickerToCik: Record<string, string> = {};
  for (const [cik, ticker] of Object.entries(cikMap)) {
    tickerToCik[ticker] = cik;
  }

  // Collect (ticker, FilingRef) pairs that need ingesting.
  const pending: Array<{ ticker: string; ref: FilingRef }> = [];

  // 1. Gather previously stashed "discovered" filings from SQLite first
  try {
    const db = getDb();
    const localPendingRows = db.prepare(`
      SELECT accession, cik, ticker, form, filed_at, accepted_at
      FROM sec_filings
      WHERE status = 'discovered' AND ticker IN (${symbols.map(() => "?").join(",")})
    `).all(...symbols) as Array<{ accession: string; cik: string; ticker: string; form: string; filed_at: string; accepted_at: string }>;

    for (const row of localPendingRows) {
      if (!hasIngestedAccession(row.accession, row.form)) {
        const artRow = db.prepare("SELECT document_name, raw_uri FROM sec_artifacts WHERE accession = ? LIMIT 1").get(row.accession) as { document_name: string; raw_uri: string } | undefined;
        const primaryDoc = artRow?.document_name || "";
        const noSlashAcc = accessionNoDashes(row.accession);
        const url = artRow?.raw_uri || (primaryDoc
          ? `${SEC_BASE}/Archives/edgar/data/${padCik(row.cik)}/${noSlashAcc}/${primaryDoc}`
          : `${SEC_BASE}/cgi-bin/browse-edgar?action=getcompany&CIK=${padCik(row.cik)}&type=${row.form}&dateb=&owner=include&count=40`);

        pending.push({
          ticker: row.ticker,
          ref: {
            accession: row.accession,
            docType: row.form as "10-K" | "10-Q",
            filedAt: row.filed_at,
            acceptanceDateTime: row.accepted_at,
            primaryDoc,
            url
          }
        });
      }
    }
  } catch (err) {
    console.warn("[sec-filings] failed to query stashed discovered filings:", err);
  }

  // 2. Dynamic online discovery: only scan tickers if we haven't hit the cap yet
  let onlineFetches = 0;
  const MAX_ONLINE_DISCOVERY_PER_RUN = 20;

  for (const symbol of symbols) {
    if (pending.length >= cap || onlineFetches >= MAX_ONLINE_DISCOVERY_PER_RUN) break;

    // Ingest fundamentals card first (uses local cache or provider API cascade).
    try {
      const fundResult = await ingestFundamentalsCard(symbol, "local", leaseGuard);
      if (fundResult.error) {
        result.errors.push(`ingestFundamentalsCard(${symbol}): ${fundResult.error}`);
      }
    } catch (err) {
      assertSecFilingLease(leaseGuard);
      const msg = err instanceof Error ? err.message : String(err);
      result.errors.push(`ingestFundamentalsCard(${symbol}) threw: ${msg}`);
    }

    const cik = tickerToCik[symbol];
    if (!cik) continue;

    try {
      assertSecFilingLease(leaseGuard);
      onlineFetches++;
      const filings = await fetchRecentFilings(cik, ["10-K", "10-Q"], 10);
      assertSecFilingLease(leaseGuard);

      const db = getDb();
      for (const ref of filings) {
        try {
          const existing = db.prepare("SELECT accession FROM sec_filings WHERE accession = ?").get(ref.accession);
          if (!existing) {
            insertSecFiling({
              accession: ref.accession,
              cik,
              ticker: symbol,
              form: ref.docType,
              filedAt: ref.filedAt,
              acceptedAt: ref.acceptanceDateTime,
              status: "discovered",
              chunkCount: 0
            });
          }
        } catch (err) {
          console.warn(`[sec-filings] insertSecFiling failed for ${ref.accession} (non-fatal):`, err instanceof Error ? err.message : String(err));
        }

        if (!hasIngestedAccession(ref.accession, ref.docType)) {
          if (!pending.some((p) => p.ref.accession === ref.accession)) {
            pending.push({ ticker: symbol, ref });
          }
        }
      }
    } catch (err) {
      assertSecFilingLease(leaseGuard);
      const msg = err instanceof Error ? err.message : String(err);
      result.errors.push(`fetchRecentFilings(${symbol}): ${msg}`);
    }

    // Polite delay between CIK fetches
    await sleep(CIK_POLITE_DELAY_MS);
  }

  // 3. Sort pending breadth-first globally so newest annual reports are ingested first
  const sortedPending = sortBreadthFirst(pending);
  pending.splice(0, pending.length, ...sortedPending);

  // Process pending filings sequentially (EDGAR + Voyage both require polite pacing).
  let processed = 0;
  for (const { ticker, ref } of pending) {
    if (result.attempted >= cap) break;
    result.attempted++;
    processed++;
    try {
      assertOperationLeaseOwnership(operationLeaseClaim);
      const ingestResult = await ingestFiling(ticker, ref, "local", leaseGuard);
      throwIfOperationLeaseCancelled(operationLeaseSignal);
      if (ingestResult.budgetExhausted) {
        // The embed layer is out of capacity for the day (or unconfigured) — every later
        // filing meets the same fate, so stop instead of fetching/chunking doomed documents.
        // Everything not embedded stays un-recorded and retries at the next tick. The count
        // is cap-aware: only filings this run WOULD have attempted, excluding the breaker
        // (which is already counted in attempted/skipped).
        result.skipped++;
        result.deferredForBudget = Math.max(0, Math.min(pending.length, cap) - processed);
        break;
      }
      if (ingestResult.skipped) {
        result.skipped++;
      } else if (ingestResult.error) {
        result.errors.push(`ingestFiling(${ticker} ${ref.accession}): ${ingestResult.error}`);
      } else {
        result.ingested++;
      }
      // Polite delay between filings (separate from VECTOR_EMBED_BATCH_DELAY_MS which governs
      // chunk-level Voyage batching). Keep at least 300ms between EDGAR fetches.
      if (result.attempted < cap) await sleep(CIK_POLITE_DELAY_MS);
    } catch (err) {
      throwIfOperationLeaseCancelled(operationLeaseSignal);
      const msg = err instanceof Error ? err.message : String(err);
      result.errors.push(`ingestFiling(${ticker} ${ref.accession}) threw: ${msg}`);
    }
  }

  audit("sec_filing_refresh", { symbols: symbols.length, ...result, freeTier, forced: Boolean(opts?.force) });
  return result;
}

// ── Blended Fundamentals Profile Card Ingest ──────────────────────────────────

function fmt(val: any, suffix = ""): string {
  if (val == null || (typeof val === "number" && !Number.isFinite(val))) return "N/A";
  if (typeof val === "number") {
    return `${val.toLocaleString(undefined, { maximumFractionDigits: 2 })}${suffix}`;
  }
  return `${val}${suffix}`;
}

export function buildFundamentalsContext(symbol: string, data: any): string {
  const name = data.companyName ? ` (${data.companyName})` : "";
  const capStr = data.marketCap != null && Number.isFinite(data.marketCap)
    ? `$${(data.marketCap / 1e9).toLocaleString(undefined, { maximumFractionDigits: 2 })}B`
    : "N/A";

  return [
    `Blended Corporate Fundamentals and Profile for ${symbol}${name}.`,
    `Sector: ${fmt(data.sector)}. Industry: ${fmt(data.industry)}.`,
    `Market Cap: ${capStr}. Current Share Price: ${fmt(data.price, " USD")}.`,
    `P/E Ratio: ${fmt(data.peRatio)}. P/B Ratio: ${fmt(data.pbRatio)}. EPS (TTM): ${fmt(data.eps, " USD")}.`,
    `FCF Yield: ${fmt(data.fcfYield, "%")}. Debt-to-Equity: ${fmt(data.debtToEquity)}.`,
    `ROE: ${fmt(data.returnOnEquity, "%")}. ROA: ${fmt(data.returnOnAssets, "%")}.`,
    `Gross Margin: ${fmt(data.grossProfitMargin, "%")}. Free Cash Flow Yield: ${fmt(data.freeCashFlowYield, "%")}.`,
    `Revenue Growth (YoY): ${fmt(data.revenueGrowth, "%")}. EPS Growth (YoY): ${fmt(data.epsGrowth, "%")}.`,
    `Short Interest (% of Float): ${fmt(data.shortPercentOfFloat, "%")}.`,
    `Analyst Consensus Rating: ${fmt(data.analystRating)} (Consensus Score: ${fmt(data.analystScore)}/100).`,
    `Days to Next Earnings: ${fmt(data.daysToEarnings)}. Institutional Ownership: ${fmt(data.institutionOwnershipPct, "%")}.`,
    `Dividend Yield: ${fmt(data.dividendYield, "%")}. Beta: ${fmt(data.beta)}.`,
    `As of: ${data.asOf || new Date().toISOString().slice(0, 10)}.`,
    `Source: blended-fundamentals-enrichment.`,
    `Use this for corporate profile, valuation ranges, capital structure, and growth trends.`,
  ].join("\n");
}

export async function ingestFundamentalsCard(
  symbol: string,
  userId: string = "local",
  leaseGuard?: SecFilingLeaseGuard
): Promise<{ skipped: boolean; error?: string }> {
  try {
    assertSecFilingLease(leaseGuard);
    const { getEnrichmentProvider } = await import("../data-providers");
    const { storeContexts } = await import("../vector-db");

    const provider = getEnrichmentProvider(userId);
    const enriched = await provider.enrich([symbol]);
    assertSecFilingLease(leaseGuard);
    const data = enriched[symbol];
    if (!data) {
      return { skipped: true, error: `No enrichment data found for symbol: ${symbol}` };
    }

    // Skip empty fundamentals cards: if every field rendered by
    // buildFundamentalsContext is null/undefined, embedding an all-"N/A" card
    // wastes budget and pollutes RAG with empty factual content (e.g. when the
    // enrichment cascade returned an empty object for an unsupported ticker or
    // all providers were skipped by quota/circuit breaker). Check every field the
    // card renders so a provider that returns only debtToEquity (for example via
    // SEC_XBRL_ENRICHMENT_ENABLED=on) is not incorrectly dropped.
    const hasRealField =
      data.companyName != null ||
      data.sector != null ||
      data.industry != null ||
      // marketCap is on MarketQuote (types.ts), not SymbolEnrichment; the card renders it
      // via buildFundamentalsContext which takes `data: any`, so check with a safe cast.
      (data as any).marketCap != null ||
      data.price != null ||
      data.peRatio != null ||
      data.pbRatio != null ||
      data.eps != null ||
      data.fcfYield != null ||
      data.debtToEquity != null ||
      data.returnOnEquity != null ||
      data.returnOnAssets != null ||
      data.grossProfitMargin != null ||
      data.freeCashFlowYield != null ||
      data.revenueGrowth != null ||
      data.epsGrowth != null ||
      data.shortPercentOfFloat != null ||
      data.analystRating != null ||
      data.analystScore != null ||
      data.daysToEarnings != null ||
      data.institutionOwnershipPct != null ||
      data.dividendYield != null ||
      data.beta != null;
    if (!hasRealField) {
      return { skipped: true };
    }
    const text = buildFundamentalsContext(symbol, data);
    const publishedAt = data.asOf || new Date().toISOString().slice(0, 10);
    const acceptanceDatetime = new Date().toISOString();

    const result = await storeContexts(
      [
        {
          text,
          metadata: {
            symbol,
            source: "blended-fundamentals",
            timestamp: publishedAt,
            accession: `${symbol}:fundamentals:${publishedAt}`,
            acceptance_datetime: acceptanceDatetime,
            section: "Fundamentals",
            doc_type: "fundamentals",
            ticker: [symbol]
          }
        }
      ],
      userId,
      {
        dedupKeyPrefix: "fundamentals",
        ...(leaseGuard ? { leaseGuard } : {})
      }
    );
    assertSecFilingLease(leaseGuard);

    if (result.error) {
      return { skipped: false, error: result.error };
    }

    const skipped = result.indexed === 0;
    audit("fundamentals_card_ingest", {
      symbol,
      asOf: publishedAt,
      indexed: result.indexed,
      skipped
    });

    return { skipped };
  } catch (err) {
    // Do not convert cooperative cancellation/ownership loss into a normal fundamentals error.
    // A healthy lease passes this check and preserves the existing error-return contract.
    assertSecFilingLease(leaseGuard);
    const error = err instanceof Error ? err.message : String(err);
    return { skipped: false, error };
  }
}

function sortBreadthFirst(
  filings: Array<{ ticker: string; ref: FilingRef }>
): Array<{ ticker: string; ref: FilingRef }> {
  // Group by ticker
  const byTicker: Record<string, { k: FilingRef[]; q: FilingRef[] }> = {};
  for (const item of filings) {
    if (!byTicker[item.ticker]) {
      byTicker[item.ticker] = { k: [], q: [] };
    }
    if (item.ref.docType === "10-K") {
      byTicker[item.ticker].k.push(item.ref);
    } else {
      byTicker[item.ticker].q.push(item.ref);
    }
  }

  // Sort each ticker's filings descending by date
  for (const ticker of Object.keys(byTicker)) {
    byTicker[ticker].k.sort((a, b) => b.filedAt.localeCompare(a.filedAt));
    byTicker[ticker].q.sort((a, b) => b.filedAt.localeCompare(a.filedAt));
  }

  const priorityLevels: Array<Array<{ ticker: string; ref: FilingRef }>> = Array.from({ length: 6 }, () => []);

  for (const [ticker, lists] of Object.entries(byTicker)) {
    // Level 0: newest 10-K
    if (lists.k.length > 0) {
      priorityLevels[0].push({ ticker, ref: lists.k[0] });
    }
    // Level 1: newest 10-Q
    if (lists.q.length > 0) {
      priorityLevels[1].push({ ticker, ref: lists.q[0] });
    }
    // Level 2: second newest 10-Q
    if (lists.q.length > 1) {
      priorityLevels[2].push({ ticker, ref: lists.q[1] });
    }
    // Level 3: third newest 10-Q
    if (lists.q.length > 2) {
      priorityLevels[3].push({ ticker, ref: lists.q[2] });
    }
    // Level 4: remaining 10-Ks
    for (let i = 1; i < lists.k.length; i++) {
      priorityLevels[4].push({ ticker, ref: lists.k[i] });
    }
    // Level 5: remaining 10-Qs
    for (let i = 3; i < lists.q.length; i++) {
      priorityLevels[5].push({ ticker, ref: lists.q[i] });
    }
  }

  // For each level, sort by filedAt DESC so the newest overall are first
  for (const level of priorityLevels) {
    level.sort((a, b) => b.ref.filedAt.localeCompare(a.ref.filedAt));
  }

  // Flatten
  return priorityLevels.flat();
}

import * as cheerio from "cheerio";

export interface ParsedBlock {
  type: "heading" | "paragraph" | "table";
  text: string;
  itemCode?: string;
  itemTitle?: string;
}

export interface ParsedFiling {
  text: string;
  sections: Array<{
    itemCode: string;
    itemTitle: string;
    text: string;
  }>;
}

const BLOCK_TAGS = new Set([
  "p",
  "div",
  "h1",
  "h2",
  "h3",
  "h4",
  "h5",
  "h6",
  "li",
  "blockquote",
  "pre",
  "section",
  "article",
  "header",
  "footer",
  "main"
]);

/** Inline/formatting wrappers that EDGAR sometimes uses for headings. */
const HEADING_WRAPPER_TAGS = new Set([
  "center", "font", "span", "b", "strong", "i", "em", "u", "a"
]);

/**
 * Estimates token counts using a calibrated character-level ratio.
 * For English prose, ~4.5 characters per token.
 */
export function estimateProseTokens(text: string): number {
  return Math.ceil(text.length / 4.5);
}

/**
 * Estimates token counts for Markdown tables, ~3.5 characters per token
 * (due to pipe formatting and whitespace padding).
 */
export function estimateTableTokens(text: string): number {
  return Math.ceil(text.length / 3.5);
}

function hasBlockChildren($: any, node: any): boolean {
  if (!node.children) return false;
  for (const child of node.children) {
    if (child.type === "tag") {
      const childName = child.name.toLowerCase();
      if (BLOCK_TAGS.has(childName) || childName === "table") {
        return true;
      }
      if (hasBlockChildren($, child)) {
        return true;
      }
    }
  }
  return false;
}

/**
 * Bounded set of well-known SEC section headings that appear WITHOUT an
 * "Item N" prefix (e.g. `<h2>Risk Factors</h2>`). Patterns are anchored to the
 * FULL trimmed block text \u2014 a prose cross-reference like "See Risk Factors"
 * never matches \u2014 and the same structural guards as Item/Part headings apply
 * (heading tag, leaf block, or EDGAR heading wrapper; see collectBlocks).
 * Codes are deliberately form-agnostic slugs, NOT numeric Item codes: the same
 * title maps to different Item numbers on 10-K vs 10-Q, and guessing would
 * mislabel sections (see the form-aware standardizeTitle note below).
 */
const STANDALONE_SECTION_HEADINGS: Array<{ pattern: RegExp; code: string; title: string }> = [
  { pattern: /^risk\s+factors$/i, code: "RISK-FACTORS", title: "Risk Factors" },
  {
    pattern: /^management['\u2019]s\s+discussion(\s+and\s+analysis(\s+of\s+financial\s+condition\s+and\s+results\s+of\s+operations)?)?$/i,
    code: "MDA",
    title: "Management's Discussion and Analysis"
  },
  {
    pattern: /^(unaudited\s+)?(condensed\s+)?(consolidated\s+)?financial\s+statements(\s+and\s+supplementary\s+data)?$/i,
    code: "FINANCIAL-STATEMENTS",
    title: "Financial Statements"
  },
  { pattern: /^legal\s+proceedings$/i, code: "LEGAL-PROCEEDINGS", title: "Legal Proceedings" },
  {
    pattern: /^quantitative\s+and\s+qualitative\s+disclosures\s+about\s+market\s+risk$/i,
    code: "MARKET-RISK",
    title: "Quantitative and Qualitative Disclosures About Market Risk"
  },
  { pattern: /^controls\s+and\s+procedures$/i, code: "CONTROLS-AND-PROCEDURES", title: "Controls and Procedures" }
];

function matchStandaloneHeading(clean: string): { code: string; title: string } | null {
  for (const entry of STANDALONE_SECTION_HEADINGS) {
    if (entry.pattern.test(clean)) return { code: entry.code, title: entry.title };
  }
  return null;
}

function isHeadingBlock(text: string): boolean {
  const clean = text.trim();
  if (clean.length === 0 || clean.length > 150) return false;
  return (
    /^\s*item\s+(\d+[a-z]?)\b/i.test(clean) ||
    /^\s*part\s+(\d+|[ivx]+)\b/i.test(clean) ||
    matchStandaloneHeading(clean) !== null
  );
}

/** Form types whose canonical Item-code \u2192 title mapping below is valid (10-K family). */
function isTenKForm(formType: string | undefined): boolean {
  return typeof formType === "string" && /^10-K/i.test(formType.trim());
}

/**
 * Canonical Item titles are FORM-SPECIFIC: "Item 1" is "Business" on a 10-K but
 * "Financial Statements" on a 10-Q. The mapping below is the 10-K mapping, so it
 * is applied ONLY when the caller explicitly passed a form type proving it valid;
 * otherwise the raw title parsed from the filing text is preserved as-is.
 */
function standardizeTitle(code: string, rawTitle: string, formType?: string): string {
  if (!isTenKForm(formType)) {
    return rawTitle || `Item ${code}`;
  }
  let title = rawTitle;
  if (code === "1") title = "Business";
  else if (code === "1A") title = "Risk Factors";
  else if (code === "3") title = "Legal Proceedings";
  else if (code === "7") title = "Management's Discussion and Analysis";
  else if (code === "7A") title = "Quantitative and Qualitative Disclosures About Market Risk";
  else if (code === "8") title = "Financial Statements and Supplementary Data";
  else if (code === "9A") title = "Controls and Procedures";
  return title || rawTitle || `Item ${code}`;
}

function normalizeItemCode(text: string, formType?: string): { code: string; title: string } | null {
  const clean = text.trim();

  // Try matching "Item <number><letter>" first (most specific)
  const itemMatch = clean.match(/item\s+(\d+[a-z]?)\b/i);
  if (itemMatch) {
    const code = itemMatch[1].toUpperCase();
    const titleMatch = clean.match(/item\s+\d+[a-z]?[.\s-:\u2013\u2014]*(.*)/i);
    const rawTitle = titleMatch ? titleMatch[1].trim() : "";
    return { code, title: standardizeTitle(code, rawTitle, formType) };
  }

  // Try matching "Part <number/roman>"
  const partMatch = clean.match(/part\s+(\d+|[ivx]+)\b/i);
  if (partMatch) {
    const code = partMatch[1].toUpperCase();
    const titleMatch = clean.match(/part\s+(?:\d+|[ivx]+)[.\s-:\u2013\u2014]*(.*)/i);
    const rawTitle = titleMatch ? titleMatch[1].trim() : "";
    return { code: `PART-${code}`, title: rawTitle || `Part ${code}` };
  }

  // Well-known standalone section headings without an "Item"/"Part" prefix
  // (full-text anchored match \u2014 see STANDALONE_SECTION_HEADINGS).
  return matchStandaloneHeading(clean);
}

function splitTableRows(rows: string[][], firstRowHasHeaders: boolean = false): string[] {
  if (rows.length <= 1) {
    return [rows.map((row) => `| ${row.join(" | ")} |`).join("\n")];
  }

  if (!firstRowHasHeaders) {
    // No real header row — keep every row as DATA (never promote the first data
    // row to a repeated header; that duplicates values across splits). GFM still
    // requires a header row before the delimiter, so synthesize a neutral
    // empty-cell header of the right width to keep each split a valid table.
    const colCount = rows[0].length;
    const emptyHeader = Array(colCount).fill("");
    const divider = Array(colCount).fill("---");
    const tables: string[] = [];
    let currentGroup: string[][] = [emptyHeader, divider];

    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];
      const proposedGroup = [...currentGroup, row];
      const markdown = proposedGroup.map((r) => `| ${r.join(" | ")} |`).join("\n");

      if (estimateTableTokens(markdown) > 400 && currentGroup.length > 2) {
        tables.push(currentGroup.map((r) => `| ${r.join(" | ")} |`).join("\n"));
        currentGroup = [emptyHeader, divider, row];
      } else {
        currentGroup.push(row);
      }
    }

    if (currentGroup.length > 2) {
      tables.push(currentGroup.map((r) => `| ${r.join(" | ")} |`).join("\n"));
    }
    return tables;
  }

  // First row is a real header — repeat it across each split
  const headerRow = rows[0];
  const colCount = headerRow.length;
  const divider = Array(colCount).fill("---");

  const tables: string[] = [];
  let currentGroup: string[][] = [headerRow, divider];

  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    // Check if adding this row exceeds the 400-token limit
    const proposedGroup = [...currentGroup, row];
    const markdown = proposedGroup.map((r) => `| ${r.join(" | ")} |`).join("\n");

    if (estimateTableTokens(markdown) > 400 && currentGroup.length > 2) {
      tables.push(currentGroup.map((r) => `| ${r.join(" | ")} |`).join("\n"));
      currentGroup = [headerRow, divider, row];
    } else {
      currentGroup.push(row);
    }
  }

  if (currentGroup.length > 2) {
    tables.push(currentGroup.map((r) => `| ${r.join(" | ")} |`).join("\n"));
  }
  return tables;
}

function collectBlocks($: any, node: any, blocks: ParsedBlock[], formType?: string) {
  if (node.type !== "tag") return;

  const name = node.name.toLowerCase();
  if (name === "script" || name === "style" || name === "noscript" || name === "iframe" || name === "head") {
    return;
  }

  // Remove display: none or visibility: hidden elements
  const style = $(node).attr("style");
  if (style) {
    const isHidden = /display\s*:\s*none/i.test(style) || /visibility\s*:\s*hidden/i.test(style);
    if (isHidden) return;
  }

  // If table, convert and do not recurse into rows/cells
  if (name === "table") {
    // Check for heading text in small layout tables (EDGAR sometimes encodes Item
    // headings as single-cell layout tables). If detected, treat as heading.
    const cellText = $(node).text().trim();
    if (isHeadingBlock(cellText) && $(node).find("tr").length <= 1 && $(node).find("td, th").length <= 2) {
      const norm = normalizeItemCode(cellText, formType);
      if (norm) {
        blocks.push({ type: "heading", text: cellText, itemCode: norm.code, itemTitle: norm.title });
        return;
      }
    }
    const grid: string[][] = [];
    let r = 0;
    let firstRowHasHeaders = false;
    let isFirstRow = true;

    $(node).find("tr").each((_: any, tr: any) => {
      // Skip rows belonging to nested tables (they will be processed when
      // collectBlocks recurses into the nested table directly)
      if ($(tr).closest("table").get(0) !== node) return;
      if (!grid[r]) grid[r] = [];

      let c = 0;
      let hasThCells = false;
      $(tr).children("td, th").each((_: any, cell: any) => {
        // Find next empty column slot in grid row r
        while (grid[r][c] !== undefined) {
          c++;
        }

        // Process nested tables in this cell FIRST (blocks are emitted before
        // we strip them from outer cell text)
        $(cell).find("table").each((__: any, nestedTable: any) => {
          collectBlocks($, nestedTable, blocks, formType);
        });
        // Remove nested tables from cell text now that content is preserved
        $(cell).find("table").remove();
        // Replace <br> with space so concatenated text nodes stay separated
        $(cell).find("br").replaceWith(" ");

        const colspan = parseInt($(cell).attr("colspan") || "1", 10);
        const rowspan = parseInt($(cell).attr("rowspan") || "1", 10);
        const cellText = $(cell).text().replace(/\s+/g, " ").trim();

        for (let rs = 0; rs < rowspan; rs++) {
          const targetRow = r + rs;
          if (!grid[targetRow]) grid[targetRow] = [];
          for (let cs = 0; cs < colspan; cs++) {
            grid[targetRow][c + cs] = cellText;
          }
        }

        const nodeName = cell.name?.toLowerCase() || cell.tagName?.toLowerCase() || "";
        if (nodeName === "th") {
          hasThCells = true;
        }
        c += colspan;
      });

      if (grid[r] && grid[r].some((val) => val !== undefined && val !== "")) {
        if (isFirstRow) {
          firstRowHasHeaders = hasThCells;
          isFirstRow = false;
        }
      }
      r++;
    });

    const tableRows: string[][] = [];
    const maxCols = grid.length > 0 ? Math.max(...grid.map((row) => (row ? row.length : 0))) : 0;
    for (let i = 0; i < grid.length; i++) {
      const row = grid[i] || [];
      const normalizedRow: string[] = [];
      for (let j = 0; j < maxCols; j++) {
        normalizedRow.push(row[j] ?? "");
      }
      if (normalizedRow.some((val) => val !== "")) {
        tableRows.push(normalizedRow);
      }
    }

    if (tableRows.length > 0) {
      const splitTables = splitTableRows(tableRows, firstRowHasHeaders);
      for (const tableMd of splitTables) {
        blocks.push({ type: "table", text: tableMd });
      }
    }
    return;
  }

  const text = $(node).text().trim();

  // If it's a heading tag, or matches heading pattern on a leaf block (no children),
  // or an EDGAR heading wrapper (center/font/span/bold) with heading text
  if (isHeadingBlock(text) && (name.match(/^h[1-6]$/) || (BLOCK_TAGS.has(name) && !hasBlockChildren($, node)) || (HEADING_WRAPPER_TAGS.has(name) && !hasBlockChildren($, node)))) {
    const norm = normalizeItemCode(text, formType);
    if (norm) {
      blocks.push({
        type: "heading",
        text,
        itemCode: norm.code,
        itemTitle: norm.title
      });
      return;
    }
  }

  // If it's a block container with no block children, extract text and do not recurse
  if (BLOCK_TAGS.has(name) && !hasBlockChildren($, node)) {
    // Replace <br> with space so leaf block text doesn't concatenate across line breaks
    $(node).find("br").replaceWith(" ");
    const cleanText = $(node).text().replace(/\s+/g, " ").trim();
    if (cleanText) {
      blocks.push({ type: "paragraph", text: cleanText });
    }
    return;
  }

  // Recurse into children; emit text node siblings so mixed-content containers
  // (e.g. <div>Note:<table>...</table>See below.</div>) don't lose prose.
  if (node.children) {
    for (const child of node.children) {
      if (child.type === "text") {
        const text = (child.data || "").replace(/\s+/g, " ").trim();
        if (text) {
          blocks.push({ type: "paragraph", text });
        }
      } else {
        collectBlocks($, child, blocks, formType);
      }
    }
  }
}

/**
 * Parses raw SEC filing HTML using cheerio, removing styles/scripts,
 * extracting sections based on Item headings, and converting tables to Markdown.
 *
 * `options.formType` (e.g. "10-K", "10-Q") controls form-aware Item-title
 * canonicalization: the 10-K Item-code → title map is applied ONLY when the
 * caller proves the filing is a 10-K; otherwise raw parsed titles are kept
 * (Item 1 is "Financial Statements" on a 10-Q, not "Business").
 */
export function parseFilingHtml(html: string, options?: { formType?: string }): ParsedFiling {
  const formType = options?.formType;
  const $ = cheerio.load(html);

  // Clean inline-XBRL tags: remove ix:hidden/ix:header entirely (their content is
  // non-rendered metadata or duplicate facts), unwrap the rest keeping their content.
  $("*").each((_, el) => {
    if (el.type === "tag" && el.name && el.name.toLowerCase().startsWith("ix:")) {
      const ixName = el.name.toLowerCase();
      if (ixName === "ix:hidden" || ixName === "ix:header") {
        $(el).remove();
      } else {
        $(el).replaceWith($(el).contents());
      }
    }
  });

  // Strip scripts/styles/noscript/iframe
  $("script, style, noscript, iframe, head").remove();

  const blocks: ParsedBlock[] = [];
  const body = $("body").get(0);
  if (body) {
    collectBlocks($, body, blocks, formType);
  } else {
    // Fallback: collect blocks from root if body doesn't exist
    const root = $.root().get(0);
    if (root) collectBlocks($, root, blocks, formType);
  }

  // Group blocks by section
  const sections: Array<{ itemCode: string; itemTitle: string; text: string }> = [];
  let currentItemCode = "GENERAL";
  let currentItemTitle = "General Section";
  let currentSectionText: string[] = [];

  for (const block of blocks) {
    if (block.type === "heading" && block.itemCode) {
      // Flush current section
      const joined = currentSectionText.join("\n\n").trim();
      if (joined) {
        sections.push({
          itemCode: currentItemCode,
          itemTitle: currentItemTitle,
          text: joined
        });
      }
      currentItemCode = block.itemCode;
      currentItemTitle = block.itemTitle || `Item ${block.itemCode}`;
      currentSectionText = [];
    } else {
      currentSectionText.push(block.text);
    }
  }

  // Flush last section
  const joined = currentSectionText.join("\n\n").trim();
  if (joined) {
    sections.push({
      itemCode: currentItemCode,
      itemTitle: currentItemTitle,
      text: joined
    });
  }

  // Construct full clean plain text
  const fullText = sections.map((s) => `## Item ${s.itemCode}. ${s.itemTitle}\n\n${s.text}`).join("\n\n");

  return {
    text: fullText,
    sections
  };
}

// SEC EDGAR insider (Form 4) ingestion.
//
// SEC EDGAR is free and authoritative but only requires a descriptive User-Agent
// (no key). There is no single market-wide feed that includes trade DIRECTION, so
// we read the "current Form 4" filings feed and parse each filing's ownership XML,
// keeping only OPEN-MARKET discretionary transactions:
//   P = open-market purchase (bullish), S = open-market sale (bearish).
// Codes like M (option exercise), A (grant/award), F (tax withholding), G (gift)
// are NOT trading signals and are deliberately ignored.
//
// Like the congress connector this is a low-frequency bulk job: each daily refresh
// captures the latest filings and merges them into a rolling window, so over time
// the dataset covers whichever symbols insiders actually traded — never fabricated.

import { audit, getInternalSetting, setInternalSetting } from "../db";
import { normalizeSymbol } from "../money";
import type { WebSourceRefreshResult } from "./types";
import { retryBackoffMs } from "./congress";
import { politeFetchText, runRateLimited, secUserAgent } from "./http";

const DATASET_KEY = "webSource:insider:dataset";
const ATTEMPT_KEY = "webSource:insider:lastAttempt";
const DEFAULT_TTL_MS = 24 * 60 * 60_000; // daily
const DEFAULT_WINDOW_DAYS = 30; // how long an insider filing stays in the rolling window
const DEFAULT_MAX_FILINGS = 30; // ownership XMLs parsed per refresh (politeness: ~2 reqs each)
const SEC_BASE = "https://www.sec.gov";

export interface InsiderFiling {
  symbol: string;
  owner: string;
  buyTx: number; // count of open-market purchase transactions
  sellTx: number; // count of open-market sale transactions
  buyShares: number;
  sellShares: number;
  filedAt: string; // ISO date
  accession: string;
}

export interface InsiderDataset {
  filings: InsiderFiling[];
  fetchedAt: string;
  recordCount: number;
}

export interface InsiderSignal {
  insiderSentiment: number; // 0–100 (buy transactions as % of open-market P+S)
  buyFilings: number;
  sellFilings: number;
  owners: string[];
  windowDays: number;
  bulletin: string;
}

export function insiderTtlMs(): number {
  const v = Number(process.env.WEB_SOURCE_INSIDER_TTL_MS ?? DEFAULT_TTL_MS);
  return Number.isFinite(v) && v > 0 ? v : DEFAULT_TTL_MS;
}

function windowDays(): number {
  const v = Number(process.env.WEB_SOURCE_INSIDER_WINDOW_DAYS ?? DEFAULT_WINDOW_DAYS);
  return Number.isFinite(v) && v > 0 ? v : DEFAULT_WINDOW_DAYS;
}

export function getInsiderDataset(): InsiderDataset | undefined {
  return getInternalSetting<InsiderDataset>(DATASET_KEY);
}

// ── Pure parsers (unit-tested without network) ───────────────────────────────

/** Extract distinct filing folders + accession numbers from the current-Form-4 atom feed. */
export function parseCurrentForm4Feed(atomXml: string): Array<{ dir: string; accession: string }> {
  const out: Array<{ dir: string; accession: string }> = [];
  const seen = new Set<string>();
  for (const m of atomXml.matchAll(/href="([^"]*\/Archives\/edgar\/data\/[^"]*?index[^"]*)"/g)) {
    const link = m[1];
    const accession = link.match(/(\d{10}-\d{2}-\d{6})/)?.[1];
    if (!accession || seen.has(accession)) continue;
    seen.add(accession);
    out.push({ dir: link.replace(/\/[^/]+$/, "/"), accession });
  }
  return out;
}

/** Pick the primary ownership XML from an EDGAR filing folder index.json. */
export function pickOwnershipXml(indexJson: unknown): string | undefined {
  const items = (indexJson as { directory?: { item?: Array<{ name?: string }> } })?.directory?.item;
  if (!Array.isArray(items)) return undefined;
  const names = items.map((i) => i?.name ?? "").filter(Boolean);
  // Prefer a primary ownership doc; exclude rendered/calc/label/schema sidecars.
  return (
    names.find((n) => /^(ownership|form4|primary_doc).*\.xml$/i.test(n)) ??
    names.find((n) => /\.xml$/i.test(n) && !/^R\d|(_|\b)(cal|def|lab|pre)\b|\.xsd$/i.test(n))
  );
}

/**
 * Validate an ISO filing date, REJECTING data-quality garbage. A Form 4 can't report a transaction
 * dated after today, so a future date (e.g. a corrupt "2026-12-26") is an unambiguous error — we
 * reject it rather than surface an impossible date in the UI or skew the recency window.
 */
function saneFilingDate(value: string | undefined, now: number = Date.now()): string | undefined {
  if (!value) return undefined;
  const m = value.trim().match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return undefined;
  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  // Reject impossible calendar dates that would otherwise roll over to a valid timestamp (e.g.
  // "2026-02-30" -> Mar 2): build the UTC date from the components and require it to round-trip.
  const d = new Date(Date.UTC(year, month - 1, day));
  if (d.getUTCFullYear() !== year || d.getUTCMonth() !== month - 1 || d.getUTCDate() !== day) return undefined;
  const iso = `${m[1]}-${m[2]}-${m[3]}`;
  const ts = d.getTime();
  if (!Number.isFinite(ts)) return undefined;
  // A Form 4 reports a transaction that already happened, so its date is a timezone-less calendar
  // date that can't be after today — reject anything strictly future (no ±3-day skew; lexicographic
  // compare is valid for YYYY-MM-DD).
  const todayIso = new Date(now).toISOString().slice(0, 10);
  if (iso > todayIso) return undefined;
  if (ts < Date.parse("2000-01-01")) return undefined; // absurd past
  return iso;
}

/** Parse a Form 4 ownership XML into a normalized insider filing (open-market P/S only). */
export function parseForm4Xml(xml: string, ctx: { accession: string }): InsiderFiling | null {
  const symbolRaw = xml.match(/<issuerTradingSymbol>([\s\S]*?)<\/issuerTradingSymbol>/)?.[1]?.trim();
  if (!symbolRaw) return null;
  const symbol = normalizeSymbol(symbolRaw);
  if (!/^[A-Z][A-Z.\-]{0,5}$/.test(symbol)) return null;
  const owner = (xml.match(/<rptOwnerName>([\s\S]*?)<\/rptOwnerName>/)?.[1] ?? "Insider").replace(/\s+/g, " ").trim();
  // A date field that is SUPPLIED but future-dated or otherwise garbage is a data error — DROP the
  // filing rather than silently re-anchoring it to the signature date or today (which would surface
  // an impossible future transaction as current insider activity). Fall through only when a field is
  // simply absent; default to today only when no date was supplied at all.
  const periodRaw = xml.match(/<periodOfReport>([\s\S]*?)<\/periodOfReport>/)?.[1]?.trim();
  const sigRaw = xml.match(/<signatureDate>[\s\S]*?<value>([\s\S]*?)<\/value>/)?.[1]?.trim();
  const period = periodRaw ? saneFilingDate(periodRaw) : undefined;
  if (periodRaw && !period) return null;
  const sig = sigRaw ? saneFilingDate(sigRaw) : undefined;
  if (sigRaw && !sig) return null;
  const filedAt = period || sig || new Date().toISOString().slice(0, 10);

  let buyTx = 0;
  let sellTx = 0;
  let buyShares = 0;
  let sellShares = 0;
  // Only non-derivative open-market transactions carry directional sentiment.
  for (const block of xml.split(/<nonDerivativeTransaction>/).slice(1)) {
    const code = block.match(/<transactionCode>([A-Z])<\/transactionCode>/)?.[1];
    if (code !== "P" && code !== "S") continue;
    const shares = Number(block.match(/<transactionShares>[\s\S]*?<value>([\d.]+)<\/value>/)?.[1] ?? 0);
    if (code === "P") {
      buyTx++;
      buyShares += Number.isFinite(shares) ? shares : 0;
    } else {
      sellTx++;
      sellShares += Number.isFinite(shares) ? shares : 0;
    }
  }
  if (buyTx === 0 && sellTx === 0) return null; // no discretionary open-market activity
  return { symbol, owner, buyTx, sellTx, buyShares, sellShares, filedAt: filedAt.slice(0, 10), accession: ctx.accession };
}

// ── Aggregation (pure) ───────────────────────────────────────────────────────

export function aggregateInsiderSignals(
  filings: InsiderFiling[],
  symbols: string[],
  now: number = Date.now(),
  window = windowDays()
): Record<string, InsiderSignal> {
  const wanted = new Set(symbols.map(normalizeSymbol).filter(Boolean));
  const cutoff = now - window * 24 * 60 * 60_000;
  const bySymbol = new Map<string, InsiderFiling[]>();
  for (const f of filings) {
    if (!wanted.has(f.symbol)) continue;
    const ts = Date.parse(f.filedAt);
    if (Number.isFinite(ts) && ts < cutoff) continue;
    const list = bySymbol.get(f.symbol) ?? [];
    list.push(f);
    bySymbol.set(f.symbol, list);
  }

  const out: Record<string, InsiderSignal> = {};
  for (const [symbol, list] of bySymbol) {
    const buyTx = list.reduce((s, f) => s + f.buyTx, 0);
    const sellTx = list.reduce((s, f) => s + f.sellTx, 0);
    if (buyTx + sellTx === 0) continue;
    const buyFilings = list.filter((f) => f.buyTx > f.sellTx).length;
    const sellFilings = list.filter((f) => f.sellTx > f.buyTx).length;
    const owners = distinct(list.map((f) => f.owner));
    out[symbol] = {
      insiderSentiment: Math.round((buyTx / (buyTx + sellTx)) * 100),
      buyFilings,
      sellFilings,
      owners,
      windowDays: window,
      bulletin: buildInsiderBulletin(symbol, buyFilings, sellFilings, owners, window)
    };
  }
  return out;
}

function distinct(names: string[]): string[] {
  return Array.from(new Set(names.filter(Boolean)));
}

function buildInsiderBulletin(symbol: string, buyFilings: number, sellFilings: number, owners: string[], window: number): string {
  const who = owners.slice(0, 2).join(", ") + (owners.length > 2 ? `, +${owners.length - 2}` : "");
  if (buyFilings > 0 && sellFilings === 0) {
    return `Insider: ${buyFilings} open-market BUY filing(s) on ${symbol} in last ${window}d (${who}); no sells.`;
  }
  if (sellFilings > 0 && buyFilings === 0) {
    return `Insider: ${sellFilings} open-market SELL filing(s) on ${symbol} in last ${window}d (${who}); no buys.`;
  }
  return `Insider: mixed open-market activity on ${symbol} in last ${window}d — ${buyFilings} buy vs ${sellFilings} sell filing(s) (${who}).`;
}

export function getInsiderSignals(symbols: string[], now: number = Date.now()): Record<string, InsiderSignal> {
  const dataset = getInsiderDataset();
  if (!dataset?.filings?.length) return {};
  return aggregateInsiderSignals(dataset.filings, symbols, now);
}

// ── Live refresh ─────────────────────────────────────────────────────────────

export function isInsiderRefreshDue(now: number = Date.now()): boolean {
  // Back off after any attempt so a failed scrape doesn't re-fire every scheduler tick.
  const lastAttempt = getInternalSetting<string>(ATTEMPT_KEY);
  if (lastAttempt && now - Date.parse(lastAttempt) < retryBackoffMs()) return false;
  const dataset = getInsiderDataset();
  if (!dataset?.fetchedAt) return true;
  return now - Date.parse(dataset.fetchedAt) >= insiderTtlMs();
}

async function scrapeRecentForm4s(now: number): Promise<InsiderFiling[]> {
  const ua = secUserAgent();
  const feed = await politeFetchText(
    `${SEC_BASE}/cgi-bin/browse-edgar?action=getcurrent&type=4&count=100&output=atom`,
    { headers: { "user-agent": ua, accept: "application/atom+xml" } }
  );
  const filings = parseCurrentForm4Feed(feed).slice(0, Number(process.env.WEB_SOURCE_INSIDER_MAX_FILINGS ?? DEFAULT_MAX_FILINGS));
  const parsed = await runRateLimited(filings, 250, async ({ dir, accession }) => {
    try {
      const indexJson = JSON.parse(await politeFetchText(`${dir}index.json`, { headers: { "user-agent": ua } }));
      const xmlName = pickOwnershipXml(indexJson);
      if (!xmlName) return null;
      const xml = await politeFetchText(`${dir}${xmlName}`, { headers: { "user-agent": ua } });
      return parseForm4Xml(xml, { accession });
    } catch {
      return null;
    }
  });
  return parsed.filter((f): f is InsiderFiling => f !== null);
}

/** Merge fresh filings into the rolling window, deduped by accession, pruned to window. */
export function mergeInsiderFilings(existing: InsiderFiling[], fresh: InsiderFiling[], now: number, window = windowDays()): InsiderFiling[] {
  const cutoff = now - window * 24 * 60 * 60_000;
  const byAccession = new Map<string, InsiderFiling>();
  for (const f of [...existing, ...fresh]) {
    const ts = Date.parse(f.filedAt);
    if (Number.isFinite(ts) && ts < cutoff) continue;
    byAccession.set(f.accession, f);
  }
  return Array.from(byAccession.values());
}

// ── External upsert (push webhook / SSE from App A congress.trade) ────────────
// App A may push raw Form-4 filings OR a precomputed per-symbol insiderSentiment (0–100). We accept
// both: raw filings merge straight into the rolling dataset; a scalar is represented as one synthetic
// "marker" filing whose buy/sell transaction counts reproduce that sentiment when aggregated.

/** Build a synthetic marker filing so a pushed insiderSentiment (0–100) flows through aggregation. */
export function insiderFilingFromSentiment(symbol: string, sentiment: number, asOf?: string): InsiderFiling | null {
  const sym = normalizeSymbol(symbol);
  const s = Math.max(0, Math.min(100, Math.round(sentiment)));
  if (!sym || !Number.isFinite(sentiment)) return null;
  const filedAt = asOf && /^\d{4}-\d{2}-\d{2}/.test(asOf) ? asOf.slice(0, 10) : new Date().toISOString().slice(0, 10);
  // buyTx/sellTx sum to 100 so aggregateInsiderSignals reproduces `s` = buyTx/(buyTx+sellTx)*100.
  // Accession is stable per symbol+day → re-sends overwrite rather than accumulate.
  return {
    symbol: sym,
    owner: "congress.trade",
    buyTx: s,
    sellTx: 100 - s,
    buyShares: 0,
    sellShares: 0,
    filedAt,
    accession: `appA:insider:${sym}:${filedAt}`
  };
}

/** Tolerantly coerce a pushed raw Form-4 row into an InsiderFiling (requires symbol + accession). */
export function coerceInsiderFiling(raw: unknown): InsiderFiling | null {
  if (!raw || typeof raw !== "object") return null;
  const o = raw as Record<string, unknown>;
  const symbol = normalizeSymbol(typeof o.symbol === "string" ? o.symbol : typeof o.ticker === "string" ? o.ticker : "");
  const accession = typeof o.accession === "string" ? o.accession : typeof o.id === "string" ? o.id : "";
  if (!symbol || !accession) return null;
  const num = (v: unknown): number => (typeof v === "number" && Number.isFinite(v) ? v : 0);
  const rawFiled = typeof o.filedAt === "string" ? o.filedAt : typeof o.date === "string" ? o.date : "";
  const saneFiled = saneFilingDate(rawFiled);
  // A supplied filing date that is future-dated or otherwise garbage is a data error → drop the row
  // rather than surface an impossible date. With no date at all, default to today.
  if (rawFiled && !saneFiled) return null;
  const filedAt = saneFiled ?? new Date().toISOString().slice(0, 10);
  return {
    symbol,
    // Never store an empty owner (the InsiderFiling contract wants a non-empty string); the
    // buy/sell counts carry the actual signal, so default a missing owner rather than dropping it.
    owner: (typeof o.owner === "string" && o.owner.trim()) || "unknown",
    buyTx: num(o.buyTx),
    sellTx: num(o.sellTx),
    buyShares: num(o.buyShares),
    sellShares: num(o.sellShares),
    filedAt,
    accession
  };
}

/** Merge externally-received insider filings into the persisted dataset. Returns the new total. */
export function upsertInsiderFilings(incoming: InsiderFiling[], now: number = Date.now()): { total: number } {
  const clean = incoming.filter((f): f is InsiderFiling => Boolean(f && f.symbol && f.accession));
  const prior = getInsiderDataset();
  if (clean.length === 0) return { total: prior?.recordCount ?? 0 };
  const merged = mergeInsiderFilings(prior?.filings ?? [], clean, now);
  const dataset: InsiderDataset = { filings: merged, fetchedAt: new Date(now).toISOString(), recordCount: merged.length };
  setInternalSetting(DATASET_KEY, dataset);
  return { total: merged.length };
}

export async function refreshInsider(now: number = Date.now(), force = false): Promise<WebSourceRefreshResult> {
  if (!force && !isInsiderRefreshDue(now)) {
    const ds = getInsiderDataset();
    return { id: "insider", ok: true, recordCount: ds?.recordCount ?? 0, sources: ds ? ["sec-edgar"] : [], fetchedAt: ds?.fetchedAt ?? "", skipped: true };
  }

  // Record the attempt so a failure backs off instead of re-firing every tick.
  setInternalSetting(ATTEMPT_KEY, new Date(now).toISOString());

  let fresh: InsiderFiling[] = [];
  let warning: string | undefined;
  try {
    fresh = await scrapeRecentForm4s(now);
  } catch (error) {
    warning = error instanceof Error ? error.message : "sec-edgar failed";
  }

  const prior = getInsiderDataset();
  const merged = mergeInsiderFilings(prior?.filings ?? [], fresh, now);
  // Only advance fetchedAt when we actually fetched something; otherwise keep the
  // prior success time so the dashboard reflects true freshness and the TTL gate
  // (with the attempt backoff above) schedules the next retry correctly.
  const fetchedAt = fresh.length > 0 ? new Date(now).toISOString() : prior?.fetchedAt ?? new Date(now).toISOString();

  // Persist as long as we have *some* data (fresh or still-valid prior). Only bail
  // entirely when there's nothing at all, so a transient outage never wipes the window.
  if (merged.length === 0) {
    audit("web_source_refresh", { id: "insider", ok: false, recordCount: 0, warning });
    return { id: "insider", ok: false, recordCount: 0, sources: [], fetchedAt: prior?.fetchedAt ?? "", warning: warning ?? "no records" };
  }

  const dataset: InsiderDataset = { filings: merged, fetchedAt, recordCount: merged.length };
  setInternalSetting(DATASET_KEY, dataset);
  const ok = fresh.length > 0;
  audit("web_source_refresh", { id: "insider", ok, recordCount: merged.length, fresh: fresh.length, warning });
  return { id: "insider", ok, recordCount: merged.length, sources: ["sec-edgar"], fetchedAt, warning };
}

// SEC EDGAR 8-K (material event) ingestion.
//
// An 8-K is filed when something material happens (results, exec changes, major
// agreements, etc.), so a fresh 8-K is a catalyst flag worth surfacing to the agent.
// Free, no key (UA only). We read the market-wide "current 8-K" atom feed, map each
// filer's CIK to a ticker via SEC's company_tickers.json (cached weekly), and keep a
// short rolling window of "TICKER filed an 8-K" events. Per-item label enrichment
// IS implemented: parseEightKItemsFromHtml() fetches the filing summary page and
// extracts item codes (e.g. "Item 5.02"); eightKHasMaterialItem() filters an
// expert-panel allowlist; items surface in bulletins and trigger the event-driven
// engine (`src/lib/triggers.ts`) when a material item code is detected.
// Never fabricated: no feed / no CIK match -> no event.

import {
  audit,
  getDb,
  getInternalSetting,
  hasIngestedAccession,
  insertIngestedAccession,
  runWithActiveVectorCommitProof,
  setInternalSetting
} from "../db";
import { normalizeSymbol } from "../money";
import { envFlagOn } from "../rag/env-flag";
import {
  eligibleMaterialTriggerUserIds,
  enqueueMaterialEventsForUsersTx,
  hasDurableMaterialTriggerWork,
  type MaterialEvent
} from "../triggers";
import {
  assertOperationLeaseOwnership,
  OPERATION_LEASE_GROUPS,
  runWithOperationLease,
  throwIfOperationLeaseCancelled,
  type OperationLeaseAware,
  type OperationLeaseClaim
} from "../operation-lease";
import { retryBackoffMs } from "./congress";
import { politeFetchText, runRateLimited, secUserAgent, sleep } from "./http";
import { extractFilingText } from "./sec-filings";
import type { VectorStoreLeaseGuard } from "../vector-db";

/**
 * R10 (2026-07-01 RAG backlog): content_hash dedup for the always-on 8-K SUMMARY ingest
 * below. Default ON - avoids re-embedding the same short summary on every refresh cycle
 * even when the underlying event data hasn't changed (the Pinecone upsert is idempotent by
 * contextId, but the Voyage embed call is NOT free). Set VECTOR_STORECONTEXTS_DEDUP=off only
 * when intentionally forcing a re-embed.
 */
function storeContextsDedupEnabled(): boolean {
  return envFlagOn("VECTOR_STORECONTEXTS_DEDUP", true);
}

const DATASET_KEY = "webSource:sec8k:dataset";
const ATTEMPT_KEY = "webSource:sec8k:lastAttempt";
const CIK_KEY = "webSource:sec:cikMap";
const DEFAULT_TTL_MS = 24 * 60 * 60_000; // daily
const CIK_TTL_MS = 7 * 24 * 60 * 60_000; // ticker↔CIK map changes slowly
const DEFAULT_WINDOW_DAYS = 4; // an 8-K is only a "fresh" catalyst for a few days
const DEFAULT_RAG_LIMIT = 16;
const SUMMARY_BACKLOG_KEY = "webSource:sec8k:summaryBacklog";
const FULL_BODY_BACKLOG_KEY = "webSource:sec8k:fullBodyBacklog";
const DEFAULT_SUMMARY_BACKLOG_MAX = 1_000;
const DEFAULT_FULL_BODY_BACKLOG_MAX = 500;
const SEC_BASE = "https://www.sec.gov";

function isValidPersistedTimestamp(value: unknown): value is string {
  return typeof value === "string" && value.length > 0 && Number.isFinite(Date.parse(value));
}

export interface EightKEvent {
  symbol: string;
  filedAt: string; // ISO date
  /** Exact SEC feed acceptance/update time used for point-in-time retrieval. */
  acceptedAt?: string;
  accession: string;
  filingUrl?: string;
  items?: string[];
}
export interface EightKDataset {
  events: EightKEvent[];
  fetchedAt: string;
  recordCount: number;
}

export function eightKTtlMs(): number {
  const v = Number(process.env.WEB_SOURCE_SEC8K_TTL_MS ?? DEFAULT_TTL_MS);
  return Number.isFinite(v) && v > 0 ? v : DEFAULT_TTL_MS;
}
function windowDays(): number {
  const v = Number(process.env.WEB_SOURCE_SEC8K_WINDOW_DAYS ?? DEFAULT_WINDOW_DAYS);
  return Number.isFinite(v) && v > 0 ? v : DEFAULT_WINDOW_DAYS;
}
export function eightKRagLimit(): number {
  const v = Number(process.env.WEB_SOURCE_SEC8K_RAG_LIMIT ?? DEFAULT_RAG_LIMIT);
  return Number.isFinite(v) && v >= 0 ? Math.floor(v) : DEFAULT_RAG_LIMIT;
}
export function getEightKDataset(): EightKDataset | undefined {
  return getInternalSetting<EightKDataset>(DATASET_KEY);
}

function fullBodyBacklogMax(): number {
  const value = Number(process.env.WEB_SOURCE_SEC8K_FULL_BODY_BACKLOG_MAX ?? DEFAULT_FULL_BODY_BACKLOG_MAX);
  return Number.isFinite(value) && value > 0
    ? Math.min(5_000, Math.floor(value))
    : DEFAULT_FULL_BODY_BACKLOG_MAX;
}

export function getEightKFullBodyBacklog(): EightKEvent[] {
  return readEightKBacklog(FULL_BODY_BACKLOG_KEY, fullBodyBacklogMax(), true);
}

function readEightKBacklog(key: string, max: number, preserveOrder = false): EightKEvent[] {
  const value = getInternalSetting<unknown>(key);
  if (!Array.isArray(value)) return [];
  const unique = new Map<string, EightKEvent>();
  for (const raw of value) {
    if (!raw || typeof raw !== "object") continue;
    const row = raw as Partial<EightKEvent>;
    if (!row.accession || !row.symbol || !row.filedAt) continue;
    unique.set(row.accession, {
      symbol: normalizeSymbol(row.symbol),
      filedAt: String(row.filedAt),
      ...(row.acceptedAt ? { acceptedAt: String(row.acceptedAt) } : {}),
      accession: String(row.accession),
      ...(row.filingUrl ? { filingUrl: String(row.filingUrl) } : {}),
      ...(Array.isArray(row.items) ? { items: row.items.map(String).filter(Boolean) } : {})
    });
  }
  const rows = [...unique.values()];
  if (!preserveOrder) {
    rows.sort((a, b) => b.filedAt.localeCompare(a.filedAt) || b.accession.localeCompare(a.accession));
  }
  return rows.slice(0, max);
}

function persistEightKFullBodyBacklog(events: EightKEvent[]): EightKEvent[] {
  return persistEightKBacklog(FULL_BODY_BACKLOG_KEY, events, fullBodyBacklogMax(), "full-body", true);
}

export function getEightKSummaryBacklog(): EightKEvent[] {
  return readEightKBacklog(SUMMARY_BACKLOG_KEY, DEFAULT_SUMMARY_BACKLOG_MAX);
}

function persistEightKSummaryBacklog(events: EightKEvent[]): EightKEvent[] {
  return persistEightKBacklog(SUMMARY_BACKLOG_KEY, events, DEFAULT_SUMMARY_BACKLOG_MAX, "summary");
}

function persistEightKBacklog(
  key: string,
  events: EightKEvent[],
  max: number,
  kind: "summary" | "full-body",
  preserveOrder = false
): EightKEvent[] {
  const { rows: bounded, dropped } = prepareEightKBacklog(events, max, preserveOrder);
  setInternalSetting(key, bounded);
  if (dropped > 0) audit("sec8k_rag_backlog_truncated", { kind, dropped, retained: bounded.length });
  return bounded;
}

function prepareEightKBacklog(
  events: EightKEvent[],
  max: number,
  preserveOrder = false
): { rows: EightKEvent[]; dropped: number } {
  const unique = new Map<string, EightKEvent>();
  for (const event of events) unique.set(event.accession, event);
  const ordered = [...unique.values()];
  if (!preserveOrder) {
    ordered.sort((a, b) => b.filedAt.localeCompare(a.filedAt) || b.accession.localeCompare(a.accession));
  }
  const bounded = ordered.slice(0, max);
  const dropped = ordered.length - bounded.length;
  return { rows: bounded, dropped };
}

/**
 * Commit discovery and both durable RAG queues in one SQLite transaction. The previous ordering
 * wrote the dataset first and enqueued only afterward, so a process crash in that gap could lose an
 * accession for the full refresh cadence (or forever once it fell out of the current feed).
 */
function persistEightKDiscovery(
  dataset: EightKDataset,
  fresh: EightKEvent[],
  includeFullBodies: boolean,
  triggerUserIds: string[],
  materialEvents: MaterialEvent[],
  nowMs: number
): void {
  const summary = prepareEightKBacklog(
    [...getEightKSummaryBacklog(), ...fresh],
    DEFAULT_SUMMARY_BACKLOG_MAX
  );
  const body = includeFullBodies
    ? prepareEightKBacklog(
        [...getEightKFullBodyBacklog(), ...fresh],
        fullBodyBacklogMax(),
        true
      )
    : { rows: [] as EightKEvent[], dropped: 0 };
  const nowIso = new Date().toISOString();
  const database = getDb();
  const upsert = database.prepare(
    "INSERT INTO settings (key, value, updated_at) VALUES (?, ?, ?) " +
    "ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at"
  );
  database.transaction(() => {
    upsert.run(DATASET_KEY, JSON.stringify(dataset), nowIso);
    upsert.run(SUMMARY_BACKLOG_KEY, JSON.stringify(summary.rows), nowIso);
    if (includeFullBodies) {
      upsert.run(FULL_BODY_BACKLOG_KEY, JSON.stringify(body.rows), nowIso);
    }
    enqueueMaterialEventsForUsersTx(database, triggerUserIds, materialEvents, nowMs);
  }).immediate();

  if (summary.dropped > 0) {
    audit("sec8k_rag_backlog_truncated", {
      kind: "summary",
      dropped: summary.dropped,
      retained: summary.rows.length
    });
  }
  if (body.dropped > 0) {
    audit("sec8k_rag_backlog_truncated", {
      kind: "full-body",
      dropped: body.dropped,
      retained: body.rows.length
    });
  }
}

function hasEightKRagBacklog(): boolean {
  return getEightKSummaryBacklog().length > 0 ||
    (eightKFullBodyEnabled() && getEightKFullBodyBacklog().length > 0);
}

// ── Pure parsers (unit-tested) ───────────────────────────────────────────────

/** Parse the current-8-K atom feed into {cik, accession, filedAt, filingUrl} rows. */
export function parseCurrent8KFeed(atomXml: string): Array<{ cik: string; accession: string; filedAt?: string; acceptedAt?: string; filingUrl?: string }> {
  const out: Array<{ cik: string; accession: string; filedAt?: string; acceptedAt?: string; filingUrl?: string }> = [];
  const seen = new Set<string>();
  for (const entry of atomXml.split(/<entry>/i).slice(1)) {
    const title = entry.match(/<title>([\s\S]*?)<\/title>/i)?.[1] ?? "";
    const cik = title.match(/\((\d{4,10})\)/)?.[1];
    const link = entry.match(/href="([^"]+)"/i)?.[1] ?? "";
    const accession = link.match(/(\d{10}-\d{2}-\d{6})/)?.[1];
    const updated = entry.match(/<updated>([\s\S]*?)<\/updated>/i)?.[1];
    if (!cik || !accession || seen.has(accession)) continue;
    seen.add(accession);
    const acceptedAt = updated && Number.isFinite(Date.parse(updated))
      ? new Date(updated).toISOString()
      : undefined;
    out.push({
      cik: String(Number(cik)),
      accession,
      filedAt: acceptedAt?.slice(0, 10),
      acceptedAt,
      filingUrl: link
    });
  }
  return out;
}

/** Parse SEC company_tickers.json into a numeric-CIK-string -> ticker map. */
export function parseCikTickerMap(json: unknown): Record<string, string> {
  const map: Record<string, string> = {};
  const rows = json && typeof json === "object" ? Object.values(json as Record<string, unknown>) : [];
  for (const row of rows) {
    const r = row as { cik_str?: number | string; ticker?: string };
    if (r?.cik_str == null || !r.ticker) continue;
    map[String(Number(r.cik_str))] = normalizeSymbol(r.ticker);
  }
  return map;
}

/**
 * Parse SEC company_tickers.json into a ticker -> numeric-CIK-string map. Unlike parseCikTickerMap
 * (which collapses each CIK to ONE ticker), this keeps EVERY ticker, so dual-class names that share a
 * CIK (e.g. GOOGL & GOOG) both resolve to their CIK.
 */
export function parseTickerCikMap(json: unknown): Record<string, string> {
  const map: Record<string, string> = {};
  const rows = json && typeof json === "object" ? Object.values(json as Record<string, unknown>) : [];
  for (const row of rows) {
    const r = row as { cik_str?: number | string; ticker?: string };
    if (r?.cik_str == null || !r.ticker) continue;
    const ticker = normalizeSymbol(r.ticker);
    if (ticker) map[ticker] = String(Number(r.cik_str));
  }
  return map;
}

// ── Read API ─────────────────────────────────────────────────────────────────

export interface EightKSignal {
  count: number;
  lastFiledAt?: string;
  bulletin: string;
}

export function getEightKSignals(symbols: string[], now: number = Date.now()): Record<string, EightKSignal> {
  const dataset = getEightKDataset();
  if (!dataset?.events?.length) return {};
  const wanted = new Set(symbols.map(normalizeSymbol).filter(Boolean));
  const cutoff = now - windowDays() * 24 * 60 * 60_000;
  const bySymbol = new Map<string, EightKEvent[]>();
  for (const e of dataset.events) {
    if (!wanted.has(e.symbol)) continue;
    const ts = Date.parse(e.filedAt);
    if (Number.isFinite(ts) && ts < cutoff) continue;
    (bySymbol.get(e.symbol) ?? bySymbol.set(e.symbol, []).get(e.symbol)!).push(e);
  }
  const out: Record<string, EightKSignal> = {};
  for (const [symbol, events] of bySymbol) {
    events.sort((a, b) => Date.parse(b.filedAt) - Date.parse(a.filedAt));
    const last = events[0]?.filedAt;
    const items = events.flatMap((event) => event.items ?? []).slice(0, 3);
    const itemText = items.length > 0 ? ` Items: ${items.join("; ")}.` : "";
    out[symbol] = {
      count: events.length,
      lastFiledAt: last,
      bulletin: `Catalyst: ${symbol} filed ${events.length > 1 ? `${events.length} 8-Ks` : "an 8-K"} (material event) ${last ? `on ${last}` : "recently"}.${itemText} Check for fresh news.`
    };
  }
  return out;
}

// ── Refresh ──────────────────────────────────────────────────────────────────

function isEightKDiscoveryDue(now: number = Date.now()): boolean {
  const lastAttempt = getInternalSetting<unknown>(ATTEMPT_KEY);
  if (isValidPersistedTimestamp(lastAttempt) && now - Date.parse(lastAttempt) < retryBackoffMs()) return false;
  const ds = getEightKDataset();
  if (!isValidPersistedTimestamp(ds?.fetchedAt)) return true;
  return now - Date.parse(ds.fetchedAt) >= eightKTtlMs();
}

/** Scheduler admission includes durable delivery work even when SEC discovery cadence is not due. */
export function isEightKRefreshDue(now: number = Date.now()): boolean {
  return isEightKDiscoveryDue(now) || hasEightKRagBacklog() || hasDurableMaterialTriggerWork();
}

// Shared in-flight promises for the cold company_tickers.json fetch. Both maps derive from the SAME
// SEC file; without these guards, concurrent scans (or repeated dashboard refreshes) that all miss the
// weekly cache would each fire a duplicate request and defeat SEC fair-access throttling. A pending load
// is shared across callers and cleared once settled, so a later cache expiry re-fetches.
let cikMapInFlight: Promise<Record<string, string>> | null = null;
let tickerCikMapInFlight: Promise<Record<string, string>> | null = null;

/** Load the CIK→ticker map, cached weekly in the settings KV. */
export async function loadCikMap(now: number): Promise<Record<string, string>> {
  const cached = getInternalSetting<{ map: Record<string, string>; fetchedAt: string }>(CIK_KEY);
  if (cached?.map && cached.fetchedAt && now - Date.parse(cached.fetchedAt) < CIK_TTL_MS) return cached.map;
  if (cikMapInFlight) return cikMapInFlight;
  cikMapInFlight = (async () => {
    const json = JSON.parse(await politeFetchText(`${SEC_BASE}/files/company_tickers.json`, { headers: { "user-agent": secUserAgent() } }));
    const map = parseCikTickerMap(json);
    if (Object.keys(map).length > 0) setInternalSetting(CIK_KEY, { map, fetchedAt: new Date(now).toISOString() });
    return map;
  })();
  try {
    return await cikMapInFlight;
  } finally {
    cikMapInFlight = null;
  }
}

const TICKER_CIK_KEY = "webSource:sec:tickerCikMap";

/** Load the ticker→CIK map (preserves dual-class tickers), cached weekly in the settings KV. */
export async function loadTickerCikMap(now: number): Promise<Record<string, string>> {
  const cached = getInternalSetting<{ map: Record<string, string>; fetchedAt: string }>(TICKER_CIK_KEY);
  if (cached?.map && cached.fetchedAt && now - Date.parse(cached.fetchedAt) < CIK_TTL_MS) return cached.map;
  if (tickerCikMapInFlight) return tickerCikMapInFlight;
  tickerCikMapInFlight = (async () => {
    const json = JSON.parse(await politeFetchText(`${SEC_BASE}/files/company_tickers.json`, { headers: { "user-agent": secUserAgent() } }));
    const map = parseTickerCikMap(json);
    if (Object.keys(map).length > 0) setInternalSetting(TICKER_CIK_KEY, { map, fetchedAt: new Date(now).toISOString() });
    return map;
  })();
  try {
    return await tickerCikMapInFlight;
  } finally {
    tickerCikMapInFlight = null;
  }
}

export function mergeEightK(existing: EightKEvent[], fresh: EightKEvent[], now: number, window = windowDays()): EightKEvent[] {
  const cutoff = now - window * 24 * 60 * 60_000;
  const byAccession = new Map<string, EightKEvent>();
  for (const e of [...existing, ...fresh]) {
    const ts = Date.parse(e.filedAt);
    if (Number.isFinite(ts) && ts < cutoff) continue;
    byAccession.set(e.accession, e);
  }
  return Array.from(byAccession.values());
}

function absoluteSecUrl(url?: string): string | undefined {
  if (!url) return undefined;
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith("/")) return `${SEC_BASE}${url}`;
  return `${SEC_BASE}/${url}`;
}

function decodeXmlEntities(value: string): string {
  return value
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">");
}

export function parseEightKItemsFromHtml(html: string): string[] {
  const items = new Set<string>();
  const infoBlocks = html.match(/<div[^>]*class=["']info["'][^>]*>[\s\S]*?<\/div>/gi) ?? [];
  for (const block of infoBlocks) {
    const text = decodeXmlEntities(block.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim());
    for (const match of text.matchAll(/Item\s+\d+\.\d{2}\s+[^;.]+/gi)) {
      items.add(match[0].trim());
    }
  }
  for (const match of html.matchAll(/Item\s+\d+\.\d{2}\s+[^<\n\r;.]+/gi)) {
    items.add(decodeXmlEntities(match[0].replace(/\s+/g, " ").trim()));
  }
  return Array.from(items).slice(0, 8);
}

async function enrichEightKEvents(events: EightKEvent[]): Promise<EightKEvent[]> {
  const limit = Number(process.env.WEB_SOURCE_SEC8K_DETAIL_LIMIT ?? 25);
  const maxDetails = Number.isFinite(limit) && limit > 0 ? limit : 25;
  const slice = events.slice(0, maxDetails);
  const enriched = await runRateLimited(slice, 250, async (event) => {
    const url = absoluteSecUrl(event.filingUrl);
    if (!url) return event;
    try {
      const html = await politeFetchText(url, { headers: { "user-agent": secUserAgent(), accept: "text/html" } });
      const items = parseEightKItemsFromHtml(html);
      return items.length > 0 ? { ...event, filingUrl: url, items } : { ...event, filingUrl: url };
    } catch {
      return { ...event, filingUrl: url };
    }
  });
  return [...enriched, ...events.slice(maxDetails)];
}

// 8-K item codes that are genuinely tradeable-material (expert panel). Most 8-Ks (5.07 votes,
// 9.01 exhibits, 5.03 bylaws, routine 8.01 PR) are noise and intentionally excluded.
const MATERIAL_8K_ITEMS = new Set(["1.01", "1.02", "1.03", "2.01", "2.02", "4.01", "4.02", "5.02"]);

export function eightKHasMaterialItem(event: EightKEvent): boolean {
  const items = event.items ?? [];
  for (const item of items) {
    const code = item.match(/(\d+\.\d{2})/)?.[1];
    if (code && MATERIAL_8K_ITEMS.has(code)) return true;
  }
  return false;
}

export function buildEightKContext(event: EightKEvent): string {
  return [
    `SEC 8-K filing for ${event.symbol}.`,
    `Filed: ${event.filedAt}.`,
    `Accession: ${event.accession}.`,
    event.items?.length ? `Reported item(s): ${event.items.join("; ")}.` : "Reported item(s): not available from the filing summary page.",
    event.filingUrl ? `SEC filing page: ${event.filingUrl}.` : "",
    "Use this as catalyst context only; infer bullish/bearish impact from item details and other market evidence."
  ].filter(Boolean).join("\n");
}

/**
 * Re-embed the *persisted* 8-K dataset into vector memory. Unlike a normal refresh (which only
 * embeds newly-`fresh` filings), this backfills everything already stored — the path used to
 * recover after the Voyage-billing 429 left the Pinecone index empty. Returns the embed/upsert
 * outcome so a caller (e.g. the reindex route) can confirm `indexed > 0`.
 */
export interface ReindexEightKResult {
  attempted: number;
  indexed: number;
  error?: string;
  skipped?: boolean;
}

export async function reindexEightKDataset(
  userId: string = "local",
  limit: number = Number.POSITIVE_INFINITY,
  operationLeaseClaim?: OperationLeaseClaim
): Promise<OperationLeaseAware<ReindexEightKResult>> {
  const guarded = await runWithOperationLease(
    {
      group: OPERATION_LEASE_GROUPS.RAG_REINDEX,
      operation: "reindex-8k",
      claim: operationLeaseClaim
    },
    async (claim, signal) => reindexEightKDatasetUnlocked(userId, limit, claim, signal)
  );
  if (!guarded.acquired) {
    return { attempted: 0, indexed: 0, skipped: true, operationLease: guarded.busy };
  }
  return guarded.value;
}

async function reindexEightKDatasetUnlocked(
  userId: string,
  limit: number,
  operationLeaseClaim: OperationLeaseClaim,
  operationLeaseSignal: AbortSignal
): Promise<ReindexEightKResult> {
  assertOperationLeaseOwnership(operationLeaseClaim);
  const dataset = getEightKDataset();
  const events = dataset?.events ?? [];
  if (events.length === 0) return { attempted: 0, indexed: 0 };
  const cap = Number.isFinite(limit) && limit > 0 ? Math.floor(limit) : events.length;
  const slice = events.slice(0, cap);
  const { storeContexts } = await import("../vector-db");
  const result = await storeContexts(
    slice.map((event) => ({
      text: buildEightKContext(event),
      metadata: {
        symbol: event.symbol,
        source: "sec-8k",
        timestamp: event.filedAt,
        // Point-in-time anchor so retrieveContextDetailed({asOf}) can exclude look-ahead filings.
        acceptance_datetime: event.acceptedAt ?? event.filedAt,
        doc_type: "8-k",
        accession: event.accession,
        filingUrl: event.filingUrl,
        items: event.items ?? []
      }
    })),
    userId,
    {
      leaseGuard: {
        signal: operationLeaseSignal,
        assertOwnership: () => {
          throwIfOperationLeaseCancelled(operationLeaseSignal);
          assertOperationLeaseOwnership(operationLeaseClaim);
        }
      }
    }
  );
  throwIfOperationLeaseCancelled(operationLeaseSignal);
  return result;
}

export async function refreshEightK(
  now: number = Date.now(),
  force = false,
  operationLeaseClaim?: OperationLeaseClaim
): Promise<OperationLeaseAware<import("./types").WebSourceRefreshResult>> {
  const discoveryDue = force || isEightKDiscoveryDue(now);
  // Discovery cadence must not gate durable delivery. A prior tick may have committed the dataset
  // and backlog and then crashed/been RAG-busy before embedding it.
  if (!discoveryDue && !hasEightKRagBacklog() && !hasDurableMaterialTriggerWork()) {
    const ds = getEightKDataset();
    return { id: "sec8k", ok: true, recordCount: ds?.recordCount ?? 0, sources: ds ? ["sec-edgar"] : [], fetchedAt: ds?.fetchedAt ?? "", skipped: true };
  }

  const guarded = await runWithOperationLease(
    {
      group: OPERATION_LEASE_GROUPS.SEC8K_WEB_SOURCE,
      operation: discoveryDue ? "refresh-websource:sec8k" : "drain-websource:sec8k-rag",
      claim: operationLeaseClaim
    },
    async (claim, signal) => refreshEightKUnlocked(now, force, claim, signal)
  );
  if (!guarded.acquired) {
    const ds = getEightKDataset();
    return {
      id: "sec8k",
      ok: true,
      recordCount: ds?.recordCount ?? 0,
      sources: ds ? ["sec-edgar"] : [],
      fetchedAt: ds?.fetchedAt ?? "",
      skipped: true,
      warning: `Skipped because ${guarded.busy.activeOperation} is already refreshing the SEC 8-K dataset.`,
      operationLease: guarded.busy
    };
  }
  return guarded.value;
}

async function refreshEightKUnlocked(
  now: number,
  force: boolean,
  operationLeaseClaim: OperationLeaseClaim,
  operationLeaseSignal: AbortSignal
): Promise<import("./types").WebSourceRefreshResult> {
  // Recheck after durable acquisition so a delayed scheduler process cannot repeat discovery after
  // the prior owner advanced the cadence. Backlog delivery remains independently due every tick.
  const discoveryDue = force || isEightKDiscoveryDue(now);
  if (!discoveryDue && !hasEightKRagBacklog() && !hasDurableMaterialTriggerWork()) {
    const ds = getEightKDataset();
    return { id: "sec8k", ok: true, recordCount: ds?.recordCount ?? 0, sources: ds ? ["sec-edgar"] : [], fetchedAt: ds?.fetchedAt ?? "", skipped: true };
  }
  assertOperationLeaseOwnership(operationLeaseClaim);

  const prior = getEightKDataset();
  let dataset = prior;
  let fresh: EightKEvent[] = [];
  let warning: string | undefined;
  if (discoveryDue) {
    setInternalSetting(ATTEMPT_KEY, new Date(now).toISOString());
    try {
      const cikMap = await loadCikMap(now);
      throwIfOperationLeaseCancelled(operationLeaseSignal);
      assertOperationLeaseOwnership(operationLeaseClaim);
      const feed = await politeFetchText(
        `${SEC_BASE}/cgi-bin/browse-edgar?action=getcurrent&type=8-K&count=100&output=atom`,
        { headers: { "user-agent": secUserAgent(), accept: "application/atom+xml" } }
      );
      throwIfOperationLeaseCancelled(operationLeaseSignal);
      assertOperationLeaseOwnership(operationLeaseClaim);
      fresh = parseCurrent8KFeed(feed)
        .map((row): EightKEvent | undefined => {
          const symbol = cikMap[row.cik];
          if (!symbol) return undefined;
          return {
            symbol,
            filedAt: row.filedAt ?? new Date(now).toISOString().slice(0, 10),
            ...(row.acceptedAt ? { acceptedAt: row.acceptedAt } : {}),
            accession: row.accession,
            ...(row.filingUrl ? { filingUrl: row.filingUrl } : {})
          };
        })
        .filter((event): event is EightKEvent => Boolean(event));
      fresh = await enrichEightKEvents(fresh);
      throwIfOperationLeaseCancelled(operationLeaseSignal);
      assertOperationLeaseOwnership(operationLeaseClaim);
    } catch (error) {
      throwIfOperationLeaseCancelled(operationLeaseSignal);
      assertOperationLeaseOwnership(operationLeaseClaim);
      warning = error instanceof Error ? error.message : "sec8k failed";
    }

    const merged = mergeEightK(prior?.events ?? [], fresh, now);
    if (merged.length > 0) {
      const fetchedAt = fresh.length > 0
        ? new Date(now).toISOString()
        : (prior?.fetchedAt ?? new Date(now).toISOString());
      dataset = { events: merged, fetchedAt, recordCount: merged.length };
      assertOperationLeaseOwnership(operationLeaseClaim);
      if (fresh.length > 0) {
        const materialEvents: MaterialEvent[] = fresh
          .filter(eightKHasMaterialItem)
          .map((event) => ({
            type: "sec8k",
            symbol: event.symbol,
            sourceId: event.accession,
            reason: `8-K ${event.items?.[0] ?? ""}`.trim()
          }));
        const triggerUserIds = materialEvents.length > 0 ? eligibleMaterialTriggerUserIds() : [];
        // This is the durability boundary: discovery and every enabled downstream queue become
        // visible together, before any trigger/provider work can fail.
        persistEightKDiscovery(
          dataset,
          fresh,
          eightKFullBodyEnabled(),
          triggerUserIds,
          materialEvents,
          now
        );
      } else {
        setInternalSetting(DATASET_KEY, dataset);
      }
      assertOperationLeaseOwnership(operationLeaseClaim);
    }
    audit("web_source_refresh", {
      id: "sec8k",
      ok: fresh.length > 0,
      recordCount: dataset?.recordCount ?? 0,
      fresh: fresh.length,
      warning
    });
  }

  const ragWarning = await drainEightKRagBacklogs(now, operationLeaseClaim, operationLeaseSignal);
  let triggerWarning: string | undefined;
  try {
    assertOperationLeaseOwnership(operationLeaseClaim);
    const { drainMaterialEventQueue } = await import("../triggers");
    drainMaterialEventQueue();
    assertOperationLeaseOwnership(operationLeaseClaim);
  } catch (error) {
    throwIfOperationLeaseCancelled(operationLeaseSignal);
    assertOperationLeaseOwnership(operationLeaseClaim);
    triggerWarning = `8-K material trigger deferred: ${error instanceof Error ? error.message : String(error)}`;
  }
  const ok = discoveryDue ? fresh.length > 0 : true;
  if (!dataset && !hasEightKRagBacklog() && !hasDurableMaterialTriggerWork()) {
    return {
      id: "sec8k",
      ok: false,
      recordCount: 0,
      sources: [],
      fetchedAt: "",
      warning: [warning ?? "no events", ragWarning, triggerWarning].filter(Boolean).join("; ") || undefined,
      ...(!discoveryDue ? { skipped: true } : {})
    };
  }

  return {
    id: "sec8k",
    ok,
    recordCount: dataset?.recordCount ?? 0,
    sources: dataset ? ["sec-edgar"] : [],
    fetchedAt: dataset?.fetchedAt ?? "",
    warning: [warning, ragWarning, triggerWarning].filter(Boolean).join("; ") || undefined,
    ...(!discoveryDue ? { skipped: true } : {})
  };
}

async function drainEightKRagBacklogs(
  now: number,
  operationLeaseClaim: OperationLeaseClaim,
  operationLeaseSignal: AbortSignal
): Promise<string | undefined> {
  const summaryBacklog = getEightKSummaryBacklog();
  const bodyBacklog = eightKFullBodyEnabled() ? getEightKFullBodyBacklog() : [];
  if (summaryBacklog.length === 0 && bodyBacklog.length === 0) return undefined;

  try {
    const ragGuarded = await runWithOperationLease(
      { group: OPERATION_LEASE_GROUPS.RAG_REINDEX, operation: "refresh-sec8k-rag" },
      async (ragClaim, ragSignal) => {
        const warnings: string[] = [];
        const combinedSignal = AbortSignal.any([operationLeaseSignal, ragSignal]);
        const assertRagOwnership = () => {
          throwIfOperationLeaseCancelled(combinedSignal);
          assertOperationLeaseOwnership(operationLeaseClaim);
          assertOperationLeaseOwnership(ragClaim);
        };
        const leaseGuard: VectorStoreLeaseGuard = {
          signal: combinedSignal,
          assertOwnership: assertRagOwnership
        };
        assertRagOwnership();
        const ragEvents = summaryBacklog.slice(0, eightKRagLimit());
        if (ragEvents.length > 0) {
          const { storeContexts } = await import("../vector-db");
          assertRagOwnership();
          const summaryResult = await storeContexts(
            ragEvents.map((event) => ({
              text: buildEightKContext(event),
              metadata: {
                symbol: event.symbol,
                source: "sec-8k",
                timestamp: event.filedAt,
                acceptance_datetime: event.acceptedAt ?? event.filedAt,
                doc_type: "8-k",
                accession: event.accession,
                filingUrl: event.filingUrl,
                items: event.items ?? []
              }
            })),
            "local",
            {
              ...(storeContextsDedupEnabled() ? { dedupKeyPrefix: "sec8k-summary" } : {}),
              leaseGuard
            }
          );
          assertRagOwnership();
          const exactWrite =
            summaryResult.attempted === ragEvents.length &&
            summaryResult.indexed === ragEvents.length;
          const summaryComplete =
            !summaryResult.error &&
            summaryResult.unconfigured !== true &&
            (summaryResult.budgetSkipped ?? 0) === 0 &&
            (summaryResult.writeUnitBudgetSkipped ?? 0) === 0 &&
            (summaryResult.rejectedInvalidEmbeddings ?? 0) === 0 &&
            (exactWrite || summaryResult.dedupComplete === true);
          if (summaryComplete) {
            const completed = new Set(ragEvents.map((event) => event.accession));
            persistEightKSummaryBacklog(summaryBacklog.filter((event) => !completed.has(event.accession)));
            assertRagOwnership();
          } else {
            warnings.push(`8-K summary RAG deferred${summaryResult.error ? `: ${summaryResult.error}` : " by RAG capacity"}`);
          }
        }

        if (bodyBacklog.length > 0) {
          const bodyLimit = Number(process.env.WEB_SOURCE_SEC8K_FULL_BODY_LIMIT ?? DEFAULT_SEC8K_FULL_BODY_LIMIT);
          const cap = Number.isFinite(bodyLimit) && bodyLimit > 0
            ? Math.floor(bodyLimit)
            : DEFAULT_SEC8K_FULL_BODY_LIMIT;
          const bodyBatch = bodyBacklog.slice(0, cap);
          const bodyResult = await ingestEightKBodies(bodyBatch, now, leaseGuard);
          assertRagOwnership();
          const completed = new Set(bodyResult.completedAccessions);
          const attemptedPrefix = bodyBatch.slice(0, bodyResult.attempted);
          const notAttempted = [
            ...bodyBatch.slice(bodyResult.attempted),
            ...bodyBacklog.slice(bodyBatch.length)
          ];
          const retryLater = attemptedPrefix.filter((event) => !completed.has(event.accession));
          // Rotate retryable failures behind never-attempted work so one permanent bad filing cannot
          // starve the bounded queue. Duplicate accessions from the next SEC feed preserve this order.
          persistEightKFullBodyBacklog([...notAttempted, ...retryLater]);
          assertRagOwnership();
          if (bodyResult.errors.length > 0) {
            warnings.push(`8-K full-body deferred (${bodyResult.errors.length} error(s))`);
          } else if (bodyResult.capacityExhausted) {
            warnings.push("8-K full-body deferred by RAG capacity");
          }
        }
        assertRagOwnership();
        return warnings;
      }
    );
    if (!ragGuarded.acquired) {
      return `8-K RAG deferred because ${ragGuarded.busy.activeOperation} owns the shared ingest lease.`;
    }
    return ragGuarded.value.join("; ") || undefined;
  } catch (error) {
    // Provider/RAG failures leave the durable queue untouched. Only loss of the outer SEC owner is
    // terminal; do not disguise it as a retryable provider warning.
    throwIfOperationLeaseCancelled(operationLeaseSignal);
    assertOperationLeaseOwnership(operationLeaseClaim);
    return `8-K RAG deferred: ${error instanceof Error ? error.message : String(error)}`;
  }
}

// ── 8-K full-body ingest (gated behind WEB_SOURCE_SEC8K_FULL_BODY) ───────────

const DEFAULT_SEC8K_FULL_BODY_LIMIT = 5;

function assertEightKIngestLease(leaseGuard?: VectorStoreLeaseGuard): void {
  if (leaseGuard?.signal) throwIfOperationLeaseCancelled(leaseGuard.signal);
  leaseGuard?.assertOwnership();
}

/** Whether full 8-K body ingestion is enabled (default OFF). */
export function eightKFullBodyEnabled(): boolean {
  const v = String(process.env.WEB_SOURCE_SEC8K_FULL_BODY ?? "off").trim().toLowerCase();
  return ["1", "true", "on", "yes"].includes(v);
}

/**
 * Fetch the full 8-K filing body for one event, chunk it via storeDocument, and record
 * the accession in ingested_accessions so the same filing is never re-fetched.
 *
 * Only calls storeDocument when the accession isn't already in ingested_accessions.
 * Returns the number of chunks indexed (0 = skipped or failed).
 */
export async function ingestEightKBody(
  event: EightKEvent,
  _now: number = Date.now(),
  leaseGuard?: VectorStoreLeaseGuard
): Promise<{
  skipped: boolean;
  chunks: number;
  error?: string;
  completed?: boolean;
  retryable?: boolean;
  capacityExhausted?: boolean;
}> {
  assertEightKIngestLease(leaseGuard);
  if (hasIngestedAccession(event.accession, "8-K-body")) {
    return { skipped: true, chunks: 0, completed: true };
  }

  const url = absoluteSecUrl(event.filingUrl);
  if (!url) {
    return { skipped: false, chunks: 0, error: "no filing URL", retryable: true };
  }
  const vectorDb = await import("../vector-db");
  assertEightKIngestLease(leaseGuard);
  if (!vectorDb.hasIngestTextBudget("local")) {
    return { skipped: true, chunks: 0, retryable: true, capacityExhausted: true };
  }

  let html: string;
  try {
    assertEightKIngestLease(leaseGuard);
    html = await politeFetchText(url, {
      headers: { "user-agent": secUserAgent(), accept: "text/html,application/xhtml+xml" },
      timeoutMs: 30_000
    });
    assertEightKIngestLease(leaseGuard);
  } catch (err) {
    assertEightKIngestLease(leaseGuard);
    return { skipped: false, chunks: 0, error: `fetch failed: ${err instanceof Error ? err.message : String(err)}`, retryable: true };
  }

  const text = extractFilingText(html);
  if (text.length < 100) {
    return { skipped: false, chunks: 0, error: "extracted text too short", retryable: true };
  }

  // Insert into sec_artifacts
  try {
    assertEightKIngestLease(leaseGuard);
    const { createHash } = await import("crypto");
    assertEightKIngestLease(leaseGuard);
    const sha256 = createHash("sha256").update(html).digest("hex");
    const byteCount = Buffer.byteLength(html, "utf8");
    const { insertSecArtifact } = await import("../db");
    assertEightKIngestLease(leaseGuard);
    insertSecArtifact({
      accession: event.accession,
      sequence: 1,
      documentName: "main.html",
      sha256,
      type: "html",
      byteCount,
      rawUri: url,
      parserVersion: "v1"
    });
    assertEightKIngestLease(leaseGuard);
  } catch (err) {
    // Artifact persistence remains best-effort for ordinary SQLite errors, but a stale owner must
    // stop immediately rather than continuing into the vector write.
    assertEightKIngestLease(leaseGuard);
    console.warn(`[sec8k] insertSecArtifact failed for ${event.accession} (non-fatal):`, err instanceof Error ? err.message : String(err));
  }

  assertEightKIngestLease(leaseGuard);
  const result = await vectorDb.storeDocument(
    {
      text,
      doc_id: event.accession,
      ticker: event.symbol,
      title: `${event.symbol} 8-K (${event.filedAt})`,
      doc_type: "8-k",
      published_at: event.filedAt,
      acceptance_datetime: event.acceptedAt ?? event.filedAt,
      source: "sec-8k",
      url
    },
    "local",
    {
      parserRevision: "sec8k-full-body-v1",
      ...(leaseGuard ? { leaseGuard } : {})
    }
  );
  assertEightKIngestLease(leaseGuard);

  if (result.error) {
    return { skipped: false, chunks: result.indexed, error: result.error, retryable: true };
  }

  const outOfCapacity =
    result.unconfigured === true ||
    (result.budgetSkipped ?? 0) > 0 ||
    (result.writeUnitBudgetSkipped ?? 0) > 0;
  const reusedCommitted =
    result.reusedCommitted === true && result.documentComplete === true && result.attempted > 0;
  if (
    outOfCapacity ||
    result.attempted <= 0 ||
    result.documentComplete !== true ||
    (!reusedCommitted && result.indexed !== result.attempted)
  ) {
    // Keep the accession retryable. A no-error partial/budget result is not a completed source
    // document and must never suppress a later full occurrence write.
    return {
      skipped: true,
      chunks: result.indexed,
      retryable: true,
      ...(outOfCapacity ? { capacityExhausted: true } : {})
    };
  }
  if (!result.managedCommitProof) {
    return { skipped: true, chunks: result.indexed, error: "document-commit-proof-missing", retryable: true };
  }

  try {
    assertEightKIngestLease(leaseGuard);
    runWithActiveVectorCommitProof(result.managedCommitProof, () => {
      insertIngestedAccession(event.accession, "8-K-body", event.symbol, result.attempted);
    });
  } catch {
    return { skipped: true, chunks: result.indexed, error: "document-commit-proof-lost", retryable: true };
  }
  return { skipped: false, chunks: result.attempted, completed: true };
}

/**
 * Ingest full 8-K bodies for multiple events sequentially (respects EDGAR fair-use).
 * Never throws — errors are logged and aggregated.
 */
export async function ingestEightKBodies(
  events: EightKEvent[],
  now: number = Date.now(),
  leaseGuard?: VectorStoreLeaseGuard
): Promise<{
  attempted: number;
  ingested: number;
  skipped: number;
  errors: string[];
  completedAccessions: string[];
  deferredAccessions: string[];
  capacityExhausted: boolean;
}> {
  const result = {
    attempted: 0,
    ingested: 0,
    skipped: 0,
    errors: [] as string[],
    completedAccessions: [] as string[],
    deferredAccessions: [] as string[],
    capacityExhausted: false
  };
  for (let index = 0; index < events.length; index += 1) {
    const event = events[index]!;
    assertEightKIngestLease(leaseGuard);
    result.attempted++;
    try {
      const ingestResult = await ingestEightKBody(event, now, leaseGuard);
      if (ingestResult.completed) {
        result.completedAccessions.push(event.accession);
        if (ingestResult.skipped) result.skipped++;
        else result.ingested++;
      } else {
        if (ingestResult.skipped) result.skipped++;
        result.deferredAccessions.push(event.accession);
      }
      if (ingestResult.error) {
        result.errors.push(`${event.symbol} ${event.accession}: ${ingestResult.error}`);
      }
      if (ingestResult.capacityExhausted) {
        result.capacityExhausted = true;
        result.deferredAccessions.push(...events.slice(index + 1).map((item) => item.accession));
        break;
      }
      // Polite delay between EDGAR fetches
      if (index + 1 < events.length) {
        await sleep(300);
        assertEightKIngestLease(leaseGuard);
      }
    } catch (err) {
      assertEightKIngestLease(leaseGuard);
      result.deferredAccessions.push(event.accession);
      result.errors.push(`${event.symbol} ${event.accession}: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  return result;
}

