});

// asOf = Friday 2026-06-19. The 5-business-day window walks back Fri 6/19 → Mon 6/15 (inclusive).
const AS_OF = new Date("2026-06-19T18:00:00.000Z"); // 2pm EDT Fri

const policy: TradingPolicy = {
  ...DEFAULT_POLICY,
  systemState: "active",
  strategyAuthority: "decide",
  accountNumber: "LIVE1",
  includedIndices: [],
  additionalSymbols: ["AAPL", "MSFT", "NVDA", "TSLA"]
};

function portfolioWithEquity(equity: number, accountNumber = "LIVE1"): Portfolio {
  return {
    accountNumber,
    totalMarketValue: equity,
    buyingPower: equity,
    equityMarketValue: equity,
    optionMarketValue: 0,
    cash: equity
  };
}

const openingProposal: TradeProposal = {
  symbol: "AAPL",
  side: "buy",
  type: "market",
  dollarAmount: 100,
  timeInForce: "gfd",
  marketHours: "regular_hours",
  rationale: "test",
  tradeThesisTag: "test",
  entryMarketRegime: "test"
};

// Seed N distinct same-day round-trips (one symbol+day each) for an account, each on its own
// market day inside the 5-business-day window. Returns nothing — fills are persisted.
async function seedDayTrades(accountNumber: string, source: "live" | "paper", count: number) {
  const { insertFillEvent } = await import("../src/lib/db");
  // Each entry is a market day (NY) inside the window Mon 6/15 .. Fri 6/19; afternoon EDT timestamps.
  const days = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"];
  const symbols = ["AAPL", "MSFT", "NVDA", "TSLA", "AMD"];
  for (let i = 0; i < count; i += 1) {
    const day = days[i];
    const symbol = symbols[i];
    const open = `${day}T17:00:00.000Z`; // 1pm EDT
    const close = `${day}T18:30:00.000Z`; // 2:30pm EDT, same NY day
    insertFillEvent({
      id: `${accountNumber}-${symbol}-open`,
      accountNumber,
      source,
      symbol,
      side: "buy" as OrderSide,
      quantity: 1,
      price: 100,
      notional: 100,
      status: "filled",
      filledAt: open
    });
    insertFillEvent({
      id: `${accountNumber}-${symbol}-close`,
      accountNumber,
      source,
      symbol,
      side: "sell" as OrderSide,
      quantity: 1,
      price: 110,
      notional: 110,
      status: "filled",
      filledAt: close
    });
  }
}

describe("countDayTradesInLastBusinessDays", () => {
  it("counts a same-day round-trip per symbol+day and excludes orphan legs", async () => {
    const { insertFillEvent, countDayTradesInLastBusinessDays } = await import("../src/lib/db");
    const account = "COUNT1";
    // Two qualifying round-trips on two business days (buy+sell same NY day each).
    insertFillEvent({ id: "c1o", accountNumber: account, source: "live", symbol: "AAPL", side: "buy", quantity: 1, price: 100, notional: 100, status: "filled", filledAt: "2026-06-16T17:00:00.000Z" });
    insertFillEvent({ id: "c1c", accountNumber: account, source: "live", symbol: "AAPL", side: "sell", quantity: 1, price: 105, notional: 105, status: "filled", filledAt: "2026-06-16T18:00:00.000Z" });
    insertFillEvent({ id: "c2o", accountNumber: account, source: "live", symbol: "MSFT", side: "buy", quantity: 1, price: 200, notional: 200, status: "filled", filledAt: "2026-06-17T17:00:00.000Z" });
    insertFillEvent({ id: "c2c", accountNumber: account, source: "live", symbol: "MSFT", side: "sell", quantity: 1, price: 210, notional: 210, status: "filled", filledAt: "2026-06-17T18:00:00.000Z" });
    // Orphan: an open with no same-day close → NOT a day-trade.
    insertFillEvent({ id: "c3o", accountNumber: account, source: "live", symbol: "NVDA", side: "buy", quantity: 1, price: 50, notional: 50, status: "filled", filledAt: "2026-06-18T17:00:00.000Z" });
    // Different calendar days for the same symbol → buy on one day, sell on the next → NOT a day-trade.
    insertFillEvent({ id: "c4o", accountNumber: account, source: "live", symbol: "TSLA", side: "buy", quantity: 1, price: 60, notional: 60, status: "filled", filledAt: "2026-06-15T18:00:00.000Z" });
    insertFillEvent({ id: "c4c", accountNumber: account, source: "live", symbol: "TSLA", side: "sell", quantity: 1, price: 65, notional: 65, status: "filled", filledAt: "2026-06-16T15:00:00.000Z" });

    expect(countDayTradesInLastBusinessDays(account, 5, AS_OF)).toBe(2);
  });

  it("counts a short→cover same-day round-trip and respects the rolling window edge", async () => {
    const { insertFillEvent, countDayTradesInLastBusinessDays } = await import("../src/lib/db");
    const account = "COUNT2";
    // short→cover same NY day inside the window → a day-trade.
    insertFillEvent({ id: "s1o", accountNumber: account, source: "live", symbol: "AAPL", side: "short", quantity: 1, price: 100, notional: 100, status: "filled", filledAt: "2026-06-17T17:00:00.000Z" });
    insertFillEvent({ id: "s1c", accountNumber: account, source: "live", symbol: "AAPL", side: "cover", quantity: 1, price: 95, notional: 95, status: "filled", filledAt: "2026-06-17T18:00:00.000Z" });
    // A round-trip on Fri 6/12 — one business day BEFORE the window start (Mon 6/15) → excluded.
    insertFillEvent({ id: "s2o", accountNumber: account, source: "live", symbol: "MSFT", side: "buy", quantity: 1, price: 200, notional: 200, status: "filled", filledAt: "2026-06-12T17:00:00.000Z" });
    insertFillEvent({ id: "s2c", accountNumber: account, source: "live", symbol: "MSFT", side: "sell", quantity: 1, price: 205, notional: 205, status: "filled", filledAt: "2026-06-12T18:00:00.000Z" });

    expect(countDayTradesInLastBusinessDays(account, 5, AS_OF)).toBe(1);
  });
});

describe("evaluateTradeProposal — margin-minimum gate (PDT rule retired, FINRA Notice 26-10)", () => {
  // The Pattern-Day-Trader rule ($25k minimum + 4-day-trades-in-5-days) was retired by SEC/FINRA.
  // The replacement is broker-side real-time intraday margin + a $2,000 minimum for MARGIN accounts.
  // The gate now enforces ONLY that static minimum, on LIVE margin accounts, for opening legs.
  const caps = (marginEnabled: boolean): AccountCapabilities => ({
    equityTrading: true,
    shortSelling: false,
    optionsTrading: false,
    futuresTrading: false,
    cryptoTrading: false,
    marginEnabled,
    accountType: "brokerage"
  });

  function evaluate(opts: {
    equity: number;
    isLiveExecution?: boolean;
    marginEnabled?: boolean;
    proposal?: TradeProposal;
    accountNumber?: string;
  }) {
    return evaluateTradeProposal(opts.proposal ?? openingProposal, {
      policy: { ...policy, accountNumber: opts.accountNumber ?? "LIVE1" },
      portfolio: portfolioWithEquity(opts.equity, opts.accountNumber ?? "LIVE1"),
      positions: [],
      dailyNotionalUsed: 0,
      dailyOrderCount: 0,
      estimatedNotional: 100,
      isLiveExecution: opts.isLiveExecution,
      accountCapabilities: opts.marginEnabled === undefined ? undefined : caps(opts.marginEnabled)
    });
  }

  it("BLOCKS a LIVE margin opening order below the $2,000 minimum", () => {
    const decision = evaluate({ equity: MARGIN_MINIMUM_EQUITY - 1, isLiveExecution: true, marginEnabled: true });
    expect(decision.approved).toBe(false);
    expect(decision.reasons.some((r) => r.includes("margin_minimum"))).toBe(true);
  });

  it("does NOT block at or above the $2,000 minimum", () => {
    expect(evaluate({ equity: MARGIN_MINIMUM_EQUITY, isLiveExecution: true, marginEnabled: true }).reasons.some((r) => r.includes("margin_minimum"))).toBe(false);
    const ample = evaluate({ equity: 50_000, isLiveExecution: true, marginEnabled: true });
    expect(ample.reasons.some((r) => r.includes("margin_minimum"))).toBe(false);
    expect(ample.approved).toBe(true);
  });

  it("does NOT block a CASH (non-margin) account below $2,000", () => {
    const decision = evaluate({ equity: 1000, isLiveExecution: true, marginEnabled: false });
    expect(decision.reasons.some((r) => r.includes("margin_minimum"))).toBe(false);
  });

  it("does NOT block a paper/Test account (not live) regardless of equity or margin", () => {
    expect(evaluate({ equity: 100, isLiveExecution: undefined, marginEnabled: true }).reasons.some((r) => r.includes("margin_minimum"))).toBe(false);
    expect(evaluate({ equity: 100, isLiveExecution: false, marginEnabled: true }).reasons.some((r) => r.includes("margin_minimum"))).toBe(false);
    const paperHigh = evaluate({ equity: 100_000, isLiveExecution: false, marginEnabled: true });
    expect(paperHigh.reasons.some((r) => r.includes("margin_minimum"))).toBe(false);
    expect(paperHigh.approved).toBe(true);
  });

  it("never blocks a CLOSING order (sell) on the margin minimum", () => {
    const sell: TradeProposal = { ...openingProposal, symbol: "AAPL", side: "sell", dollarAmount: undefined, quantity: 1 };
    const decision = evaluate({ equity: 100, isLiveExecution: true, marginEnabled: true, proposal: sell });
    expect(decision.reasons.some((r) => r.includes("margin_minimum"))).toBe(false);
  });
});

// reconcile-refire (handoff 4.3 + 6b.3): live closed lots write episodic memory when the receipt
// flips to filled during reconciliation; absent-from-listing orders NEVER auto-flip (fill_events
// is not a complete broker ledger and no gateway exposes a per-order lookup) — they stay pending
// and escalate with position evidence as diagnostic context; aged escalation fires exactly once
// and ONLY for genuinely-unresolvable fills (never a matched open/working order).
import { randomUUID } from "node:crypto";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { beforeAll, describe, expect, it, vi } from "vitest";
import type { BrokerGateway, EquityOrder, EquityPosition } from "../src/lib/types";

// vi.hoisted: the vi.mock factory can run while STATIC imports (../src/lib/db and friends) are
// still evaluating, i.e. before this module's own body — a plain const here would not exist yet.
const { storeContextsMock } = vi.hoisted(() => ({
  storeContextsMock: vi.fn(async (_documents: Array<{ metadata: Record<string, unknown> }>) => ({ attempted: 1, indexed: 1 }))
}));

vi.mock("../src/lib/vector-db", () => ({
  managedVectorLedgerAuthority: vi.fn(),
  getCurrentVectorProviderAuthority: vi.fn(),
  findRelevantExperiences: async () => [],
  upsertExperiences: async () => {},
  retrieveContext: async () => [],
  storeContext: async () => {},
  storeContexts: storeContextsMock
}));

import { insertFillEvent, listFillEvents, listNotificationEvents } from "../src/lib/db";
import { reconcilePendingFills } from "../src/lib/strategy-execution";

function createMockGateway(overrides: Partial<BrokerGateway>): BrokerGateway {
  return overrides as BrokerGateway;
}

function brokerOrder(partial: Partial<EquityOrder> & Pick<EquityOrder, "id" | "symbol" | "side" | "state">): EquityOrder {
  return {
    type: "market",
    createdAt: new Date().toISOString(),
    ...partial
  } as EquityOrder;
}

const sellProposal = (symbol: string, quantity: number) => ({
  symbol,
  side: "sell" as const,
  type: "market" as const,
  quantity,
  timeInForce: "gfd" as const,
  marketHours: "regular_hours" as const,
  rationale: "Thesis complete; taking the exit.",
  tradeThesisTag: "Momentum-Breakout",
  entryMarketRegime: "Neutral"
});

beforeAll(() => {
  process.env.DATABASE_URL = `file:${join(tmpdir(), `agentic-refire-${randomUUID()}.db`)}`;
});

describe("experience-memory re-fire on pending_reconciliation -> filled", () => {
  it("writes the closed-lot experience exactly once across two reconcile passes", async () => {
    const accountNumber = `ACC-REFIRE-${randomUUID()}`;
    const brokerOrderId = randomUUID();
    // Entry lot already booked as accounting truth.
    insertFillEvent({
      accountNumber,
      source: "live",
      executionMode: "broker/live",
      symbol: "AAPL",
      side: "buy",
      quantity: 10,
      price: 150,
      notional: 1500,
      status: "filled",
      filledAt: "2026-07-14T14:00:00.000Z"
    });
    // Closing sell landed as pending_reconciliation (the live default) — the write hook in
    // recordFillFromProposal would have matched no closed lot at insert time.
    const sellFillId = randomUUID();
    insertFillEvent({
      id: sellFillId,
      proposalId: randomUUID(),
      accountNumber,
      source: "live",
      executionMode: "broker/live",
      symbol: "AAPL",
      side: "sell",
      quantity: 10,
      price: 0,
      notional: 0,
      status: "pending_reconciliation",
      brokerOrderId,
      raw: { proposal: sellProposal("AAPL", 10) }
    });

    const gateway = createMockGateway({
      getEquityOrders: async () => [
        brokerOrder({
          id: brokerOrderId,
          symbol: "AAPL",
          side: "sell",
          state: "filled",
          filledQuantity: 10,
          averagePrice: 156,
          updatedAt: "2026-07-14T15:00:00.000Z"
        })
      ]
    });

    await reconcilePendingFills(gateway, accountNumber);
    await vi.waitFor(() => expect(storeContextsMock).toHaveBeenCalledTimes(1));

    const flipped = listFillEvents(accountNumber, "live").find((fill) => fill.id === sellFillId);
    expect(flipped).toMatchObject({ status: "filled", price: 156, quantity: 10, notional: 1560 });

    const documents = storeContextsMock.mock.calls[0]![0];
    expect(documents.length).toBeGreaterThan(0);
    expect(String(documents[0]!.metadata.accession)).toMatch(/^exp:/);
    expect(documents[0]!.metadata.symbol).toBe("AAPL");

    // Second pass: the fill left the pending list — no duplicate experience write.
    await reconcilePendingFills(gateway, accountNumber);
    await new Promise((resolve) => setTimeout(resolve, 50));
    expect(storeContextsMock).toHaveBeenCalledTimes(1);
  });
});

describe("absent broker orders NEVER auto-flip (no direct per-order lookup available)", () => {
  it("does NOT flip a fill when the position delta is ambiguous", async () => {
    const accountNumber = `ACC-AMBIG-${randomUUID()}`;
    const fillId = randomUUID();
    insertFillEvent({
      id: fillId,
      accountNumber,
      source: "live",
      executionMode: "broker/live",
      symbol: "AAPL",
      side: "buy",
      quantity: 10,
      price: 0,
      notional: 0,
      status: "pending_reconciliation",
      brokerOrderId: randomUUID()
    });

    const gateway = createMockGateway({
      // ordersListIncludesTerminal deliberately unset (Robinhood-style).
      getEquityOrders: async () => [],
      // Position shows 4 shares — matches neither "not executed" (0) nor "executed" (10).
      getEquityPositions: async (): Promise<EquityPosition[]> => [
        { symbol: "AAPL", quantity: 4, averageCost: 150, marketValue: 600 }
      ]
    });

    await reconcilePendingFills(gateway, accountNumber);

    expect(listFillEvents(accountNumber, "live").find((fill) => fill.id === fillId)).toMatchObject({
      status: "pending_reconciliation",
      price: 0,
      notional: 0
    });
  });

  it("never flips even when the position delta exactly matches execution — external holdings fake the same delta; escalates with the evidence instead", async () => {
    const accountNumber = `ACC-NOFLIP-${randomUUID()}`;
    const fillId = randomUUID();
    insertFillEvent({
      id: fillId,
      accountNumber,
      source: "live",
      executionMode: "broker/live",
      symbol: "NVDA",
      side: "buy",
      quantity: 5,
      price: 0,
      notional: 0,
      status: "pending_reconciliation",
      brokerOrderId: randomUUID(),
      filledAt: new Date(Date.now() - 2 * 60 * 60_000).toISOString() // past the 30m default threshold
    });

    const gateway = createMockGateway({
      // ordersListIncludesTerminal deliberately unset (Robinhood-style, non-authoritative).
      getEquityOrders: async () => [],
      // The owner already held 5 NVDA bought manually OUTSIDE the app (never in fill_events).
      // The delta "matches" this order executing even though it may never have — quantity
      // arithmetic cannot distinguish an external trade from this order's execution.
      getEquityPositions: async (): Promise<EquityPosition[]> => [
        { symbol: "NVDA", quantity: 5, averageCost: 120, marketValue: 600 }
      ]
    });

    await reconcilePendingFills(gateway, accountNumber);

    // The fill must stay pending — never a fabricated fill at an inferred price.
    const fill = listFillEvents(accountNumber, "live").find((f) => f.id === fillId);
    expect(fill).toMatchObject({ status: "pending_reconciliation", price: 0, notional: 0 });
    expect((fill!.raw as Record<string, unknown>).positionInference).toBeUndefined();

    // The escalation carries the observed position comparison as DIAGNOSTIC context only.
    const escalations = listNotificationEvents("local", 100).filter(
      (event) => event.type === "run_failed" && (event.payload as Record<string, unknown>)?.fillId === fillId
    );
    expect(escalations).toHaveLength(1);
    const payload = escalations[0]!.payload as Record<string, unknown>;
    expect(payload.reason).toBe("order_absent_from_listing");
    expect(payload.evidence).toMatchObject({
      brokerPositionQuantity: 5,
      bookedNetQuantity: 0,
      intendedQuantity: 5,
      deltaConsistentWithExecution: true
    });
    expect(String((payload.evidence as Record<string, unknown>).summary)).toContain("NOT proof");
  });

  it("never flips an absent-order SELL even when the position is gone (consistent with execution, but not proof)", async () => {
    const accountNumber = `ACC-SELLABS-${randomUUID()}`;
    insertFillEvent({
      accountNumber,
      source: "live",
      executionMode: "broker/live",
      symbol: "MSFT",
      side: "buy",
      quantity: 8,
      price: 100,
      notional: 800,
      status: "filled",
      filledAt: "2026-07-14T14:00:00.000Z"
    });
    const fillId = randomUUID();
    insertFillEvent({
      id: fillId,
      accountNumber,
      source: "live",
      executionMode: "broker/live",
      symbol: "MSFT",
      side: "sell",
      quantity: 8,
      price: 0,
      notional: 0,
      status: "pending_reconciliation",
      brokerOrderId: randomUUID()
    });

    const gateway = createMockGateway({
      getEquityOrders: async () => [],
      // Position gone: consistent with the sell having executed — but a manual/MCP sell outside
      // the app produces the same picture, so the fill must stay pending for owner resolution.
      getEquityPositions: async (): Promise<EquityPosition[]> => []
    });

    await reconcilePendingFills(gateway, accountNumber);

    expect(listFillEvents(accountNumber, "live").find((fill) => fill.id === fillId)).toMatchObject({
      status: "pending_reconciliation",
      price: 0
    });
  });

  it("fetches no positions when nothing escalates (fresh fill, authoritative listing)", async () => {
    const accountNumber = `ACC-AUTH-${randomUUID()}`;
    const fillId = randomUUID();
    insertFillEvent({
      id: fillId,
      accountNumber,
      source: "live",
      executionMode: "broker/live",
      symbol: "NVDA",
      side: "buy",
      quantity: 5,
      price: 0,
      notional: 0,
      status: "pending_reconciliation",
      brokerOrderId: randomUUID()
    });
    const getEquityPositions = vi.fn(async (): Promise<EquityPosition[]> => [
      { symbol: "NVDA", quantity: 5, averageCost: 120, marketValue: 600 }
    ]);
    const gateway = createMockGateway({
      ordersListIncludesTerminal: true,
      getEquityOrders: async () => [],
      getEquityPositions
    } as Partial<BrokerGateway>);

    await reconcilePendingFills(gateway, accountNumber);

    // No flip, no inference: the fill just stays pending, and since it is younger than the
    // escalation threshold no position evidence is even collected.
    expect(getEquityPositions).not.toHaveBeenCalled();
    expect(listFillEvents(accountNumber, "live").find((fill) => fill.id === fillId)).toMatchObject({
      status: "pending_reconciliation"
    });
  });
});

describe("age-based escalation of stuck pending fills", () => {
  it("emits exactly one notification + persists a marker across two reconcile passes, without touching accounting state", async () => {
    const accountNumber = `ACC-ESC-${randomUUID()}`;
    const fillId = randomUUID();
    insertFillEvent({
      id: fillId,
      accountNumber,
      source: "live",
      executionMode: "broker/live",
      symbol: "TSLA",
      side: "buy",
      quantity: 3,
      price: 0,
      notional: 0,
      status: "pending_reconciliation",
      brokerOrderId: randomUUID(),
      filledAt: new Date(Date.now() - 2 * 60 * 60_000).toISOString() // 2h old > 30m default
    });

    const gateway = createMockGateway({
      getEquityOrders: async () => [],
      // Broker position unchanged (none) — inference correctly concludes "no execution shown".
      getEquityPositions: async (): Promise<EquityPosition[]> => []
    });

    await reconcilePendingFills(gateway, accountNumber);
    await reconcilePendingFills(gateway, accountNumber);

    const escalations = listNotificationEvents("local", 100).filter(
      (event) => event.type === "run_failed" && (event.payload as Record<string, unknown>)?.fillId === fillId
    );
    expect(escalations).toHaveLength(1);
    expect(escalations[0]!.title).toContain("pending reconciliation");
    expect((escalations[0]!.payload as Record<string, unknown>).reconcile).toBe("uncertain");

    const fill = listFillEvents(accountNumber, "live").find((f) => f.id === fillId);
    // Informational only: the fill stays pending, with the once-per-fill marker persisted.
    expect(fill).toMatchObject({ status: "pending_reconciliation", price: 0 });
    expect((fill!.raw as Record<string, unknown>).pendingEscalation).toBeTruthy();
  });

  it("does not escalate a fill younger than the threshold", async () => {
    const accountNumber = `ACC-YOUNG-${randomUUID()}`;
    const fillId = randomUUID();
    insertFillEvent({
      id: fillId,
      accountNumber,
      source: "live",
      executionMode: "broker/live",
      symbol: "AMD",
      side: "buy",
      quantity: 2,
      price: 0,
      notional: 0,
      status: "pending_reconciliation",
      brokerOrderId: randomUUID()
    });

    await reconcilePendingFills(createMockGateway({
      getEquityOrders: async () => [],
      getEquityPositions: async (): Promise<EquityPosition[]> => []
    }), accountNumber);

    const escalations = listNotificationEvents("local", 100).filter(
      (event) => event.type === "run_failed" && (event.payload as Record<string, unknown>)?.fillId === fillId
    );
    expect(escalations).toHaveLength(0);
    const fill = listFillEvents(accountNumber, "live").find((f) => f.id === fillId);
    expect((fill!.raw ?? {}) as Record<string, unknown>).not.toHaveProperty("pendingEscalation");
  });

  it("NEVER escalates a fill whose matched broker order is still open/working, even past the threshold", async () => {
    const accountNumber = `ACC-WORKING-${randomUUID()}`;
    const brokerOrderId = randomUUID();
    const fillId = randomUUID();
    insertFillEvent({
      id: fillId,
      accountNumber,
      source: "live",
      executionMode: "broker/live",
      symbol: "GOOG",
      side: "buy",
      quantity: 4,
      price: 0,
      notional: 0,
      status: "pending_reconciliation",
      brokerOrderId,
      filledAt: new Date(Date.now() - 3 * 60 * 60_000).toISOString() // 3h old — a healthy day limit
    });

    const gateway = createMockGateway({
      getEquityOrders: async () => [
        // A resting working limit — normal for a day limit order; stale-limit-order alerting
        // owns this case, so the pending-fill escalation must stay silent.
        brokerOrder({ id: brokerOrderId, symbol: "GOOG", side: "buy", state: "accepted", type: "limit" })
      ]
    });

    await reconcilePendingFills(gateway, accountNumber);

    const escalations = listNotificationEvents("local", 100).filter(
      (event) => event.type === "run_failed" && (event.payload as Record<string, unknown>)?.fillId === fillId
    );
    expect(escalations).toHaveLength(0);
    const fill = listFillEvents(accountNumber, "live").find((f) => f.id === fillId);
    expect(fill).toMatchObject({ status: "pending_reconciliation" });
    expect((fill!.raw ?? {}) as Record<string, unknown>).not.toHaveProperty("pendingEscalation");
  });

  it("escalates a matched order in a TERMINAL state whose execution data is unusable (executed quantity, no price)", async () => {
    const accountNumber = `ACC-TERM-${randomUUID()}`;
    const brokerOrderId = randomUUID();
    const fillId = randomUUID();
    insertFillEvent({
      id: fillId,
      accountNumber,
      source: "live",
      executionMode: "broker/live",
      symbol: "META",
      side: "buy",
      quantity: 6,
      price: 0,
      notional: 0,
      status: "pending_reconciliation",
      brokerOrderId,
      filledAt: new Date(Date.now() - 2 * 60 * 60_000).toISOString()
    });

    const gateway = createMockGateway({
      getEquityOrders: async () => [
        // Canceled after a partial execution the broker reports WITHOUT a realized price — the
        // receipt cannot be booked (no defensible price) and the order will never progress.
        brokerOrder({ id: brokerOrderId, symbol: "META", side: "buy", state: "canceled", filledQuantity: 3 })
      ]
    });

    await reconcilePendingFills(gateway, accountNumber);

    const escalations = listNotificationEvents("local", 100).filter(
      (event) => event.type === "run_failed" && (event.payload as Record<string, unknown>)?.fillId === fillId
    );
    expect(escalations).toHaveLength(1);
    const payload = escalations[0]!.payload as Record<string, unknown>;
    expect(payload.reason).toBe("terminal_state_unusable_execution_data");
    expect(payload.brokerState).toBe("canceled");
    expect(payload.knownBrokerQuantity).toBe(3);
    expect(payload.reconcile).toBe("uncertain");
    // Advisory only: accounting state untouched, marker persisted once.
    const fill = listFillEvents(accountNumber, "live").find((f) => f.id === fillId);
    expect(fill).toMatchObject({ status: "pending_reconciliation", price: 0 });
    expect((fill!.raw as Record<string, unknown>).pendingEscalation).toMatchObject({
      reason: "terminal_state_unusable_execution_data"
    });
  });
});

/**
 * persist-pool-v2 (2026-07-06): RAG_PERSIST_CANDIDATE_POOL_FULL wiring in
 * `retrieveContextDetailed` (vector-db.ts) + `rankPool`'s `onDispositions` hook +
 * `recordCandidatePoolFull` (rag/candidate-pool.ts).
 *
 * v1 (test/persist-candidate-pool.test.ts, RAG_PERSIST_CANDIDATE_POOL) honestly captures only
 * `rankPool`'s OUTPUT pool (`ordered`) — a candidate dropped by minScore/asOf/dedupe/rerank never
 * enters `ordered` and so is invisible to v1. v2 closes that gap: it captures the PRE-`rankPool`
 * `matches` pool (raw Pinecone recall, or the #822 fused multi-query pool) together with a
 * per-candidate DISPOSITION naming the exact stage that dropped it (or `used`/`kept_not_used` for
 * survivors).
 *
 * Four things pinned here (mirrors the v1 file's four-point pin list):
 *  1. Flag OFF (default/unset): retrieveContextDetailed's audit-call count and returned chunks are
 *     byte-identical to pre-v2 behavior — `audit("rag_candidate_pool_full", ...)` is never called,
 *     and (critically) `rankPool` runs its exact pure-function path (no `onDispositions` is even
 *     constructed) so retrieval itself is unaffected.
 *  2. Flag ON: a synthetic matches pool where candidates are dropped at DIFFERENT stages (below
 *     minScore, dated-after-asOf, near-duplicate, cut by the final slice, and some used) yields a
 *     record whose per-candidate dispositions correctly name each stage.
 *  3. A #822 multi-query case: exactly ONE fused record covering ids from every query variant,
 *     with correct dispositions.
 *  4. v1 and v2 can be enabled independently (distinct flags, distinct audit `kind`s) and neither
 *     regresses the other when both are on.
 *
 * Mocking pattern mirrors test/persist-candidate-pool.test.ts (full Pinecone/Voyage mock, no live
 * network, `audit` mocked so we can assert on its call args).
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => {
  const upsert = vi.fn();
  const query = vi.fn();
  const index = vi.fn(() => ({ upsert, query }));
  return {
    upsert,
    query,
    index,
    listIndexes: vi.fn(),
    createIndex: vi.fn(),
    embed: vi.fn(),
    rerank: vi.fn(),
    resolveApiKey: vi.fn(),
    audit: vi.fn()
  };
});

vi.mock("@pinecone-database/pinecone", () => ({
  Pinecone: vi.fn(function Pinecone() {
    return {
      listIndexes: mocks.listIndexes,
      createIndex: mocks.createIndex,
      Index: mocks.index
    };
  })
}));

vi.mock("voyageai", () => ({
  VoyageAIClient: vi.fn(function VoyageAIClient() {
    return {
      embed: mocks.embed,
      rerank: mocks.rerank
    };
  })
}));

vi.mock("../src/lib/db", () => ({
  resolveApiKey: mocks.resolveApiKey,
  audit: mocks.audit,
  setInternalSetting: vi.fn()
}));

function fullPoolCalls() {
  return mocks.audit.mock.calls.filter((call) => call[0] === "rag_candidate_pool_full");
}

function v1PoolCalls() {
  return mocks.audit.mock.calls.filter((call) => call[0] === "rag_candidate_pool");
}

describe("retrieveContextDetailed: RAG_PERSIST_CANDIDATE_POOL_FULL wiring", () => {
  beforeEach(() => {
    vi.resetModules();
    vi.clearAllMocks();

    process.env.PINECONE_API_KEY = "pinecone-test";
    process.env.VOYAGE_API_KEY = "voyage-test";
    process.env.PINECONE_INDEX_READY_WAIT_MS = "0";
