describe("recordCandidatePoolFull: defensive hard cap on persisted candidate count (review fix)", () => {
  beforeEach(() => {
    vi.resetModules();
    vi.clearAllMocks();
    delete process.env.RAG_PERSIST_CANDIDATE_POOL_FULL;
  });

  afterEach(() => {
