      rationale: "Breakout with volume.",
      action: "BUY AAPL $1000",
      thesisTag: "Momentum",
      regime: "Risk-On",
      evidence: [
        { kind: "safety", title: "Possible prompt-injection pattern in headlines:AAPL", summary: "Scanner receipt.", tone: "warning" }
      ],
