      });
      broker.positions = [{ symbol: "AAPL", quantity: 100, averageCost: 100, marketValue: 10000 }];
      broker.quotes = { AAPL: { price: 90 } }; // breaches 95 trigger

      const policyOn = {
        ...policyFor("SYN-HALTED-ON"),
