    await rerankMatches(
      voyage,
      "AAPL guidance",
      [
        { id: "m1", score: 0.5, metadata: { text: "AAPL raised full-year guidance." } },
        { id: "m2", score: 0.4, metadata: { text: "AAPL announced a buyback." } }
      ],
